BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH  = os.path.join(BASE_DIR, "database", "metalerp.db")
app = Flask(__name__, template_folder="templates", static_folder="static")
app.secret_key = secrets.token_hex(32)
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"

# ── Bitácora de auditoría ─────────────────────────────────────────────────────
# Toda alta/modificación/baja de datos queda registrada en la tabla `auditoria`
# SIN tocar los controladores: se intercepta en la capa de conexión. Por acá
# pasan tanto los helpers query()/execute() como los db.execute(...) sueltos
# que hay repartidos por el archivo, así que no hay forma de escribir en la
# base sin dejar rastro.
#
# Reglas:
#   · El registro nunca puede voltear la operación principal: todo el trabajo
#     de auditoría va envuelto en try/except y, si falla, solo se avisa por
#     consola (SQLite hace rollback a nivel sentencia, no de transacción).
#   · Origen "usuario" cuando hay sesión HTTP; "sistema" para procesos
#     automáticos (arranque, backfills, cálculos) o cuando un bloque se marca
#     explícitamente con auditoria_proceso("nombre").
#   · Nunca se guardan contraseñas ni columnas de marca de tiempo técnica.

AUDITORIA_TABLAS_EXCLUIDAS = {"auditoria"}
# Nombres exactos que nunca se guardan.
AUDITORIA_COLUMNAS_EXCLUIDAS = {"password", "passwd", "pwd", "clave", "updated_at", "modificado_en"}
# Fragmentos: cualquier columna que los contenga tampoco se guarda.
AUDITORIA_COLUMNAS_FRAGMENTOS = ("password", "contrasena", "contraseña", "updated_at", "token", "secret")
# Tope de filas inspeccionadas por sentencia (un UPDATE masivo no debe hacer
# que la auditoría cueste más que la operación en sí).
AUDITORIA_MAX_FILAS = 500
# Los valores muy largos (ej. imágenes en base64 en `configuracion`) se cortan.
AUDITORIA_MAX_LARGO_VALOR = 2000

_aud_local = threading.local()


def _aud_estado(nombre, default=None):
    return getattr(_aud_local, nombre, default)


def _aud_aviso(e):
    try:
        print(f"[auditoria] No se pudo registrar el cambio: {e}")
    except Exception:
        pass


class auditoria_proceso:
    """Marca un bloque como cambio hecho por el sistema y no por el usuario.

    Sirve tanto de context manager como de decorador:

        with auditoria_proceso("MRP"):
            ...
        @auditoria_proceso("backfill requerimientos")
        def _backfill(): ...

    Es el único punto de extensión pensado para el resto del código: todo lo
    demás se audita solo.
    """

    def __init__(self, nombre):
        self.nombre = nombre

    def __enter__(self):
        self._previo = _aud_estado("proceso")
        _aud_local.proceso = self.nombre
        return self

    def __exit__(self, *exc):
        _aud_local.proceso = self._previo
        return False

    def __call__(self, f):
        @wraps(f)
        def _envuelto(*a, **kw):
            with auditoria_proceso(self.nombre):
                return f(*a, **kw)
        return _envuelto


def _aud_identidad():
    """(origen, usuario_id, actor) de quien está haciendo el cambio."""
    proceso = _aud_estado("proceso")
    if proceso:
        return "sistema", None, proceso
    try:
        if has_request_context():
            if session.get("user_id"):
                nombre = session.get("nombre") or session.get("username") or f"usuario #{session['user_id']}"
                return "usuario", session["user_id"], nombre
            return "sistema", None, "solicitud sin sesión"
    except Exception:
        pass
    return "sistema", None, "proceso interno"


def _aud_ruta():
    try:
        if has_request_context():
            return f"{request.method} {request.path}"
    except Exception:
        pass
    return None


# ── Lectura del SQL ───────────────────────────────────────────────────────────
_AUD_DML = re.compile(r"^\s*(INSERT|REPLACE|UPDATE|DELETE)\b", re.I)
_AUD_TABLA = re.compile(
    r"^\s*(?:INSERT(?:\s+OR\s+[A-Za-z]+)?\s+INTO"
    r"|REPLACE(?:\s+INTO)?"
    r"|UPDATE(?:\s+OR\s+[A-Za-z]+)?"
    r"|DELETE\s+FROM)\s+[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)", re.I)


def _aud_mascara(sql):
    """Copia del SQL con literales y comentarios pisados por espacios, más la
    profundidad de paréntesis de cada carácter (misma longitud que `sql`).

    Hace falta para encontrar el WHERE *de la sentencia* y no el de una
    subconsulta, y para contar los '?' que corresponden al SET.
    """
    out, prof = [], []
    nivel, estado, cierre, i, n = 0, None, "", 0, len(sql)
    while i < n:
        c = sql[i]
        if estado is None:
            if c in "'\"`[":
                estado, cierre = "lit", ("]" if c == "[" else c)
                out.append(" "); prof.append(nivel)
            elif c == "-" and i + 1 < n and sql[i + 1] == "-":
                estado = "lin"; out.append(" "); prof.append(nivel)
            elif c == "/" and i + 1 < n and sql[i + 1] == "*":
                estado = "blk"; out.append(" "); prof.append(nivel)
            elif c == "(":
                nivel += 1; out.append(c); prof.append(nivel)
            elif c == ")":
                out.append(c); prof.append(nivel); nivel -= 1
            else:
                out.append(c); prof.append(nivel)
        elif estado == "lit":
            out.append(" "); prof.append(nivel)
            if c == cierre:
                if c != "]" and i + 1 < n and sql[i + 1] == c:
                    i += 1; out.append(" "); prof.append(nivel)   # '' = comilla escapada
                else:
                    estado = None
        elif estado == "lin":
            out.append("\n" if c == "\n" else " "); prof.append(nivel)
            if c == "\n":
                estado = None
        else:  # blk
            out.append(" "); prof.append(nivel)
            if c == "/" and i > 0 and sql[i - 1] == "*":
                estado = None
        i += 1
    return "".join(out), prof


def _aud_partes(sql, params):
    """(verbo, tabla, where_sql, params_del_where) o (None, ...) si no aplica."""
    m = _AUD_TABLA.match(sql)
    if not m:
        return None, None, None, None
    verbo = re.match(r"^\s*([A-Za-z]+)", sql).group(1).upper()
    tabla = m.group(1)
    if verbo in ("INSERT", "REPLACE"):
        return verbo, tabla, None, ()
    if isinstance(params, dict):
        return None, None, None, None          # parámetros nombrados: no se usan acá
    seq = tuple(params or ())
    mascara, prof = _aud_mascara(sql)
    pos = -1
    for w in re.finditer(r"\bWHERE\b", mascara, re.I):
        if prof[w.start()] == 0:
            pos = w.start()
    if pos < 0:
        return verbo, tabla, "", ()            # sin WHERE: afecta a toda la tabla
    where_sql = sql[pos:]
    fin = re.search(r"\bRETURNING\b", mascara[pos:], re.I)
    if fin:
        where_sql = where_sql[:fin.start()]
    return verbo, tabla, where_sql, seq[mascara.count("?", 0, pos):]


# ── Metadatos de las tablas (se leen una vez por proceso) ─────────────────────
_aud_meta = {}


def _aud_tabla_meta(conn, tabla):
    meta = _aud_meta.get(tabla)
    if meta is None:
        cols, pks = [], []
        for c in conn._crudo(f'PRAGMA table_info("{tabla}")').fetchall():
            nombre = c[1]
            cols.append(nombre)
            if c[5]:
                pks.append(nombre)
        excluidas = {c for c in cols
                     if c.lower() in AUDITORIA_COLUMNAS_EXCLUIDAS
                     or any(f in c.lower() for f in AUDITORIA_COLUMNAS_FRAGMENTOS)}
        meta = {"cols": cols, "pk": pks[0] if len(pks) == 1 else None, "excluidas": excluidas}
        _aud_meta[tabla] = meta
    return meta


def _aud_valor(v):
    if isinstance(v, (bytes, bytearray)):
        return f"<binario, {len(v)} bytes>"
    if isinstance(v, str) and len(v) > AUDITORIA_MAX_LARGO_VALOR:
        return v[:AUDITORIA_MAX_LARGO_VALOR] + f"… (+{len(v) - AUDITORIA_MAX_LARGO_VALOR} caracteres)"
    return v


def _aud_fila(fila, excluidas):
    return {k: _aud_valor(fila[k]) for k in fila.keys()
            if k != "_aud_rowid" and k not in excluidas}


def _aud_enmascarar(d):
    """Reemplaza los importes por un marcador. La bitácora sigue mostrando QUÉ
    campo cambió, pero no el valor, para quien no puede ver importes."""
    if not d:
        return d
    return {k: ("\u2014 (oculto)" if k in CAMPOS_MONETARIOS else v) for k, v in d.items()}


def _aud_leer(conn, tabla, where_sql, where_params, meta):
    """Filas afectadas, con su rowid, antes de ejecutar la sentencia."""
    try:
        cur = conn._crudo(f'SELECT rowid AS _aud_rowid, * FROM "{tabla}" {where_sql or ""}', where_params)
    except sqlite3.Error:
        cur = conn._crudo(f'SELECT * FROM "{tabla}" {where_sql or ""}', where_params)
    cur.row_factory = sqlite3.Row
    filas = cur.fetchmany(AUDITORIA_MAX_FILAS + 1)
    truncado = len(filas) > AUDITORIA_MAX_FILAS
    out = []
    for f in filas[:AUDITORIA_MAX_FILAS]:
        claves = f.keys()
        out.append({
            "rowid": f["_aud_rowid"] if "_aud_rowid" in claves else None,
            "id": f[meta["pk"]] if meta["pk"] and meta["pk"] in claves else (
                f["_aud_rowid"] if "_aud_rowid" in claves else None),
            "datos": _aud_fila(f, meta["excluidas"]),
        })
    return out, truncado


def _aud_releer(conn, tabla, rowid, meta):
    if rowid is None:
        return None
    try:
        cur = conn._crudo(f'SELECT * FROM "{tabla}" WHERE rowid=?', (rowid,))
        cur.row_factory = sqlite3.Row
        f = cur.fetchone()
    except sqlite3.Error:
        return None
    return _aud_fila(f, meta["excluidas"]) if f else None


def _aud_json(d):
    if d is None:
        return None
    return _json.dumps(d, ensure_ascii=False, default=str)


def _aud_registrar(conn, tabla, accion, registro_id, antes, despues):
    origen, uid, actor = _aud_identidad()
    conn._crudo(
        "INSERT INTO auditoria (fecha,origen,usuario_id,actor,entidad,registro_id,accion,ruta,valores_antes,valores_despues)"
        " VALUES (datetime('now','localtime'),?,?,?,?,?,?,?,?,?)",
        (origen, uid, actor, tabla, None if registro_id is None else str(registro_id),
         accion, _aud_ruta(), _aud_json(antes), _aud_json(despues)))


def _aud_antes(conn, sql, params):
    verbo, tabla, where_sql, where_params = _aud_partes(sql, params)
    if not tabla or tabla.lower() in AUDITORIA_TABLAS_EXCLUIDAS:
        return None
    meta = _aud_tabla_meta(conn, tabla)
    if not meta["cols"]:
        return None                                   # vista o tabla inexistente
    ctx = {"verbo": verbo, "tabla": tabla, "meta": meta, "filas": [], "truncado": False}
    if verbo not in ("INSERT", "REPLACE"):
        if where_sql is None:
            return None
        ctx["filas"], ctx["truncado"] = _aud_leer(conn, tabla, where_sql, where_params, meta)
    return ctx


def _aud_despues(conn, cur, ctx):
    if not ctx:
        return
    tabla, meta, verbo = ctx["tabla"], ctx["meta"], ctx["verbo"]
    if verbo in ("INSERT", "REPLACE"):
        nueva = _aud_releer(conn, tabla, cur.lastrowid, meta)
        if nueva is None:
            return
        if (cur.rowcount or 1) > 1:
            nueva = dict(nueva, _filas_insertadas=cur.rowcount)
        rid = nueva.get(meta["pk"]) if meta["pk"] else cur.lastrowid
        _aud_registrar(conn, tabla, "alta", rid, None, nueva)
        return
    if verbo == "UPDATE":
        for f in ctx["filas"]:
            despues = _aud_releer(conn, tabla, f["rowid"], meta)
            antes = f["datos"]
            if despues is None:
                continue
            # Solo los campos que efectivamente cambiaron.
            dif_a, dif_d = {}, {}
            for k in set(antes) | set(despues):
                if antes.get(k) != despues.get(k):
                    dif_a[k] = antes.get(k)
                    dif_d[k] = despues.get(k)
            if not dif_d:
                continue                               # UPDATE que no cambió nada
            _aud_registrar(conn, tabla, "modificacion", f["id"], dif_a, dif_d)
        return
    for f in ctx["filas"]:                             # DELETE
        _aud_registrar(conn, tabla, "baja", f["id"], f["datos"], None)


class _AuditConnection(sqlite3.Connection):
    """Conexión que deja registrada toda escritura en la tabla `auditoria`."""

    def _crudo(self, sql, params=()):
        """Ejecuta sin auditar (uso interno de la auditoría)."""
        return sqlite3.Connection.execute(self, sql, params)

    def execute(self, sql, parameters=()):
        if _aud_estado("dentro") or not isinstance(sql, str) or not _AUD_DML.match(sql):
            return sqlite3.Connection.execute(self, sql, parameters)
        ctx = None
        _aud_local.dentro = True
        try:
            ctx = _aud_antes(self, sql, parameters)
        except Exception as e:
            _aud_aviso(e)
        finally:
            _aud_local.dentro = False
        cur = sqlite3.Connection.execute(self, sql, parameters)
        _aud_local.dentro = True
        try:
            _aud_despues(self, cur, ctx)
        except Exception as e:
            _aud_aviso(e)
        finally:
            _aud_local.dentro = False
        return cur

    def executemany(self, sql, seq_of_parameters):
        if _aud_estado("dentro") or not isinstance(sql, str) or not _AUD_DML.match(sql):
            return sqlite3.Connection.executemany(self, sql, seq_of_parameters)
        filas = list(seq_of_parameters)
        # Lote chico: se ejecuta fila por fila para que cada una quede
        # auditada con su valor real. Lote grande: se prioriza la velocidad
        # de la operación y se deja un único asiento con el resumen.
        if len(filas) <= 200:
            cur = None
            for p in filas:
                cur = self.execute(sql, p)
            return cur if cur is not None else sqlite3.Connection.execute(self, "SELECT 1")
        cur = sqlite3.Connection.executemany(self, sql, filas)
        _aud_local.dentro = True
        try:
            tabla = (_AUD_TABLA.match(sql) or [None, None])[1]
            if tabla and tabla.lower() not in AUDITORIA_TABLAS_EXCLUIDAS:
                _aud_registrar(self, tabla, "alta", None, None, {"_filas_afectadas": len(filas)})
        except Exception as e:
            _aud_aviso(e)
        finally:
            _aud_local.dentro = False
        return cur


def get_db():
    if "db" not in g:
        # timeout=30 -> si la DB esta bloqueada por otra conexion (varios
        # operarios en simultaneo), espera hasta 30s en vez de fallar al toque
        g.db = sqlite3.connect(DB_PATH, timeout=30, factory=_AuditConnection)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
        # WAL permite que lecturas y escrituras convivan sin bloquearse entre si,
        # clave cuando hay varias cuentas conectadas por la misma red local
        g.db.execute("PRAGMA journal_mode = WAL")
        g.db.execute("PRAGMA busy_timeout = 30000")
        g.db.create_function("cant_material", 3, cant_material, deterministic=True)
    return g.db

@app.teardown_appcontext
def close_db(e=None):
    db = g.pop("db", None)
    if db: db.close()

def query(sql, params=(), one=False):
    cur = get_db().execute(sql, params)
    rows = cur.fetchall()
    return (rows[0] if rows else None) if one else rows

def execute(sql, params=()):
    db = get_db()
    cur = db.execute(sql, params)
    db.commit()
    return cur.lastrowid

def get_config_valor(clave, default=""):
    row = query("SELECT valor FROM configuracion WHERE clave=?", (clave,), one=True)
    return row["valor"] if row and row["valor"] not in (None, "") else default

def _sc_automaticas_activas():
    """¿El sistema puede crear Solicitudes de Compra por su cuenta?

    Por defecto NO: las SC se cargan a mano desde Compras. Hay cuatro puntos
    que históricamente las generaban solos — stock por debajo del mínimo,
    faltante de insumo al remitir una OTT, envío a un tercero, y materiales
    faltantes de una OT auxiliar — y todos preguntan acá antes de crear nada.

    Para volver a habilitarlas: configuracion.sc_automaticas = '1'.
    """
    try:
        return get_config_valor("sc_automaticas", "0") == "1"
    except Exception:
        # Ante la duda (sin contexto de base, por ejemplo) no se crea nada.
        return False


def cant_material(cantidad_unit, piezas, vida_util):
    """Cantidad de un material de una operación para procesar `piezas` piezas.

    Herramienta con vida útil (piezas que hace cada una): ceil(piezas / vida
    útil), p.ej. 100 piezas con vida útil 4 -> 25 herramientas, 101 -> 26.
    Sin vida útil (vacía o 0): cantidad por pieza x piezas, como siempre.
    También está registrada como función SQL (ver get_db):
    cant_material(om.cantidad, oo.qty_requerida, om.vida_util_herramienta)."""
    try:
        piezas = float(piezas or 0)
        vida = float(vida_util or 0)
    except (TypeError, ValueError):
        return 0.0
    if vida > 0:
        return float(math.ceil(piezas / vida - 1e-9)) if piezas > 0 else 0.0
    return float(cantidad_unit or 0) * piezas


def _vida_util_valida(material_id, valor):
    """Vida útil a guardar para un material de una operación: entero > 0 solo
    si el material es de categoría Herramienta; en cualquier otro caso None."""
    try:
        vida = int(float(valor))
    except (TypeError, ValueError):
        return None
    if vida <= 0 or not material_id:
        return None
    mat = query("SELECT categoria FROM materiales WHERE id=?", (material_id,), one=True)
    return vida if mat and mat["categoria"] == "Herramienta" else None


def siguiente_numero(tabla, prefijo, ancho, reservar=False):
    """Próximo número correlativo de `tabla` con la forma <prefijo><N>, N con
    `ancho` dígitos: siguiente_numero("ordenes", "OT-", 3) -> "OT-169". Las
    series por año llevan el año en el prefijo ("LOTE-2026-").

    Parte del número más alto ya cargado con ese prefijo exacto; los que
    después del prefijo no son solo dígitos (otra serie, o cargados a mano con
    otro formato) no cuentan. Si el resultado ya existe, sigue sumando hasta
    encontrar uno libre.

    reservar=True lo hace atómico: toma el lock de escritura de la base
    (BEGIN IMMEDIATE) antes de leer, así ninguna otra conexión puede sacar el
    mismo número entre esta lectura y el INSERT del que llama, cuyo commit
    libera el lock. Junto con el UNIQUE de la columna `numero`, dos altas
    simultáneas nunca comparten número."""
    if reservar:
        db = get_db()
        if not db.in_transaction:
            db.execute("BEGIN IMMEDIATE")
    filas = query(f"""SELECT numero FROM {tabla} WHERE SUBSTR(numero, 1, ?) = ?
        ORDER BY CAST(SUBSTR(numero, ?) AS INTEGER) DESC, id DESC LIMIT 20""",
        (len(prefijo), prefijo, len(prefijo) + 1))
    n = 1
    for f in filas:
        resto = (f["numero"] or "")[len(prefijo):]
        if resto.isdigit():
            n = int(resto) + 1
            break
    numero = f"{prefijo}{n:0{ancho}d}"
    while query(f"SELECT 1 FROM {tabla} WHERE numero=?", (numero,), one=True):
        n += 1
        numero = f"{prefijo}{n:0{ancho}d}"
    return numero


def next_numero_sc():
    # Próximo número de SC (SC-0001, SC-0002, ...) a salvo de condiciones de
    # carrera: si dos solicitudes se crean casi al mismo tiempo (ej: una
    # manual y otra automática por stock bajo) podían calcular el mismo número
    # -> UNIQUE constraint failed. Con BEGIN IMMEDIATE tomamos el lock de
    # escritura antes de leer, así ninguna otra conexión puede colarse entre
    # el SELECT y el INSERT. Las series SC-PROD-0003 y SC-TERC-0005 (MRP y
    # faltantes de terceros) son independientes y no cuentan acá.
    db = get_db()
    db.execute("BEGIN IMMEDIATE")
    try:
        return siguiente_numero("solicitudes_compra", "SC-", 4)
    except:
        db.rollback()
        raise

def next_numero_oc():
    # Mismo problema que next_numero_sc (dos OC creadas casi al mismo tiempo,
    # o un doble-click): BEGIN IMMEDIATE toma el lock de escritura antes de leer.
    db = get_db()
    db.execute("BEGIN IMMEDIATE")
    try:
        return siguiente_numero("ordenes_compra", "OCP-", 4)
    except:
        db.rollback()
        raise

def get_or_create_pt_material(prod):
    """Devuelve el artículo de stock de un producto terminado.

    Desde la unificación de productos y materiales (ver
    migracion_unificacion.py) el producto ES el artículo de stock: la misma
    fila de `materiales` tiene el proceso, el stock y los lotes, y conserva
    el id que tenía en la vieja tabla `productos`. Ya no existe un "gemelo"
    que crear ni sincronizar, así que esta función solo devuelve esa fila.

    Se conserva el nombre (y la firma) porque la usan muchos puntos del
    código: generación de PT al completar una OT, novedades, insumos de tipo
    producto, diagnósticos, etc. Requiere que `prod` tenga "id".
    """
    prod_keys = prod.keys() if hasattr(prod, "keys") else prod
    if "id" not in prod_keys or prod["id"] is None:
        raise ValueError("get_or_create_pt_material requiere prod['id'] (producto_id)")
    art = query("SELECT id,stock FROM materiales WHERE id=?", (prod["id"],), one=True)
    if art:
        return art
    raise ValueError(f"El artículo id={prod['id']} no existe")

def _firma_insumos_operacion(proceso_op_id):
    """Firma de lo que se le manda al proveedor en una operación tercerizada.

    Es la identidad del semielaborado que vuelve: mismos insumos = misma
    pieza. Si en Procesos se le agrega o se le cambia un material a la
    operación, lo que devuelve el proveedor ya no es lo mismo y necesita su
    propio código (ver _get_or_create_pse).

    El PROVEEDOR no entra en la firma a propósito: queda trazado por lote
    (lotes.proveedor_id) y por OTT (ordenes_tercerizado.proveedor_id), que se
    congelan al momento del envío y no se ven afectados por editar el proceso
    más tarde.
    """
    rows = query("""SELECT material_id, producto_id, cantidad
        FROM operacion_materiales WHERE operacion_id=?
        ORDER BY COALESCE(material_id,0), COALESCE(producto_id,0)""",
        (proceso_op_id,))
    partes = ["%s:%s:%g" % (r["material_id"] or 0, r["producto_id"] or 0,
                            float(r["cantidad"] or 0)) for r in rows]
    return "|".join(partes) if partes else "(sin insumos)"


def _get_or_create_pse(proceso_op_id):
    """Devuelve (creando si hace falta) el id del material 'Semielaborado' de
    una operación tercerizada intermedia, en su versión VIGENTE.

    Un semielaborado queda definido por la operación MAS sus insumos. Mientras
    la firma no cambie se reusa el mismo material; apenas cambia se crea una
    versión nueva con su propio código (-v2, -v3, ...) en vez de mezclar dos
    piezas distintas bajo el mismo stock y la misma trazabilidad.

    Las OT en curso no se ven afectadas: la OTT congela su semielaborado en
    material_se_id al crearse, igual que ya congela proveedor y precio.

    Devuelve None si la operación no existe o perdió el vínculo con su
    producto (proceso_op_id NULL porque se borró la operación del proceso).
    """
    if not proceso_op_id:
        return None
    op = query("""SELECT po.id, po.nombre, po.producto_id,
            pr.codigo prod_codigo, pr.nombre prod_nombre, pr.unidad prod_unidad
        FROM proceso_operaciones po JOIN productos pr ON pr.id=po.producto_id
        WHERE po.id=?""", (proceso_op_id,), one=True)
    if not op:
        return None

    firma = _firma_insumos_operacion(proceso_op_id)
    vigente = query("""SELECT id FROM materiales
        WHERE producto_id=? AND operacion_id=? AND categoria='Semielaborado'
          AND COALESCE(pse_firma,'')=? AND activo=1
        ORDER BY id DESC LIMIT 1""",
        (op["producto_id"], proceso_op_id, firma), one=True)
    if vigente:
        return vigente["id"]

    # Firma nueva: hace falta otra versión. El código base queda para la
    # primera; de ahí en más se numeran -v2, -v3...
    op_nombre = (op["nombre"] or "SE").strip()
    base = "%s-%s" % (op["prod_codigo"], op_nombre)
    previas = query("""SELECT COUNT(*) c FROM materiales
        WHERE producto_id=? AND operacion_id=? AND categoria='Semielaborado'""",
        (op["producto_id"], proceso_op_id), one=True)["c"]
    n = int(previas or 0) + 1
    candidato = base if n == 1 else "%s-v%d" % (base, n)
    while query("SELECT id FROM materiales WHERE codigo=?", (candidato,), one=True):
        n += 1
        candidato = "%s-v%d" % (base, n)

    return execute("""INSERT INTO materiales
        (codigo,descripcion,categoria,producto_id,operacion_id,pse_firma,
         unidad,stock,stock_min,precio_unit,activo)
        VALUES (?,?,?,?,?,?,?,0,0,0,1)""",
        (candidato, "%s — %s" % (op["prod_nombre"], op_nombre),
         "Semielaborado", op["producto_id"], proceso_op_id, firma,
         op["prod_unidad"] or "unid"))


def _material_retorno_operacion(orden_operacion_id):
    """v147 (punto 9): en una operación tercerizada el primer insumo de tipo
    'material' es el material que se genera al ingresar el remito del proveedor.
    v148: se lee de la copia propia de la OT (orden_operacion_materiales)."""
    if not orden_operacion_id:
        return None
    r = query("""SELECT om.material_id FROM orden_operacion_materiales om
        WHERE om.orden_operacion_id=? AND om.tipo='material' AND om.material_id IS NOT NULL
        ORDER BY om.id LIMIT 1""", (orden_operacion_id,), one=True)
    return r["material_id"] if r else None


def _sincronizar_estado_paso(orden_operacion_id):
    """Cierra (o reabre) un paso mirando su TOTAL, no cada ruta por separado.

    Un paso puede tener rutas alternativas: varias orden_operaciones con el
    mismo `orden` (p.ej. dos máquinas que hacen lo mismo). Si el trabajo se
    reparte entre dos, ninguna llega sola a lo requerido y el paso no se
    cerraba nunca, aunque entre las dos estuviera completo — y la OT quedaba
    trabada. Lo requerido del paso es el mayor de sus rutas (cualquiera
    podría hacerlo entero) y lo producido es la suma de todas. Es el mismo
    criterio que ya usaba generar_pt_faltante_si_corresponde para el PT.
    """
    op = query("SELECT orden_id, orden FROM orden_operaciones WHERE id=?",
               (orden_operacion_id,), one=True)
    if not op:
        return
    rutas = query("""SELECT id, qty_requerida, qty_producida, estado
        FROM orden_operaciones WHERE orden_id=? AND orden=?""",
        (op["orden_id"], op["orden"]))
    requerido = max([float(r["qty_requerida"] or 0) for r in rutas] or [0.0])
    if requerido <= 0:
        return
    producido = sum(float(r["qty_producida"] or 0) for r in rutas)
    completo = producido >= requerido - 0.0001
    for r in rutas:
        # Una ruta que nunca se usó no se marca como hecha: el paso se cierra
        # con las que efectivamente trabajaron.
        if float(r["qty_producida"] or 0) <= 0 and r["id"] != orden_operacion_id:
            continue
        if completo and r["estado"] != "Completada":
            execute("UPDATE orden_operaciones SET estado='Completada' WHERE id=?", (r["id"],))
        elif not completo and r["estado"] == "Completada":
            execute("UPDATE orden_operaciones SET estado='En proceso' WHERE id=?", (r["id"],))


def _copiar_materiales_a_ot_op(oo_id, proceso_op_id):
    """v148 (punto 4): al generarse la OT se COPIA el proceso. Desde ahí la OT es
    independiente: sus materiales se editan en la OT y no se validan contra el proceso."""
    if not oo_id or not proceso_op_id:
        return
    execute("DELETE FROM orden_operacion_materiales WHERE orden_operacion_id=?", (oo_id,))
    for r in query("SELECT material_id,producto_id,cantidad,unidad,tipo,vida_util_herramienta FROM operacion_materiales WHERE operacion_id=?", (proceso_op_id,)):
        execute("""INSERT INTO orden_operacion_materiales (orden_operacion_id,material_id,producto_id,cantidad,unidad,tipo,vida_util_herramienta)
                   VALUES (?,?,?,?,?,?,?)""", (oo_id, r["material_id"], r["producto_id"], r["cantidad"], r["unidad"], r["tipo"] or "material", r["vida_util_herramienta"]))


def _tiene_insumo_material(materiales):
    return any((m.get("tipo", "material") == "material" and m.get("material_id") and m.get("cantidad"))
               for m in (materiales or []))


def _lotes_vinculados_material(orden_id, material_id):
    """Todos los lotes vinculados a este material en esta OT (vía
    orden_lotes), en orden FIFO por fecha de ingreso del lote. Puede haber
    MÁS DE UNO: la OT puede cubrir la cantidad requerida combinando varios
    lotes (ej. uno de 90 + uno de 10, o varios lotes chicos) en vez de
    exigir que un solo lote alcance para todo el consumo."""
    return query("""SELECT l.id, l.numero, l.cantidad_activa, l.fecha_ingreso,
            ol.cantidad_usada, COALESCE(ol.cantidad_consumida,0) cantidad_consumida
        FROM orden_lotes ol JOIN lotes l ON l.id=ol.lote_id
        WHERE ol.orden_id=? AND ol.material_id=?
        ORDER BY l.fecha_ingreso, l.id""", (orden_id, material_id))

def _plan_consumo_adicional(vinculos, requerido):
    """Distribuye `requerido` entre los lotes vinculados (orden FIFO por
    fecha de ingreso). Se usa cantidad_activa como disponible sin restar
    cantidad_reservada porque estos lotes ya están vinculados/reservados
    para ESTA MISMA OT (esa resta solo aplica al elegir un lote nuevo desde
    "Lotes asignados", no acá). Devuelve (plan, disponible_total, cubierto)
    donde plan es una lista de tuplas (lote, cantidad_a_tomar_de_ese_lote)."""
    plan = []
    restante = requerido
    disponible_total = 0
    for lote in vinculos:
        disp = max(0, float(lote["cantidad_activa"] or 0))
        disponible_total += disp
        if restante <= 0.0000001:
            continue
        tomar = min(disp, restante)
        if tomar > 0:
            plan.append((lote, round(tomar, 6)))
            restante -= tomar
    return plan, disponible_total, restante <= 0.0001

def _materiales_ott_pendientes_por_operacion(orden_id, oo_id):
    """Devuelve el material semielaborado generado por el retorno de una
    operación tercerizada ANTERIOR (por orden) dentro de la misma OT, cuyo
    consumo debe imputarse a ESTA operación puntual — la primera operación
    posterior a la tercerizada en la ruta. Este material se crea de forma
    dinámica al recibir el retorno de la OTT (ver registrar_retorno) y por
    lo tanto NUNCA está declarado en operacion_materiales (la plantilla de
    proceso del producto), así que sin este chequeo create_novedad/editar/
    eliminar novedad lo ignoran por completo y el lote de la OTT nunca se
    gasta aunque esté reservado y vinculado (orden_lotes) a la OT — bug
    reportado. Se asume consumo 1:1 (1 unidad de semielaborado por cada
    unidad producida en esta operación), que es el criterio con el que se
    genera la cantidad recibida de la OTT."""
    op = query("SELECT orden_id,orden FROM orden_operaciones WHERE id=?", (oo_id,), one=True)
    if not op or op["orden_id"] != orden_id:
        return []
    try:
        orden_num = float(op["orden"])
    except (TypeError, ValueError):
        return []
    # Tercerizada previa MÁS CERCANA (mayor "orden" que sea < la de esta
    # operación), que sea intermedia (es_ultimo_nivel=0, ya que la de último
    # nivel no genera semielaborado sino que cierra la OT directamente) y
    # cuyo lote de retorno ya exista.
    terc_prev = query("""SELECT ott.lote_retorno_id, l.material_id
        FROM orden_operaciones oo
        JOIN ordenes_tercerizado ott ON ott.operacion_id=oo.id
        LEFT JOIN lotes l ON l.id=ott.lote_retorno_id
        WHERE oo.orden_id=? AND oo.es_tercerizada=1 AND ott.es_ultimo_nivel=0
          AND CAST(oo.orden AS REAL) < ?
        ORDER BY CAST(oo.orden AS REAL) DESC LIMIT 1""", (orden_id, orden_num), one=True)
    if not terc_prev or not terc_prev["material_id"]:
        return []
    mat = query("SELECT id,descripcion,unidad,categoria FROM materiales WHERE id=?",
        (terc_prev["material_id"],), one=True)
    if not mat:
        return []
    return [{"material_id": mat["id"], "cantidad": 1, "categoria": mat["categoria"] or "Semielaborado",
        "descripcion": mat["descripcion"], "unidad": mat["unidad"]}]

def _plan_devolucion(vinculos, a_devolver):
    """Distribuye una devolución de stock (por edición o eliminación de una
    novedad) entre los lotes vinculados, en orden inverso (LIFO: el lote
    agregado más recientemente primero), sin devolver a un lote más de lo
    que efectivamente se le registró como consumido (cantidad_consumida),
    para no inflar su stock por encima de lo real.
    NOTA: cantidad_consumida es un acumulado por lote+material+OT a través
    de TODAS las novedades de esa OT (el schema no trackea qué lote sirvió
    a cada novedad puntual), así que esta distribución es una aproximación
    razonable y no un reverso exacto por novedad individual."""
    plan = []
    restante = a_devolver
    for lote in reversed(vinculos):
        consumida = float(lote["cantidad_consumida"] or 0)
        if restante <= 0.0000001:
            continue
        tomar = min(consumida, restante)
        if tomar > 0:
            plan.append((lote, round(tomar, 6)))
            restante -= tomar
    return plan

def hash_pw(pw):
    return hashlib.sha256(pw.encode()).hexdigest()

ROLES_BASE = ("admin", "operario", "vendedor", "almacen", "logistica")

def _rol_row(nombre):
    try:
        return query("SELECT * FROM roles WHERE nombre=?", (nombre,), one=True)
    except Exception:
        return None

def _rol_base(nombre):
    """Rol base (define qué endpoints puede usar) de un rol, sea de sistema o creado
    desde Configuración. Si el rol no existe (dato viejo) se usa el nombre tal cual."""
    r = _rol_row(nombre)
    return r["base_rol"] if r else nombre

def _permisos_rol(nombre):
    """Permisos predeterminados de un rol: los de la tabla roles, o los DEFAULT."""
    import json as _j
    r = _rol_row(nombre)
    if r and r["permisos"]:
        try:
            p = _j.loads(r["permisos"])
            if isinstance(p, dict) and p:
                return {k: str(v) for k, v in p.items()}
        except Exception:
            pass
    return dict(DEFAULT_PERMISIONES.get(_rol_base(nombre), {}))

def login_required(roles=None):
    def decorator(f):
        @wraps(f)
        def wrapped(*a, **kw):
            if "user_id" not in session:
                # Las rutas /api/* siempre son llamadas por fetch() esperando
                # JSON (ver api() en app.html). Devolverles un redirect HTML
                # a /login hace que r.json() explote con un error críptico
                # ("Unexpected token '<'") en vez de mostrar algo entendible.
                # Solo se redirige de verdad para rutas que no son de API
                # (navegación directa del browser).
                if request.path.startswith("/api/"):
                    return jsonify({"error": "Sesión expirada, volvé a iniciar sesión."}), 401
                return redirect("/login")
            if roles and session.get("rol") not in roles:
                return jsonify({"error": "Sin permiso"}), 403
            return f(*a, **kw)
        return wrapped
    return decorator

# ── Schema ────────────────────────────────────────────────────────────────────
# ── Permiso "ver valores monetarios" ─────────────────────────────────────────
# Regla única de todo el sistema: el servidor decide, y lo que no sale de acá
# no puede filtrarse en el navegador. Antes esto vivía solo en app.html
# (const VER_MONETARIO) y la API mandaba igual todos los importes: bastaba
# abrir la pestaña Red del navegador para verlos.
#
# Para agregar un campo monetario nuevo alcanza con registrarlo en
# CAMPOS_MONETARIOS: el after_request lo saca de todas las respuestas JSON y
# el before_request lo descarta de los payloads de escritura. Si el campo es
# ambiguo (un "total" que son unidades, un "valor" que es un texto), va en
# NO_MONETARIO con el motivo, y tests/test_monetario_schema.py falla si
# aparece una columna nueva que no esté en ninguna de las dos listas.

CAMPOS_MONETARIOS = frozenset({
    # Precios
    "precio", "precio_unit", "precio_unitario", "precio_venta",
    "precio_acordado", "precio_tercerizado", "oc_precio_reciente",
    # Costos
    "costo", "costo_mat", "costo_mo", "costo_total", "costo_terc",
    "costo_terciarizado", "costo_mat_item", "costo_unitario",
    # Montos / totales de dinero
    "monto", "monto_total", "monto_pedido", "monto_entregado",
    "monto_compras_pend", "total_monto_pedido", "total_monto_entregado",
    "subtotal", "importe", "exceso_monto", "precio_total",
    # Facturación
    "facturacion", "facturacion_mes", "facturacion_historico",
    "facturado", "total_facturado",
    # Configuración con contenido monetario
    "valor_hora_mo",
})

# Columnas/claves que el patrón de nombres marca como sospechosas pero NO son
# importes. Si alguna de estas pasara a representar dinero, hay que moverla
# a CAMPOS_MONETARIOS.
NO_MONETARIO = {
    "iva": "condición frente al IVA del cliente (texto: 'Responsable Inscripto'), no un importe",
    "iva_pct": "alícuota en porcentaje del presupuesto, no un importe",
    "nro_factura": "número de comprobante, no un importe",
    "centro_costo": "código de centro de costo, no un importe",
    "cantidad_activa": "unidades aprobadas de un lote; matchea el patrón por 'iva' dentro de 'activa'",
    "cantidad_activa_actual": "idem cantidad_activa",
    "nueva_activa": "idem cantidad_activa",
    "nueva_activa_total": "idem cantidad_activa",
    "cant_activa": "idem cantidad_activa",
    "pdf_mostrar_costos": "bandera 0/1 de configuración; igual se filtra aparte en /api/config",
    "pdf_mostrar_precios": "bandera 0/1 de configuración; igual se filtra aparte en /api/config",
    "mostrar_costos": "bandera interna del PDF",
    "mostrar_precios": "bandera interna del PDF",
}

# Nombres que NO se resuelven por nombre: cada endpoint decide. Se dejan
# anotados para que nadie los agregue al filtro automático sin pensarlo.
CAMPOS_AMBIGUOS = {
    "total": "puede ser unidades (total_realizado) o plata; se resuelve por endpoint",
    "valor": "configuracion.valor es texto genérico; se filtra por clave en /api/config",
    "cantidad": "unidades",
}


def puede_ver_monetario():
    """True si el usuario de la sesión puede ver importes. Cacheado por request."""
    if has_request_context() and "ver_monetario" in g:
        return g.ver_monetario
    ok = _calcular_ver_monetario()
    if has_request_context():
        g.ver_monetario = ok
    return ok


def _calcular_ver_monetario():
    if "user_id" not in session:
        return False                     # sin sesión, lo más restrictivo
    if _rol_base(session.get("rol_nombre") or session.get("rol", "")) == "logistica":
        return False
    try:
        rows = query("SELECT clave, valor FROM usuario_permisos WHERE usuario_id=?",
                     (session["user_id"],))
        perms = {r["clave"]: r["valor"] for r in rows}
    except Exception:
        perms = {}
    if not perms and session.get("rol") != "admin":
        perms = _permisos_rol(session.get("rol_nombre") or session.get("rol", "operario"))
    return perms.get("ver_monetario") != "0"


def solo_con_monetario(f):
    """Endpoint que no tiene nada que devolver sin el permiso: 403 directo."""
    @wraps(f)
    def _envuelto(*a, **kw):
        if not puede_ver_monetario():
            return jsonify({"error": "Sin permiso"}), 403
        return f(*a, **kw)
    return _envuelto


def _sin_monetario(dato):
    """Saca recursivamente toda clave monetaria de un JSON ya parseado."""
    if isinstance(dato, dict):
        for k in [k for k in dato if k in CAMPOS_MONETARIOS]:
            del dato[k]
        for v in dato.values():
            _sin_monetario(v)
    elif isinstance(dato, list):
        for v in dato:
            _sin_monetario(v)
    return dato


@app.before_request
def _descartar_monetario_entrante():
    """Un usuario restringido no puede escribir importes: se descartan del
    payload antes de que el endpoint lo lea, así no pisa con 0 ni con null lo
    que ya estaba guardado. Los costos que calcula el server siguen igual."""
    if not request.path.startswith("/api/"):
        return
    if request.method not in ("POST", "PUT", "PATCH"):
        return
    if puede_ver_monetario():
        return
    try:
        cuerpo = request.get_json(silent=True)
    except Exception:
        return
    # get_json cachea: mutar el objeto devuelto alcanza para que el endpoint
    # lo vea ya filtrado, sin tocar cada handler.
    if cuerpo is not None:
        _sin_monetario(cuerpo)


@app.after_request
def _descartar_monetario_saliente(resp):
    """Saca los importes de toda respuesta JSON de /api/ para los restringidos."""
    try:
        if not request.path.startswith("/api/"):
            return resp
        if resp.direct_passthrough or not (resp.content_type or "").startswith("application/json"):
            return resp
        if puede_ver_monetario():
            return resp
        datos = _json.loads(resp.get_data(as_text=True))
        resp.set_data(_json.dumps(_sin_monetario(datos), ensure_ascii=False, default=str))
    except Exception as e:
        print(f"[monetario] No se pudo filtrar la respuesta de {request.path}: {e}")
    return resp


SCHEMA = """
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS usuarios (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    nombre TEXT NOT NULL,
    rol TEXT NOT NULL,
    activo INTEGER DEFAULT 1,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS categorias_maquina (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT UNIQUE NOT NULL,
    descripcion TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS maquinas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo TEXT UNIQUE NOT NULL,
    nombre TEXT NOT NULL,
    categoria_id INTEGER REFERENCES categorias_maquina(id),
    marca TEXT,
    modelo TEXT,
    numero_serie TEXT,
    anio INTEGER,
    ubicacion TEXT,
    estado TEXT DEFAULT 'Operativa',
    horas_uso REAL DEFAULT 0,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS maquina_reemplazos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    maquina_id INTEGER NOT NULL REFERENCES maquinas(id) ON DELETE CASCADE,
    reemplazo_id INTEGER NOT NULL REFERENCES maquinas(id) ON DELETE CASCADE,
    UNIQUE(maquina_id, reemplazo_id)
);

CREATE TABLE IF NOT EXISTS mantenimiento_plan (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    maquina_id INTEGER NOT NULL REFERENCES maquinas(id) ON DELETE CASCADE,
    tarea TEXT NOT NULL,
    tipo TEXT DEFAULT 'Frecuencia fija',
    frecuencia_tipo TEXT,
    frecuencia_valor INTEGER,
    ultima_fecha TEXT,
    proxima_fecha TEXT,
    responsable TEXT,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS tickets_reparacion (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    maquina_id INTEGER NOT NULL REFERENCES maquinas(id),
    tipo TEXT DEFAULT 'Correctivo',
    descripcion TEXT NOT NULL,
    prioridad TEXT DEFAULT 'Normal',
    estado TEXT DEFAULT 'Abierto',
    responsable TEXT,
    fecha_apertura TEXT DEFAULT (datetime('now','localtime')),
    fecha_cierre TEXT,
    horas_paro REAL DEFAULT 0,
    costo REAL DEFAULT 0,
    solucion TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime')),
    horas_ajuste REAL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS categorias_producto (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT UNIQUE NOT NULL,
    descripcion TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS proveedores (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    razon TEXT NOT NULL,
    cuit TEXT,
    contacto TEXT,
    telefono TEXT,
    email TEXT,
    materiales TEXT,
    plazo_dias INTEGER DEFAULT 3,
    calificacion INTEGER DEFAULT 5,
    estado TEXT DEFAULT 'Activo',
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    categoria_compra TEXT
);

CREATE TABLE IF NOT EXISTS materiales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo TEXT UNIQUE NOT NULL,
    descripcion TEXT NOT NULL,
    categoria TEXT DEFAULT 'Material',
    categoria_producto_id INTEGER REFERENCES categorias_producto(id),
    unidad TEXT DEFAULT 'kg',
    stock REAL DEFAULT 0,
    stock_min REAL DEFAULT 0,
    stock_max REAL DEFAULT 0,
    precio_unit REAL DEFAULT 0,
    proveedor_id INTEGER REFERENCES proveedores(id),
    obs TEXT,
    actualizado TEXT DEFAULT (datetime('now','localtime')),
    activo INTEGER DEFAULT 1,
    producto_id INTEGER REFERENCES materiales(id),
    pse_firma TEXT,
    operacion_id INTEGER REFERENCES proceso_operaciones(id),
    tipo TEXT CHECK(tipo IN ('MP','PSE','PSET')),
    cliente_id INTEGER REFERENCES clientes(id),
    codigo_barras TEXT,
    descripcion_larga TEXT,
    tiempo_total_hs REAL DEFAULT 0,
    costo_mat REAL DEFAULT 0,
    costo_mo REAL DEFAULT 0,
    precio_venta REAL DEFAULT 0,
    peso_kg REAL DEFAULT 0,
    capacidad_cajon INTEGER,
    creado TEXT DEFAULT (datetime('now','localtime'))
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_materiales_producto_categoria_sinop ON materiales(producto_id, categoria) WHERE producto_id IS NOT NULL AND operacion_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_materiales_prod_cat_op_firma ON materiales(producto_id, categoria, operacion_id, COALESCE(pse_firma,'')) WHERE producto_id IS NOT NULL AND operacion_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_materiales_categoria ON materiales(categoria);
CREATE VIEW IF NOT EXISTS productos AS
SELECT id,
       codigo,
       descripcion            AS nombre,
       descripcion_larga      AS descripcion,
       categoria_producto_id  AS categoria_id,
       unidad,
       tiempo_total_hs,
       costo_mat,
       costo_mo,
       precio_venta,
       activo,
       obs,
       creado,
       peso_kg,
       cliente_id,
       capacidad_cajon,
       CASE WHEN categoria='Producto terminado' THEN 'PT' END AS tipo,
       codigo_barras,
       categoria              AS tipo_articulo
FROM materiales;
CREATE TRIGGER IF NOT EXISTS trg_materiales_pt_alta
    AFTER INSERT ON materiales
    WHEN NEW.categoria='Producto terminado' AND (NEW.producto_id IS NULL OR NEW.producto_id<>NEW.id)
    BEGIN
        UPDATE materiales SET producto_id=NEW.id WHERE id=NEW.id;
    END;
CREATE TRIGGER IF NOT EXISTS trg_materiales_pt_cambio
    AFTER UPDATE OF categoria, producto_id ON materiales
    WHEN NEW.categoria='Producto terminado' AND (NEW.producto_id IS NULL OR NEW.producto_id<>NEW.id)
    BEGIN
        UPDATE materiales SET producto_id=NEW.id WHERE id=NEW.id;
    END;
CREATE TRIGGER IF NOT EXISTS trg_materiales_pt_baja
    AFTER UPDATE OF categoria ON materiales
    WHEN OLD.categoria='Producto terminado' AND NEW.categoria<>'Producto terminado'
         AND NEW.producto_id=NEW.id
    BEGIN
        UPDATE materiales SET producto_id=NULL WHERE id=NEW.id;
    END;

CREATE TABLE IF NOT EXISTS proveedor_materiales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    proveedor_id INTEGER NOT NULL REFERENCES proveedores(id) ON DELETE CASCADE,
    material_id INTEGER NOT NULL REFERENCES materiales(id) ON DELETE CASCADE,
    precio_unit REAL DEFAULT 0,
    plazo_dias INTEGER DEFAULT 3,
    es_principal INTEGER DEFAULT 0,
    UNIQUE(proveedor_id, material_id)
);

CREATE TABLE IF NOT EXISTS clientes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    razon TEXT NOT NULL,
    cuit TEXT UNIQUE,
    iva TEXT,
    rubro TEXT,
    localidad TEXT,
    direccion TEXT,
    contacto TEXT,
    cargo TEXT,
    telefono TEXT,
    email TEXT,
    categoria TEXT DEFAULT 'Regular',
    plazo_pago TEXT,
    trabajos TEXT,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS proceso_operaciones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    producto_id INTEGER NOT NULL REFERENCES materiales(id) ON DELETE CASCADE,
    orden INTEGER DEFAULT 1,
    nombre TEXT NOT NULL,
    descripcion TEXT,
    categoria_maquina_id INTEGER REFERENCES categorias_maquina(id),
    maquina_id INTEGER REFERENCES maquinas(id),
    tiempo_setup_min INTEGER DEFAULT 0,
    tiempo_ciclo_seg REAL DEFAULT 0,
    es_tercerizada INTEGER DEFAULT 0,
    proveedor_id INTEGER REFERENCES proveedores(id),
    precio_tercerizado REAL DEFAULT 0,
    tiempo_minimo_dias INTEGER DEFAULT 0,
    obs TEXT,
    volumen_agrupado INTEGER DEFAULT 0,
    valor_recalculado REAL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS operacion_materiales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    operacion_id INTEGER NOT NULL REFERENCES proceso_operaciones(id) ON DELETE CASCADE,
    material_id INTEGER REFERENCES materiales(id),
    producto_id INTEGER REFERENCES materiales(id),
    cantidad REAL NOT NULL,
    unidad TEXT,
    tipo TEXT DEFAULT 'material',
    vida_util_herramienta INTEGER
);

CREATE TABLE IF NOT EXISTS ordenes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    cliente_id INTEGER REFERENCES clientes(id),
    producto_id INTEGER REFERENCES materiales(id),
    descripcion TEXT NOT NULL,
    detalle TEXT,
    cantidad REAL DEFAULT 1,
    operario TEXT,
    maquina TEXT,
    prioridad TEXT DEFAULT 'Normal',
    estado TEXT DEFAULT 'Pendiente',
    fecha_inicio TEXT,
    fecha_entrega TEXT,
    costo_mat REAL DEFAULT 0,
    costo_mo REAL DEFAULT 0,
    precio_venta REAL DEFAULT 0,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    actualizado TEXT DEFAULT (datetime('now','localtime')),
    stock_descontado INTEGER DEFAULT 0,
    requiere_material INTEGER DEFAULT 1
);

-- Pedidos de cotización que llegan de clientes (pestaña dentro de
-- Presupuestos). Un pedido = un producto terminado, una cantidad y el precio
-- total por esa cantidad; el unitario se deriva en pantalla.
CREATE TABLE IF NOT EXISTS pedidos_cotizacion (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    fecha TEXT NOT NULL DEFAULT (date('now','localtime')),
    cliente_id INTEGER NOT NULL REFERENCES clientes(id),
    producto_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad REAL NOT NULL CHECK(cantidad > 0),
    precio_total REAL,
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime'))
);

-- Cajones: piezas físicas de una OT agrupadas desde la 1ª operación hasta que
-- Calidad las libera (numero = cajon-<código de la pieza>-NNN, nunca se
-- reutiliza: un cajón no se borra, pasa a Baja). Lo que hizo cada paso en
-- cada cajón queda en novedad_cajones (operaciones internas) y ott_cajones
-- (tercerizadas); lo que salió por remito, en remito_item_cajones.
CREATE TABLE IF NOT EXISTS cajones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    orden_id INTEGER NOT NULL REFERENCES ordenes(id),
    orden_origen_id INTEGER REFERENCES ordenes(id),
    producto_id INTEGER NOT NULL REFERENCES materiales(id),
    lote_id INTEGER REFERENCES lotes(id),
    capacidad INTEGER NOT NULL,
    cantidad REAL NOT NULL DEFAULT 0,
    cantidad_liberada REAL NOT NULL DEFAULT 0,
    cantidad_rechazada REAL NOT NULL DEFAULT 0,
    cantidad_remitida REAL NOT NULL DEFAULT 0,
    estado TEXT NOT NULL DEFAULT 'En proceso',
    calidad_por INTEGER REFERENCES usuarios(id),
    calidad_fecha TEXT,
    calidad_obs TEXT,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);
CREATE INDEX IF NOT EXISTS idx_cajones_orden ON cajones(orden_id);
CREATE INDEX IF NOT EXISTS idx_cajones_lote ON cajones(lote_id);

CREATE TABLE IF NOT EXISTS novedad_cajones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    novedad_id INTEGER NOT NULL REFERENCES novedades_produccion(id) ON DELETE CASCADE,
    cajon_id INTEGER NOT NULL REFERENCES cajones(id),
    cantidad REAL NOT NULL CHECK(cantidad > 0),
    UNIQUE(novedad_id, cajon_id)
);
CREATE INDEX IF NOT EXISTS idx_novedad_cajones_cajon ON novedad_cajones(cajon_id);

CREATE TABLE IF NOT EXISTS ott_cajones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_operacion_id INTEGER NOT NULL REFERENCES orden_operaciones(id) ON DELETE CASCADE,
    cajon_id INTEGER NOT NULL REFERENCES cajones(id),
    cantidad REAL NOT NULL CHECK(cantidad > 0),
    UNIQUE(orden_operacion_id, cajon_id)
);
CREATE INDEX IF NOT EXISTS idx_ott_cajones_cajon ON ott_cajones(cajon_id);

CREATE TABLE IF NOT EXISTS remito_item_cajones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    remito_item_id INTEGER NOT NULL REFERENCES remito_items(id) ON DELETE CASCADE,
    cajon_id INTEGER NOT NULL REFERENCES cajones(id),
    cantidad REAL NOT NULL CHECK(cantidad > 0)
);
CREATE INDEX IF NOT EXISTS idx_remito_item_cajones_cajon ON remito_item_cajones(cajon_id);

CREATE TABLE IF NOT EXISTS presupuestos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    cliente_id INTEGER REFERENCES clientes(id),
    descripcion TEXT NOT NULL,
    items TEXT,
    subtotal REAL DEFAULT 0,
    iva_pct REAL DEFAULT 21,
    total REAL DEFAULT 0,
    validez_dias INTEGER DEFAULT 30,
    estado TEXT DEFAULT 'Borrador',
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS lotes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    material_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad_original REAL NOT NULL,
    cantidad_disponible REAL NOT NULL,
    cantidad_activa REAL DEFAULT 0,
    cantidad_rechazada REAL DEFAULT 0,
    cantidad_reservada REAL DEFAULT 0,
    proveedor_id INTEGER REFERENCES proveedores(id),
    fecha_ingreso TEXT DEFAULT (datetime('now','localtime')),
    referencia_proveedor TEXT,
    certificado TEXT,
    estado TEXT DEFAULT 'Ingresado' CHECK(estado IN ('Ingresado','Abierto','Aprobado','Agotado','Rechazado')),
    obs TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime')),
    stock_computado INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS remitos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    cliente_id INTEGER REFERENCES clientes(id),
    orden_cliente_id INTEGER REFERENCES ordenes_cliente(id),
    fecha TEXT DEFAULT (datetime('now','localtime')),
    estado TEXT DEFAULT 'Emitido',
    obs TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime')),
    tipo TEXT DEFAULT 'entrega_cliente',
    ott_id INTEGER REFERENCES ordenes_tercerizado(id),
    oc_id INTEGER REFERENCES ordenes_compra(id),
    ott_cantidad REAL
);

CREATE TABLE IF NOT EXISTS remito_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    remito_id INTEGER NOT NULL REFERENCES remitos(id) ON DELETE CASCADE,
    material_id INTEGER NOT NULL REFERENCES materiales(id),
    lote_id INTEGER NOT NULL REFERENCES lotes(id),
    orden_cliente_item_id INTEGER REFERENCES ordenes_cliente_items(id),
    cantidad REAL NOT NULL,
    obs TEXT
);

CREATE TABLE IF NOT EXISTS orden_lotes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_id INTEGER NOT NULL REFERENCES ordenes(id) ON DELETE CASCADE,
    lote_id INTEGER NOT NULL REFERENCES lotes(id),
    material_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad_usada REAL NOT NULL,
    fecha TEXT DEFAULT (datetime('now','localtime')),
    cantidad_consumida REAL DEFAULT 0,
    UNIQUE(orden_id, lote_id)
);

CREATE TABLE IF NOT EXISTS movimientos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    material_id INTEGER REFERENCES materiales(id),
    lote_id INTEGER REFERENCES lotes(id),
    tipo TEXT NOT NULL,
    cantidad REAL NOT NULL,
    referencia TEXT,
    usuario_id INTEGER REFERENCES usuarios(id),
    fecha TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS recepciones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    material_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad REAL NOT NULL,
    proveedor_id INTEGER REFERENCES proveedores(id),
    remito TEXT,
    precio_unit REAL,
    lote_id INTEGER REFERENCES lotes(id),
    obs TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    fecha TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS producto_clientes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    producto_id INTEGER NOT NULL REFERENCES materiales(id) ON DELETE CASCADE,
    cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,
    UNIQUE(producto_id, cliente_id)
);

CREATE TABLE IF NOT EXISTS orden_operaciones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_id INTEGER NOT NULL REFERENCES ordenes(id) ON DELETE CASCADE,
    proceso_op_id INTEGER REFERENCES proceso_operaciones(id),
    orden INTEGER DEFAULT 1,
    nombre TEXT NOT NULL,
    categoria_maquina_id INTEGER REFERENCES categorias_maquina(id),
    maquina_id INTEGER REFERENCES maquinas(id),
    tiempo_setup_min INTEGER DEFAULT 0,
    tiempo_ciclo_seg REAL DEFAULT 0,
    estado TEXT DEFAULT 'Pendiente',
    qty_requerida REAL DEFAULT 0,
    qty_producida REAL DEFAULT 0,
    es_tercerizada INTEGER DEFAULT 0,
    proveedor_id INTEGER REFERENCES proveedores(id),
    precio_tercerizado REAL DEFAULT 0,
    tiempo_minimo_dias INTEGER DEFAULT 0
);

-- Scheduling de producción: cada renglón es un bloque de trabajo (una jornada
-- de 9 o 12 h) de una operación de OT en una máquina, con su operario.
CREATE TABLE IF NOT EXISTS planificacion (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_operacion_id INTEGER NOT NULL REFERENCES orden_operaciones(id) ON DELETE CASCADE,
    maquina_id INTEGER NOT NULL REFERENCES maquinas(id),
    empleado_id INTEGER REFERENCES empleados(id) ON DELETE SET NULL,
    inicio TEXT NOT NULL,
    fin TEXT NOT NULL,
    jornada_horas INTEGER DEFAULT 9,
    cantidad_plan REAL DEFAULT 0,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);
CREATE INDEX IF NOT EXISTS idx_planif_maq ON planificacion(maquina_id, inicio);
CREATE INDEX IF NOT EXISTS idx_planif_emp ON planificacion(empleado_id, inicio);
CREATE INDEX IF NOT EXISTS idx_planif_op ON planificacion(orden_operacion_id);

CREATE TABLE IF NOT EXISTS orden_materiales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_id INTEGER NOT NULL REFERENCES ordenes(id) ON DELETE CASCADE,
    material_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad_requerida REAL DEFAULT 0,
    cantidad_asignada REAL DEFAULT 0,
    unidad TEXT
);

CREATE TABLE IF NOT EXISTS empleados (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    legajo TEXT UNIQUE NOT NULL,
    nombre TEXT NOT NULL,
    apellido TEXT,
    cargo TEXT,
    tipo TEXT DEFAULT 'Indirecto',
    turno TEXT,
    activo INTEGER DEFAULT 1,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    fecha_alta TEXT,
    fecha_baja TEXT
);

CREATE TABLE IF NOT EXISTS empleado_maquinas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    empleado_id INTEGER NOT NULL REFERENCES empleados(id) ON DELETE CASCADE,
    categoria_maquina_id INTEGER NOT NULL REFERENCES categorias_maquina(id) ON DELETE CASCADE,
    UNIQUE(empleado_id, categoria_maquina_id)
);

CREATE TABLE IF NOT EXISTS ordenes_cliente (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    cliente_id INTEGER NOT NULL REFERENCES clientes(id),
    fecha TEXT DEFAULT (datetime('now','localtime')),
    fecha_entrega TEXT,
    estado TEXT DEFAULT 'Recibida',
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS ordenes_cliente_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_cliente_id INTEGER NOT NULL REFERENCES ordenes_cliente(id) ON DELETE CASCADE,
    producto_id INTEGER NOT NULL REFERENCES materiales(id),
    cantidad REAL NOT NULL,
    precio_unit REAL DEFAULT 0,
    fecha_deseada TEXT,
    ot_id INTEGER REFERENCES ordenes(id),
    obs TEXT
);

CREATE TABLE IF NOT EXISTS orden_cliente_item_ots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    item_id INTEGER NOT NULL REFERENCES ordenes_cliente_items(id) ON DELETE CASCADE,
    ot_id INTEGER NOT NULL REFERENCES ordenes(id),
    creado TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(item_id, ot_id)
);

CREATE TABLE IF NOT EXISTS novedades_produccion (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    orden_id INTEGER NOT NULL REFERENCES ordenes(id),
    orden_operacion_id INTEGER NOT NULL REFERENCES orden_operaciones(id),
    empleado_id INTEGER REFERENCES empleados(id),
    cantidad_producida REAL NOT NULL,
    tiempo_real_min REAL NOT NULL,
    turno TEXT,
    fecha TEXT DEFAULT (datetime('now','localtime')),
    rendimiento_pct REAL DEFAULT 0,
    desvio INTEGER DEFAULT 0,
    obs TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    maquina_id INTEGER REFERENCES maquinas(id),
    piezas_observadas REAL DEFAULT 0,
    tiempo_perdido REAL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS novedades_eliminadas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    novedad_numero TEXT NOT NULL,
    orden_id INTEGER,
    orden_numero TEXT,
    orden_operacion_id INTEGER,
    operacion_nombre TEXT,
    producto_id INTEGER,
    producto_nombre TEXT,
    empleado_id INTEGER,
    empleado_nombre TEXT,
    maquina_id INTEGER,
    maquina_nombre TEXT,
    cantidad_producida REAL,
    piezas_observadas REAL,
    tiempo_real_min REAL,
    tiempo_perdido REAL,
    turno TEXT,
    fecha_novedad TEXT,
    rendimiento_pct REAL,
    obs TEXT,
    novedad_creado_por INTEGER,
    novedad_creado_por_nombre TEXT,
    detalle_json TEXT,
    eliminado_por INTEGER REFERENCES usuarios(id),
    eliminado_por_nombre TEXT,
    eliminado TEXT DEFAULT (datetime('now','localtime')),
    restaurado TEXT,
    restaurado_por INTEGER REFERENCES usuarios(id),
    restaurado_por_nombre TEXT
);

CREATE TABLE IF NOT EXISTS trabajo_no_productivo (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    empleado_id INTEGER REFERENCES empleados(id),
    descripcion TEXT NOT NULL,
    tiempo_min REAL NOT NULL,
    fecha TEXT DEFAULT (datetime('now','localtime')),
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS solicitudes_compra (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    tipo TEXT DEFAULT 'Productiva' CHECK(tipo IN ('Productiva','Indirecta')),
    material_id INTEGER REFERENCES materiales(id),
    descripcion TEXT NOT NULL,
    cantidad REAL NOT NULL,
    unidad TEXT,
    urgencia TEXT DEFAULT 'Normal',
    estado TEXT DEFAULT 'Pendiente',
    ot_origen_id INTEGER REFERENCES ordenes(id),
    centro_costo TEXT,
    solicitante_id INTEGER REFERENCES usuarios(id),
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    ott_id INTEGER REFERENCES ordenes_tercerizado(id),
    ott_remito TEXT
);

CREATE TABLE IF NOT EXISTS cotizaciones_compra (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    solicitud_id INTEGER NOT NULL REFERENCES solicitudes_compra(id) ON DELETE CASCADE,
    proveedor_id INTEGER NOT NULL REFERENCES proveedores(id),
    precio_unit REAL NOT NULL,
    plazo_entrega_dias INTEGER DEFAULT 3,
    condicion_pago TEXT,
    seleccionada INTEGER DEFAULT 0,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS ordenes_compra (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    proveedor_id INTEGER NOT NULL REFERENCES proveedores(id),
    estado TEXT DEFAULT 'Borrador',
    monto_total REAL DEFAULT 0,
    limite_aprobacion REAL DEFAULT 50000,
    aprobado_por INTEGER REFERENCES usuarios(id),
    fecha_aprobacion TEXT,
    fecha_entrega_est TEXT,
    obs TEXT,
    creado_por INTEGER REFERENCES usuarios(id),
    creado TEXT DEFAULT (datetime('now','localtime')),
    remito_devolucion_id INTEGER REFERENCES remitos(id),
    remito_numero TEXT,
    fecha_completada TEXT,
    motivo_anulacion TEXT,
    fecha_anulada TEXT
);

CREATE TABLE IF NOT EXISTS ordenes_compra_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    oc_id INTEGER NOT NULL REFERENCES ordenes_compra(id) ON DELETE CASCADE,
    solicitud_id INTEGER REFERENCES solicitudes_compra(id),
    material_id INTEGER REFERENCES materiales(id),
    descripcion TEXT NOT NULL,
    cantidad REAL NOT NULL,
    cantidad_recibida REAL DEFAULT 0,
    precio_unit REAL NOT NULL,
    unidad TEXT,
    lote_id INTEGER REFERENCES lotes(id),
    cantidad_rechazada_devuelta REAL DEFAULT 0,
    cantidad_rechazada_reingresada REAL DEFAULT 0,
    fecha_recibida TEXT
);

CREATE TABLE IF NOT EXISTS pronosticos_venta (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo TEXT UNIQUE NOT NULL,
    estado TEXT NOT NULL DEFAULT 'Alta',
    fecha_emision TEXT NOT NULL,
    periodos INTEGER NOT NULL DEFAULT 3,
    creado TEXT DEFAULT (datetime('now','localtime')),
    cliente_id INTEGER REFERENCES clientes(id)
);

CREATE TABLE IF NOT EXISTS pronostico_venta_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    pronostico_id INTEGER NOT NULL REFERENCES pronosticos_venta(id) ON DELETE CASCADE,
    producto_id INTEGER NOT NULL REFERENCES materiales(id),
    mes TEXT NOT NULL,
    cantidad REAL NOT NULL DEFAULT 0,
    UNIQUE(pronostico_id, producto_id, mes)
);

CREATE TABLE IF NOT EXISTS pronostico_item_ots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    item_id INTEGER NOT NULL REFERENCES pronostico_venta_items(id) ON DELETE CASCADE,
    ot_id INTEGER NOT NULL REFERENCES ordenes(id),
    UNIQUE(item_id, ot_id)
);

CREATE TABLE IF NOT EXISTS requerimientos_productivos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT NOT NULL,
    cliente_id INTEGER REFERENCES clientes(id),
    codigo TEXT,
    material_proceso TEXT,
    provision TEXT,
    cantidad_pedida REAL NOT NULL DEFAULT 0,
    unidad TEXT,
    proveedor_id INTEGER REFERENCES proveedores(id),
    nro_oc_remito TEXT,
    f_pedido TEXT,
    f_necesidad TEXT,
    f_estimada TEXT,
    f_entrega TEXT,
    estado TEXT DEFAULT 'PROXIMO',
    cantidad_entregada REAL,
    remito TEXT,
    nro_factura TEXT,
    cumple_fecha INTEGER,
    cumple_cantidad INTEGER,
    cumple_calidad INTEGER,
    nro_icp TEXT,
    cant_no_conforme REAL,
    ubicacion_remito TEXT,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    origen_item_id INTEGER,
    ot_origen_id INTEGER REFERENCES ordenes(id),
    cantidad_aprobada REAL
);

-- Bitacora de auditoria: una fila por alta / modificacion / baja de datos.
-- La escribe la capa de conexion (ver _AuditConnection), no los controladores.
CREATE TABLE IF NOT EXISTS auditoria (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    fecha TEXT NOT NULL,
    origen TEXT NOT NULL,                -- 'usuario' | 'sistema'
    usuario_id INTEGER,                  -- NULL cuando origen='sistema'
    actor TEXT NOT NULL,                 -- nombre del usuario o del proceso
    entidad TEXT NOT NULL,               -- tabla afectada
    registro_id TEXT,                    -- clave primaria del registro afectado
    accion TEXT NOT NULL,                -- 'alta' | 'modificacion' | 'baja'
    ruta TEXT,                           -- endpoint que origino el cambio
    valores_antes TEXT,                  -- JSON (solo los campos que cambiaron)
    valores_despues TEXT                 -- JSON (solo los campos que cambiaron)
);
CREATE INDEX IF NOT EXISTS ix_auditoria_fecha ON auditoria(fecha);
CREATE INDEX IF NOT EXISTS ix_auditoria_entidad ON auditoria(entidad, registro_id);
CREATE INDEX IF NOT EXISTS ix_auditoria_actor ON auditoria(actor);

CREATE TABLE IF NOT EXISTS ordenes_tercerizado (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    numero TEXT UNIQUE NOT NULL,
    ot_origen_id INTEGER REFERENCES ordenes(id) ON DELETE SET NULL,
    operacion_id INTEGER REFERENCES orden_operaciones(id) ON DELETE SET NULL,
    proceso_op_id INTEGER REFERENCES proceso_operaciones(id),
    proveedor_id INTEGER REFERENCES proveedores(id),
    precio_acordado REAL DEFAULT 0,
    estado TEXT DEFAULT 'Pendiente' CHECK(estado IN ('Pendiente','Remito emitido','En proceso','Recibido','Completado','Cancelado')),
    es_ultimo_nivel INTEGER DEFAULT 0,
    remito_traslado_id INTEGER REFERENCES remitos(id),
    lote_retorno_id INTEGER REFERENCES lotes(id),
    fecha_envio TEXT,
    fecha_retorno_est TEXT,
    fecha_retorno_real TEXT,
    obs TEXT,
    creado TEXT DEFAULT (datetime('now','localtime')),
    creado_por INTEGER REFERENCES usuarios(id),
    cantidad_enviada REAL DEFAULT 0,
    cantidad_recibida REAL DEFAULT 0,
    cantidad_rechazada_devuelta REAL DEFAULT 0,
    remito_devolucion_id INTEGER REFERENCES remitos(id),
    material_se_id INTEGER REFERENCES materiales(id),
    cantidad_plan REAL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS herramientas_operacion (
    id INTEGER PRIMARY KEY,
    operacion_id INTEGER NOT NULL REFERENCES proceso_operaciones(id) ON DELETE CASCADE,
    orden INTEGER DEFAULT 1,
    nombre TEXT NOT NULL,
    descripcion TEXT,
    duracion_min REAL DEFAULT 0,
    unidad TEXT DEFAULT 'unid',
    cantidad REAL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS usuario_permisos (
    id INTEGER PRIMARY KEY,
    usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    clave TEXT NOT NULL,
    valor TEXT,
    UNIQUE(usuario_id, clave)
);

CREATE TABLE IF NOT EXISTS configuracion (
    clave TEXT PRIMARY KEY,
    valor TEXT,
    descripcion TEXT
);

CREATE TABLE IF NOT EXISTS roles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT UNIQUE NOT NULL,
    descripcion TEXT,
    base_rol TEXT NOT NULL,
    permisos TEXT DEFAULT '{}',
    es_sistema INTEGER DEFAULT 0,
    creado TEXT DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS orden_operacion_materiales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orden_operacion_id INTEGER NOT NULL REFERENCES orden_operaciones(id) ON DELETE CASCADE,
    material_id INTEGER REFERENCES materiales(id),
    producto_id INTEGER REFERENCES materiales(id),
    cantidad REAL DEFAULT 0,
    unidad TEXT,
    tipo TEXT DEFAULT 'material',
    vida_util_herramienta INTEGER
);
CREATE INDEX IF NOT EXISTS idx_ooom_oo ON orden_operacion_materiales(orden_operacion_id);

CREATE TABLE IF NOT EXISTS producto_versiones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    producto_id INTEGER NOT NULL REFERENCES materiales(id) ON DELETE CASCADE,
    version_num INTEGER NOT NULL DEFAULT 1,
    motivo TEXT,
    snapshot TEXT NOT NULL,
    creado_por TEXT,
    creado TEXT DEFAULT (datetime('now','localtime'))
);
"""

def _backfill_remitos_ott_cantidad(db):
    """Completa remitos.ott_cantidad en remitos de OTT emitidos antes de que
    existiera la columna. Fuentes, en orden: la SC generada por ese envío,
    los movimientos de salida que citan el remito, el "envío parcial: X" de
    la observación, y por último (si en la OTT queda un solo remito sin
    cantidad) lo enviado/devuelto de la OTT menos lo ya identificado."""
    import re
    pend = db.execute("""SELECT r.id, r.numero, r.tipo, r.obs, r.ott_id, ott.numero ott_numero
        FROM remitos r JOIN ordenes_tercerizado ott ON ott.id=r.ott_id
        WHERE r.tipo IN ('traslado_ott','devolucion_ott') AND r.ott_cantidad IS NULL""").fetchall()
    cols_rem = {c[1] for c in db.execute("PRAGMA table_info(remitos)")}
    for r in pend:
        cant = None
        if "cantidad_ott" in cols_rem:
            # Columna de una versión anterior, sin uso hoy pero con datos.
            v = db.execute("SELECT cantidad_ott FROM remitos WHERE id=?", (r["id"],)).fetchone()[0]
            if v: cant = v
        if cant is None and r["tipo"] == "traslado_ott":
            # La auditoría guarda cantidad_enviada antes/después de cada envío.
            try:
                import json as _json
                for a in db.execute("""SELECT valores_antes, valores_despues FROM auditoria
                        WHERE entidad='ordenes_tercerizado' AND registro_id=?
                        AND ruta LIKE '%/emitir_remito'""", (str(r["ott_id"]),)):
                    antes = _json.loads(a["valores_antes"] or "{}")
                    desp = _json.loads(a["valores_despues"] or "{}")
                    if desp.get("remito_traslado_id") == r["id"]:
                        delta = float(desp.get("cantidad_enviada") or 0) - float(antes.get("cantidad_enviada") or 0)
                        if delta > 0: cant = delta
                        break
            except Exception:
                pass
        if cant is None and r["tipo"] == "traslado_ott":
            sc = db.execute("""SELECT SUM(cantidad) FROM solicitudes_compra
                WHERE ott_id=? AND ott_remito=?""", (r["ott_id"], r["numero"])).fetchone()[0]
            if sc: cant = sc
            if cant is None:
                mov = db.execute("""SELECT SUM(cantidad) FROM movimientos WHERE tipo='salida'
                    AND (referencia=? OR referencia LIKE ?)""",
                    (f"Envío a tercerizado OTT {r['ott_numero']} — {r['numero']}",
                     f"Reenvío a tercerizado OTT {r['ott_numero']} — {r['numero']} (%")).fetchone()[0]
                if mov: cant = mov
            if cant is None:
                m = re.search(r"envío parcial:\s*([\d.]+)", r["obs"] or "")
                if m: cant = float(m.group(1))
        if cant is not None:
            db.execute("UPDATE remitos SET ott_cantidad=? WHERE id=?", (cant, r["id"]))
    # Un único remito sin cantidad en la OTT: se deduce del total de la OTT.
    for tipo, col in (("traslado_ott", "cantidad_enviada"), ("devolucion_ott", "cantidad_rechazada_devuelta")):
        for o in db.execute(f"""SELECT r.ott_id, ott.{col} total,
                SUM(r.ott_cantidad IS NULL) sin_cant, COALESCE(SUM(r.ott_cantidad),0) conocida
            FROM remitos r JOIN ordenes_tercerizado ott ON ott.id=r.ott_id
            WHERE r.tipo=? GROUP BY r.ott_id""", (tipo,)).fetchall():
            resto = float(o["total"] or 0) - float(o["conocida"] or 0)
            if o["sin_cant"] == 1 and resto > 0.0001:
                db.execute("""UPDATE remitos SET ott_cantidad=?
                    WHERE ott_id=? AND tipo=? AND ott_cantidad IS NULL""", (resto, o["ott_id"], tipo))
    db.commit()

# ── Versión del esquema ───────────────────────────────────────────────────────
# SCHEMA (arriba) describe la base completa tal como la usa este código: una
# instalación nueva se crea directamente así, sin migraciones. La versión de
# cada base queda guardada en PRAGMA user_version.
#
# Para cambiar el esquema más adelante:
#   1. Agregar la tabla o columna en SCHEMA (para las instalaciones nuevas).
#   2. Agregar en MIGRACIONES una función con el número siguiente que haga el
#      mismo cambio sobre una base existente (por ejemplo un ALTER TABLE).
#   3. Subir ESQUEMA_VERSION a ese número.
# Cada migración corre una sola vez por base.
ESQUEMA_VERSION = 4


def _agregar_columna(db, tabla, columna, tipo):
    """ALTER TABLE ADD COLUMN solo si la columna no existe (idempotente)."""
    if columna not in {r[1] for r in db.execute(f"PRAGMA table_info({tabla})")}:
        db.execute(f"ALTER TABLE {tabla} ADD COLUMN {columna} {tipo}")


def _crear_tabla_de_schema(db, tabla):
    """Crea `tabla` (con sus índices) tal como está escrita en SCHEMA, solo si
    todavía no existe (idempotente). Evita repetir el CREATE TABLE."""
    if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (tabla,)).fetchone():
        return
    ref = sqlite3.connect(":memory:")
    ref.executescript(SCHEMA)
    for (sql,) in ref.execute("""SELECT sql FROM sqlite_master
            WHERE tbl_name=? AND sql IS NOT NULL ORDER BY type='index'""", (tabla,)).fetchall():
        db.execute(sql)
    ref.close()


def _migracion_2(db):
    # Vida útil de herramienta (piezas que hace cada una), en la plantilla
    # del proceso y en la copia propia de cada OT.
    _agregar_columna(db, "operacion_materiales", "vida_util_herramienta", "INTEGER")
    _agregar_columna(db, "orden_operacion_materiales", "vida_util_herramienta", "INTEGER")


def _migracion_4(db):
    # Cajones y su trazabilidad por paso, calidad y remito.
    for tabla in ("cajones", "novedad_cajones", "ott_cajones", "remito_item_cajones"):
        _crear_tabla_de_schema(db, tabla)


MIGRACIONES = {
    2: _migracion_2,
    3: lambda db: _crear_tabla_de_schema(db, "pedidos_cotizacion"),
    4: _migracion_4,
}


def _verificar_base_sin_version(db):
    """Base con datos pero sin versión (user_version=0): viene de antes de que
    existiera el versionado, cuando las migraciones corrían todas en cada
    arranque. Si ya tiene todas las tablas y columnas del SCHEMA actual (el
    caso normal: se venía actualizando), se la toma como versión 1. Si le falta
    algo es una base más vieja que este server.py ya no sabe migrar, y se corta
    el arranque sin tocarla."""
    ref = sqlite3.connect(":memory:")
    ref.executescript(SCHEMA)
    faltan = []
    for nombre, tipo in ref.execute("""SELECT name, type FROM sqlite_master
            WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%'""").fetchall():
        fila = db.execute("SELECT type FROM sqlite_master WHERE name=?", (nombre,)).fetchone()
        if not fila or fila[0] != tipo:
            faltan.append(f"{tipo} {nombre}")
        elif tipo == "table":
            cols = {r[1] for r in db.execute(f"PRAGMA table_info({nombre})")}
            faltan += [f"{nombre}.{r[1]}" for r in ref.execute(f"PRAGMA table_info({nombre})")
                       if r[1] not in cols]
    ref.close()
    if faltan:
        db.close()
        raise SystemExit(
            "La base de datos es de una versión anterior de MetalERP. Le falta: "
            + ", ".join(faltan[:10]) + (" ..." if len(faltan) > 10 else "") + ".\n"
            "Para actualizarla, arrancá UNA vez con un server.py anterior (un "
            "server.py.bak_* que todavía tenga las migraciones viejas, junto con "
            "migracion_unificacion.py) y después volvé a este. La base no se tocó.")


# ── Arranque de la base ───────────────────────────────────────────────────────
def init_db():
    os.makedirs(os.path.dirname(DB_PATH), exist_ok=True)
    db = sqlite3.connect(DB_PATH)
    db.row_factory = sqlite3.Row

    nueva = not db.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='usuarios'").fetchone()
    if nueva:
        db.executescript(SCHEMA)
        db.execute(f"PRAGMA user_version = {ESQUEMA_VERSION}")
    else:
        version = db.execute("PRAGMA user_version").fetchone()[0]
        if version == 0:
            _verificar_base_sin_version(db)
            version = 1
        for v in range(version + 1, ESQUEMA_VERSION + 1):
            MIGRACIONES[v](db)
            db.execute(f"PRAGMA user_version = {v}")
            db.commit()
        db.execute(f"PRAGMA user_version = {max(version, ESQUEMA_VERSION)}")
        # Crea lo que falte (todo es IF NOT EXISTS: no toca lo que ya existe).
        db.executescript(SCHEMA)

    # ── Datos iniciales ──────────────────────────────────────────────────────
    if db.execute("SELECT COUNT(*) FROM usuarios").fetchone()[0] == 0:
        db.execute("INSERT INTO usuarios (username,password,nombre,rol) VALUES (?,?,?,?)",
            ("admin", hash_pw("admin123"), "Administrador", "admin"))

    # Configuración por defecto (INSERT OR IGNORE: no pisa lo ya cargado).
    _cfg_defaults = [
        ('empresa_nombre',      'Mecanizado Ituzaingo',    'Nombre del taller / empresa'),
        ('empresa_subtitulo',   'Taller de Mecanizados', 'Subtítulo o rubro'),
        ('empresa_direccion',   '',                   'Dirección'),
        ('empresa_telefono',    '',                   'Teléfono / WhatsApp'),
        ('empresa_email',       '',                   'Email'),
        ('pdf_color_hex',       '2C5F8A',             'Color principal PDF (hex sin #)'),
        ('pdf_mostrar_costos',  '0',                  'Mostrar costos en PDF (0/1)'),
        ('pdf_mostrar_precios', '0',                  'Mostrar precio de venta en PDF (0/1)'),
        ('pdf_nota_pie',        '',                   'Nota al pie del PDF de OT'),
        ('valor_hora_mo',       '0',                  'Valor de mano de obra por hora ($)'),
        ('sc_automaticas',      '0',                  'Generar Solicitudes de Compra automáticamente (0/1)'),
    ]
    for _k, _v, _d in _cfg_defaults:
        db.execute("INSERT OR IGNORE INTO configuracion (clave,valor,descripcion) VALUES (?,?,?)",
                   (_k, _v, _d))

    # Roles del sistema (los demás se administran desde Configuración).
    for _rn, _desc in (("admin","Administrador — acceso total"),
                       ("operario","Producción — órdenes de trabajo, procesos, novedades"),
                       ("vendedor","Comercial — clientes, presupuestos, pedidos, compras"),
                       ("almacen","Almacén — inventario, lotes, recepción"),
                       ("logistica","Logística — remitos y stock, sin valores monetarios")):
        db.execute("INSERT OR IGNORE INTO roles (nombre,descripcion,base_rol,permisos,es_sistema) VALUES (?,?,?,?,1)",
                   (_rn, _desc, _rn, _json.dumps(DEFAULT_PERMISIONES.get(_rn, {}))))

    _reparar_datos_al_arrancar(db)
    db.close()


def _reparar_datos_al_arrancar(db):
    """Correcciones de datos que corren en cada arranque. No cambian el
    esquema: completan o corrigen filas que quedaron mal por errores ya
    arreglados. Todas son idempotentes (si no hay nada que corregir, no
    hacen nada)."""

    # Vínculos OC-item -> OT: volcar los que estén en la columna vieja
    # ot_id (de a uno por ítem) a la tabla orden_cliente_item_ots, que ahora
    # permite vincular varias OTs por ítem (repartiendo la cantidad pedida
    # entre varias OTs del mismo material/producto).
    for row in db.execute("""SELECT id,ot_id FROM ordenes_cliente_items
            WHERE ot_id IS NOT NULL AND ot_id NOT IN
            (SELECT ot_id FROM orden_cliente_item_ots WHERE item_id=ordenes_cliente_items.id)""").fetchall():
        try:
            db.execute("INSERT OR IGNORE INTO orden_cliente_item_ots (item_id,ot_id) VALUES (?,?)",
                       (row["id"], row["ot_id"]))
        except Exception:
            pass

    # Reparación: vincular OTs generadas por MRP (antes del fix) a los renglones
    # de OC que quedaron con ot_id NULL, siempre que el cruce producto+cliente
    # sea inequívoco (una sola OT candidata, no usada ya por otro renglón).
    try:
        huerfanos = db.execute("""
            SELECT i.id item_id, i.producto_id, oc.cliente_id
            FROM ordenes_cliente_items i
            JOIN ordenes_cliente oc ON oc.id=i.orden_cliente_id
            WHERE (i.ot_id IS NULL OR i.ot_id=0) AND oc.estado != 'Pendiente'
        """).fetchall()
        for h in huerfanos:
            candidatas = db.execute("""
                SELECT o.id FROM ordenes o
                WHERE o.producto_id=? AND o.cliente_id=?
                AND o.id NOT IN (SELECT ot_id FROM ordenes_cliente_items WHERE ot_id IS NOT NULL)
                AND o.id NOT IN (SELECT ot_id FROM orden_cliente_item_ots)
            """, (h["producto_id"], h["cliente_id"])).fetchall()
            if len(candidatas) == 1:
                db.execute("UPDATE ordenes_cliente_items SET ot_id=? WHERE id=?",
                           (candidatas[0]["id"], h["item_id"]))
                db.execute("INSERT OR IGNORE INTO orden_cliente_item_ots (item_id,ot_id) VALUES (?,?)",
                           (h["item_id"], candidatas[0]["id"]))
    except Exception:
        pass

    try:
        _backfill_remitos_ott_cantidad(db)
    except Exception as e:
        print("[remitos] no se pudo completar ott_cantidad de remitos viejos:", e)
    try:
        # Backfill: los requerimientos de compra ya creados con el esquema
        # viejo tienen numero="OCP-ITEM-{item_id}" y origen_item_id NULL. Se
        # completa origen_item_id a partir de ese numero para que el sync los
        # siga encontrando (y no duplique) aunque más adelante se les asigne
        # un numero correlativo nuevo.
        db.execute("""UPDATE requerimientos_productivos
            SET origen_item_id = CAST(SUBSTR(numero, 10) AS INTEGER)
            WHERE numero LIKE 'OCP-ITEM-%' AND origen_item_id IS NULL""")
    except Exception: pass
    try:
        # Backfill: antes, cantidad_original de un lote generado por retorno
        # de OTT (ver ott_registrar_retorno) se iba SUMANDO en cada recepción
        # parcial, sin bajar nunca al devolver piezas rechazadas — un ciclo
        # de rechazo → devolución → reingreso del reemplazo terminaba
        # inflando el original más allá de lo realmente enviado (ver fix en
        # ott_registrar_retorno). Se corrige una sola vez: para todo lote de
        # retorno de OTT cuyo original quedó por encima de lo enviado, se
        # baja a cantidad_enviada.
        db.execute("""UPDATE lotes SET cantidad_original=(
                SELECT ott.cantidad_enviada FROM ordenes_tercerizado ott WHERE ott.lote_retorno_id=lotes.id
            )
            WHERE id IN (
                SELECT ott.lote_retorno_id FROM ordenes_tercerizado ott
                WHERE ott.lote_retorno_id IS NOT NULL AND COALESCE(ott.cantidad_enviada,0) > 0
                  AND (SELECT l2.cantidad_original FROM lotes l2 WHERE l2.id=ott.lote_retorno_id) > ott.cantidad_enviada
            )""")
    except Exception: pass

    # Backfill: filas viejas de "producto como insumo" (tipo='producto') que
    # quedaron con material_id NULL — de antes de que estas filas se
    # resolvieran al material 'Producto terminado' del producto al guardar
    # la operación (ver create_operacion/update_operacion). Sin material_id
    # estas filas quedaban afuera de toda la trazabilidad por lote (no
    # aparecían en "Lotes asignados", en el modal de novedad, ni se
    # descontaban del stock/lote al completar la OT). Se completan acá para
    # que las operaciones ya guardadas también queden con selección de lote.
    try:
        huerfanas = db.execute(
            "SELECT id, producto_id FROM operacion_materiales WHERE tipo='producto' AND material_id IS NULL AND producto_id IS NOT NULL"
        ).fetchall()
        for hr in huerfanas:
            prod_h = db.execute("SELECT id,codigo,nombre,unidad FROM productos WHERE id=?", (hr["producto_id"],)).fetchone()
            if not prod_h:
                continue
            # Réplica in-line de get_or_create_pt_material (acá no hay contexto
            # de Flask/g todavía para usar query()/execute()/esa función).
            mat_h = db.execute(
                "SELECT id FROM materiales WHERE producto_id=? AND categoria='Producto terminado'",
                (prod_h["id"],)).fetchone()
            if mat_h:
                mat_h_id = mat_h["id"]
            else:
                codigo_base = prod_h["codigo"]
                candidato = codigo_base
                intento = 1
                while db.execute("SELECT id FROM materiales WHERE codigo=?", (candidato,)).fetchone():
                    intento += 1
                    candidato = f"{codigo_base}-PT{intento}"
                cur_h = db.execute(
                    "INSERT INTO materiales (codigo,descripcion,categoria,producto_id,unidad,stock,stock_min) VALUES (?,?,?,?,?,0,0)",
                    (candidato, prod_h["nombre"], "Producto terminado", prod_h["id"], prod_h["unidad"]))
                mat_h_id = cur_h.lastrowid
            db.execute("UPDATE operacion_materiales SET material_id=? WHERE id=?", (mat_h_id, hr["id"]))
        if huerfanas:
            db.commit()
    except Exception as e:
        print(f"[init_db] Advertencia: no se pudo hacer backfill de operacion_materiales.material_id para tipo='producto': {e}")

    # Recalcular rendimiento de novedades existentes descontando tiempo_perdido
    try:
        novedades = db.execute(
            "SELECT n.id, n.cantidad_producida, n.tiempo_real_min, "
            "COALESCE(n.tiempo_perdido,0) tiempo_perdido, "
            "COALESCE(po.tiempo_ciclo_seg, oo.tiempo_ciclo_seg, 60) ciclo "
            "FROM novedades_produccion n "
            "JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id "
            "LEFT JOIN proceso_operaciones po ON po.id=oo.proceso_op_id"
        ).fetchall()
        for nov in novedades:
            # El ciclo estandar se carga en SEGUNDOS; tiempo_real_min esta en
            # minutos, asi que se pasa a minutos antes de comparar.
            ciclo  = float(nov["ciclo"] or 60) / 60.0
            qty    = float(nov["cantidad_producida"] or 0)
            t_real = float(nov["tiempo_real_min"] or 0)
            t_perd = float(nov["tiempo_perdido"] or 0)
            t_prod = max(t_real - t_perd, 0.1)
            if qty > 0 and t_prod > 0:
                rend = round((qty / t_prod) / (1 / ciclo) * 100, 1)
                rend = min(rend, 999)
                desv = 1 if rend < 80 else 0
                db.execute(
                    "UPDATE novedades_produccion SET rendimiento_pct=?, desvio=? WHERE id=?",
                    (rend, desv, nov["id"])
                )
    except Exception as e:
        print(f"[init_db] Advertencia al recalcular rendimiento: {e}")

    # Red de seguridad: topear cualquier rendimiento que haya quedado por
    # encima de 999 (incluidas novedades que no entraron en el recálculo
    # anterior, p.ej. por operación eliminada).
    try:
        db.execute("UPDATE novedades_produccion SET rendimiento_pct=999 WHERE rendimiento_pct>999")
    except Exception as e:
        print(f"[init_db] Advertencia al topear rendimiento: {e}")

    db.commit()  # liberar la transacción abierta por las correcciones de arriba:
                 # las de abajo usan get_db()/query(), que abren una conexión
                 # sqlite3 aparte; si 'db' sigue con una transacción sin
                 # confirmar, esa segunda conexión choca con "database is locked".

    # Reparación: OTTs intermedias cuyo lote de retorno ya está Aprobado
    # pero la orden_operacion tercerizada quedó sin marcarse Completada
    # (bug: faltaba la sincronización — ver _sync_ott_retorno_a_operacion).
    # Esto dejaba la OT pausada para siempre en operaciones posteriores.
    try:
        with app.app_context():
            pendientes = query("""SELECT lote_retorno_id FROM ordenes_tercerizado
                WHERE es_ultimo_nivel=0 AND lote_retorno_id IS NOT NULL""")
            for p in pendientes:
                _sync_ott_retorno_a_operacion(p["lote_retorno_id"])
    except Exception as e:
        print(f"[init_db] Advertencia reparando OTTs con lote aprobado: {e}")

    # Reparación: materiales de retorno de OTT intermedia (semielaborados)
    # que quedaron con categoria distinta a 'Semielaborado' porque
    # ott_registrar_retorno reutilizaba cualquier material existente con
    # el mismo producto_id sin filtrar por categoria (bug corregido). Un
    # material así puede tener MEZCLADOS lotes propios (p.ej. Producto
    # terminado real) con lotes de retorno de OTT. NO se puede arreglar
    # recategorizando el material entero (eso arrastra también el stock
    # ajeno) — hay que separar lote por lote: los vinculados a una OTT
    # (ordenes_tercerizado.lote_retorno_id) van a un material nuevo
    # 'Semielaborado' con código (código del producto)-SE; el resto se
    # queda donde estaba.
    try:
        with app.app_context():
            afectados = query("""
                SELECT DISTINCT m.id mat_id, m.codigo mat_codigo, pr.codigo prod_codigo,
                       pr.id producto_id, m.unidad, m.precio_unit
                FROM ordenes_tercerizado ott
                JOIN lotes l ON l.id=ott.lote_retorno_id
                JOIN materiales m ON m.id=l.material_id
                JOIN productos pr ON pr.id=m.producto_id
                WHERE ott.es_ultimo_nivel=0 AND m.categoria != 'Semielaborado'
            """)
            for m in afectados:
                lotes_ott_ids = {r["lote_retorno_id"] for r in query(
                    """SELECT lote_retorno_id FROM ordenes_tercerizado
                       WHERE lote_retorno_id IS NOT NULL
                         AND EXISTS (SELECT 1 FROM lotes l2 WHERE l2.id=ordenes_tercerizado.lote_retorno_id
                                     AND l2.material_id=?)""", (m["mat_id"],))}
                if not lotes_ott_ids:
                    continue
                nuevo_codigo = f"{m['prod_codigo']}-SE"
                candidato = nuevo_codigo
                intento = 1
                while query("SELECT id FROM materiales WHERE codigo=?", (candidato,), one=True):
                    intento += 1
                    candidato = f"{nuevo_codigo}{intento}"
                se_mat_id = execute("""INSERT INTO materiales
                    (codigo,descripcion,categoria,producto_id,unidad,stock,stock_min,precio_unit,activo)
                    SELECT ?, descripcion, 'Semielaborado', producto_id, unidad, 0, 0, precio_unit, 1
                    FROM materiales WHERE id=?""", (candidato, m["mat_id"]))
                lotes_a_mover = query(
                    f"SELECT id,cantidad_activa FROM lotes WHERE id IN "
                    f"({','.join('?'*len(lotes_ott_ids))})", tuple(lotes_ott_ids))
                total_mover = sum(float(l["cantidad_activa"] or 0) for l in lotes_a_mover)
                execute(f"UPDATE lotes SET material_id=? WHERE id IN "
                        f"({','.join('?'*len(lotes_ott_ids))})",
                        (se_mat_id, *lotes_ott_ids))
                execute("UPDATE materiales SET stock=stock-? WHERE id=?", (total_mover, m["mat_id"]))
                execute("UPDATE materiales SET stock=stock+? WHERE id=?", (total_mover, se_mat_id))
                print(f"[init_db] Separados {len(lotes_ott_ids)} lote(s) de retorno OTT "
                      f"({total_mover:g} unid.) del material id={m['mat_id']} ({m['mat_codigo']}) "
                      f"hacia material nuevo id={se_mat_id} ({candidato})")
    except Exception as e:
        print(f"[init_db] Advertencia reparando materiales semielaborados: {e}")

    # Backfill del versionado de semielaborados. Los que ya existen se quedan
    # con la firma que tienen HOY sus insumos: son la versión vigente, y así
    # _get_or_create_pse los reusa en vez de crear un -v2 de entrada para
    # todos. Las OTT que ya tienen lote de retorno se congelan al material de
    # ese lote, que es el que efectivamente están usando.
    try:
        with app.app_context():
            for m in query("""SELECT id, operacion_id FROM materiales
                    WHERE categoria='Semielaborado' AND operacion_id IS NOT NULL
                      AND pse_firma IS NULL"""):
                execute("UPDATE materiales SET pse_firma=? WHERE id=?",
                        (_firma_insumos_operacion(m["operacion_id"]), m["id"]))
            huerfanas = query("""SELECT ott.id, l.material_id
                FROM ordenes_tercerizado ott JOIN lotes l ON l.id=ott.lote_retorno_id
                WHERE ott.material_se_id IS NULL AND ott.es_ultimo_nivel=0""")
            for o in huerfanas:
                execute("UPDATE ordenes_tercerizado SET material_se_id=? WHERE id=?",
                        (o["material_id"], o["id"]))
            if huerfanas:
                print(f"[init_db] Semielaborado congelado en {len(huerfanas)} OTT(s) ya en curso")
    except Exception as e:
        print(f"[init_db] Advertencia en el backfill de semielaborados: {e}")

    # Reparación de la reparación anterior: una versión previa de esta
    # migración recategorizaba el material entero in-place a
    # 'Semielaborado' en vez de separar lotes, arrastrando también el
    # stock de lotes ajenos (p.ej. Producto terminado real) que
    # compartían el material. Acá se detectan esos materiales (codigo
    # terminado en "-SE", categoria 'Semielaborado') que todavía tengan
    # lotes NO vinculados a ninguna OTT, y se los separa hacia el
    # material original (o uno nuevo si no existe más).
    try:
        with app.app_context():
            se_materiales = query("""SELECT id, codigo, producto_id, unidad, precio_unit
                FROM materiales WHERE categoria='Semielaborado' AND codigo LIKE '%-SE'""")
            for m in se_materiales:
                lotes_ott_ids = {r["lote_retorno_id"] for r in query(
                    "SELECT lote_retorno_id FROM ordenes_tercerizado WHERE lote_retorno_id IS NOT NULL")}
                lotes_del_material = query(
                    "SELECT id,cantidad_activa FROM lotes WHERE material_id=?", (m["id"],))
                ajenos = [l for l in lotes_del_material if l["id"] not in lotes_ott_ids]
                if not ajenos:
                    continue
                codigo_original = m["codigo"][:-3]  # quita el sufijo "-SE"
                otro = query("SELECT id FROM materiales WHERE codigo=?", (codigo_original,), one=True)
                if otro:
                    destino_id = otro["id"]
                else:
                    destino_id = execute("""INSERT INTO materiales
                        (codigo,descripcion,categoria,producto_id,unidad,stock,stock_min,precio_unit,activo)
                        SELECT ?, descripcion, 'Producto terminado', producto_id, unidad, 0, stock_min, precio_unit, 1
                        FROM materiales WHERE id=?""", (codigo_original, m["id"]))
                total_mover = sum(float(l["cantidad_activa"] or 0) for l in ajenos)
                ph = ",".join("?"*len(ajenos))
                execute(f"UPDATE lotes SET material_id=? WHERE id IN ({ph})",
                        (destino_id, *[l["id"] for l in ajenos]))
                execute("UPDATE materiales SET stock=stock-? WHERE id=?", (total_mover, m["id"]))
                execute("UPDATE materiales SET stock=stock+? WHERE id=?", (total_mover, destino_id))
                print(f"[init_db] Separados {len(ajenos)} lote(s) ajenos ({total_mover:g} unid.) "
                      f"del material Semielaborado id={m['id']} hacia material id={destino_id} "
                      f"(codigo {codigo_original})")
    except Exception as e:
        print(f"[init_db] Advertencia separando lotes mezclados en semielaborados: {e}")

def _snapshot_producto(prod_id):
    """Genera un snapshot JSON del producto y sus operaciones/materiales actuales."""
    import json
    db = get_db()
    prod = db.execute("SELECT * FROM productos WHERE id=?", (prod_id,)).fetchone()
    if not prod:
        return None
    ops = db.execute(
        "SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden", (prod_id,)
    ).fetchall()
    ops_list = []
    for op in ops:
        op_d = dict(op)
        if op_d.get("categoria_maquina_id"):
            cm = db.execute("SELECT nombre FROM categorias_maquina WHERE id=?", (op_d["categoria_maquina_id"],)).fetchone()
            op_d["cat_maq_nombre"] = cm["nombre"] if cm else None
        mats = db.execute(
            """SELECT om.*,m.codigo mat_codigo,m.descripcion mat_descripcion,m.unidad mat_unidad
               FROM operacion_materiales om
               LEFT JOIN materiales m ON m.id=om.material_id
               WHERE om.operacion_id=?""", (op["id"],)
        ).fetchall()
        op_d["materiales"] = [dict(m) for m in mats]
        ops_list.append(op_d)
    snap = {"producto": dict(prod), "operaciones": ops_list}
    return json.dumps(snap, ensure_ascii=False)

def guardar_version_producto(prod_id, motivo=None, creado_por=None):
    """Guarda una versión/snapshot del proceso actual antes de modificarlo."""
    snap = _snapshot_producto(prod_id)
    if not snap:
        return
    # Obtener número de versión correlativo
    last = query(
        "SELECT COALESCE(MAX(version_num),0) n FROM producto_versiones WHERE producto_id=?",
        (prod_id,), one=True
    )
    next_num = (last["n"] if last else 0) + 1
    execute(
        "INSERT INTO producto_versiones (producto_id,version_num,motivo,snapshot,creado_por) VALUES (?,?,?,?,?)",
        (prod_id, next_num, motivo, snap, creado_por)
    )

# ── Auth ──────────────────────────────────────────────────────────────────────
@app.route("/login", methods=["GET","POST"])
def login():
    if request.method == "POST":
        d = request.get_json(silent=True) or request.form
        user = query("SELECT * FROM usuarios WHERE username=? AND activo=1", (d.get("username",""),), one=True)
        if user and user["password"] == hash_pw(d.get("password","")):
            session.update({"user_id":user["id"],"username":user["username"],"nombre":user["nombre"],
                            "rol":_rol_base(user["rol"]),"rol_nombre":user["rol"]})
            if request.is_json: return jsonify({"ok":True,"rol":_rol_base(user["rol"]),"rol_nombre":user["rol"],"nombre":user["nombre"]})
            return redirect("/")
        if request.is_json: return jsonify({"ok":False,"error":"Usuario o contraseña incorrectos"}), 401
    return render_template("login.html")

@app.route("/logout")
def logout(): session.clear(); return redirect("/login")

@app.route("/")
@login_required()
def index():
    uid = session["user_id"]
    perm_rows = query("SELECT clave, valor FROM usuario_permisos WHERE usuario_id=?", (uid,))
    perms = {r["clave"]: r["valor"] for r in perm_rows}
    
    # Si no hay permisos explícitos y no es admin, usar permisos predeterminados del rol
    if not perms and session.get("rol") != "admin":
        perms = _permisos_rol(session.get("rol_nombre") or session.get("rol", "operario"))
    
    ver_mon = puede_ver_monetario()
    # La plantilla recibe el permiso ya resuelto por el servidor; sacarlo de
    # perms evita que quede una segunda fuente de verdad en el navegador.
    perms = {k: v for k, v in perms.items() if k != "ver_monetario"}
    return render_template("app.html",
                          nombre=session["nombre"],
                          rol=session["rol"],
                          rol_nombre=session.get("rol_nombre") or session["rol"],
                          perms=perms,
                          ver_monetario=ver_mon)



# ── Dashboard operativo — rendimiento semanal ─────────────────────────────────
@app.route("/api/dashboard/rendimiento_semanal")
@login_required()
def dashboard_rendimiento_semanal():
    semanas = [dict(r) for r in query("""
        SELECT strftime('%Y-%W', fecha) semana,
               MIN(fecha) fecha_inicio,
               ROUND(AVG(rendimiento_pct),1) avg_rend,
               COUNT(*) novedades,
               ROUND(SUM(cantidad_producida),1) total_prod
        FROM novedades_produccion
        WHERE fecha >= date('now','-26 weeks')
        GROUP BY strftime('%Y-%W', fecha)
        ORDER BY semana""")]
    # Current week label
    import datetime
    hoy = datetime.date.today()
    semana_actual = hoy.strftime('%Y-%W')
    return jsonify({"semanas": semanas, "semana_actual": semana_actual})

# ── Dashboard económico — facturación por cliente por mes ─────────────────────
@app.route("/api/dashboard/facturacion_por_cliente")
@login_required()
@solo_con_monetario
def dashboard_facturacion_por_cliente():
    import datetime
    hoy = datetime.date.today()
    anio = hoy.year
    # Facturación pasada (presupuestos facturados)
    facturado = [dict(r) for r in query("""
        SELECT strftime('%Y-%m', p.creado) mes,
               c.razon cliente,
               ROUND(SUM(p.total),2) total
        FROM presupuestos p
        JOIN clientes c ON c.id=p.cliente_id
        WHERE p.estado='Facturado'
          AND strftime('%Y', p.creado)=?
        GROUP BY mes, c.id
        ORDER BY mes, c.razon""", (str(anio),))]
    # Pedidos futuros (OC confirmadas/en proceso con items sin facturar)
    pedidos = [dict(r) for r in query("""
        SELECT strftime('%Y-%m', COALESCE(i.fecha_deseada, oc.fecha_entrega, oc.creado)) mes,
               c.razon cliente,
               ROUND(SUM(i.cantidad * i.precio_unit),2) total
        FROM ordenes_cliente_items i
        JOIN ordenes_cliente oc ON oc.id=i.orden_cliente_id
        JOIN clientes c ON c.id=oc.cliente_id
        WHERE oc.estado IN ('Recibida','Confirmada','En proceso')
          AND strftime('%Y', COALESCE(i.fecha_deseada, oc.fecha_entrega, oc.creado))=?
        GROUP BY mes, c.id
        ORDER BY mes, c.razon""", (str(anio),))]
    # Ratio empleados
    emps = [dict(r) for r in query("""
        SELECT COALESCE(tipo,'Sin tipo') tipo, COUNT(*) cantidad
        FROM empleados WHERE activo=1 GROUP BY tipo ORDER BY cantidad DESC""")]
    return jsonify({
        "anio": anio,
        "mes_actual": hoy.strftime('%Y-%m'),
        "facturado": facturado,
        "pedidos": pedidos,
        "empleados": emps,
    })

