# ── Operaciones pendientes por sector (punto 19) ─────────────────────────────
@app.route("/api/operaciones_pendientes", methods=["GET"])
@login_required()
def get_operaciones_pendientes():
    """Renglones de operaciones Pendientes / En proceso de OTs Pendientes / En proceso.
    Filtro opcional por sector (categoria_maquina_id), maquina, estado y texto."""
    cat = request.args.get("categoria_id")
    estado = request.args.get("estado")
    q = (request.args.get("q") or "").strip()
    sql = """SELECT oo.id, oo.orden_id, oo.orden, oo.nombre operacion, oo.estado,
        oo.qty_requerida, oo.qty_producida, oo.es_tercerizada,
        oo.categoria_maquina_id, cm.nombre sector, oo.maquina_id, m.nombre maquina_nombre,
        o.numero ot_numero, o.prioridad, o.fecha_entrega, o.estado ot_estado,
        p.codigo producto_codigo, p.nombre producto_nombre, c.razon cliente_nombre,
        pr.razon proveedor_nombre
        FROM orden_operaciones oo
        JOIN ordenes o ON o.id=oo.orden_id
        LEFT JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
        LEFT JOIN maquinas m ON m.id=oo.maquina_id
        LEFT JOIN productos p ON p.id=o.producto_id
        LEFT JOIN clientes c ON c.id=o.cliente_id
        LEFT JOIN proveedores pr ON pr.id=oo.proveedor_id
        WHERE o.estado IN ('Pendiente','En proceso')
          AND (oo.estado IN ('Pendiente','En proceso') OR oo.qty_producida<oo.qty_requerida)
          AND oo.estado NOT IN ('Completada','Cancelada')"""
    args = []
    if cat == "terceros":
        sql += " AND oo.es_tercerizada=1"
    elif cat:
        sql += " AND oo.categoria_maquina_id=? AND COALESCE(oo.es_tercerizada,0)=0"
        args.append(cat)
    if estado:
        sql += " AND oo.estado=?"
        args.append(estado)
    if q:
        sql += " AND (o.numero LIKE ? OR oo.nombre LIKE ? OR p.nombre LIKE ? OR p.codigo LIKE ? OR c.razon LIKE ?)"
        args += [f"%{q}%"] * 5
    sql += " ORDER BY COALESCE(o.fecha_entrega,'9999'), o.id, CAST(oo.orden AS INTEGER)"
    rows = query(sql, tuple(args))
    return jsonify([dict(r) for r in rows])


# ── Scheduling de producción ─────────────────────────────────────────────────
# Gantt por máquina. Un "bloque" = una operación de OT, en una máquina, con un
# operario y una jornada de 9 o 12 horas. No modifica la OT ni sus operaciones:
# es solo la planificación; el avance real sigue yendo por Control de producción.
from datetime import datetime as _dt, timedelta as _td

_SCH_JORNADAS = (9, 12)
_SCH_FMT = "%Y-%m-%d %H:%M"


def _sch_parse(v):
    """Acepta 'YYYY-MM-DD HH:MM' o 'YYYY-MM-DDTHH:MM' (con o sin segundos)."""
    v = str(v or "").strip().replace("T", " ")[:16]
    try:
        return _dt.strptime(v, _SCH_FMT)
    except ValueError:
        return None


def _sch_corto(v):
    """'2026-10-14 06:00' -> '14/10 06:00' para los mensajes."""
    return f"{v[8:10]}/{v[5:7]} {v[11:16]}"


# Los bloques de OTs u operaciones cerradas quedan como historial en el Gantt,
# pero ya no ocupan la máquina ni al operario.
_SCH_ACTIVO = " AND o.estado NOT IN ('Completada','Cancelada') AND oo.estado NOT IN ('Completada','Cancelada')"


def _sch_ahora():
    return _dt.now().strftime(_SCH_FMT)


def _sch_qty_futura(oo_id):
    """Cantidad planificada en bloques que todavía no terminaron. Los bloques
    ya pasados no cuentan: lo que se hizo en ellos ya está en qty_producida."""
    r = query("SELECT COALESCE(SUM(cantidad_plan),0) q FROM planificacion WHERE orden_operacion_id=? AND fin>?",
              (oo_id, _sch_ahora()), one=True)
    return float(r["q"] or 0)


def _sch_disponible(oo_id, requerida, falta, excluir_bid=None):
    """Cuánto queda por planificar de una operación: lo que falta producir
    menos lo ya planificado a futuro en otros bloques. None si la operación
    no tiene cantidad requerida (no hay tope que controlar)."""
    if float(requerida or 0) <= 0:
        return None
    r = query("""SELECT COALESCE(SUM(cantidad_plan),0) q FROM planificacion
                 WHERE orden_operacion_id=? AND fin>? AND id<>?""",
              (oo_id, _sch_ahora(), excluir_bid or 0), one=True)
    return round(falta - float(r["q"] or 0), 6)


def _sch_tope_error(v, disponible):
    """Una operación planificada por completo no admite más planificación
    (sí la misma operación de otra OT, que es otra orden_operacion)."""
    if disponible is None:
        return None
    if disponible <= 0.0001:
        return (f"La operación {v['op_desc']} ya está planificada por completo. "
                "Para cambiarla, editá o eliminá sus bloques.")
    if v["qty"] > disponible + 0.0001:
        return (f"La operación {v['op_desc']} solo tiene {disponible:g} u sin planificar "
                f"(pediste {v['qty']:g} u).")
    return None


def _sch_bloque_sql():
    return """SELECT pl.id, pl.orden_operacion_id, pl.maquina_id, pl.empleado_id, pl.inicio, pl.fin,
        pl.jornada_horas, pl.cantidad_plan, pl.obs,
        TRIM(COALESCE(e.apellido,'')||' '||COALESCE(e.nombre,'')) empleado_nombre,
        oo.nombre operacion, oo.orden op_orden, oo.estado op_estado, oo.qty_requerida, oo.qty_producida,
        oo.categoria_maquina_id,
        o.id orden_id, o.numero ot_numero, o.prioridad, o.fecha_entrega, o.estado ot_estado,
        p.codigo producto_codigo, p.nombre producto_nombre, c.razon cliente_nombre
        FROM planificacion pl
        JOIN orden_operaciones oo ON oo.id=pl.orden_operacion_id
        JOIN ordenes o ON o.id=oo.orden_id
        LEFT JOIN empleados e ON e.id=pl.empleado_id
        LEFT JOIN productos p ON p.id=o.producto_id
        LEFT JOIN clientes c ON c.id=o.cliente_id"""


@app.route("/api/scheduling", methods=["GET"])
@login_required()
def sch_get():
    """Datos del Gantt: máquinas (recursos) + bloques que tocan la ventana pedida."""
    desde = request.args.get("desde") or _dt.now().strftime("%Y-%m-%d")
    try:
        dias = max(1, min(60, int(request.args.get("dias") or 7)))
        d0 = _dt.strptime(desde[:10], "%Y-%m-%d")
    except ValueError:
        return jsonify({"error": "Fecha o cantidad de días inválida"}), 400
    d1 = d0 + _td(days=dias)
    maqs = query("""SELECT m.id, m.codigo, m.nombre, m.estado, m.categoria_id,
                    COALESCE(cm.nombre,'Sin sector') grupo
                    FROM maquinas m LEFT JOIN categorias_maquina cm ON cm.id=m.categoria_id
                    ORDER BY COALESCE(cm.nombre,'~'), m.codigo""")
    bl = query(_sch_bloque_sql() + " WHERE pl.inicio < ? AND pl.fin > ? ORDER BY pl.inicio",
               (d1.strftime(_SCH_FMT), d0.strftime(_SCH_FMT)))
    return jsonify({"desde": d0.strftime("%Y-%m-%d"), "dias": dias,
                    "maquinas": [dict(x) for x in maqs], "bloques": [dict(x) for x in bl]})


@app.route("/api/scheduling/pendientes", methods=["GET"])
@login_required()
def sch_pendientes():
    """Operaciones de OTs Pendientes / En proceso (no tercerizadas) con lo ya planificado."""
    rows = query("""SELECT oo.id, oo.orden_id, oo.orden, oo.nombre operacion, oo.estado,
        oo.qty_requerida, oo.qty_producida, oo.categoria_maquina_id, cm.nombre sector,
        oo.maquina_id, COALESCE(oo.tiempo_setup_min,0) setup_min, COALESCE(oo.tiempo_ciclo_seg,0) ciclo_seg,
        o.numero ot_numero, o.prioridad, o.fecha_entrega, o.estado ot_estado,
        p.codigo producto_codigo, p.nombre producto_nombre, c.razon cliente_nombre,
        (SELECT COALESCE(SUM(pl.cantidad_plan),0) FROM planificacion pl WHERE pl.orden_operacion_id=oo.id AND pl.fin>?) qty_planificada,
        (SELECT COUNT(*) FROM planificacion pl WHERE pl.orden_operacion_id=oo.id) bloques
        FROM orden_operaciones oo
        JOIN ordenes o ON o.id=oo.orden_id
        LEFT JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
        LEFT JOIN productos p ON p.id=o.producto_id
        LEFT JOIN clientes c ON c.id=o.cliente_id
        WHERE o.estado IN ('Pendiente','En proceso')
          AND COALESCE(oo.es_tercerizada,0)=0
          AND oo.estado NOT IN ('Completada','Cancelada')
          AND (oo.estado IN ('Pendiente','En proceso') OR oo.qty_producida<oo.qty_requerida)
        ORDER BY COALESCE(o.fecha_entrega,'9999'), o.id, CAST(oo.orden AS INTEGER)""", (_sch_ahora(),))
    return jsonify([dict(r) for r in rows])


def _sch_validar(d, bid=None, emp_actual=None):
    """Valida un bloque. Devuelve (datos, error, avisos). Choques de máquina u
    operario son error (409): una máquina o una persona no pueden estar en dos
    trabajos a la vez."""
    avisos = []
    try:
        oo_id = int(d.get("orden_operacion_id"))
        maq_id = int(d.get("maquina_id"))
    except (TypeError, ValueError):
        return None, ("Falta la operación o la máquina", 400), avisos
    try:
        jor = int(d.get("jornada_horas") or 9)
    except (TypeError, ValueError):
        jor = 0
    if jor not in _SCH_JORNADAS:
        return None, ("La jornada debe ser de 9 o 12 horas", 400), avisos
    ini = _sch_parse(d.get("inicio"))
    if not ini:
        return None, ("Fecha/hora de inicio inválida", 400), avisos
    fin = ini + _td(hours=jor)
    op = query("""SELECT oo.*, o.numero ot_numero, o.fecha_entrega, o.estado ot_estado
                  FROM orden_operaciones oo JOIN ordenes o ON o.id=oo.orden_id WHERE oo.id=?""", (oo_id,), one=True)
    if not op:
        return None, ("Operación no encontrada", 404), avisos
    if op["es_tercerizada"]:
        return None, ("Una operación tercerizada no se programa en una máquina propia", 400), avisos
    if op["estado"] in ("Completada", "Cancelada") or op["ot_estado"] in ("Completada", "Cancelada"):
        return None, ("La operación ya está " + op["estado"].lower() + " y no se puede programar", 400), avisos
    maq = query("SELECT * FROM maquinas WHERE id=?", (maq_id,), one=True)
    if not maq:
        return None, ("Máquina no encontrada", 404), avisos
    emp_id = d.get("empleado_id")
    emp = None
    if emp_id not in (None, "", 0, "0"):
        emp = query("SELECT * FROM empleados WHERE id=?", (int(emp_id),), one=True)
        if not emp:
            return None, ("Operario no encontrado", 404), avisos
        if not emp["activo"]:
            # Un bloque que ya lo tenía asignado se puede seguir editando
            # (p.ej. cambiar la observación) sin perder el operario.
            if emp_actual is None or int(emp_actual) != emp["id"]:
                return None, ("El operario está dado de baja", 400), avisos
            avisos.append("El operario está dado de baja")
    try:
        qty = float(d.get("cantidad_plan") or 0)
    except (TypeError, ValueError):
        return None, ("Cantidad inválida", 400), avisos
    if qty < 0:
        return None, ("La cantidad no puede ser negativa", 400), avisos
    a, b = ini.strftime(_SCH_FMT), fin.strftime(_SCH_FMT)
    ex = bid or 0
    # Choque de máquina
    c = query(_sch_bloque_sql() + " WHERE pl.maquina_id=? AND pl.id<>? AND pl.inicio<? AND pl.fin>?" + _SCH_ACTIVO + " LIMIT 1",
              (maq_id, ex, b, a), one=True)
    if c:
        return None, (f"La máquina {maq['nombre']} ya está ocupada de {_sch_corto(c['inicio'])} a {_sch_corto(c['fin'])} "
                      f"({c['ot_numero']} · {c['operacion']})", 409), avisos
    # Choque de operario
    if emp:
        c = query(_sch_bloque_sql() + " WHERE pl.empleado_id=? AND pl.id<>? AND pl.inicio<? AND pl.fin>?" + _SCH_ACTIVO + " LIMIT 1",
                  (emp["id"], ex, b, a), one=True)
        if c:
            mq = query("SELECT nombre FROM maquinas WHERE id=?", (c["maquina_id"],), one=True)
            return None, (f"{emp['apellido']} {emp['nombre']} ya tiene trabajo de {_sch_corto(c['inicio'])} a {_sch_corto(c['fin'])} "
                          f"en {mq['nombre'] if mq else 'otra máquina'} ({c['ot_numero']})", 409), avisos
        if op["categoria_maquina_id"]:
            hab = query("SELECT 1 FROM empleado_maquinas WHERE empleado_id=? AND categoria_maquina_id=?",
                        (emp["id"], op["categoria_maquina_id"]), one=True)
            if not hab:
                avisos.append("El operario no está habilitado en el sector de esta operación")
    else:
        avisos.append("Sin operario asignado")
    if maq["estado"] != "Operativa":
        avisos.append(f"La máquina está en estado «{maq['estado']}»")
    if op["categoria_maquina_id"] and maq["categoria_id"] and op["categoria_maquina_id"] != maq["categoria_id"]:
        avisos.append("La máquina es de otro sector distinto al de la operación")
    if op["fecha_entrega"] and fin.strftime("%Y-%m-%d") > str(op["fecha_entrega"])[:10]:
        avisos.append(f"Termina después de la fecha de entrega de la OT ({str(op['fecha_entrega'])[:10]})")
    return {"oo": oo_id, "maq": maq_id, "emp": emp["id"] if emp else None, "ini": a, "fin": b,
            "jor": jor, "qty": qty, "obs": (d.get("obs") or "").strip() or None,
            "requerida": float(op["qty_requerida"] or 0),
            "op_desc": f"{op['ot_numero']} · {op['nombre']}",
            "falta": max(0.0, float(op["qty_requerida"] or 0) - float(op["qty_producida"] or 0))}, None, avisos


@app.route("/api/scheduling", methods=["POST"])
@login_required(roles=["admin", "operario"])
def sch_crear():
    d = request.get_json(silent=True) or {}
    # BEGIN IMMEDIATE toma el lock de escritura antes de validar los choques:
    # sin esto, dos altas simultáneas en la misma máquina y horario pasaban
    # las dos la validación y quedaban superpuestas.
    db = get_db()
    if db.in_transaction:
        db.commit()
    db.execute("BEGIN IMMEDIATE")
    try:
        res = _sch_crear(d, db)
        if db.in_transaction:
            db.commit()
        return res
    except:
        db.rollback()
        raise


def _sch_crear(d, db):
    v, err, avisos = _sch_validar(d)
    if err:
        db.rollback()
        return jsonify({"error": err[0]}), err[1]
    tope = _sch_tope_error(v, _sch_disponible(v["oo"], v["requerida"], v["falta"]))
    if tope:
        db.rollback()
        return jsonify({"error": tope}), 400
    # Repetir en los N días siguientes (como el Excel: mismo trabajo, mismo
    # operario, todos los días). Se valida TODO antes de grabar nada.
    try:
        rep = max(0, min(30, int(d.get("repetir") or 0)))
    except (TypeError, ValueError):
        rep = 0
    habiles = bool(d.get("solo_habiles", True))
    # Con cantidad por jornada, las repeticiones se reparten lo que falta
    # producir (descontado lo ya planificado a futuro) en vez de copiar la
    # misma cantidad todos los días: faltaban 40 u, repetir 5 días daba 200 u.
    resta = None
    if rep and v["qty"] > 0:
        resta = v["falta"] - _sch_qty_futura(v["oo"])
        if resta <= 0:
            avisos.append("La operación ya tiene planificado todo lo que falta: no se repitió el bloque")
            rep = 0
            resta = None
        else:
            v["qty"] = min(v["qty"], resta)
            resta -= v["qty"]
    plan = [v]
    cur = _sch_parse(v["ini"])
    while len(plan) < rep + 1 and (resta is None or resta > 0):
        cur = cur + _td(days=1)
        if habiles and cur.weekday() >= 5:
            continue
        dd = dict(d); dd["inicio"] = cur.strftime(_SCH_FMT)
        vv, err, av = _sch_validar(dd)
        if err:
            db.rollback()
            return jsonify({"error": f"Día {cur.strftime('%d/%m')}: {err[0]}"}), err[1]
        for x in av:
            if x not in avisos:
                avisos.append(x)
        if resta is not None:
            vv["qty"] = min(vv["qty"], resta)
            resta -= vv["qty"]
        plan.append(vv)
    if len(plan) < rep + 1:
        avisos.append(f"Con {len(plan)} jornada(s) alcanza para lo que falta producir: no se crearon las otras {rep + 1 - len(plan)}")
    ids = []
    for x in plan:
        ids.append(db.execute("""INSERT INTO planificacion (orden_operacion_id,maquina_id,empleado_id,inicio,fin,jornada_horas,cantidad_plan,obs)
                                 VALUES (?,?,?,?,?,?,?,?)""",
                              (x["oo"], x["maq"], x["emp"], x["ini"], x["fin"], x["jor"], x["qty"], x["obs"])).lastrowid)
    return jsonify({"ok": True, "id": ids[0], "ids": ids, "avisos": avisos}), 201


@app.route("/api/scheduling/<int:bid>", methods=["PUT"])
@login_required(roles=["admin", "operario"])
def sch_editar(bid):
    d = request.get_json(silent=True) or {}
    db = get_db()
    if db.in_transaction:
        db.commit()
    db.execute("BEGIN IMMEDIATE")  # ver sch_crear
    try:
        cur = query("SELECT * FROM planificacion WHERE id=?", (bid,), one=True)
        if not cur:
            db.rollback()
            return jsonify({"error": "Bloque no encontrado"}), 404
        # lo que no se manda queda como estaba (permite mover solo máquina/hora arrastrando)
        base = {"orden_operacion_id": cur["orden_operacion_id"], "maquina_id": cur["maquina_id"],
                "empleado_id": cur["empleado_id"], "inicio": cur["inicio"], "jornada_horas": cur["jornada_horas"],
                "cantidad_plan": cur["cantidad_plan"], "obs": cur["obs"]}
        base.update({k: d[k] for k in base if k in d})
        v, err, avisos = _sch_validar(base, bid, emp_actual=cur["empleado_id"])
        if err:
            db.rollback()
            return jsonify({"error": err[0]}), err[1]
        # Mover el bloque (máquina, hora, operario) siempre se puede; pasarlo a
        # otra operación o subirle la cantidad no puede exceder lo que queda.
        if v["oo"] != cur["orden_operacion_id"] or v["qty"] > float(cur["cantidad_plan"] or 0) + 0.0001:
            tope = _sch_tope_error(v, _sch_disponible(v["oo"], v["requerida"], v["falta"], excluir_bid=bid))
            if tope:
                db.rollback()
                return jsonify({"error": tope}), 400
        db.execute("""UPDATE planificacion SET orden_operacion_id=?,maquina_id=?,empleado_id=?,inicio=?,fin=?,
                      jornada_horas=?,cantidad_plan=?,obs=? WHERE id=?""",
                   (v["oo"], v["maq"], v["emp"], v["ini"], v["fin"], v["jor"], v["qty"], v["obs"], bid))
        db.commit()
    except:
        db.rollback()
        raise
    return jsonify({"ok": True, "avisos": avisos})


@app.route("/api/scheduling/<int:bid>", methods=["DELETE"])
@login_required(roles=["admin", "operario"])
def sch_borrar(bid):
    if not query("SELECT id FROM planificacion WHERE id=?", (bid,), one=True):
        return jsonify({"error": "Bloque no encontrado"}), 404
    execute("DELETE FROM planificacion WHERE id=?", (bid,))
    return jsonify({"ok": True})


# ── Ordenes ───────────────────────────────────────────────────────────────────
@app.route("/api/ordenes", methods=["GET"])
@login_required()
def get_ordenes():
    estado = request.args.get("estado")
    sql = """SELECT o.*,c.razon cliente_nombre,p.nombre producto_nombre,p.codigo producto_codigo,
        (SELECT SUM(oo2.qty_producida) FROM orden_operaciones oo2
         WHERE oo2.orden_id=o.id AND oo2.orden=(
            SELECT oo.orden FROM orden_operaciones oo
            WHERE oo.orden_id=o.id ORDER BY CAST(oo.orden AS INTEGER) DESC, oo.orden DESC LIMIT 1
         )) total_realizado,
        (SELECT oci.orden_cliente_id FROM orden_cliente_item_ots ocio
         JOIN ordenes_cliente_items oci ON oci.id=ocio.item_id WHERE ocio.ot_id=o.id LIMIT 1) oc_id,
        (SELECT oc.numero FROM orden_cliente_item_ots ocio
         JOIN ordenes_cliente_items oci ON oci.id=ocio.item_id JOIN ordenes_cliente oc ON oc.id=oci.orden_cliente_id
         WHERE ocio.ot_id=o.id LIMIT 1) oc_numero,
        (SELECT COUNT(*) FROM orden_operaciones oo3 WHERE oo3.orden_id=o.id) ops_count,
        (SELECT COUNT(*) FROM orden_operaciones oo4 WHERE oo4.orden_id=o.id
         AND (oo4.estado!='Completada' OR oo4.qty_producida<oo4.qty_requerida)) ops_pendientes,
        (SELECT COALESCE(SUM(ot.precio_acordado * COALESCE(oo_ot.qty_requerida,1)),0)
         FROM ordenes_tercerizado ot LEFT JOIN orden_operaciones oo_ot ON oo_ot.id=ot.operacion_id
         WHERE ot.ot_origen_id=o.id AND ot.estado!='Cancelado') costo_terciarizado
        FROM ordenes o LEFT JOIN clientes c ON c.id=o.cliente_id LEFT JOIN productos p ON p.id=o.producto_id"""
    rows = query(sql+" WHERE o.estado=? ORDER BY o.id DESC",(estado,)) if estado else query(sql+" ORDER BY o.id DESC")
    result = []
    for r in rows:
        d = dict(r)
        d["lista_para_completar"] = bool(
            d.get("estado") not in ("Completada", "Cancelada")
            and (d.get("ops_count") or 0) > 0
            and (d.get("ops_pendientes") or 0) == 0
        )
        d["costo_total"] = float(d.get("costo_mat") or 0) + float(d.get("costo_terciarizado") or 0)
        result.append(d)
    return jsonify(result)

@app.route("/api/ordenes", methods=["POST"])
@login_required(roles=["admin","operario","vendedor"])
def create_orden():
    d = request.json
    if not d.get("producto_id"): return jsonify({"error":"Producto requerido"}), 400
    prod = query("SELECT codigo,nombre FROM productos WHERE id=?", (d["producto_id"],), one=True)
    if not prod: return jsonify({"error":"Producto no encontrado"}), 404
    descripcion = d.get("descripcion") or f"{prod['codigo']} — {prod['nombre']}"
    numero = siguiente_numero("ordenes", "OT-", 3)
    # El estado de una OT nueva siempre arranca en "Pendiente" — no se acepta
    # un estado inicial distinto desde el body, aunque el cliente lo mande
    # (el campo se sacó del formulario de creación en el frontend, pero se
    # blinda también acá por si se llama directo a la API).
    lid = execute("INSERT INTO ordenes (numero,cliente_id,producto_id,descripcion,detalle,cantidad,prioridad,estado,fecha_inicio,fecha_entrega,costo_mat,costo_mo,precio_venta,obs) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (numero,d.get("cliente_id"),d["producto_id"],descripcion,d.get("detalle"),d.get("cantidad",1),d.get("prioridad","Normal"),"Pendiente",d.get("fecha_inicio"),d.get("fecha_entrega"),d.get("costo_mat",0),d.get("costo_mo",0),0,d.get("obs")))
    if "requiere_material" in d and str(d.get("requiere_material")) in ("0","False","false"):
        execute("UPDATE ordenes SET requiere_material=0 WHERE id=?", (lid,))
    return jsonify({"ok":True,"id":lid,"numero":numero}), 201

def _generar_ott_para_ot(ot_id, ot_numero):
    """Genera la OTT (Orden de Trabajo de Terceros) correspondiente a cada
    operación tercerizada de la OT, si todavía no tiene una. Es idempotente:
    si la operación ya tiene una OTT vinculada (por operacion_id), no crea
    otra — así se puede llamar desde cualquier camino de creación/regeneración
    de operaciones de la OT (creación manual, explosión multinivel, MRP)
    sin duplicar.

    Esta OTT es la que sostiene la pausa de la OT: mientras no tenga un lote
    de retorno Aprobado, la operación tercerizada (y todo lo que va después
    en la ruta) queda bloqueada — ver create_novedad() y update_lote()."""
    ops = query("""SELECT oo.* FROM orden_operaciones oo
        WHERE oo.orden_id=? AND oo.es_tercerizada=1""", (ot_id,))
    max_orden = query("""SELECT MAX(CAST(orden AS INTEGER)) mx
        FROM orden_operaciones WHERE orden_id=?""", (ot_id,), one=True)["mx"]
    for op in ops:
        ya_existe = query("SELECT id FROM ordenes_tercerizado WHERE operacion_id=?", (op["id"],), one=True)
        if ya_existe:
            continue
        num_ott = siguiente_numero("ordenes_tercerizado", "OTT-", 4)
        try:
            es_ult = 1 if (max_orden is not None and int(op["orden"]) == int(max_orden)) else 0
        except Exception:
            es_ult = 0
        # El semielaborado que va a volver se congela acá, igual que el
        # proveedor y el precio: si más adelante alguien edita los insumos en
        # Procesos, esta OT sigue con el PSE que tenía y la definición nueva
        # arranca recién en las OT siguientes. Solo aplica a operaciones
        # INTERMEDIAS: la última no genera semielaborado sino el PT de la OT.
        mat_se_id = None
        # v147: si la operación define su material insumo, ése es el que se
        # genera al ingresar el remito; si no, se usa el semielaborado (legado).
        mat_ret_id = _material_retorno_operacion(op["id"])
        if mat_ret_id:
            mat_se_id = mat_ret_id
        elif not es_ult:
            try:
                mat_se_id = _get_or_create_pse(op["proceso_op_id"])
            except Exception as e:
                print(f"[WARN] No se pudo resolver el semielaborado de la "
                      f"operación {op['id']} al crear {num_ott}: {e}")
        execute("""INSERT INTO ordenes_tercerizado
            (numero,ot_origen_id,operacion_id,proceso_op_id,proveedor_id,
             precio_acordado,estado,es_ultimo_nivel,material_se_id,creado_por)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (num_ott, ot_id, op["id"], op["proceso_op_id"],
             op["proveedor_id"] if "proveedor_id" in op.keys() else None,
             op["precio_tercerizado"] if "precio_tercerizado" in op.keys() else 0,
             "Pendiente", es_ult, mat_se_id, session.get("user_id")))


@app.route("/api/ordenes/<int:oid>", methods=["GET"])
@login_required()
def get_orden(oid):
    r = query("""SELECT o.*,c.razon cliente_nombre,p.nombre producto_nombre,p.codigo producto_codigo
        FROM ordenes o
        LEFT JOIN clientes c ON c.id=o.cliente_id
        LEFT JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    if not r: return jsonify({"error":"OT no encontrada"}), 404
    return jsonify(dict(r))

def _completar_ot_automatico(oid):
    """Completa automáticamente una OT cuando su última operación (tercerizada)
    recibe la totalidad de lo remitido — mismo cierre que completar la OT a
    mano desde Órdenes de Trabajo (descuento de insumos sin lote + generación
    del lote de PT), pero disparado desde registrar_retorno de la OTT en vez
    de pasar por el formulario de edición de la OT. Es idempotente: si la OT
    ya está Completada, no hace nada."""
    orden_actual = query("SELECT * FROM ordenes WHERE id=?", (oid,), one=True)
    if not orden_actual or orden_actual["estado"] == "Completada":
        return
    numero_ot = orden_actual["numero"]
    ya_descontado = int(orden_actual["stock_descontado"] or 0) == 1
    try:
        if not ya_descontado:
            execute("UPDATE ordenes SET stock_descontado=1 WHERE id=?", (oid,))
            insumos = query("""
                SELECT om.material_id, m.codigo, m.descripcion,
                       SUM(cant_material(om.cantidad, oo.qty_producida, om.vida_util_herramienta)) consumo
                FROM orden_operaciones oo
                JOIN orden_operacion_materiales om ON om.orden_operacion_id=oo.id
                JOIN materiales m ON m.id=om.material_id
                WHERE oo.orden_id=? AND m.categoria IN ('Insumo','Herramienta')
                GROUP BY om.material_id
            """, (oid,))
            for ins in insumos:
                consumo = float(ins["consumo"] or 0)
                if consumo <= 0:
                    continue
                execute("""UPDATE materiales SET stock=MAX(0, stock-?),
                    actualizado=datetime('now','localtime') WHERE id=?""",
                    (consumo, ins["material_id"]))
                auto_generar_sc_bajo_stock(ins["material_id"], f"consumo insumos OT {numero_ot}")
                execute("""INSERT INTO movimientos
                    (material_id, lote_id, tipo, cantidad, referencia, usuario_id)
                    VALUES (?, NULL, 'salida', ?, ?, ?)""",
                    (ins["material_id"], consumo,
                     f"Consumo OT {numero_ot} — Insumo {ins['codigo']} (sin lote)",
                     session["user_id"]))
        generar_pt_faltante_si_corresponde(oid)
        _consumir_pse_sobrante_ot(oid)
        execute("UPDATE lotes SET estado='Ingresado' WHERE estado='Abierto' AND numero LIKE ?",
            (numero_ot + "-C%",))
    except Exception as e:
        print(f"[OTT] No se pudo autocompletar OT {numero_ot} desde retorno OTT: {e}")
        return
    execute("UPDATE ordenes SET estado='Completada' WHERE id=?", (oid,))


def _lote_stock_computado(lote_id):
    """True si las piezas de este lote ya se sumaron a materiales.stock al
    crearlo. Los lotes viejos (anteriores a este cambio) devuelven False y
    siguen con el modelo anterior: su stock lo mueve Calidad."""
    r = query("SELECT stock_computado FROM lotes WHERE id=?", (lote_id,), one=True)
    return bool(r and r["stock_computado"])


def _reducir_lotes_pt(mat_pt_id, lotes, sobrante, ot_lote_num):
    """Descuenta `sobrante` piezas de los lotes de PT de una OT, empezando por
    el mas nuevo (los lotes vienen ordenados por el llamador).

    Solo se toca lo que Calidad TODAVIA NO clasifico
    (cantidad_original - cantidad_activa - cantidad_rechazada): lo aprobado ya
    entro a `materiales.stock` y puede estar consumido por otra OT, asi que
    descontarlo desde aca dejaria un descuadre peor que el que se intenta
    corregir. Si no alcanza con lo sin clasificar, se descuenta lo que se
    pueda y se avisa por consola en vez de romper la edicion.

    Devuelve lo que NO se pudo descontar.
    """
    for lote in lotes:
        if sobrante <= 0.0001:
            break
        sin_clasificar = (float(lote["cantidad_original"] or 0)
                          - float(lote["cantidad_activa"] or 0)
                          - float(lote["cantidad_rechazada"] or 0))
        quitar = min(sobrante,
                     max(0.0, sin_clasificar),
                     float(lote["cantidad_disponible"] or 0))
        if quitar <= 0.0001:
            continue
        execute("""UPDATE lotes SET
            cantidad_original=MAX(0, cantidad_original-?),
            cantidad_disponible=MAX(0, cantidad_disponible-?),
            estado=CASE WHEN cantidad_original-? <= 0.0001 AND estado<>'Abierto'
                        THEN 'Agotado' ELSE estado END
            WHERE id=?""", (quitar, quitar, quitar, lote["id"]))
        # Si al crearse el lote ya se habia computado el stock (las piezas
        # entraron al deposito), sacarlas del lote tiene que sacarlas tambien
        # del inventario.
        if _lote_stock_computado(lote["id"]):
            execute("""UPDATE materiales SET stock=MAX(0, stock-?),
                actualizado=datetime('now','localtime') WHERE id=?""",
                (quitar, mat_pt_id))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,?,?,?,?)""",
            (mat_pt_id, lote["id"], "ajuste", quitar,
             f"Correccion de produccion OT {ot_lote_num} - se descuentan {quitar:g} piezas "
             f"del lote {lote['numero']} (no habian pasado por Calidad)",
             session.get("user_id")))
        sobrante -= quitar
    if sobrante > 0.0001:
        print(f"[WARN] OT {ot_lote_num}: quedaron {sobrante:g} piezas de PT sin poder "
              f"descontar del lote - ya estaban clasificadas por Calidad.")
    return sobrante


# ── Cajones ───────────────────────────────────────────────────────────────────
# Un cajón agrupa piezas físicas de una OT desde la 1ª operación hasta que
# Calidad las libera. Lo que hizo cada paso en cada cajón sale de
# novedad_cajones (operaciones internas) y ott_cajones (tercerizadas). El paso
# es el número de "orden" de la operación (las rutas alternativas comparten
# paso), así un cajón transferido desde otra OT del mismo producto sigue desde
# el paso donde quedó. Estados: En proceso, En espera (su OT se canceló y
# espera pasar a otra), Liberado / Rechazado (Calidad clasificó todo lo que
# terminó la última operación) y Baja.

def _pasos_ot(oid):
    return [r["p"] for r in query("""SELECT DISTINCT CAST(orden AS INTEGER) p
        FROM orden_operaciones WHERE orden_id=? ORDER BY 1""", (oid,))]


def _ot_tiene_cajones(oid):
    return bool(query("SELECT 1 FROM cajones WHERE orden_id=? LIMIT 1", (oid,), one=True))


def _ot_usa_cajones(oid):
    """La OT trabaja con cajones si ya tiene alguno, o si su producto tiene
    "piezas por cajón" y su primer paso todavía no produjo nada. Las OTs que
    ya habían empezado siguen sin cajones, como antes."""
    if _ot_tiene_cajones(oid):
        return True
    o = query("""SELECT p.capacidad_cajon FROM ordenes o JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    if not o or not o["capacidad_cajon"] or int(o["capacidad_cajon"]) <= 0:
        return False
    pasos = _pasos_ot(oid)
    if not pasos:
        return False
    hecho = query("""SELECT COALESCE(SUM(qty_producida),0) s FROM orden_operaciones
        WHERE orden_id=? AND CAST(orden AS INTEGER)=?""", (oid, pasos[0]), one=True)["s"]
    return float(hecho or 0) <= 0.0001


def _cajon_por_paso(cajon_id, sin_novedad=None, sin_op=None):
    """{paso: piezas} que registró cada paso en el cajón (sin contar la
    novedad `sin_novedad` ni la operación tercerizada `sin_op`)."""
    out = {}
    for r in query("""SELECT CAST(oo.orden AS INTEGER) p, SUM(nc.cantidad) c
            FROM novedad_cajones nc
            JOIN novedades_produccion n ON n.id=nc.novedad_id
            JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
            WHERE nc.cajon_id=? AND nc.novedad_id<>? GROUP BY 1""", (cajon_id, sin_novedad or 0)):
        out[r["p"]] = out.get(r["p"], 0.0) + float(r["c"] or 0)
    for r in query("""SELECT CAST(oo.orden AS INTEGER) p, SUM(oc.cantidad) c
            FROM ott_cajones oc JOIN orden_operaciones oo ON oo.id=oc.orden_operacion_id
            WHERE oc.cajon_id=? AND oc.orden_operacion_id<>? GROUP BY 1""", (cajon_id, sin_op or 0)):
        out[r["p"]] = out.get(r["p"], 0.0) + float(r["c"] or 0)
    return out


def _cajon_pasos(cajon, por_paso):
    return sorted(set(_pasos_ot(cajon["orden_id"])) | set(por_paso))


def _cajon_terminadas(cajon, por_paso=None):
    """Piezas del cajón que ya hizo la última operación de su OT."""
    pasos = _pasos_ot(cajon["orden_id"])
    if not pasos:
        return 0.0
    if por_paso is None:
        por_paso = _cajon_por_paso(cajon["id"])
    return por_paso.get(pasos[-1], 0.0)


def _cajon_disponible(cajon, paso, por_paso):
    """Piezas del cajón que el paso anterior ya hizo y este paso todavía no."""
    previos = [p for p in _cajon_pasos(cajon, por_paso) if p < paso]
    if not previos:
        return 0.0
    return max(0.0, por_paso.get(previos[-1], 0.0) - por_paso.get(paso, 0.0))


def _cajon_error(cajon, por_paso):
    """Valida un cajón con las cantidades por paso que quedarían: ningún paso
    puede tener más piezas que el anterior, y la última operación no puede
    quedar por debajo de lo que Calidad ya clasificó."""
    if cajon["estado"] == "Baja":
        return f"El cajón {cajon['numero']} está dado de baja"
    pasos = _cajon_pasos(cajon, por_paso)
    for a, b in zip(pasos, pasos[1:]):
        if por_paso.get(b, 0.0) > por_paso.get(a, 0.0) + 0.0001:
            return (f"El cajón {cajon['numero']} quedaría con {por_paso.get(b, 0.0):g} piezas en el paso {b} "
                    f"y solo {por_paso.get(a, 0.0):g} en el paso {a}")
    clasif = float(cajon["cantidad_liberada"] or 0) + float(cajon["cantidad_rechazada"] or 0)
    if clasif > 0 and _cajon_terminadas(cajon, por_paso) < clasif - 0.0001:
        return (f"El cajón {cajon['numero']} ya tiene {clasif:g} piezas clasificadas por Calidad: "
                f"no puede quedar con menos piezas terminadas")
    return None


def _cajon_nuevo(oid, capacidad):
    o = query("""SELECT o.producto_id, m.codigo FROM ordenes o
        JOIN materiales m ON m.id=o.producto_id WHERE o.id=?""", (oid,), one=True)
    numero = siguiente_numero("cajones", f"cajon-{o['codigo']}-", 3, reservar=True)
    return execute("""INSERT INTO cajones (numero,orden_id,orden_origen_id,producto_id,capacidad)
        VALUES (?,?,?,?,?)""", (numero, oid, oid, o["producto_id"], capacidad))


def _llenar_cajones(oid, qty):
    """Primer paso: las piezas OK llenan el cajón abierto de la OT y abren los
    que hagan falta (250 con 100 por cajón -> 100, 100, 50). Devuelve
    [(cajon_id, cantidad)]."""
    prod = query("""SELECT p.capacidad_cajon FROM ordenes o JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    plan = []
    restante = float(qty)
    while restante > 0.0001:
        caj = query("""SELECT * FROM cajones WHERE orden_id=? AND orden_origen_id=orden_id
            AND estado='En proceso' AND cantidad < capacidad - 0.0001
            AND cantidad_liberada + cantidad_rechazada = 0
            ORDER BY id LIMIT 1""", (oid,), one=True)
        if not caj:
            cap = int(prod["capacidad_cajon"] or 0) if prod else 0
            if cap <= 0:
                # Se borró "piezas por cajón" con la OT en curso: sigue con
                # la capacidad de sus cajones.
                ult = query("SELECT capacidad FROM cajones WHERE orden_id=? ORDER BY id DESC LIMIT 1",
                    (oid,), one=True)
                cap = int(ult["capacidad"]) if ult else 0
            if cap <= 0:
                break
            caj = query("SELECT * FROM cajones WHERE id=?", (_cajon_nuevo(oid, cap),), one=True)
        poner = min(restante, float(caj["capacidad"]) - float(caj["cantidad"]))
        execute("UPDATE cajones SET cantidad=cantidad+? WHERE id=?", (poner, caj["id"]))
        plan.append((caj["id"], poner))
        restante -= poner
    return plan


def _plan_cajones_paso(oid, paso, qty, pedido=None, sin_novedad=None, sin_op=None, parcial=False):
    """Paso que no es el primero: valida en qué cajones se trabajó (`pedido`
    = [{cajon_id, cantidad}]) o, si no vino, los toma en orden (FIFO). Cada
    cajón admite como máximo lo que el paso anterior hizo en él menos lo que
    este paso ya cargó. Devuelve (plan, error)."""
    cajones = query("""SELECT * FROM cajones WHERE orden_id=? AND estado NOT IN ('Baja','En espera')
        ORDER BY id""", (oid,))
    disp = {c["id"]: _cajon_disponible(c, paso, _cajon_por_paso(c["id"], sin_novedad, sin_op))
            for c in cajones}
    por_id = {c["id"]: c for c in cajones}
    if pedido:
        plan, vistos = [], set()
        for it in pedido:
            try:
                cid = int(it.get("cajon_id"))
                cant = float(it.get("cantidad") or 0)
            except (TypeError, ValueError, AttributeError):
                return None, "Cajón o cantidad inválidos"
            if cant <= 0:
                continue
            if cid not in por_id:
                return None, "Uno de los cajones indicados no es de esta OT o no está disponible"
            if cid in vistos:
                return None, f"El cajón {por_id[cid]['numero']} está repetido"
            vistos.add(cid)
            if cant > disp[cid] + 0.0001:
                return None, (f"El cajón {por_id[cid]['numero']} tiene {disp[cid]:g} piezas disponibles "
                              f"para esta operación y se cargan {cant:g}")
            plan.append((cid, cant))
        total = sum(c for _, c in plan)
        if abs(total - qty) > 0.0001:
            return None, f"La suma por cajón ({total:g}) tiene que ser igual a las piezas OK ({qty:g})"
        return plan, None
    plan, restante = [], float(qty)
    for c in cajones:
        tomar = min(restante, disp[c["id"]])
        if tomar > 0.0001:
            plan.append((c["id"], tomar))
            restante -= tomar
    if restante > 0.0001 and not parcial:
        return None, (f"Los cajones de la OT tienen {qty - restante:g} piezas disponibles para esta "
                      f"operación y se cargan {qty:g}")
    return plan, None


def _quitar_lifo(filas, quitar):
    """Saca `quitar` piezas de [(cajon_id, cantidad)] empezando por el último."""
    filas = [list(f) for f in filas]
    for f in reversed(filas):
        if quitar <= 0.0001:
            break
        t = min(f[1], quitar)
        f[1] -= t
        quitar -= t
    return [(c, q) for c, q in filas if q > 0.0001]


def _replan_novedad_cajones(nov_id, oid, oo_id, qty_new, pedido=None):
    """Plan de cajones para una novedad que se edita (o se borra: qty_new=0).
    Devuelve (plan, extra_primer_paso, error): `plan` son las filas que le
    quedan a la novedad y `extra_primer_paso` las piezas a sumar llenando
    cajones (solo en el primer paso). Valida cada cajón afectado antes de
    tocar nada."""
    paso = query("SELECT CAST(orden AS INTEGER) p FROM orden_operaciones WHERE id=?", (oo_id,), one=True)["p"]
    pasos = _pasos_ot(oid)
    primero = bool(pasos) and paso == pasos[0]
    actuales = [(r["cajon_id"], float(r["cantidad"])) for r in query(
        "SELECT cajon_id, cantidad FROM novedad_cajones WHERE novedad_id=? ORDER BY cajon_id", (nov_id,))]
    total = sum(q for _, q in actuales)
    extra = 0.0
    if pedido and not primero and qty_new > 0:
        plan, err = _plan_cajones_paso(oid, paso, qty_new, pedido, sin_novedad=nov_id)
        if err:
            return None, 0.0, err
    elif qty_new < total - 0.0001:
        plan = _quitar_lifo(actuales, total - qty_new)
    elif qty_new > total + 0.0001:
        plan = actuales
        if primero:
            extra = qty_new - total
        else:
            mas, err = _plan_cajones_paso(oid, paso, qty_new - total)
            if err:
                return None, 0.0, err
            d = dict(plan)
            for cid, q in mas:
                d[cid] = d.get(cid, 0.0) + q
            plan = sorted(d.items())
    else:
        plan = actuales
    nuevo = dict(plan)
    for cid in set(nuevo) | {c for c, _ in actuales}:
        cajon = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
        por_paso = _cajon_por_paso(cid, sin_novedad=nov_id)
        if nuevo.get(cid, 0.0) > 0:
            por_paso[paso] = por_paso.get(paso, 0.0) + nuevo[cid]
        if dict(actuales).get(cid, 0.0) == nuevo.get(cid, 0.0) and cajon["estado"] != "Baja":
            continue
        err = _cajon_error(cajon, por_paso)
        if err:
            return None, 0.0, err
    return plan, extra, None


def _cajon_recalcular(cid):
    """Recalcula las piezas de entrada y el estado de un cajón."""
    c = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
    if not c:
        return
    por_paso = _cajon_por_paso(cid)
    cantidad = por_paso[min(por_paso)] if por_paso else 0.0
    estado = c["estado"]
    if estado not in ("Baja", "En espera"):
        term = _cajon_terminadas(c, por_paso)
        clasif = float(c["cantidad_liberada"] or 0) + float(c["cantidad_rechazada"] or 0)
        if cantidad <= 0.0001:
            estado = "Baja"
        elif term > 0.0001 and clasif >= term - 0.0001:
            estado = "Liberado" if float(c["cantidad_liberada"] or 0) > 0 else "Rechazado"
        else:
            estado = "En proceso"
    execute("UPDATE cajones SET cantidad=?, estado=? WHERE id=?", (cantidad, estado, cid))


def _guardar_novedad_cajones(nov_id, oid, plan, extra=0.0):
    """Deja a la novedad con las filas `plan` (+ `extra` piezas llenando
    cajones del primer paso) y recalcula los cajones tocados."""
    tocados = {r["cajon_id"] for r in query("SELECT cajon_id FROM novedad_cajones WHERE novedad_id=?", (nov_id,))}
    execute("DELETE FROM novedad_cajones WHERE novedad_id=?", (nov_id,))
    filas = dict()
    for cid, q in plan:
        filas[cid] = filas.get(cid, 0.0) + q
    if extra > 0.0001:
        # _llenar_cajones ya suma a cajones.cantidad; el recálculo de abajo
        # lo vuelve a derivar de las filas, así que no queda doble.
        for cid, q in _llenar_cajones(oid, extra):
            filas[cid] = filas.get(cid, 0.0) + q
    for cid, q in filas.items():
        if q > 0.0001:
            execute("INSERT INTO novedad_cajones (novedad_id,cajon_id,cantidad) VALUES (?,?,?)", (nov_id, cid, q))
    for cid in tocados | set(filas):
        _cajon_recalcular(cid)


def _lote_pt_ot(oid):
    """Lote de PT de la OT (ver generar_pt_faltante_si_corresponde)."""
    o = query("SELECT numero, producto_id FROM ordenes WHERE id=?", (oid,), one=True)
    if not o or not o["producto_id"]:
        return None
    r = query("""SELECT id FROM lotes WHERE material_id=? AND numero IN (?,?)
        ORDER BY numero=? DESC LIMIT 1""",
        (o["producto_id"], o["numero"], o["numero"] + "-PT", o["numero"]), one=True)
    return r["id"] if r else None


def _cajones_vincular_lote(oid):
    lote_id = _lote_pt_ot(oid)
    if lote_id:
        execute("UPDATE cajones SET lote_id=? WHERE orden_id=? AND lote_id IS NULL", (lote_id, oid))


def _sync_cajones_op_tercerizada(oo_id, usa):
    """Una operación tercerizada no carga novedades: lo que registra como hecho
    (qty_producida) se imputa a cajones. En el primer paso crea/llena
    cajones; en los demás los toma en orden (FIFO) hasta lo disponible. Si
    bajó, se descuenta de los últimos cajones mientras los pasos siguientes
    lo permitan."""
    if not usa:
        return
    oo = query("""SELECT id, orden_id, CAST(orden AS INTEGER) p, qty_producida
        FROM orden_operaciones WHERE id=?""", (oo_id,), one=True)
    if not oo:
        return
    oid = oo["orden_id"]
    pasos = _pasos_ot(oid)
    actuales = [(r["cajon_id"], float(r["cantidad"])) for r in query(
        "SELECT cajon_id, cantidad FROM ott_cajones WHERE orden_operacion_id=? ORDER BY cajon_id", (oo_id,))]
    delta = float(oo["qty_producida"] or 0) - sum(q for _, q in actuales)
    filas = dict(actuales)
    if delta > 0.0001:
        if pasos and oo["p"] == pasos[0]:
            nuevos = _llenar_cajones(oid, delta)
        else:
            nuevos, _ = _plan_cajones_paso(oid, oo["p"], delta, parcial=True)
        for cid, q in nuevos:
            filas[cid] = filas.get(cid, 0.0) + q
    elif delta < -0.0001:
        quitar = -delta
        for cid, q in reversed(actuales):
            if quitar <= 0.0001:
                break
            cajon = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
            t = min(q, quitar)
            por_paso = _cajon_por_paso(cid, sin_op=oo_id)
            por_paso[oo["p"]] = por_paso.get(oo["p"], 0.0) + q - t
            if _cajon_error(cajon, por_paso):
                continue
            filas[cid] = q - t
            quitar -= t
        if quitar > 0.0001:
            print(f"[WARN] Operación {oo_id}: {quitar:g} piezas tercerizadas menos que no se "
                  f"pudieron sacar de sus cajones (ya avanzaron en pasos siguientes).")
    else:
        return
    execute("DELETE FROM ott_cajones WHERE orden_operacion_id=?", (oo_id,))
    for cid, q in filas.items():
        if q > 0.0001:
            execute("INSERT INTO ott_cajones (orden_operacion_id,cajon_id,cantidad) VALUES (?,?,?)",
                (oo_id, cid, q))
    for cid in filas:
        _cajon_recalcular(cid)


def _lote_estado_por_cajones(lote_id):
    """Estado del lote derivado de lo que Calidad clasificó en sus cajones."""
    l = query("SELECT * FROM lotes WHERE id=?", (lote_id,), one=True)
    if not l:
        return
    disp = float(l["cantidad_disponible"] or 0)
    act = float(l["cantidad_activa"] or 0)
    rech = float(l["cantidad_rechazada"] or 0)
    if disp <= 0.0001:
        estado = "Agotado"
    elif disp - act - rech > 0.001:
        estado = "Ingresado"
    else:
        estado = "Aprobado" if act > 0.0001 else "Rechazado"
    execute("UPDATE lotes SET estado=? WHERE id=?", (estado, lote_id))


def _remitir_de_cajones(remito_item_id, lote_id, qty):
    """Un remito de un lote con cajones sale de sus cajones liberados, del más
    viejo al más nuevo, y queda anotado de qué cajón salió cada pieza."""
    restante = float(qty)
    for c in query("""SELECT id, cantidad_liberada - cantidad_remitida libre FROM cajones
            WHERE lote_id=? AND cantidad_liberada - cantidad_remitida > 0.0001 ORDER BY id""", (lote_id,)):
        if restante <= 0.0001:
            break
        tomar = min(restante, float(c["libre"]))
        execute("INSERT INTO remito_item_cajones (remito_item_id,cajon_id,cantidad) VALUES (?,?,?)",
            (remito_item_id, c["id"], tomar))
        execute("UPDATE cajones SET cantidad_remitida=cantidad_remitida+? WHERE id=?", (tomar, c["id"]))
        restante -= tomar


@auditoria_proceso("generación automática de PT")
def generar_pt_faltante_si_corresponde(oid):
    """Red de seguridad: si la OT se marca 'Completada' pero el flujo de
    Novedades no generó (o generó parcialmente) el stock de Producto
    Terminado correspondiente, completa la diferencia acá.

    Es idempotente: calcula cuánto PT ya se generó (lote cuyo número
    coincide con el número de la OT) y solo agrega lo que falte hasta
    llegar a la cantidad solicitada en la OT. Si las Novedades ya
    generaron todo, no hace nada.
    """
    orden = query("SELECT * FROM ordenes WHERE id=?", (oid,), one=True)
    if not orden or not orden["producto_id"]:
        return
    prod = query("SELECT * FROM productos WHERE id=?", (orden["producto_id"],), one=True)
    if not prod:
        return

    # ── Cantidad real a generar como PT: es lo que EFECTIVAMENTE hizo la
    # ÚLTIMA operación de la ruta, sin techo. Si la OT se completa ANTES de
    # llegar al 100% (ej. se cancela/cierra con menos piezas de las
    # pedidas), el PT que corresponde generar es esa cantidad menor. Si en
    # cambio la última operación PRODUJO DE MÁS respecto de lo pedido (ej.
    # se pidieron 100 y la operación anterior había llegado a 108, entonces
    # esta última puede llegar hasta 108), el lote de PT también refleja
    # esas 108 — no se recorta al pedido original. Cada operación puede
    # cargar cualquier cantidad de piezas terminadas, sin tope respecto de
    # lo que haya producido la operación anterior.
    # Si el último paso tiene rutas alternativas (2+ operaciones con el
    # mismo número de "orden" — p.ej. dos máquinas/procesos posibles para el
    # mismo paso) y se trabajó en más de una, lo producido de ese paso es la
    # SUMA de lo que hizo cada alternativa, no solo una de ellas.
    ultimo_orden = query("""SELECT orden FROM orden_operaciones
        WHERE orden_id=? ORDER BY CAST(orden AS INTEGER) DESC, orden DESC LIMIT 1""", (oid,), one=True)
    target_qty = 0.0
    if ultimo_orden:
        target_qty = float(query("""SELECT COALESCE(SUM(qty_producida),0) s FROM orden_operaciones
            WHERE orden_id=? AND orden=?""", (oid, ultimo_orden["orden"]), one=True)["s"] or 0)
    if target_qty <= 0:
        return

    # Todo lo producido (incluso por encima de lo pedido en la OT) se vuelca
    # íntegramente al lote de PT de esta OT — ya no existe el desvío a
    # "Producto sin lote" para el excedente.
    lote_target = target_qty

    mat_pt = get_or_create_pt_material(prod)
    ot_lote_num = orden["numero"]

    lotes_usados = query("""SELECT l.numero FROM orden_lotes ol
        JOIN lotes l ON l.id=ol.lote_id WHERE ol.orden_id=?""", (oid,))
    lotes_ref = ", ".join(l["numero"] for l in lotes_usados) if lotes_usados else "—"

    # Un único lote de PT por OT (pendiente de Calidad). Si la OT trabaja con
    # cajones, sus cajones apuntan a este lote y Calidad clasifica por cajón.
    lote_pt_row = query("""SELECT id, numero, cantidad_original, cantidad_disponible,
        COALESCE(cantidad_activa,0) cantidad_activa,
        COALESCE(cantidad_rechazada,0) cantidad_rechazada
        FROM lotes WHERE numero=? AND material_id=?""",
        (ot_lote_num, mat_pt["id"]), one=True)
    ya_generado = float(lote_pt_row["cantidad_original"]) if lote_pt_row else 0.0
    faltante = lote_target - ya_generado
    if faltante < -0.0001 and lote_pt_row:
        # Se corrigio una novedad HACIA ABAJO: el lote tiene mas piezas de
        # las que la planta termino declarando. Se devuelve la diferencia
        # en vez de dejar el lote inflado.
        _reducir_lotes_pt(mat_pt["id"], [lote_pt_row], -faltante, ot_lote_num)
        return
    if faltante <= 0:
        return  # Las Novedades ya cubrieron toda la cantidad (del lote de esta OT)

    # lotes.numero es UNIQUE a nivel global (no por material). Si no hay
    # lote de PT para esta OT pero el número ya está tomado por un lote
    # de OTRO material, se le agrega un sufijo para no chocar.
    if not lote_pt_row:
        choque = query("SELECT id FROM lotes WHERE numero=?", (ot_lote_num,), one=True)
        if choque:
            ot_lote_num = f"{ot_lote_num}-PT"

    if lote_pt_row:
        execute("""UPDATE lotes SET
            cantidad_disponible=cantidad_disponible+?,
            cantidad_original=cantidad_original+?,
            estado='Ingresado', stock_computado=1
            WHERE id=?""",
            (faltante, faltante, lote_pt_row["id"]))
        lote_pt_id = lote_pt_row["id"]
    else:
        lote_pt_id = execute("""INSERT INTO lotes
            (numero,material_id,cantidad_original,cantidad_disponible,
             cantidad_activa,referencia_proveedor,estado,obs,creado_por,stock_computado)
            VALUES (?,?,?,?,?,?,?,?,?,1)""",
            (ot_lote_num, mat_pt["id"], faltante, faltante, 0,
             f"OT {ot_lote_num}", "Ingresado",
             f"Lotes MP: {lotes_ref}", session.get("user_id")))

    # Las piezas entraron al depósito: entran a inventario ahora, sin
    # esperar a Calidad. Clasificarlas después no vuelve a moverlas.
    execute("""UPDATE materiales SET stock=stock+?,
        actualizado=datetime('now','localtime') WHERE id=?""",
        (faltante, mat_pt["id"]))
    execute(
        "INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
        (mat_pt["id"], lote_pt_id, "ingreso", faltante,
         f"Generación automática al completar OT {ot_lote_num} — ingreso a inventario, pendiente de clasificación de Calidad | Lotes MP: {lotes_ref}",
         session.get("user_id")))
    return


@app.route("/api/ordenes/<int:oid>", methods=["PUT"])
@login_required(roles=["admin","operario","vendedor"])
def update_orden(oid):
    d = request.json
    if not d.get("producto_id"): return jsonify({"error":"Producto requerido"}), 400
    prod = query("SELECT codigo,nombre FROM productos WHERE id=?", (d["producto_id"],), one=True)
    if not prod: return jsonify({"error":"Producto no encontrado"}), 404
    descripcion = d.get("descripcion") or f"{prod['codigo']} — {prod['nombre']}"

    # Obtener estado actual antes de actualizar
    orden_actual = query("SELECT estado, stock_descontado, numero, producto_id FROM ordenes WHERE id=?", (oid,), one=True)
    nuevo_estado = d.get("estado", "Pendiente")

    # ── No permitir completar la OT si quedan operaciones sin completar ───────
    # El descuento de stock (lotes + insumos) se dispara cuando la OT pasa a
    # "Completada", así que primero hay que garantizar que TODAS sus
    # operaciones ya estén en estado "Completada".
    ya_estaba_completada_chk = orden_actual and orden_actual["estado"] == "Completada"
    if nuevo_estado == "Completada" and not ya_estaba_completada_chk:
        # Si un paso tiene rutas alternativas (mismo número de "orden"),
        # alcanza con que UNA de ellas esté Completada para dar el paso por
        # hecho — las demás alternativas no usadas quedan en Pendiente.
        pendientes = query("""SELECT COUNT(*) c FROM (
            SELECT orden FROM orden_operaciones WHERE orden_id=?
            GROUP BY orden HAVING SUM(CASE WHEN estado='Completada' THEN 1 ELSE 0 END)=0)""",
            (oid,), one=True)["c"]
        if pendientes > 0:
            return jsonify({"error": f"No se puede completar la OT: quedan {pendientes} operación(es) sin completar"}), 400

    # ── Cambio de producto en una OT existente ────────────────────────────────
    # Las operaciones (orden_operaciones), los materiales requeridos
    # (orden_materiales) y los lotes ya vinculados (orden_lotes) se generan a
    # partir del producto de la OT. Si el producto cambia, todo eso queda
    # "huérfano": las operaciones siguen siendo las del producto viejo, y por
    # eso al declarar una novedad seguía ofreciendo vincular un lote de la
    # operación/producto anterior. Para evitarlo, si cambia el producto y la
    # OT no tiene nada de trabajo real ya declarado, se regeneran las
    # operaciones y materiales para el producto nuevo. Si ya hay novedades,
    # lotes vinculados o producción declarada, se bloquea el cambio de
    # producto para no perder ni corromper ese historial.
    producto_anterior = orden_actual["producto_id"] if orden_actual else None
    cambia_producto = producto_anterior is not None and int(producto_anterior) != int(d["producto_id"])
    if cambia_producto:
        novedades_previas = query("""SELECT COUNT(*) c FROM novedades_produccion n
            JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
            WHERE oo.orden_id=?""", (oid,), one=True)["c"]
        lotes_vinculados = query("SELECT COUNT(*) c FROM orden_lotes WHERE orden_id=?", (oid,), one=True)["c"]
        produccion_declarada = query("""SELECT COUNT(*) c FROM orden_operaciones
            WHERE orden_id=? AND qty_producida>0""", (oid,), one=True)["c"]
        if novedades_previas > 0 or lotes_vinculados > 0 or produccion_declarada > 0:
            return jsonify({"error": "No se puede cambiar el producto de la OT: ya tiene novedades, lotes vinculados o producción declarada. Cancelá o revertí esa actividad antes de cambiar el producto."}), 400
        n_pl = _n_bloques_planificados(oid)
        if n_pl:
            return jsonify({"error": f"No se puede cambiar el producto de la OT: tiene {n_pl} bloque/s en el Scheduling de producción. Quitalos de la planificación antes de cambiar el producto."}), 400

    # ── Completar la OT: no confirmar el estado hasta que todo salga bien ─────
    # Antes, el UPDATE de abajo grababa estado='Completada' de entrada, y el
    # descuento de stock / generación del lote de PT se hacían DESPUÉS, cada
    # uno con su propio commit. Si algo fallaba a mitad de camino (una
    # excepción en el descuento o en la generación del PT), la OT quedaba
    # guardada como "Completada" en la base aunque el stock nunca se hubiera
    # descontado ni el lote de PT se hubiera generado — y como ya figuraba
    # "Completada", un reintento (incluso revirtiendo a "En proceso" y volviendo
    # a completar) volvía a chocar con el mismo error, dejando la OT trabada.
    # Para evitarlo: si la OT recién está pasando a "Completada", el UPDATE
    # principal graba el estado ANTERIOR (no toca nada más), y solo al final,
    # una vez que el descuento de stock y la generación del PT terminaron sin
    # errores, se confirma el cambio a "Completada" en un último UPDATE.
    completando_ahora = nuevo_estado == "Completada" and not ya_estaba_completada_chk
    estado_a_grabar = (orden_actual["estado"] if orden_actual else "Pendiente") if completando_ahora else nuevo_estado

    execute("UPDATE ordenes SET cliente_id=?,producto_id=?,descripcion=?,detalle=?,cantidad=?,prioridad=?,estado=?,fecha_inicio=?,fecha_entrega=?,costo_mat=?,costo_mo=?,precio_venta=0,obs=?,actualizado=datetime('now','localtime') WHERE id=?",
        (d.get("cliente_id"),d["producto_id"],descripcion,d.get("detalle"),d.get("cantidad",1),d.get("prioridad","Normal"),estado_a_grabar,d.get("fecha_inicio"),d.get("fecha_entrega"),d.get("costo_mat",0),d.get("costo_mo",0),d.get("obs"),oid))

    # Punto 4 (v147): flag "requiere materia prima" de la OT. Solo se toca si el
    # body lo trae (el cambio rápido de estado no lo manda).
    if "requiere_material" in d:
        nuevo_rm = 1 if str(d.get("requiere_material")) in ("1","True","true") else 0
        actual_rm = query("SELECT requiere_material FROM ordenes WHERE id=?", (oid,), one=True)
        actual_rm = 1 if (actual_rm is None or actual_rm["requiere_material"] is None) else int(actual_rm["requiere_material"])
        if nuevo_rm != actual_rm:
            lotes_v = query("SELECT COUNT(*) c FROM orden_lotes WHERE orden_id=?", (oid,), one=True)["c"]
            if lotes_v > 0:
                return jsonify({"error": "No se puede cambiar 'Requiere materia prima': la OT ya tiene lotes vinculados."}), 400
            execute("UPDATE ordenes SET requiere_material=? WHERE id=?", (nuevo_rm, oid))
            if not cambia_producto:
                _populate_orden_materiales(oid)

    # Al cambiar el producto (sin actividad previa), regenerar operaciones y
    # materiales requeridos para que reflejen la ruta del producto nuevo.
    if cambia_producto:
        _populate_orden_operaciones(oid)
        _populate_orden_materiales(oid)

    # ── Descontar stock de materiales al completar la OT ──────────────────────
    # Solo importa si ya se descontó o no (stock_descontado). NO alcanza con
    # mirar si el estado anterior ya era "Completada": si la OT quedó cargada
    # como Completada de entrada (ej. datos migrados/de prueba) sin pasar
    # nunca por este descuento, stock_descontado sigue en 0 y hay que
    # generarlo igual la próxima vez que se guarde la OT.
    ya_descontado = orden_actual and int(orden_actual["stock_descontado"] or 0) == 1

    # Todo lo que sigue (descuento de stock + generación del lote de PT) se
    # ejecuta dentro de un try/except: si algo falla acá, la OT NO debe quedar
    # confirmada como "Completada" (ver estado_a_grabar más arriba), para que
    # el usuario reciba el error real y pueda reintentar sin quedar trabado.
    try:
        if nuevo_estado == "Completada" and not ya_descontado:
            numero_ot = orden_actual["numero"] if orden_actual else str(oid)

            # NOTA: los materiales/PT que llevan lote YA se descuentan del
            # stock y del lote en el momento en que se declara cada novedad
            # (ver create_novedad), no acá. Antes este bloque volvía a
            # descontar cantidad_disponible/cantidad_activa/stock a partir
            # de orden_lotes.cantidad_usada al completar la OT, lo que
            # duplicaba el descuento (una vez por novedad + una vez acá).
            # Se deja el flag stock_descontado en 1 igual, para no romper
            # la idempotencia de este bloque ni la lógica de PT de abajo.
            execute("UPDATE ordenes SET stock_descontado=1 WHERE id=?", (oid,))

            # ── Insumos (sin lote): descuento directo del stock general ──────────
            # A diferencia de los materiales con lote, los insumos no se validan
            # ni descuentan al declarar la novedad (ver create_novedad). Acá se
            # calcula el consumo total a partir de lo realmente producido en cada
            # operación de la OT (qty_producida) por la cantidad unitaria definida
            # en operacion_materiales, y se descuenta de una sola vez al completar.
            insumos = query("""
                SELECT om.material_id, m.codigo, m.descripcion,
                       SUM(cant_material(om.cantidad, oo.qty_producida, om.vida_util_herramienta)) consumo
                FROM orden_operaciones oo
                JOIN orden_operacion_materiales om ON om.orden_operacion_id=oo.id
                JOIN materiales m ON m.id=om.material_id
                WHERE oo.orden_id=? AND m.categoria IN ('Insumo','Herramienta')
                GROUP BY om.material_id
            """, (oid,))
            for ins in insumos:
                consumo = float(ins["consumo"] or 0)
                if consumo <= 0:
                    continue
                execute("""UPDATE materiales
                    SET stock=MAX(0, stock-?), actualizado=datetime('now','localtime')
                    WHERE id=?""", (consumo, ins["material_id"]))
                auto_generar_sc_bajo_stock(ins["material_id"], f"consumo insumos OT {numero_ot}")
                execute("""INSERT INTO movimientos
                    (material_id, lote_id, tipo, cantidad, referencia, usuario_id)
                    VALUES (?, NULL, 'salida', ?, ?, ?)""",
                    (ins["material_id"], consumo,
                     f"Consumo OT {numero_ot} — Insumo {ins['codigo']} (sin lote)",
                     session["user_id"]))

        # ── Red de seguridad: asegurar que el PT quede generado ──────────────────
        # Se ejecuta SIEMPRE que la OT quede en estado "Completada", incluso si
        # stock_descontado ya estaba en 1 (ej: la OT ya se había completado antes
        # y se vuelve a guardar). La función es idempotente: calcula cuánto PT ya
        # existe en el lote OT-N y solo agrega lo que falte hasta la cantidad
        # total de la OT, así que no duplica nada.
        if nuevo_estado == "Completada":
            generar_pt_faltante_si_corresponde(oid)
            if completando_ahora:
                _consumir_pse_sobrante_ot(oid)
            # Si quedó un cajón "Abierto" (parcialmente lleno) para esta OT,
            # se cierra igual: al completarse la OT no van a llegar más
            # piezas para terminar de llenarlo, así que pasa a "Ingresado"
            # (pendiente de Calidad) con lo que tenga hasta ahora.
            numero_ot_cierre = orden_actual["numero"] if orden_actual else str(oid)
            execute("UPDATE lotes SET estado='Ingresado' WHERE estado='Abierto' AND numero LIKE ?",
                (numero_ot_cierre + "-C%",))
    except Exception as e:
        # Algo falló al descontar stock o generar el lote de PT: NO confirmar
        # la OT como "Completada" (ya quedó grabada con su estado anterior más
        # arriba), para que el usuario vea el error real y pueda reintentar
        # sin que la OT quede en un limbo "Completada" sin stock ni lote.
        return jsonify({"error": f"No se pudo completar la OT: {e}"}), 500

    # Recién acá, con el descuento de stock y la generación del PT ya
    # confirmados sin errores, se graba el cambio de estado a "Completada".
    if completando_ahora:
        execute("UPDATE ordenes SET estado='Completada' WHERE id=?", (oid,))

    # Si se revierte de Completada a otro estado, restaurar el stock
    if orden_actual and orden_actual["estado"] == "Completada" and nuevo_estado != "Completada" and ya_descontado:
        numero_ot = orden_actual["numero"] if orden_actual else str(oid)

        # NOTA IMPORTANTE: los materiales/PT que llevan LOTE ya NO se
        # reversan acá. Desde que el descuento de esos materiales pasó a
        # hacerse al instante en cada novedad (ver create_novedad, descuento
        # inmediato), completar la OT NUNCA vuelve a descontar ese stock —
        # por lo tanto reabrir la OT (revertir de "Completada") tampoco debe
        # devolverlo. Antes este bloque SÍ lo devolvía (cantidad_disponible,
        # cantidad_activa y, peor, cantidad_reservada) basándose en
        # orden_lotes.cantidad_usada, como si el completar hubiera vuelto a
        # descontarlo — lo cual generaba stock/reserva fantasma cada vez que
        # se reabría y volvía a completar una OT (bug reportado: reservado
        # que crecía sin corresponder a ningún consumo real). El único lugar
        # que debe tocar cantidad_reservada/cantidad_disponible/activa de un
        # lote por consumo de OT es create_novedad, en el momento en que se
        # declara cada novedad real.
        execute("UPDATE ordenes SET stock_descontado=0 WHERE id=?", (oid,))

        # ── Reversión de insumos (sin lote) ───────────────────────────────────
        insumos_rev = query("""
            SELECT om.material_id, m.codigo,
                   SUM(cant_material(om.cantidad, oo.qty_producida, om.vida_util_herramienta)) consumo
            FROM orden_operaciones oo
            JOIN orden_operacion_materiales om ON om.orden_operacion_id=oo.id
            JOIN materiales m ON m.id=om.material_id
            WHERE oo.orden_id=? AND m.categoria IN ('Insumo','Herramienta')
            GROUP BY om.material_id
        """, (oid,))
        for ins in insumos_rev:
            consumo = float(ins["consumo"] or 0)
            if consumo <= 0:
                continue
            execute("""UPDATE materiales
                SET stock=stock+?, actualizado=datetime('now','localtime')
                WHERE id=?""", (consumo, ins["material_id"]))
            execute("""INSERT INTO movimientos
                (material_id, lote_id, tipo, cantidad, referencia, usuario_id)
                VALUES (?, NULL, 'entrada', ?, ?, ?)""",
                (ins["material_id"], consumo,
                 f"Reversión OT {numero_ot} — Insumo {ins['codigo']} (estado cambiado a {nuevo_estado})",
                 session["user_id"]))

    # ── Cancelar la OT: desvincular lotes de materiales ya asignados ──────────
    # Al cancelar, cualquier lote vinculado a esta OT (por "Asignar lote" o
    # automáticamente al declarar una novedad) debe desvincularse, INCLUSO si
    # ya se consumió parte del material desde ese lote. Se libera la reserva
    # pendiente que pudiera quedar sobre el lote (cantidad_reservada) para
    # que vuelva a estar disponible para otras OTs; el material que ya se
    # descontó como consumo real (stock/cantidad_activa) NO se devuelve acá
    # — desvincular no es lo mismo que reponer stock ya gastado.
    ya_estaba_cancelada = orden_actual and orden_actual["estado"] == "Cancelada"
    if nuevo_estado == "Cancelada" and not ya_estaba_cancelada:
        vinculos = query("SELECT * FROM orden_lotes WHERE orden_id=?", (oid,))
        for v in vinculos:
            execute("UPDATE lotes SET cantidad_reservada=MAX(0, COALESCE(cantidad_reservada,0)-?) WHERE id=?",
                (float(v["cantidad_usada"] or 0), v["lote_id"]))
        execute("DELETE FROM orden_lotes WHERE orden_id=?", (oid,))
        execute("UPDATE orden_materiales SET cantidad_asignada=0 WHERE orden_id=?", (oid,))
        # Los cajones que todavía no terminaron ninguna pieza quedan En espera
        # para pasarlos a otra OT abierta del mismo producto (o darlos de baja).
        for c in query("SELECT * FROM cajones WHERE orden_id=? AND estado='En proceso'", (oid,)):
            if _cajon_terminadas(c) <= 0.0001:
                execute("UPDATE cajones SET estado='En espera' WHERE id=?", (c["id"],))
        # Las OTT que todavía no salieron al proveedor (sin envíos) se
        # cancelan junto con la OT; las que ya tienen piezas afuera quedan
        # como están para poder recibirlas de vuelta.
        execute("""UPDATE ordenes_tercerizado SET estado='Cancelado'
            WHERE ot_origen_id=? AND estado='Pendiente' AND COALESCE(cantidad_enviada,0)=0""", (oid,))
    elif ya_estaba_cancelada and nuevo_estado != "Cancelada":
        # Se reactiva la OT: sus OTT canceladas sin envíos vuelven a Pendiente.
        execute("""UPDATE ordenes_tercerizado SET estado='Pendiente'
            WHERE ot_origen_id=? AND estado='Cancelado' AND COALESCE(cantidad_enviada,0)=0""", (oid,))
        # y sus cajones en espera (los que no se pasaron a otra OT) vuelven.
        for c in query("SELECT id FROM cajones WHERE orden_id=? AND estado='En espera'", (oid,)):
            execute("UPDATE cajones SET estado='En proceso' WHERE id=?", (c["id"],))
            _cajon_recalcular(c["id"])

    return jsonify({"ok":True})

# ── Presupuestos ──────────────────────────────────────────────────────────────
@app.route("/api/presupuestos", methods=["GET"])
@login_required()
def get_presupuestos():
    return jsonify([dict(r) for r in query("SELECT p.*,c.razon cliente_nombre FROM presupuestos p LEFT JOIN clientes c ON c.id=p.cliente_id ORDER BY p.id DESC")])

@app.route("/api/presupuestos", methods=["POST"])
@login_required(roles=["admin","vendedor"])
def create_presupuesto():
    d = request.json
    if not d.get("cliente_id"): return jsonify({"error":"Cliente requerido"}), 400
    d["descripcion"] = d.get("descripcion") or f"Presupuesto para cliente {d['cliente_id']}"
    numero = siguiente_numero("presupuestos", "PRES-", 3)
    sub = float(d.get("subtotal", 0))
    iva = float(d.get("iva_pct", 21))
    total = float(d.get("total")) if d.get("total") else sub * (1 + iva/100)
    if not sub and total: sub = total / (1 + iva/100)
    lid = execute("INSERT INTO presupuestos (numero,cliente_id,descripcion,items,subtotal,iva_pct,total,validez_dias,estado,obs) VALUES (?,?,?,?,?,?,?,?,?,?)",
        (numero,d.get("cliente_id"),d["descripcion"],d.get("items"),sub,iva,total,d.get("validez_dias",30),d.get("estado","Borrador"),d.get("obs")))
    return jsonify({"ok":True,"id":lid,"numero":numero,"total":total}), 201

# ── Pedidos de cotización (pestaña de Presupuestos) ──────────────────────────
def _validar_pedido_cotizacion(d, actual=None):
    """Devuelve (valores, None) o (None, mensaje de error). En una edición,
    lo que no viene en el payload conserva el valor actual (un usuario sin
    ver_monetario no manda precio_total: se descarta en before_request)."""
    v = dict(actual) if actual else {}
    for k in ("fecha", "cliente_id", "producto_id", "cantidad", "precio_total"):
        if k in d:
            v[k] = d[k]
    if not v.get("cliente_id") or not query("SELECT 1 FROM clientes WHERE id=?", (v["cliente_id"],), one=True):
        return None, "Cliente requerido"
    if not v.get("producto_id"):
        return None, "Producto requerido"
    prod = query("SELECT categoria FROM materiales WHERE id=?", (v["producto_id"],), one=True)
    if not prod or prod["categoria"] != "Producto terminado":
        return None, ("Solo se pueden cotizar productos terminados — materiales, insumos, "
                      "herramientas y semielaborados no se cotizan a clientes")
    try:
        v["cantidad"] = float(v.get("cantidad") or 0)
    except (TypeError, ValueError):
        v["cantidad"] = 0
    if v["cantidad"] <= 0:
        return None, "La cantidad de piezas debe ser mayor a 0"
    if v.get("precio_total") in ("", None):
        v["precio_total"] = None
    else:
        try:
            v["precio_total"] = float(v["precio_total"])
        except (TypeError, ValueError):
            return None, "Precio total inválido"
        if v["precio_total"] < 0:
            return None, "El precio total no puede ser negativo"
    v["fecha"] = (v.get("fecha") or date.today().isoformat())[:10]
    return v, None


@app.route("/api/pedidos_cotizacion", methods=["GET"])
@login_required()
def get_pedidos_cotizacion():
    return jsonify([dict(r) for r in query("""SELECT pc.*, c.razon cliente_nombre,
            m.codigo producto_codigo, m.descripcion producto_nombre, m.unidad producto_unidad
        FROM pedidos_cotizacion pc
        LEFT JOIN clientes c ON c.id=pc.cliente_id
        LEFT JOIN materiales m ON m.id=pc.producto_id
        ORDER BY pc.id DESC""")])


@app.route("/api/pedidos_cotizacion", methods=["POST"])
@login_required(roles=["admin","vendedor"])
def create_pedido_cotizacion():
    v, err = _validar_pedido_cotizacion(request.json or {})
    if err: return jsonify({"error": err}), 400
    numero = siguiente_numero("pedidos_cotizacion", "PCOT-", 4, reservar=True)
    lid = execute("""INSERT INTO pedidos_cotizacion
        (numero,fecha,cliente_id,producto_id,cantidad,precio_total,creado_por)
        VALUES (?,?,?,?,?,?,?)""",
        (numero, v["fecha"], v["cliente_id"], v["producto_id"], v["cantidad"],
         v["precio_total"], session.get("user_id")))
    return jsonify({"ok": True, "id": lid, "numero": numero}), 201


@app.route("/api/pedidos_cotizacion/<int:pid>", methods=["PUT"])
@login_required(roles=["admin","vendedor"])
def update_pedido_cotizacion(pid):
    actual = query("SELECT * FROM pedidos_cotizacion WHERE id=?", (pid,), one=True)
    if not actual: return jsonify({"error": "Pedido de cotización no encontrado"}), 404
    v, err = _validar_pedido_cotizacion(request.json or {}, actual)
    if err: return jsonify({"error": err}), 400
    execute("""UPDATE pedidos_cotizacion SET fecha=?,cliente_id=?,producto_id=?,
        cantidad=?,precio_total=? WHERE id=?""",
        (v["fecha"], v["cliente_id"], v["producto_id"], v["cantidad"], v["precio_total"], pid))
    return jsonify({"ok": True})


@app.route("/api/pedidos_cotizacion/<int:pid>", methods=["DELETE"])
@login_required(roles=["admin","vendedor"])
def delete_pedido_cotizacion(pid):
    if not query("SELECT 1 FROM pedidos_cotizacion WHERE id=?", (pid,), one=True):
        return jsonify({"error": "Pedido de cotización no encontrado"}), 404
    execute("DELETE FROM pedidos_cotizacion WHERE id=?", (pid,))
    return jsonify({"ok": True})

# ── Pronósticos de venta ───────────────────────────────────────────────────────
@app.route("/api/pronosticos_venta", methods=["GET"])
@login_required()
def get_pronosticos_venta():
    return jsonify([dict(r) for r in query("""
        SELECT p.*, cl.razon cliente_nombre
        FROM pronosticos_venta p
        LEFT JOIN clientes cl ON cl.id=p.cliente_id
        ORDER BY p.id DESC""")])

@app.route("/api/pronosticos_venta", methods=["POST"])
@login_required()
def create_pronostico_venta():
    d = request.json or {}
    codigo = (d.get("codigo") or "").strip()
    fecha_emision = d.get("fecha_emision")
    periodos = d.get("periodos")
    cliente_id = d.get("cliente_id") or None
    if not codigo: return jsonify({"error":"Código requerido"}), 400
    if not fecha_emision: return jsonify({"error":"Fecha de emisión requerida"}), 400
    try: periodos = int(periodos)
    except (TypeError, ValueError): return jsonify({"error":"Periodos inválido"}), 400
    if periodos <= 0: return jsonify({"error":"Periodos inválido"}), 400
    if cliente_id:
        try: cliente_id = int(cliente_id)
        except (TypeError, ValueError): return jsonify({"error":"Cliente inválido"}), 400
        if not query("SELECT id FROM clientes WHERE id=?", (cliente_id,), one=True):
            return jsonify({"error":"Cliente no encontrado"}), 400
    if query("SELECT id FROM pronosticos_venta WHERE codigo=?", (codigo,), one=True):
        return jsonify({"error":"Ya existe un pronóstico con ese código"}), 409
    estado = d.get("estado") or "Alta"
    if estado not in ("Alta","Baja"): estado = "Alta"

    pid = execute("INSERT INTO pronosticos_venta (codigo,estado,fecha_emision,periodos,cliente_id) VALUES (?,?,?,?,?)",
        (codigo, estado, fecha_emision, periodos, cliente_id))

    # Generar los meses del periodo a partir de fecha_emision, y crear una
    # fila (cantidad 0) por cada producto activo x mes, para que la tabla
    # se pueda editar directamente. Si se eligió un cliente, el pronóstico
    # solo toma los productos de ese cliente.
    try:
        base = datetime.strptime(fecha_emision[:10], "%Y-%m-%d")
    except ValueError:
        base = datetime.now()
    meses = []
    y, m = base.year, base.month
    for i in range(periodos):
        mm = ((m - 1 + i) % 12) + 1
        yy = y + ((m - 1 + i) // 12)
        meses.append(f"{yy:04d}-{mm:02d}")

    if cliente_id:
        productos = query("SELECT id FROM productos WHERE activo=1 AND tipo_articulo='Producto terminado' AND cliente_id=?", (cliente_id,))
    else:
        productos = query("SELECT id FROM productos WHERE activo=1 AND tipo_articulo='Producto terminado'")
    rows = [(pid, p["id"], mes, 0) for p in productos for mes in meses]
    if rows:
        db = get_db()
        db.executemany("INSERT OR IGNORE INTO pronostico_venta_items (pronostico_id,producto_id,mes,cantidad) VALUES (?,?,?,?)", rows)
        db.commit()

    return jsonify({"ok":True,"id":pid}), 201

@app.route("/api/pronosticos_venta/<int:pid>", methods=["PUT"])
@login_required()
def update_pronostico_venta(pid):
    d = request.json or {}
    p = query("SELECT * FROM pronosticos_venta WHERE id=?", (pid,), one=True)
    if not p: return jsonify({"error":"No encontrado"}), 404
    estado = d.get("estado", p["estado"])
    if estado not in ("Alta","Baja"): return jsonify({"error":"Estado inválido"}), 400
    execute("UPDATE pronosticos_venta SET estado=? WHERE id=?", (estado, pid))
    return jsonify({"ok":True})

@app.route("/api/pronosticos_venta/<int:pid>", methods=["DELETE"])
@login_required()
def delete_pronostico_venta(pid):
    execute("DELETE FROM pronosticos_venta WHERE id=?", (pid,))
    return jsonify({"ok":True})

@app.route("/api/pronosticos_venta/<int:pid>/tabla", methods=["GET"])
@login_required()
def get_pronostico_venta_tabla(pid):
    p = query("""SELECT p.*, cl.razon cliente_nombre
        FROM pronosticos_venta p
        LEFT JOIN clientes cl ON cl.id=p.cliente_id
        WHERE p.id=?""", (pid,), one=True)
    if not p: return jsonify({"error":"No encontrado"}), 404
    meses = [r["mes"] for r in query(
        "SELECT DISTINCT mes FROM pronostico_venta_items WHERE pronostico_id=? ORDER BY mes", (pid,))]
    filas = query("""
        SELECT pr.id producto_id, pr.codigo, pr.nombre, pr.unidad, pr.precio_venta, i.mes, i.cantidad,
               cl.razon cliente
        FROM pronostico_venta_items i
        JOIN productos pr ON pr.id=i.producto_id
        LEFT JOIN clientes cl ON cl.id=pr.cliente_id
        WHERE i.pronostico_id=?
        ORDER BY pr.codigo, i.mes""", (pid,))
    productos = {}
    for f in filas:
        pr = productos.setdefault(f["producto_id"], {
            "producto_id": f["producto_id"], "codigo": f["codigo"],
            "nombre": f["nombre"], "unidad": f["unidad"],
            "cliente": f["cliente"], "precio_venta": f["precio_venta"], "cantidades": {}})
        pr["cantidades"][f["mes"]] = f["cantidad"]
    return jsonify({"pronostico": dict(p), "meses": meses, "productos": list(productos.values())})

@app.route("/api/pronosticos_venta/<int:pid>/items", methods=["PUT"])
@login_required()
def update_pronostico_venta_items(pid):
    d = request.json or {}
    items = d.get("items") or []
    for it in items:
        execute("""UPDATE pronostico_venta_items SET cantidad=?
                   WHERE pronostico_id=? AND producto_id=? AND mes=?""",
            (float(it.get("cantidad") or 0), pid, it["producto_id"], it["mes"]))
    return jsonify({"ok":True})

# ── Usuarios ──────────────────────────────────────────────────────────────────
@app.route("/api/usuarios", methods=["GET"])
@login_required(roles=["admin"])
def get_usuarios():
    return jsonify([dict(r) for r in query("SELECT id,username,nombre,rol,activo,creado FROM usuarios ORDER BY nombre")])

@app.route("/api/usuarios", methods=["POST"])
@login_required(roles=["admin"])
def create_usuario():
    d = request.json
    if not d.get("username") or not d.get("password"): 
        return jsonify({"error":"Username y contraseña requeridos"}), 400
    if query("SELECT id FROM usuarios WHERE username=?", (d["username"],), one=True): 
        return jsonify({"error":"Usuario ya existe"}), 409
    
    rol = d.get("rol", "operario")
    if not _rol_row(rol):
        return jsonify({"error": f"El rol \"{rol}\" no existe. Crealo antes en Configuración → Roles."}), 400
    
    # Crear el usuario
    execute("INSERT INTO usuarios (username,password,nombre,rol) VALUES (?,?,?,?)",
            (d["username"], hash_pw(d["password"]), d.get("nombre", d["username"]), rol))
    
    # Obtener el ID del usuario recién creado
    usuario_id = query("SELECT id FROM usuarios WHERE username=?", (d["username"],), one=True)["id"]
    
    # Asignar permisos predeterminados según el rol
    # Admin no necesita permisos explícitos (tiene acceso total)
    if rol != "admin":
        for clave, valor in _permisos_rol(rol).items():
            execute("""INSERT OR IGNORE INTO usuario_permisos (usuario_id, clave, valor) 
                      VALUES (?, ?, ?)""",
                    (usuario_id, clave, valor))
    
    return jsonify({"ok": True}), 201

@app.route("/api/usuarios/<int:uid>", methods=["PUT"])
@login_required(roles=["admin"])
def update_usuario(uid):
    d = request.json
    if not query("SELECT id FROM usuarios WHERE id=?", (uid,), one=True):
        return jsonify({"error":"Usuario no encontrado"}), 404
    dup = query("SELECT id FROM usuarios WHERE username=? AND id<>?", (d.get("username",""), uid), one=True)
    if dup:
        return jsonify({"error":"Usuario ya existe"}), 409

    nombre = d.get("nombre") or d.get("username","")
    rol = d.get("rol", "operario")
    if not _rol_row(rol):
        return jsonify({"error": f"El rol \"{rol}\" no existe. Crealo antes en Configuración → Roles."}), 400
    activo = 1 if d.get("activo", 1) else 0
    _rol_previo = query("SELECT rol FROM usuarios WHERE id=?", (uid,), one=True)["rol"]

    if d.get("password"):
        execute("UPDATE usuarios SET username=?,nombre=?,rol=?,activo=?,password=? WHERE id=?",
                (d["username"], nombre, rol, activo, hash_pw(d["password"]), uid))
    else:
        execute("UPDATE usuarios SET username=?,nombre=?,rol=?,activo=? WHERE id=?",
                (d["username"], nombre, rol, activo, uid))

    # Si cambió el rol, el usuario recibe los permisos predeterminados del rol nuevo.
    if rol != _rol_previo and rol != "admin":
        execute("DELETE FROM usuario_permisos WHERE usuario_id=?", (uid,))
        for clave, valor in _permisos_rol(rol).items():
            execute("INSERT OR IGNORE INTO usuario_permisos (usuario_id,clave,valor) VALUES (?,?,?)", (uid, clave, valor))

    return jsonify({"ok": True})

# ── Roles editables (v147, punto 12) ─────────────────────────────────────────
@app.route("/api/roles", methods=["GET"])
@login_required()
def get_roles():
    import json as _j
    out = []
    for r in query("SELECT * FROM roles ORDER BY es_sistema DESC, nombre"):
        d = dict(r)
        try: d["permisos"] = _j.loads(d.get("permisos") or "{}")
        except Exception: d["permisos"] = {}
        d["usuarios"] = query("SELECT COUNT(*) c FROM usuarios WHERE rol=? AND activo=1", (d["nombre"],), one=True)["c"]
        out.append(d)
    return jsonify(out)

@app.route("/api/roles", methods=["POST"])
@login_required(roles=["admin"])
def create_rol():
    import json as _j
    d = request.json or {}
    nombre = (d.get("nombre") or "").strip().lower().replace(" ", "_")
    if not nombre: return jsonify({"error":"Nombre requerido"}), 400
    if d.get("base_rol") not in ROLES_BASE: return jsonify({"error":"Rol base inválido"}), 400
    if _rol_row(nombre): return jsonify({"error":"Ya existe un rol con ese nombre"}), 409
    permisos = {k: str(v) for k, v in (d.get("permisos") or {}).items()}
    rid = execute("INSERT INTO roles (nombre,descripcion,base_rol,permisos,es_sistema) VALUES (?,?,?,?,0)",
                  (nombre, d.get("descripcion"), d["base_rol"], _j.dumps(permisos)))
    return jsonify({"ok":True,"id":rid,"nombre":nombre}), 201

@app.route("/api/roles/<int:rid>", methods=["PUT"])
@login_required(roles=["admin"])
def update_rol(rid):
    import json as _j
    d = request.json or {}
    r = query("SELECT * FROM roles WHERE id=?", (rid,), one=True)
    if not r: return jsonify({"error":"Rol no encontrado"}), 404
    permisos = {k: str(v) for k, v in (d.get("permisos") or {}).items()} if "permisos" in d else None
    if r["es_sistema"]:
        # los roles de sistema conservan nombre y rol base; solo se editan descripción y permisos
        execute("UPDATE roles SET descripcion=?, permisos=COALESCE(?,permisos) WHERE id=?",
                (d.get("descripcion", r["descripcion"]), _j.dumps(permisos) if permisos is not None else None, rid))
        return jsonify({"ok":True})
    nuevo = (d.get("nombre") or r["nombre"]).strip().lower().replace(" ", "_")
    base = d.get("base_rol", r["base_rol"])
    if base not in ROLES_BASE: return jsonify({"error":"Rol base inválido"}), 400
    if nuevo != r["nombre"] and _rol_row(nuevo): return jsonify({"error":"Ya existe un rol con ese nombre"}), 409
    execute("UPDATE roles SET nombre=?,descripcion=?,base_rol=?,permisos=COALESCE(?,permisos) WHERE id=?",
            (nuevo, d.get("descripcion", r["descripcion"]), base, _j.dumps(permisos) if permisos is not None else None, rid))
    if nuevo != r["nombre"]:
        execute("UPDATE usuarios SET rol=? WHERE rol=?", (nuevo, r["nombre"]))
    return jsonify({"ok":True})

@app.route("/api/roles/<int:rid>/aplicar_permisos", methods=["POST"])
@login_required(roles=["admin"])
def aplicar_permisos_rol(rid):
    """Copia los permisos del rol a todos sus usuarios (reemplaza los individuales)."""
    r = query("SELECT * FROM roles WHERE id=?", (rid,), one=True)
    if not r: return jsonify({"error":"Rol no encontrado"}), 404
    if r["nombre"] == "admin": return jsonify({"ok":True,"usuarios":0})
    n = 0
    for u in query("SELECT id FROM usuarios WHERE rol=?", (r["nombre"],)):
        execute("DELETE FROM usuario_permisos WHERE usuario_id=?", (u["id"],))
        for clave, valor in _permisos_rol(r["nombre"]).items():
            execute("INSERT OR IGNORE INTO usuario_permisos (usuario_id,clave,valor) VALUES (?,?,?)", (u["id"], clave, valor))
        n += 1
    return jsonify({"ok":True,"usuarios":n})

@app.route("/api/roles/<int:rid>", methods=["DELETE"])
@login_required(roles=["admin"])
def delete_rol(rid):
    r = query("SELECT * FROM roles WHERE id=?", (rid,), one=True)
    if not r: return jsonify({"error":"Rol no encontrado"}), 404
    if r["es_sistema"]: return jsonify({"error":"Los roles de sistema no se pueden eliminar"}), 400
    en_uso = query("SELECT COUNT(*) c FROM usuarios WHERE rol=?", (r["nombre"],), one=True)["c"]
    if en_uso: return jsonify({"error":f"El rol está asignado a {en_uso} usuario(s). Reasignalos antes de eliminarlo."}), 400
    execute("DELETE FROM roles WHERE id=?", (rid,))
    return jsonify({"ok":True})

@app.route("/api/usuarios/<int:uid>", methods=["DELETE"])
@login_required(roles=["admin"])
def delete_usuario(uid):
    if uid == session["user_id"]: return jsonify({"error":"No podés eliminar tu propio usuario"}), 400
    execute("UPDATE usuarios SET activo=0 WHERE id=?", (uid,))
    return jsonify({"ok":True})


# ── Operaciones de OT (desglose en renglones) ─────────────────────────────────
@app.route("/api/ordenes/<int:oid>/operaciones", methods=["GET"])
@login_required()
def get_orden_operaciones(oid):
    rows = query("""SELECT oo.*,cm.nombre cat_maquina_nombre,m.nombre maquina_nombre,
        p.razon proveedor_nombre, ott.id ott_id
        FROM orden_operaciones oo
        LEFT JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
        LEFT JOIN maquinas m ON m.id=oo.maquina_id
        LEFT JOIN proveedores p ON p.id=oo.proveedor_id
        LEFT JOIN ordenes_tercerizado ott ON ott.operacion_id=oo.id
        WHERE oo.orden_id=? ORDER BY CAST(oo.orden AS INTEGER), oo.orden""", (oid,))
    out = [dict(r) for r in rows]
    # Una operación queda bloqueada para revertir su estado (una vez
    # Completada) si depende de una tercerización previa en la misma OT
    # (ver _tiene_terc_previa) — el resto se puede revertir libremente.
    for r in out:
        try:
            orden_num = int(r["orden"])
        except Exception:
            orden_num = None
        r["depende_terc_previa"] = orden_num is not None and any(
            o.get("es_tercerizada") for o in out
            if o is not r and _orden_int(o.get("orden")) is not None and _orden_int(o.get("orden")) < orden_num
        )
    return jsonify(out)

def _orden_int(v):
    try:
        return int(v)
    except Exception:
        return None

def _motivo_no_repoblar(oid):
    """Por qué NO se puede regenerar las operaciones de esta OT, o None.

    Regenerar borra y rehace orden_operaciones. Eso es inofensivo mientras la
    OT no arrancó, pero deja de serlo en cuanto hay trabajo declarado o
    piezas en la calle:

      · Novedades declaradas: novedades_produccion referencia la operación
        con ON DELETE NO ACTION, así que el DELETE fallaba con un
        "FOREIGN KEY constraint failed" y el endpoint devolvía un 500 sin
        explicación. Además, borrar la operación perdería la producción.
      · OTT ya en movimiento: la tercerizada referencia la operación con
        ON DELETE SET NULL, así que el DELETE pasaba pero dejaba la OTT
        huérfana, apuntando a nada, con piezas ya remitidas al proveedor.
    """
    n_nov = query("""SELECT COUNT(*) c FROM novedades_produccion nov
        JOIN orden_operaciones oo ON oo.id=nov.orden_operacion_id
        WHERE oo.orden_id=?""", (oid,), one=True)["c"]
    if n_nov:
        return ("La OT ya tiene producción declarada (%d novedad/es): no se pueden "
                "regenerar sus operaciones sin perder ese trabajo." % n_nov)
    en_curso = query("""SELECT numero, estado FROM ordenes_tercerizado
        WHERE ot_origen_id=? AND (COALESCE(cantidad_enviada,0) > 0
              OR estado NOT IN ('Pendiente','Anulada'))
        LIMIT 1""", (oid,), one=True)
    if en_curso:
        return ("La OT tiene una orden de tercerizado en curso (%s, %s): no se pueden "
                "regenerar sus operaciones." % (en_curso["numero"], en_curso["estado"]))
    # La planificación cuelga de orden_operaciones con ON DELETE CASCADE:
    # regenerar borraría en silencio todos los bloques del Scheduling.
    n_pl = _n_bloques_planificados(oid)
    if n_pl:
        return ("La OT tiene %d bloque/s en el Scheduling de producción: quitalos de la "
                "planificación antes de regenerar sus operaciones." % n_pl)
    return None


def _n_bloques_planificados(oid, opid=None):
    sql = """SELECT COUNT(*) c FROM planificacion pl
        JOIN orden_operaciones oo ON oo.id=pl.orden_operacion_id WHERE oo.orden_id=?"""
    args = [oid]
    if opid is not None:
        sql += " AND oo.id=?"
        args.append(opid)
    return query(sql, tuple(args), one=True)["c"]


def _populate_orden_operaciones(oid):
    """Borra y regenera orden_operaciones a partir del producto actual de la OT.
    Función interna reutilizada por el endpoint POST y por update_orden cuando
    se cambia el producto de una OT existente.

    Devuelve la cantidad de operaciones creadas, None si la OT no tiene
    producto, o el string con el motivo si no se puede regenerar."""
    orden = query("SELECT producto_id FROM ordenes WHERE id=?", (oid,), one=True)
    if not orden or not orden["producto_id"]: return None
    motivo = _motivo_no_repoblar(oid)
    if motivo:
        return motivo
    # Las OTT que todavía no se movieron se borran junto con las operaciones:
    # si no, quedarían apuntando a nada (ON DELETE SET NULL) y después
    # _generar_ott_para_ot crearía otras, duplicándolas.
    execute("""DELETE FROM ordenes_tercerizado WHERE ot_origen_id=?
        AND COALESCE(cantidad_enviada,0)=0 AND estado IN ('Pendiente','Anulada')""", (oid,))
    execute("DELETE FROM orden_operaciones WHERE orden_id=?", (oid,))
    ops = query("""SELECT po.*,cm.nombre cat_maq FROM proceso_operaciones po
        LEFT JOIN categorias_maquina cm ON cm.id=po.categoria_maquina_id
        WHERE po.producto_id=? ORDER BY CAST(po.orden AS INTEGER), po.orden""", (orden["producto_id"],))
    qty = query("SELECT cantidad FROM ordenes WHERE id=?", (oid,), one=True)["cantidad"]
    for op in ops:
        # Volumen agrupado: si la operación agrupa el total a realizar en
        # lotes de tamaño "valor_recalculado", la cantidad requerida de esta
        # operación puntual pasa a ser ceil(total_ot / valor_recalculado) en
        # lugar del total de la OT. Ej: OT total=100, valor_recalculado=33 →
        # requerido=3.
        vol_agrup = op["volumen_agrupado"] if "volumen_agrupado" in op.keys() else 0
        valor_recalc = op["valor_recalculado"] if "valor_recalculado" in op.keys() else 0
        if vol_agrup and valor_recalc and valor_recalc > 0:
            qty_op = math.ceil(qty / valor_recalc)
        else:
            qty_op = qty
        _oo_nuevo = execute("""INSERT INTO orden_operaciones
            (orden_id,proceso_op_id,orden,nombre,categoria_maquina_id,maquina_id,
             tiempo_setup_min,tiempo_ciclo_seg,estado,qty_requerida,
             es_tercerizada,proveedor_id,precio_tercerizado,tiempo_minimo_dias)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (oid,op["id"],op["orden"],op["nombre"],op["categoria_maquina_id"],op["maquina_id"],
             op["tiempo_setup_min"],op["tiempo_ciclo_seg"],"Pendiente",qty_op,
             op["es_tercerizada"] if "es_tercerizada" in op.keys() else 0,
             op["proveedor_id"] if "proveedor_id" in op.keys() else None,
             op["precio_tercerizado"] if "precio_tercerizado" in op.keys() else 0,
             op["tiempo_minimo_dias"] if "tiempo_minimo_dias" in op.keys() else 0))
        _copiar_materiales_a_ot_op(_oo_nuevo, op["id"])
    # Auto-generate OTT para ops tercerizadas (ya no se genera SC acá: la
    # compra/gestión del servicio tercerizado se maneja desde la OTT).
    ot_row = query("SELECT numero FROM ordenes WHERE id=?", (oid,), one=True)
    if ot_row:
        _generar_ott_para_ot(oid, ot_row["numero"])

    return len(ops)


def _populate_orden_materiales(oid):
    """Borra y regenera orden_materiales a partir del producto actual de la OT."""
    orden = query("SELECT producto_id,cantidad,requiere_material FROM ordenes WHERE id=?", (oid,), one=True)
    if not orden or not orden["producto_id"]: return None
    execute("DELETE FROM orden_materiales WHERE orden_id=?", (oid,))
    # Herramientas con vida útil: ceil(piezas que procesa esa operación /
    # vida útil); el resto, cantidad por pieza x cantidad de la OT (como antes).
    mats = query("""SELECT om.material_id,
        SUM(CASE WHEN COALESCE(om.vida_util_herramienta,0)>0
            THEN cant_material(om.cantidad, oo.qty_requerida, om.vida_util_herramienta)
            ELSE om.cantidad*? END) AS total, m.unidad
        FROM orden_operaciones oo
        JOIN orden_operacion_materiales om ON om.orden_operacion_id=oo.id
        JOIN materiales m ON m.id=om.material_id
        WHERE oo.orden_id=? AND om.material_id IS NOT NULL GROUP BY om.material_id""",
        (orden["cantidad"], oid))
    if not mats:
        mats = query("""SELECT om.material_id,
            SUM(cant_material(om.cantidad, ?, om.vida_util_herramienta)) AS total, m.unidad
            FROM proceso_operaciones po
            JOIN operacion_materiales om ON om.operacion_id=po.id
            JOIN materiales m ON m.id=om.material_id
            WHERE po.producto_id=? GROUP BY om.material_id""",
            (orden["cantidad"], orden["producto_id"]))
    # Si la OT no requiere materia prima, se omiten los materiales de categoría
    # "Material" (los insumos/herramientas se siguen descontando igual).
    if orden["requiere_material"] is not None and int(orden["requiere_material"]) == 0:
        mats = [m for m in mats if (query("SELECT categoria FROM materiales WHERE id=?", (m["material_id"],), one=True) or {"categoria":None})["categoria"] != "Material"]
    for mat in mats:
        execute("INSERT INTO orden_materiales (orden_id,material_id,cantidad_requerida,cantidad_asignada,unidad) VALUES (?,?,?,0,?)",
            (oid, mat["material_id"], mat["total"], mat["unidad"]))
    return len(mats)


@app.route("/api/ordenes/<int:oid>/operaciones/populate", methods=["POST"])
@login_required()
def populate_orden_operaciones(oid):
    n = _populate_orden_operaciones(oid)
    if n is None: return jsonify({"error":"La OT no tiene producto asignado"}), 400
    if isinstance(n, str): return jsonify({"error": n}), 409
    return jsonify({"ok":True,"ops_created":n})

def _tiene_terc_previa(orden_id, orden_num):
    """True si existe alguna operación tercerizada ANTERIOR (orden menor) en
    la misma OT, sin importar su estado. Se usa para restringir la reversión
    de estado 'Completada': solo las operaciones que consumen o dependen de
    una tercerización previa quedan bloqueadas una vez completadas; el resto
    de las operaciones se puede revertir libremente."""
    try:
        orden_num_int = float(orden_num)
    except Exception:
        return False
    row = query("""SELECT 1 FROM orden_operaciones
        WHERE orden_id=? AND es_tercerizada=1
          AND CAST(orden AS REAL) < ?
        LIMIT 1""", (orden_id, orden_num_int), one=True)
    return row is not None


# ── CRUD completo para operaciones de OT ─────────────────────────────────────
def _recalcular_material_requerido_ot(oid, material_id):
    """Recalcula orden_materiales.cantidad_requerida de UN material de la OT en
    función de la qty_requerida de cada operación de la OT que lo usa
    (orden_operacion_materiales: copia propia de la OT, v148). Si el material
    ya no lo usa ninguna operación y no tiene nada asignado, se quita de la OT;
    si lo usa y no estaba, se agrega. No toca lo ya asignado/reservado."""
    row = query("""SELECT SUM(cant_material(om.cantidad, oo.qty_requerida, om.vida_util_herramienta)) AS total, m.unidad
        FROM orden_operaciones oo
        JOIN orden_operacion_materiales om ON om.orden_operacion_id=oo.id AND om.material_id=?
        JOIN materiales m ON m.id=om.material_id
        WHERE oo.orden_id=?""", (material_id, oid), one=True)
    total = float(row["total"] or 0) if row else 0
    existing = query("SELECT id,cantidad_asignada FROM orden_materiales WHERE orden_id=? AND material_id=?", (oid, material_id), one=True)
    if existing:
        if total <= 0:
            usado = query("SELECT COUNT(*) c FROM orden_lotes WHERE orden_id=? AND material_id=?", (oid, material_id), one=True)["c"]
            if float(existing["cantidad_asignada"] or 0) <= 0 and not usado:
                execute("DELETE FROM orden_materiales WHERE id=?", (existing["id"],))
                return
        execute("UPDATE orden_materiales SET cantidad_requerida=? WHERE id=?", (total, existing["id"]))
    elif total > 0:
        unidad = (row["unidad"] if row else None)
        execute("INSERT INTO orden_materiales (orden_id,material_id,cantidad_requerida,cantidad_asignada,unidad) VALUES (?,?,?,0,?)",
                (oid, material_id, total, unidad))


@app.route("/api/ordenes/<int:oid>/operaciones/<int:opid>", methods=["PUT"])
@login_required(roles=["admin","operario"])
def update_ot_operacion(oid, opid):
    d = request.json or {}
    # Build dynamic UPDATE based on which fields were provided
    allowed = {
        "orden", "nombre", "categoria_maquina_id", "maquina_id",
        "tiempo_setup_min", "tiempo_ciclo_seg", "qty_requerida", "estado",
    }
    fields = {k: v for k, v in d.items() if k in allowed}
    if not fields:
        return jsonify({"ok": True, "noop": True})
    if fields.get("estado"):
        oo = query("SELECT orden, estado, es_tercerizada FROM orden_operaciones WHERE id=? AND orden_id=?", (opid, oid), one=True)
        if not oo: return jsonify({"error":"Operación no encontrada"}), 404
        if oo["estado"] == "Completada" and fields["estado"] != "Completada" and _tiene_terc_previa(oid, oo["orden"]):
            return jsonify({"error": "Esta operación depende de una tercerización previa y ya está "
                "Completada: no se puede revertir a un estado anterior."}), 400
        if fields["estado"] in ("En proceso","Completada"):
            if oo["es_tercerizada"]:
                return jsonify({"error": "Esta operación es tercerizada: se completa sola cuando vuelve "
                    "el lote del proveedor (OTT) y queda Aprobado en Lotes, no se marca a mano."}), 400
            bloqueo = _bloqueo_terc_previo(oid, oo["orden"])
            if bloqueo:
                return jsonify({"error": f"OT pausada: la operación tercerizada \"{bloqueo['nombre']}\" "
                    f"(orden {bloqueo['orden']}) todavía no fue recibida/aprobada."}), 400
            # Si esta operación es la que debe consumir el semielaborado
            # devuelto por una OTT anterior, no se puede completar a mano
            # desde este select: hay que declarar la Novedad de producción
            # con la cantidad, que es lo único que descuenta/libera el lote
            # de la OTT (ver _materiales_ott_pendientes_por_operacion). Si
            # se permitiera acá, el lote queda "pegado" con cantidad
            # aprobada y reservada para siempre (bug reportado).
            pendientes_ott = _materiales_ott_pendientes_por_operacion(oid, opid)
            if pendientes_ott:
                return jsonify({"error": "Esta operación consume el semielaborado devuelto por una "
                    "tercerización anterior: no se puede completar cambiando el estado a mano. "
                    "Cargá una Novedad de producción con la cantidad para que el lote de la OTT "
                    "se descuente correctamente."}), 400
    # Si se está por cambiar qty_requerida, necesitamos el proceso_op_id ANTES
    # del UPDATE para saber qué materiales de esta operación recalcular después.
    proceso_op_id = opid if "qty_requerida" in fields else None
    set_clause = ", ".join(f"{k}=?" for k in fields.keys())
    params = list(fields.values()) + [opid, oid]
    execute(f"UPDATE orden_operaciones SET {set_clause} WHERE id=? AND orden_id=?", params)
    # ── La cantidad que se le pide al lote/stock por cada material que usa
    # esta operación cambia en función de la nueva qty_requerida ingresada.
    if "qty_requerida" in fields and proceso_op_id:
        mat_ids = query("SELECT DISTINCT material_id FROM orden_operacion_materiales WHERE orden_operacion_id=?", (opid,))
        for mr in mat_ids:
            _recalcular_material_requerido_ot(oid, mr["material_id"])
    # Si se puso esta operación "En proceso" o "Completada" a mano, la OT
    # también pasa de "Pendiente" a "En proceso" (ya se empezó a producir).
    if fields.get("estado") in ("En proceso", "Completada"):
        execute("UPDATE ordenes SET estado='En proceso' WHERE id=? AND estado='Pendiente'", (oid,))
    return jsonify({"ok": True})

# ── Materiales por operación de la OT (v148, punto 4): la OT es independiente del proceso ──
@app.route("/api/orden_operaciones/<int:ooid>/materiales", methods=["GET"])
@login_required()
def get_ot_op_materiales(ooid):
    rows = query("""SELECT om.id,om.material_id,om.cantidad,om.unidad,om.tipo,om.vida_util_herramienta,m.codigo,m.descripcion,m.categoria,m.stock
        FROM orden_operacion_materiales om LEFT JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_operacion_id=? ORDER BY om.id""", (ooid,))
    return jsonify([dict(r) for r in rows])

@app.route("/api/orden_operaciones/<int:ooid>/materiales", methods=["PUT"])
@login_required(roles=["admin","operario"])
def set_ot_op_materiales(ooid):
    """Reemplaza la lista de materiales/insumos de UNA operación de la OT.
    Lista vacía = la operación no consume material. No toca el proceso del producto."""
    oo = query("SELECT * FROM orden_operaciones WHERE id=?", (ooid,), one=True)
    if not oo: return jsonify({"error": "Operación no encontrada"}), 404
    lista = (request.json or {}).get("materiales")
    if not isinstance(lista, list): return jsonify({"error": "materiales (lista) requerido"}), 400
    limpia = []
    for m in lista:
        try:
            mid = int(m.get("material_id")); cant = float(m.get("cantidad") or 0)
        except (TypeError, ValueError):
            return jsonify({"error": "Material o cantidad inválidos"}), 400
        if cant <= 0: return jsonify({"error": "La cantidad de cada material debe ser mayor a 0"}), 400
        mat = query("SELECT id,unidad FROM materiales WHERE id=?", (mid,), one=True)
        if not mat: return jsonify({"error": f"Material {mid} no existe"}), 404
        limpia.append((mid, cant, m.get("unidad") or mat["unidad"], m.get("tipo") or "material",
                       _vida_util_valida(mid, m.get("vida_util_herramienta"))))
    if oo["es_tercerizada"] and not any(t == "material" for _, _, _, t, _ in limpia):
        return jsonify({"error": "Una operación tercerizada necesita un insumo (el material que vuelve del tercero)."}), 400
    previos = [r["material_id"] for r in query("SELECT DISTINCT material_id FROM orden_operacion_materiales WHERE orden_operacion_id=?", (ooid,)) if r["material_id"]]
    execute("DELETE FROM orden_operacion_materiales WHERE orden_operacion_id=?", (ooid,))
    for mid, cant, un, tipo, vida in limpia:
        execute("INSERT INTO orden_operacion_materiales (orden_operacion_id,material_id,cantidad,unidad,tipo,vida_util_herramienta) VALUES (?,?,?,?,?,?)", (ooid, mid, cant, un, tipo, vida))
    for mid in set(previos) | {x[0] for x in limpia}:
        _recalcular_material_requerido_ot(oo["orden_id"], mid)
    # OTT de esta operación que todavía no inició: actualizar el material de retorno
    if oo["es_tercerizada"]:
        ret = _material_retorno_operacion(ooid)
        if ret:
            execute("""UPDATE ordenes_tercerizado SET material_se_id=? WHERE operacion_id=? AND estado='Pendiente' AND COALESCE(cantidad_enviada,0)=0""", (ret, ooid))
    return jsonify({"ok": True})

@app.route("/api/ordenes/<int:oid>/operaciones/<int:opid>", methods=["DELETE"])
@login_required(roles=["admin","operario"])
def delete_ot_operacion(oid, opid):
    n_pl = _n_bloques_planificados(oid, opid)
    if n_pl:
        return jsonify({"error": f"La operación tiene {n_pl} bloque/s en el Scheduling de producción: quitalos de la planificación antes de borrarla."}), 409
    mat_ids_prev = query("SELECT DISTINCT material_id FROM orden_operacion_materiales WHERE orden_operacion_id=?", (opid,))
    execute("DELETE FROM orden_operacion_materiales WHERE orden_operacion_id=?", (opid,))
    execute("DELETE FROM orden_operaciones WHERE id=? AND orden_id=?", (opid, oid))
    # Al borrar la operación, lo pedido de sus materiales también baja (ya no
    # hay ninguna operación pendiente que lo necesite, salvo que otra
    # operación de la misma OT use el mismo material).
    for mr in mat_ids_prev:
        _recalcular_material_requerido_ot(oid, mr["material_id"])
    return jsonify({"ok": True})

@app.route("/api/ordenes/<int:oid>/operaciones", methods=["POST"])
@login_required(roles=["admin","operario"])
def add_ot_operacion(oid):
    d = request.json
    if not d.get("nombre"): return jsonify({"error":"Nombre requerido"}), 400
    new_id = execute("""INSERT INTO orden_operaciones
        (orden_id,orden,nombre,categoria_maquina_id,maquina_id,
         tiempo_setup_min,tiempo_ciclo_seg,estado,qty_requerida,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (oid, d.get("orden",1), d["nombre"],
         d.get("categoria_maquina_id") or None,
         d.get("maquina_id") or None,
         d.get("tiempo_setup_min",0), d.get("tiempo_ciclo_seg",0),
         d.get("estado","Pendiente"), d.get("qty_requerida",0),
         d.get("obs")))
    for m in (d.get("materiales") or []):
        try:
            if float(m.get("cantidad") or 0) > 0 and m.get("material_id"):
                execute("INSERT INTO orden_operacion_materiales (orden_operacion_id,material_id,cantidad,unidad,tipo,vida_util_herramienta) VALUES (?,?,?,?,?,?)",
                        (new_id, int(m["material_id"]), float(m["cantidad"]), m.get("unidad"), m.get("tipo") or "material",
                         _vida_util_valida(int(m["material_id"]), m.get("vida_util_herramienta"))))
                _recalcular_material_requerido_ot(oid, int(m["material_id"]))
        except (TypeError, ValueError):
            pass
    return jsonify({"ok": True, "id": new_id}), 201

# ── Materiales de OT ──────────────────────────────────────────────────────────
@app.route("/api/ordenes/<int:oid>/materiales", methods=["GET"])
@login_required()
def get_orden_materiales(oid):
    rows = query("""SELECT om.*,m.descripcion,m.codigo,m.unidad,m.stock,m.categoria
        FROM orden_materiales om JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_id=? ORDER BY m.codigo""", (oid,))
    # Lotes ya vinculados a esta OT (asignados manualmente y/o consumidos por
    # novedades), para que el frontend pueda mostrar QUÉ lote(s) se eligieron
    # para cada material en la tabla de "Lotes asignados".
    lotes_rows = query("""SELECT ol.material_id, ol.lote_id, l.numero, ol.cantidad_usada, ol.cantidad_consumida
        FROM orden_lotes ol JOIN lotes l ON l.id=ol.lote_id
        WHERE ol.orden_id=?""", (oid,))
    lotes_por_mat = {}
    for lr in lotes_rows:
        lotes_por_mat.setdefault(lr["material_id"], []).append(
            {"lote_id": lr["lote_id"], "numero": lr["numero"], "cantidad_usada": lr["cantidad_usada"],
             "cantidad_consumida": lr["cantidad_consumida"] or 0})
    # A qué operación(es) del proceso está destinado cada material (un mismo
    # material puede estar requerido por más de un paso de la ruta, así que
    # se lista cada uno con su número de orden).
    ops_por_mat = {}
    if True:
        ops_rows = query("""SELECT om2.material_id, oo.orden op_orden, oo.nombre op_nombre
            FROM orden_operacion_materiales om2
            JOIN orden_operaciones oo ON oo.id=om2.orden_operacion_id
            WHERE oo.orden_id=? ORDER BY CAST(oo.orden AS INTEGER)""", (oid,))
        for orow in ops_rows:
            ops_por_mat.setdefault(orow["material_id"], []).append(
                f"{orow['op_orden']}. {orow['op_nombre']}")
    out = []
    for r in rows:
        rd = dict(r)
        rd["lotes_asignados"] = lotes_por_mat.get(r["material_id"], [])
        rd["operaciones"] = ops_por_mat.get(r["material_id"], [])
        out.append(rd)
    return jsonify(out)

@app.route("/api/ordenes/<int:oid>/materiales/populate", methods=["POST"])
@login_required()
def populate_orden_materiales(oid):
    n = _populate_orden_materiales(oid)
    if n is None: return jsonify({"error":"OT sin producto"}), 400
    # Si algún material requerido es un Producto Terminado (no se puede
    # comprar en Compras) y no hay stock suficiente para cubrir esta OT, se
    # genera automáticamente una OT auxiliar por el faltante — misma lógica
    # que ya se usaba al consolidar pedidos de cliente/pronóstico, ahora
    # también al crear/editar una OT manualmente desde Órdenes de trabajo.
    solicitudes_creadas, ots_auxiliares = _gap_analysis_materiales_multipass()
    return jsonify({"ok":True,"mats":n,"ots_auxiliares":ots_auxiliares,"solicitudes_compra":solicitudes_creadas})


# ══════════════════════════════════════════════════════════════════════════════
# OTT — Órdenes de Trabajo de Terceros
# ══════════════════════════════════════════════════════════════════════════════

@app.route("/api/ott", methods=["GET"])
@login_required()
def get_ott_list():
    estado = request.args.get("estado")
    prov_id = request.args.get("proveedor_id")
    sql = """SELECT ott.*,
        o.numero ot_numero, o.estado ot_estado, p.razon proveedor_nombre,
        po.nombre op_nombre, po.orden op_orden,
        pr.nombre producto_nombre, pr.codigo producto_codigo,
        mse.codigo material_codigo, mse.descripcion material_descripcion,
        (SELECT GROUP_CONCAT(sc.numero, ', ') FROM solicitudes_compra sc WHERE sc.ott_id=ott.id) sc_numeros,
        COALESCE((SELECT l.cantidad_rechazada FROM lotes l WHERE l.id=ott.lote_retorno_id), 0)
            - COALESCE(ott.cantidad_rechazada_devuelta,0) AS rechazado_pendiente_devolver,
        (SELECT l.estado FROM lotes l WHERE l.id=ott.lote_retorno_id) AS lote_retorno_estado
        FROM ordenes_tercerizado ott
        LEFT JOIN materiales mse ON mse.id=ott.material_se_id
        LEFT JOIN ordenes o ON o.id=ott.ot_origen_id
        LEFT JOIN proveedores p ON p.id=ott.proveedor_id
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        LEFT JOIN productos pr ON pr.id=po.producto_id
        WHERE 1=1"""
    params = []
    if estado:
        sql += " AND ott.estado=?"; params.append(estado)
    if prov_id:
        sql += " AND ott.proveedor_id=?"; params.append(prov_id)
    sql += " ORDER BY ott.creado DESC"
    return jsonify([dict(r) for r in query(sql, params)])

@app.route("/api/ott/<int:oid>", methods=["GET"])
@login_required()
def get_ott(oid):
    r = query("""SELECT ott.*,
        o.numero ot_numero, p.razon proveedor_nombre, p.telefono proveedor_tel,
        p.email proveedor_email, po.nombre op_nombre, po.orden op_orden,
        pr.nombre producto_nombre, pr.codigo producto_codigo,
        rem.numero remito_numero, remdev.numero remito_devolucion_numero,
        oo.qty_requerida oo_qty_requerida,
        oo.orden_id oo_orden_id, oo.orden oo_orden,
        mse.codigo material_codigo, mse.descripcion material_descripcion,
        l.cantidad_rechazada lote_cantidad_rechazada
        FROM ordenes_tercerizado ott
        LEFT JOIN materiales mse ON mse.id=ott.material_se_id
        LEFT JOIN ordenes o ON o.id=ott.ot_origen_id
        LEFT JOIN proveedores p ON p.id=ott.proveedor_id
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        LEFT JOIN productos pr ON pr.id=po.producto_id
        LEFT JOIN remitos rem ON rem.id=ott.remito_traslado_id
        LEFT JOIN remitos remdev ON remdev.id=ott.remito_devolucion_id
        LEFT JOIN orden_operaciones oo ON oo.id=ott.operacion_id
        LEFT JOIN lotes l ON l.id=ott.lote_retorno_id
        WHERE ott.id=?""", (oid,), one=True)
    if not r: return jsonify({"error":"OTT no encontrada"}), 404
    r = dict(r)
    r["rechazado_pendiente_devolver"] = round(
        float(r.get("lote_cantidad_rechazada") or 0) - float(r.get("cantidad_rechazada_devuelta") or 0), 6)
    # Cantidad disponible para remitir. Prioridad:
    # 1) Si hay una operación ANTERIOR dentro de la misma OT (misma
    #    secuencia de proceso), lo disponible es lo que esa operación
    #    anterior ya PRODUJO (orden_operaciones.qty_producida) — sea una
    #    operación propia (cargada por Novedades) o tercerizada (recibida
    #    y aprobada) — menos lo que ya se remitió de esta OTT. Esto es lo
    #    que corresponde en un proceso multi-nivel: el semielaborado recién
    #    salido de un paso previo puede no estar todavía reflejado en
    #    materiales.stock (eso solo pasa automáticamente cuando el paso
    #    previo también fue tercerizado y su lote de retorno ya fue
    #    Aprobado; una operación propia completada por Novedades NUNCA
    #    vuelca su producción a materiales.stock, solo queda registrada en
    #    qty_producida de esa operación — de ahí el bug donde el stock de
    #    la operación anterior "no aparecía" para remitir).
    # 2) Si no hay operación anterior (es el primer paso del proceso), se
    #    usa el stock general del material del producto si existe.
    # 3) Si tampoco hay stock cargado, se usa la cantidad planificada para
    #    la operación en la OT.
    cantidad_enviada = r.get("cantidad_enviada") or 0
    op_anterior = None
    if r.get("oo_orden_id") is not None and r.get("oo_orden") is not None:
        try:
            orden_num_int = float(r["oo_orden"])
        except Exception:
            orden_num_int = None
        if orden_num_int is not None:
            op_anterior = query("""SELECT qty_producida FROM orden_operaciones
                WHERE orden_id=? AND CAST(orden AS REAL) < ?
                ORDER BY CAST(orden AS REAL) DESC LIMIT 1""",
                (r["oo_orden_id"], orden_num_int), one=True)
    if op_anterior is not None:
        producido_anterior = float(op_anterior["qty_producida"] or 0)
        r["cantidad_disponible"] = max(producido_anterior - cantidad_enviada, 0)
        r["cantidad_disponible_origen"] = "produccion_previa"
    else:
        mat_stock = None
        prod_id = query("SELECT producto_id FROM proceso_operaciones WHERE id=?", (r["proceso_op_id"],), one=True)
        prod_id = prod_id["producto_id"] if prod_id else None
        if prod_id:
            # Primero el propio artículo PT (id=producto_id), después semielaborados.
            mat = query("SELECT stock FROM materiales WHERE producto_id=? AND activo=1 ORDER BY (id=producto_id) DESC, id LIMIT 1", (prod_id,), one=True)
            if mat: mat_stock = mat["stock"]
        if mat_stock is not None:
            # Acá NO se resta lo ya enviado: al emitir cada remito las piezas
            # salieron del depósito y materiales.stock ya bajó. Restarlas otra
            # vez las descontaba dos veces y el modal ofrecía 0 cuando todavía
            # quedaban piezas por mandar. Es el mismo criterio que usa
            # ott_emitir_remito para validar (ver rama `elif mat:` de allá).
            r["cantidad_disponible"] = max(mat_stock, 0)
            r["cantidad_disponible_origen"] = "stock"
        elif not r.get("operacion_id") and float(r.get("cantidad_plan") or 0) > 0:
            r["cantidad_disponible"] = max(float(r["cantidad_plan"]) - cantidad_enviada, 0)
            r["cantidad_disponible_origen"] = "cantidad_plan"
        else:
            r["cantidad_disponible"] = max((r.get("oo_qty_requerida") or 0) - cantidad_enviada, 0)
            r["cantidad_disponible_origen"] = "qty_requerida"

    # Tope adicional por insumos tipo 'material' cargados en la operación
    # (ver ott_emitir_remito para la validación real al confirmar el envío;
    # esto es solo para que el modal ya muestre/limite el valor correcto).
    if r.get("operacion_id"):
        # Mismo criterio que ott_emitir_remito: el material que representa la
        # operación comprada al tercero no es un insumo físico y no limita.
        _mat_ret = _material_retorno_operacion(r["operacion_id"])
        limite_insumo = None
        for ins in query("""SELECT om.material_id, om.cantidad, m.stock mat_stock
                FROM orden_operacion_materiales om JOIN materiales m ON m.id=om.material_id
                WHERE om.orden_operacion_id=? AND om.tipo='material'""", (r["operacion_id"],)):
            if _mat_ret and ins["material_id"] == _mat_ret:
                continue
            cant_unit = float(ins["cantidad"] or 0)
            if cant_unit <= 0:
                continue
            max_por_insumo = float(ins["mat_stock"] or 0) / cant_unit
            if limite_insumo is None or max_por_insumo < limite_insumo:
                limite_insumo = max_por_insumo
        if limite_insumo is not None and limite_insumo < r["cantidad_disponible"]:
            r["cantidad_disponible"] = round(limite_insumo, 3)
            r["cantidad_disponible_origen"] = "insumo"
    return jsonify(r)

@app.route("/api/ott", methods=["POST"])
@login_required(roles=["admin","operario"])
def create_ott():
    d = request.json
    if not d.get("proveedor_id"):
        return jsonify({"error":"Proveedor requerido"}), 400
    # v147 (punto 10): OTT manual — sin OT/operación de origen. Exige el material
    # como insumo (el mismo que se genera al ingresar el remito) y la cantidad.
    es_manual = not d.get("operacion_id") and not d.get("proceso_op_id")
    material_id = d.get("material_id")
    cantidad_plan = 0
    if es_manual:
        if not material_id:
            return jsonify({"error":"Seleccioná el material como insumo (es el mismo que se generará al ingresar el remito)"}), 400
        mat = query("SELECT id,categoria FROM materiales WHERE id=? AND activo=1", (material_id,), one=True)
        if not mat:
            return jsonify({"error":"Material no encontrado"}), 404
        if mat["categoria"] == "Producto terminado":
            return jsonify({"error":"Un producto terminado no puede usarse como insumo de una OTT manual"}), 400
        try: cantidad_plan = float(d.get("cantidad") or 0)
        except (TypeError, ValueError): cantidad_plan = 0
        if cantidad_plan <= 0:
            return jsonify({"error":"Indicá la cantidad a enviar a terceros"}), 400
    numero = siguiente_numero("ordenes_tercerizado", "OTT-", 4)
    lid = execute("""INSERT INTO ordenes_tercerizado
        (numero,ot_origen_id,operacion_id,proceso_op_id,proveedor_id,
         precio_acordado,estado,es_ultimo_nivel,fecha_retorno_est,obs,creado_por,material_se_id,cantidad_plan)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero, d.get("ot_origen_id"), d.get("operacion_id"),
         d.get("proceso_op_id"), d["proveedor_id"],
         d.get("precio_acordado", 0), "Pendiente",
         1 if d.get("es_ultimo_nivel") else 0,
         d.get("fecha_retorno_est"), d.get("obs"), session["user_id"],
         material_id if es_manual else None, cantidad_plan))
    _sync_requerimiento_desde_ott(lid)
    return jsonify({"ok": True, "id": lid, "numero": numero}), 201

@app.route("/api/ott/<int:oid>", methods=["PUT"])
@login_required(roles=["admin","operario"])
def update_ott(oid):
    d = request.json
    # v147 (punto 9): el proveedor se puede cambiar solo antes de iniciarse la OTT
    # (antes del primer envío), porque al enviar se genera la solicitud de compra.
    _ott_act = query("SELECT proveedor_id,cantidad_enviada FROM ordenes_tercerizado WHERE id=?", (oid,), one=True)
    if not _ott_act: return jsonify({"error":"OTT no encontrada"}), 404
    if float(_ott_act["cantidad_enviada"] or 0) > 0 and d.get("proveedor_id") != _ott_act["proveedor_id"]:
        return jsonify({"error":"No se puede cambiar el proveedor: la OTT ya inició (tiene envíos)."}), 400
    execute("""UPDATE ordenes_tercerizado SET estado=?,proveedor_id=?,precio_acordado=?,
        fecha_retorno_est=?,fecha_envio=?,obs=? WHERE id=?""",
        (d.get("estado"), d.get("proveedor_id"), d.get("precio_acordado",0),
         d.get("fecha_retorno_est"), d.get("fecha_envio"), d.get("obs"), oid))
    _sync_requerimiento_desde_ott(oid)
    return jsonify({"ok": True})

@auditoria_proceso("SC automática por insumo de OTT")
def _generar_sc_insumo_ott(material_id, faltante, motivo):
    """Genera (o amplía, si ya hay una activa) una Solicitud de Compra por
    el faltante puntual de un material/insumo requerido para remitir una
    OTT — a diferencia de auto_generar_sc_bajo_stock, esto NO depende de
    stock_min/stock_max: es el faltante exacto para cubrir este remito.

    Desactivado por defecto: ver _sc_automaticas_activas()."""
    if not _sc_automaticas_activas():
        return None
    if faltante <= 0 or not material_id:
        return None
    mat = query("SELECT codigo,descripcion,unidad FROM materiales WHERE id=?", (material_id,), one=True)
    if not mat:
        return None
    sc_exist = query("""SELECT id,cantidad FROM solicitudes_compra
        WHERE material_id=? AND estado IN ('Pendiente','Cotizada','En evaluación')
        ORDER BY id DESC LIMIT 1""", (material_id,), one=True)
    if sc_exist:
        nueva_cant = round(float(sc_exist["cantidad"] or 0) + faltante, 3)
        execute("""UPDATE solicitudes_compra SET cantidad=?,
            obs=COALESCE(obs,'') || ? WHERE id=?""",
            (nueva_cant, f" | +{round(faltante,3)} {mat['unidad']} por {motivo}.", sc_exist["id"]))
        return {"numero": None, "material": mat["descripcion"], "cantidad": round(faltante, 3), "actualizada": True}
    numero = next_numero_sc()
    execute("""INSERT INTO solicitudes_compra
        (numero,tipo,material_id,descripcion,cantidad,unidad,urgencia,estado,solicitante_id,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (numero, "Productiva", material_id, mat["descripcion"], round(faltante, 3), mat["unidad"],
         "Urgente", "Pendiente", session.get("user_id"),
         f"Generada automáticamente: faltante de insumo por {motivo}."))
    return {"numero": numero, "material": mat["descripcion"], "cantidad": round(faltante, 3)}


def _generar_ot_aux_insumo_ott(producto_id, faltante, motivo):
    """Genera (o amplía, si ya hay una OT auxiliar en curso para el mismo
    producto) una OT auxiliar para fabricar el faltante de un producto
    usado como insumo de una operación tercerizada, para cubrir un remito
    de OTT. Mismo patrón que las OT auxiliares del MRP (_gap_analysis_materiales),
    pero disparado puntualmente por el faltante de este remito."""
    if faltante <= 0 or not producto_id:
        return None
    prod = query("SELECT id,codigo,nombre FROM productos WHERE id=? AND activo=1", (producto_id,), one=True)
    if not prod:
        return None
    ot_exist = query("""SELECT id,numero,cantidad FROM ordenes
        WHERE producto_id=? AND estado IN ('Pendiente','En proceso')
          AND obs LIKE 'OT auxiliar generada automáticamente por remito de OTT%'
        ORDER BY id DESC LIMIT 1""", (producto_id,), one=True)
    if ot_exist:
        nueva_cant = round(float(ot_exist["cantidad"] or 0) + faltante, 3)
        execute("UPDATE ordenes SET cantidad=? WHERE id=?", (nueva_cant, ot_exist["id"]))
        execute("DELETE FROM orden_materiales WHERE orden_id=?", (ot_exist["id"],))
        populate_mats_internal(ot_exist["id"], producto_id, nueva_cant)
        return {"numero": ot_exist["numero"], "producto": prod["nombre"],
                "cantidad": round(faltante, 3), "actualizada": True}
    numero_aux = siguiente_numero("ordenes", "OT-", 3)
    ops_proc_aux = query(
        "SELECT * FROM proceso_operaciones WHERE producto_id=? ORDER BY CAST(orden AS INTEGER), orden",
        (producto_id,))
    tiempo_std_aux = tiempo_std_min(ops_proc_aux, faltante)
    costo_mat_aux = calcular_costo_producto(producto_id, faltante)
    oid_aux = execute("""INSERT INTO ordenes
        (numero,cliente_id,producto_id,descripcion,cantidad,prioridad,estado,fecha_entrega,costo_mat,costo_mo,precio_venta,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero_aux, None, producto_id,
         f"{prod['codigo']} — {prod['nombre']} (OT auxiliar por faltante de insumo)",
         round(faltante, 3), "Alta", "Pendiente", date.today().isoformat(),
         round(costo_mat_aux, 2), round(tiempo_std_aux, 0), 0,
         f"OT auxiliar generada automáticamente por remito de OTT. Motivo: {motivo}."))
    populate_ops_internal(oid_aux, producto_id, faltante)
    populate_mats_internal(oid_aux, producto_id, faltante)
    return {"numero": numero_aux, "producto": prod["nombre"], "cantidad": round(faltante, 3)}


@auditoria_proceso("SC automática por envío a tercero")
def _generar_sc_por_envio_ott(ott_id, cantidad, num_rem):
    """v147 — punto 9: al emitir un envío de una OTT se genera una Solicitud de
    Compra por la cantidad enviada (servicio tercerizado), con una cotización
    precargada del proveedor de la OTT al precio acordado, SIN seleccionar:
    Compras debe confirmar el precio (seleccionando la cotización) y emitir la
    OC. Devuelve None si la OTT no tiene material de retorno definido (legado).

    Desactivado por defecto: ver _sc_automaticas_activas()."""
    if not _sc_automaticas_activas():
        return None
    ott = query("""SELECT ott.*, po.nombre op_nombre, o.numero ot_numero
        FROM ordenes_tercerizado ott
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        LEFT JOIN ordenes o ON o.id=ott.ot_origen_id WHERE ott.id=?""", (ott_id,), one=True)
    if not ott or not ott["proveedor_id"]:
        return None
    mat_id = None
    if ott["operacion_id"]:
        mat_id = _material_retorno_operacion(ott["operacion_id"])
    elif ott["material_se_id"]:
        mat_id = ott["material_se_id"]
    if not mat_id:
        return None
    mat = query("SELECT id,codigo,descripcion,unidad,categoria FROM materiales WHERE id=?", (mat_id,), one=True)
    if not mat:
        return None
    numero = next_numero_sc()
    tipo_sc = "Productiva" if mat["categoria"] == "Material" else "Indirecta"
    desc = (f"Servicio tercerizado {ott['op_nombre'] or 'OTT manual'} — {mat['descripcion']} "
            f"(OTT {ott['numero']}, remito {num_rem})")
    sid = execute("""INSERT INTO solicitudes_compra
        (numero,tipo,material_id,descripcion,cantidad,unidad,urgencia,estado,ot_origen_id,
         solicitante_id,obs,ott_id,ott_remito)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero, tipo_sc, mat["id"], desc, cantidad, mat["unidad"], "Normal", "Pendiente",
         ott["ot_origen_id"], session.get("user_id"),
         f"Generada automáticamente por el envío {num_rem} de la OTT {ott['numero']}. "
         "Compras debe confirmar el precio y emitir la OC.",
         ott_id, num_rem))
    execute("""INSERT INTO cotizaciones_compra
        (solicitud_id,proveedor_id,precio_unit,plazo_entrega_dias,seleccionada,obs)
        VALUES (?,?,?,?,0,?)""",
        (sid, ott["proveedor_id"], float(ott["precio_acordado"] or 0), 3,
         "Precio precargado desde la OTT — confirmar antes de emitir la OC"))
    return {"numero": numero, "cantidad": cantidad, "material": mat["descripcion"]}

@app.route("/api/ott/<int:oid>/emitir_remito", methods=["POST"])
@login_required(roles=["admin","operario"])
def ott_emitir_remito(oid):
    """Genera remito de traslado: piezas salen del taller hacia el proveedor.
    Si el material ya existe en stock (ej. semielaborado de un paso anterior),
    se descuenta y se deja registro del movimiento de salida, para que mientras
    la pieza está afuera no figure como stock disponible en el taller.

    Soporta envíos parciales: se puede llamar más de una vez sobre la misma
    OTT (ej. remitir 50 de 100 y más adelante remitir el resto), igual que
    "registrar_retorno" ya soporta recepciones parciales. Cada llamada suma
    a cantidad_enviada y genera un remito nuevo (todos quedan vinculados a
    la OTT vía remitos.ott_id)."""
    ott = query("""SELECT ott.*, po.producto_id
        FROM ordenes_tercerizado ott
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        WHERE ott.id=?""", (oid,), one=True)
    if not ott: return jsonify({"error":"OTT no encontrada"}), 404
    if ott["estado"] not in ("Pendiente","Remito emitido","En proceso","Recibido"):
        return jsonify({"error":"No se puede emitir remito en el estado actual de la OTT"}), 400
    if not ott["proveedor_id"]:
        return jsonify({"error":"La OTT no tiene proveedor asignado: editala y elegí el proveedor antes de emitir el remito"}), 400
    if ott["ot_origen_id"]:
        _ot_est = query("SELECT estado FROM ordenes WHERE id=?", (ott["ot_origen_id"],), one=True)
        if _ot_est and _ot_est["estado"] in ("Cancelada", "Completada"):
            return jsonify({"error": f"No se puede emitir remito: la OT de origen está {_ot_est['estado']}"}), 400

    d = request.json or {}
    cantidad = float(d.get("cantidad") or 0)
    if cantidad <= 0:
        return jsonify({"error":"Ingresá la cantidad de piezas que se envían al proveedor"}), 400

    cantidad_enviada_previa = float(ott["cantidad_enviada"] or 0)

    # Cantidad disponible para remitir. Misma prioridad que usa GET /api/ott/<id>:
    # 1) Si hay una operación ANTERIOR en la misma OT, lo disponible es lo que
    #    esa operación ya PRODUJO (orden_operaciones.qty_producida) — sea propia
    #    (cargada por Novedades) o tercerizada y ya recibida — menos TODO lo ya
    #    enviado para este mismo paso (de esta OTT y de otras OTTs del mismo
    #    paso, si las hubiera). Este "stock auxiliar" interno nunca se refleja
    #    en materiales.stock cuando el paso anterior fue una operación propia,
    #    así que NO hay que exigir stock físico acá.
    # 2) Si no hay operación anterior (primer paso del proceso), se usa el
    #    stock físico del material si existe.
    # 3) Si tampoco hay stock cargado, se usa la cantidad planificada de la
    #    operación en la OT, también neta de todo lo ya enviado para ese paso.
    oo = query("SELECT qty_requerida, orden_id, orden FROM orden_operaciones WHERE id=?",
               (ott["operacion_id"],), one=True) if ott["operacion_id"] else None

    op_anterior = None
    if oo and oo["orden_id"] is not None and oo["orden"] is not None:
        try:
            orden_num_int = float(oo["orden"])
        except Exception:
            orden_num_int = None
        if orden_num_int is not None:
            op_anterior = query("""SELECT id, qty_producida, es_tercerizada FROM orden_operaciones
                WHERE orden_id=? AND CAST(orden AS REAL) < ?
                ORDER BY CAST(orden AS REAL) DESC LIMIT 1""",
                (oo["orden_id"], orden_num_int), one=True)

    # Total ya enviado para este paso, sumando TODAS las OTTs de esa
    # operación (incluida esta misma, con sus envíos previos) — así un
    # segundo envío parcial de esta OTT descuenta correctamente lo que
    # esta OTT ya remitió antes, y no solo lo de otras OTTs.
    total_ya_enviado = 0
    if ott["operacion_id"]:
        total_ya_enviado = query("""SELECT COALESCE(SUM(cantidad_enviada),0) tot
            FROM ordenes_tercerizado WHERE operacion_id=?""",
            (ott["operacion_id"],), one=True)["tot"]

    # Antes acá se buscaba "el material del producto" (materiales.producto_id),
    # pero desde la unificación de artículos eso devuelve el propio Producto
    # Terminado: enviar a terceros el PRIMER paso de la ruta validaba y
    # descontaba stock del PT, cuando lo que sale son piezas en bruto. Lo
    # único físico que se descuenta al enviar es el semielaborado de una
    # tercerizada anterior (abajo) y los insumos de la operación.
    mat = None

    # Si el paso anterior fue tercerizado, lo que se reenvía al segundo
    # proveedor es SU semielaborado, no un material cualquiera del producto.
    # La consulta de arriba no filtra por categoría y suele devolver el
    # material de Producto Terminado, así que el descuento de más abajo no
    # encontraba lotes vinculados y salteaba el consumo en silencio: el
    # semielaborado quedaba en stock aunque las piezas ya estuvieran de nuevo
    # afuera. Se resuelve por el PSE que congeló la OTT anterior.
    if op_anterior is not None and op_anterior["es_tercerizada"]:
        pse_previo = query("""SELECT m.id, m.stock, m.codigo
            FROM ordenes_tercerizado o JOIN materiales m ON m.id=o.material_se_id
            WHERE o.operacion_id=? AND o.material_se_id IS NOT NULL
            ORDER BY o.id DESC LIMIT 1""", (op_anterior["id"],), one=True)
        if pse_previo:
            mat = pse_previo

    # Tope adicional por insumos (materiales, no productos) cargados en la
    # operación como "Material/Producto como insumo": si la operación
    # requiere, por ejemplo, 3 unidades de un material por cada unidad de
    # pieza a tercerizar, y solo hay 300 en stock, no se puede remitir más
    # de 100 piezas aunque el resto de los límites (planificado, producido
    # por la operación anterior, etc.) permitan más — no alcanzaría material
    # para acompañar ese envío. Los insumos tipo 'producto' NO entran acá:
    # su faltante se resuelve generando una OT auxiliar (ver más abajo), no
    # limitando el remito.
    # El insumo que representa la operación comprada al tercero (el material
    # de retorno de la OTT) NO es un insumo físico: existe para poder
    # COMPRARLE la operación al proveedor, y es el que se genera cuando entra
    # su remito. No hay que exigirlo en stock para poder mandar las piezas ni
    # consumirlo: se adquiere con la SC que genera el propio envío.
    mat_retorno_id = _material_retorno_operacion(ott["operacion_id"]) if ott["operacion_id"] else None
    limite_insumo, limite_insumo_cod = None, None
    if ott["operacion_id"]:
        for ins in query("""SELECT om.material_id, om.cantidad, m.stock mat_stock, m.codigo mat_codigo
                FROM orden_operacion_materiales om JOIN materiales m ON m.id=om.material_id
                WHERE om.orden_operacion_id=? AND om.tipo='material'""", (ott["operacion_id"],)):
            if mat_retorno_id and ins["material_id"] == mat_retorno_id:
                continue
            cant_unit = float(ins["cantidad"] or 0)
            if cant_unit <= 0:
                continue
            max_por_insumo = float(ins["mat_stock"] or 0) / cant_unit
            if limite_insumo is None or max_por_insumo < limite_insumo:
                limite_insumo, limite_insumo_cod = max_por_insumo, ins["mat_codigo"]

    if op_anterior is not None:
        disponible = max(float(op_anterior["qty_producida"] or 0) - float(total_ya_enviado or 0), 0)
        if limite_insumo is not None:
            disponible = min(disponible, limite_insumo)
        if cantidad > disponible:
            return jsonify({"error": f"Cantidad excede lo producido en la operación anterior "
                                      f"(disponible: {disponible}, solicitado: {cantidad})"
                                      + (f" — limitado por stock de insumo {limite_insumo_cod}"
                                         if limite_insumo is not None and disponible < float(op_anterior["qty_producida"] or 0) - float(total_ya_enviado or 0)
                                         else "")}), 400
    elif mat:
        disponible = mat["stock"]
        if limite_insumo is not None:
            disponible = min(disponible, limite_insumo)
        if disponible < cantidad:
            return jsonify({"error": f"Stock insuficiente de {mat['codigo'] if disponible==mat['stock'] else limite_insumo_cod} "
                                      f"para enviar a tercerizar (disponible: {disponible}, solicitado: {cantidad})"}), 400
    elif oo and oo["qty_requerida"]:
        # Primer paso del proceso: el límite es la cantidad planificada de la
        # operación en la OT (no hay stock físico todavía para acotarlo),
        # neta de todo lo ya enviado para ese paso.
        disponible = max(float(oo["qty_requerida"]) - float(total_ya_enviado or 0), 0)
        if limite_insumo is not None:
            disponible = min(disponible, limite_insumo)
        if cantidad > disponible:
            return jsonify({"error": f"Cantidad excede lo planificado para la operación "
                                      f"(disponible: {disponible}, solicitado: {cantidad})"
                                      + (f" — limitado por stock de insumo {limite_insumo_cod}"
                                         if limite_insumo is not None and limite_insumo < float(oo["qty_requerida"]) - float(total_ya_enviado or 0)
                                         else "")}), 400
    elif not ott["operacion_id"] and float(ott["cantidad_plan"] or 0) > 0:
        # v147: OTT manual — el techo es la cantidad indicada al crearla.
        disponible = max(float(ott["cantidad_plan"]) - cantidad_enviada_previa, 0)
        if cantidad > disponible + 0.0001:
            return jsonify({"error": f"Cantidad excede lo indicado en la OTT (disponible: {disponible:g}, solicitado: {cantidad:g})"}), 400
        _mat_man = query("SELECT codigo,stock FROM materiales WHERE id=?", (ott["material_se_id"],), one=True)
        if _mat_man and float(_mat_man["stock"] or 0) + 0.0001 < cantidad:
            return jsonify({"error": f"Stock insuficiente del material insumo {_mat_man['codigo']} "
                                      f"(disponible: {float(_mat_man['stock'] or 0):g}, solicitado: {cantidad:g})"}), 400
    elif limite_insumo is not None and cantidad > limite_insumo:
        # No hay operación anterior, ni stock propio del semielaborado, ni
        # cantidad planificada cargada — el único límite que queda es el
        # insumo.
        return jsonify({"error": f"Cantidad excede la disponible según stock de insumo "
                                  f"{limite_insumo_cod} (disponible: {limite_insumo}, solicitado: {cantidad})"}), 400

    # Create remito de traslado
    num_rem = siguiente_numero("remitos", "REM-", 4)

    rid = execute("""INSERT INTO remitos (numero,cliente_id,fecha,estado,obs,creado_por,tipo,ott_id,ott_cantidad)
        VALUES (?,NULL,date('now','localtime'),'Emitido',?,?,?,?,?)""",
        (num_rem, d.get("obs", f"Traslado a proveedor externo (envío parcial: {cantidad})"
                               if cantidad_enviada_previa > 0 else "Traslado a proveedor externo"),
         session["user_id"], "traslado_ott", oid, cantidad))

    # El descuento de materiales.stock/lote solo corresponde cuando esa
    # cantidad efectivamente había entrado a inventario. Hay DOS casos:
    #  1) Primer paso del proceso, stock "físico" común (mat, op_anterior
    #     None): ya se descuenta más abajo.
    #  2) La operación anterior fue TERCERIZADA: su retorno se aprobó vía
    #     Lotes, lo que YA sumó esa cantidad a materiales.stock Y quedó
    #     reservado/vinculado a esta OT en un lote concreto (ver
    #     ott_registrar_retorno/update_lote). Al reenviar ese semielaborado a
    #     un SEGUNDO proveedor, hay que consumir ese mismo lote (igual que
    #     create_novedad) — si no, queda "cantidad_reservada"/stock fantasma
    #     que nunca se gasta aunque la pieza ya salió del taller de nuevo.
    #  Si la operación anterior fue PROPIA (no tercerizada), nunca se cargó
    #  a materiales.stock ni a ningún lote — no hay nada que descontar.
    stock_descontado = False
    if mat and op_anterior is None:
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,NULL,'salida',?,?,?)""",
            (mat["id"], cantidad, f"Envío a tercerizado OTT {ott['numero']} — {num_rem}",
             session["user_id"]))
        execute("UPDATE materiales SET stock=stock-? WHERE id=?", (cantidad, mat["id"]))
        stock_descontado = True
    elif op_anterior is not None and op_anterior["es_tercerizada"] and mat:
        vinculos = _lotes_vinculados_material(oo["orden_id"], mat["id"])
        if vinculos:
            plan, disponible_total, cubierto = _plan_consumo_adicional(vinculos, cantidad)
            if not cubierto:
                return jsonify({"error": f"Stock disponible insuficiente en lote(s) vinculados de "
                    f"\"{mat['codigo']}\" (disponible {disponible_total}, requerido {cantidad}) para "
                    f"reenviar a este proveedor."}), 400
            for lote_activo, consumo in plan:
                execute("""UPDATE lotes SET
                        cantidad_disponible=MAX(0, cantidad_disponible-?),
                        cantidad_activa=MAX(0, cantidad_activa-?),
                        cantidad_reservada=MAX(0, COALESCE(cantidad_reservada,0)-?),
                        estado=CASE WHEN cantidad_disponible-? <= 0 THEN 'Agotado' ELSE estado END
                    WHERE id=?""", (consumo, consumo, consumo, consumo, lote_activo["id"]))
                execute("""UPDATE materiales SET stock=MAX(0, stock-?), actualizado=datetime('now','localtime')
                    WHERE id=?""", (consumo, mat["id"]))
                execute("""UPDATE orden_lotes SET cantidad_consumida=COALESCE(cantidad_consumida,0)+?
                    WHERE orden_id=? AND lote_id=?""", (consumo, oo["orden_id"], lote_activo["id"]))
                execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
                    VALUES (?,?,'salida',?,?,?)""",
                    (mat["id"], lote_activo["id"], consumo,
                     f"Reenvío a tercerizado OTT {ott['numero']} — {num_rem} (Lote {lote_activo['numero']})",
                     session["user_id"]))
            stock_descontado = True

    # ── Insumos de la operación tercerizada (materiales/productos que se
    # mandan al proveedor junto con la pieza, cargados en "Material/Producto
    # como insumo" del proceso). Se consumen proporcionalmente a la cantidad
    # remitida (om.cantidad * cantidad). Si no alcanza el stock: el faltante
    # de un MATERIAL genera/amplía una Solicitud de Compra puntual; el
    # faltante de un PRODUCTO (semielaborado) genera/amplía una OT auxiliar
    # para fabricarlo. El remito igual se emite — no se bloquea por esto.
    insumos_op = query("""SELECT om.tipo, om.material_id, om.producto_id, om.cantidad,
            m.codigo mat_codigo, m.stock mat_stock
        FROM orden_operacion_materiales om
        JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_operacion_id=?""", (ott["operacion_id"],)) if ott["operacion_id"] else []
    scs_insumo, ots_insumo = [], []
    for ins in insumos_op:
        if mat_retorno_id and ins["material_id"] == mat_retorno_id:
            continue   # es la operación que se le compra al tercero, no un insumo físico
        requerido = round(float(ins["cantidad"] or 0) * cantidad, 4)
        if requerido <= 0:
            continue
        stock_disp = float(ins["mat_stock"] or 0)
        consumir = min(requerido, stock_disp)
        faltante = round(requerido - consumir, 4)
        if consumir > 0:
            execute("""UPDATE materiales SET stock=stock-?, actualizado=datetime('now','localtime')
                WHERE id=?""", (consumir, ins["material_id"]))
            execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
                VALUES (?,NULL,'salida',?,?,?)""",
                (ins["material_id"], consumir,
                 f"Consumo insumo p/ remito OTT {ott['numero']} — {num_rem} ({ins['mat_codigo']})",
                 session["user_id"]))
        if faltante > 0:
            motivo = f"remito {num_rem} de OTT {ott['numero']}"
            if ins["tipo"] == "producto" and ins["producto_id"]:
                r = _generar_ot_aux_insumo_ott(ins["producto_id"], faltante, motivo)
                if r: ots_insumo.append(r)
            else:
                r = _generar_sc_insumo_ott(ins["material_id"], faltante, motivo)
                if r: scs_insumo.append(r)

    # v147 (punto 10): OTT manual — se consume el material insumo enviado.
    if not ott["operacion_id"] and ott["material_se_id"] and float(ott["cantidad_plan"] or 0) > 0:
        execute("""UPDATE materiales SET stock=MAX(0,stock-?), actualizado=datetime('now','localtime') WHERE id=?""",
                (cantidad, ott["material_se_id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,NULL,'salida',?,?,?)""",
            (ott["material_se_id"], cantidad, f"Envío a tercerizado OTT {ott['numero']} — {num_rem}", session["user_id"]))

    # Si ya estaba "En proceso" (hubo una recepción parcial previa), se
    # mantiene ese estado — no se retrocede a "Remito emitido". Si estaba
    # "Pendiente" o "Remito emitido", pasa (o queda) en "Remito emitido".
    nuevo_estado = ott["estado"] if ott["estado"] == "En proceso" else "Remito emitido"
    # El retorno estimado se fija al emitir el PRIMER remito: antes de enviar
    # el material no hay desde cuándo contar. Sale del plazo pactado con el
    # proveedor (proveedores.plazo_dias). Sin esto el campo quedaba siempre en
    # NULL para las OTT generadas automáticamente desde una OT, y entonces
    # _calc_cumplimientos_req devolvia cumple_fecha=None: ninguna OTT podia
    # aparecer en el grafico de Cumplimiento de entrega ni marcarse VENCIDA.
    # COALESCE: si alguien ya lo cargo a mano en la OTT, se respeta, y los
    # remitos parciales posteriores no lo recalculan.
    execute("""UPDATE ordenes_tercerizado SET estado=?,
        remito_traslado_id=?, fecha_envio=COALESCE(fecha_envio,date('now','localtime')),
        fecha_retorno_est=COALESCE(fecha_retorno_est,
            date(COALESCE(fecha_envio, date('now','localtime')), '+' ||
                 COALESCE((SELECT plazo_dias FROM proveedores
                           WHERE id=ordenes_tercerizado.proveedor_id), 3) || ' days')),
        cantidad_enviada=? WHERE id=?""",
        (nuevo_estado, rid, cantidad_enviada_previa + cantidad, oid))
    _sync_requerimiento_desde_ott(oid)
    # v147 (punto 9): cada envío genera una solicitud de compra por la cantidad
    # enviada; Compras confirma el precio y emite la OC.
    sc_ott = _generar_sc_por_envio_ott(oid, cantidad, num_rem)
    return jsonify({"ok": True, "remito_numero": num_rem, "remito_id": rid,
                     "solicitud_compra_ott": sc_ott,
                     "cantidad_enviada_total": cantidad_enviada_previa + cantidad,
                     "stock_descontado": stock_descontado,
                     "solicitudes_compra_insumo": scs_insumo,
                     "ots_auxiliares_insumo": ots_insumo})

@app.route("/api/ott/<int:oid>/registrar_retorno", methods=["POST"])
@login_required(roles=["admin","operario","almacen"])
def ott_registrar_retorno(oid):
    """Registra la recepción de piezas devueltas por el proveedor.

    Igual que "Recibir" en OC emitidas: se puede recibir en distintas
    ocasiones (recepciones parciales) mientras el proveedor va entregando.
    Todo lo recibido para una misma OTT va SIEMPRE al mismo lote (se
    amplía cantidad_disponible en vez de crear uno nuevo por cada
    recepción parcial, para no fragmentar la trazabilidad de calidad de
    una misma tanda de piezas tercerizadas). cantidad_original del lote se
    fija en cantidad_enviada de la OTT (no se va acumulando con cada
    recepción) para que un ciclo de rechazo → devolución → reingreso de
    reemplazo no la infle más allá de lo realmente enviado."""
    ott = query("""SELECT ott.*,po.producto_id,po.nombre op_nombre,pr.codigo prod_codigo,pr.nombre prod_nombre,
        pr.unidad prod_unidad,o.numero ot_numero
        FROM ordenes_tercerizado ott
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        LEFT JOIN productos pr ON pr.id=po.producto_id
        LEFT JOIN ordenes o ON o.id=ott.ot_origen_id
        WHERE ott.id=?""", (oid,), one=True)
    if not ott: return jsonify({"error":"OTT no encontrada"}), 404
    if ott["estado"] not in ("Remito emitido","En proceso"):
        return jsonify({"error":"Estado inválido para registrar retorno"}), 400

    d = request.json
    cantidad = float(d.get("cantidad", 1))
    if cantidad <= 0:
        return jsonify({"error":"Cantidad debe ser mayor a 0"}), 400
    # v147 (punto 9): el remito del proveedor se ingresa desde Recepción
    remito_prov = (d.get("remito") or "").strip()

    cantidad_enviada = float(ott["cantidad_enviada"] or 0)
    cantidad_recibida_previa = float(ott["cantidad_recibida"] or 0)
    if cantidad_enviada > 0:
        pendiente = cantidad_enviada - cantidad_recibida_previa
        if cantidad - pendiente > 0.0001:
            return jsonify({"error": f"La cantidad supera lo pendiente de recibir "
                                      f"(pendiente: {pendiente:g})"}), 400

    cantidad_recibida_total = cantidad_recibida_previa + cantidad
    # Recepción completa (cubre lo enviado, o no había cantidad_enviada
    # cargada) → OTT pasa a Recibido y se cierra la recepción. Si todavía
    # queda pendiente, queda "En proceso" para que el botón "Recibir" siga
    # disponible y se pueda seguir recibiendo contra el mismo lote/OT.
    completa = cantidad_enviada <= 0 or cantidad_recibida_total >= cantidad_enviada - 0.0001
    nuevo_estado = "Recibido" if completa else "En proceso"

    # ── Caso ÚLTIMA operación (PT → cliente) ───────────────────────────────
    # Acá NO se crea/amplía ningún lote a medida que llegan recepciones
    # parciales de la OTT. En su lugar, lo recibido va sumando directo al
    # "Total realizado" de la OT (orden_operaciones.qty_producida de la
    # última operación). El lote de PT se genera una sola vez, cuando la
    # operación llega al 100% y la OT se completa sola (descuento de
    # insumos + generación del lote PT vía _completar_ot_automatico /
    # generar_pt_faltante_si_corresponde) — mismo cierre que completar la
    # OT a mano.
    if ott["es_ultimo_nivel"]:
        execute("""UPDATE ordenes_tercerizado
            SET estado=?, cantidad_recibida=?,
                fecha_retorno_real=CASE WHEN ? THEN date('now','localtime') ELSE fecha_retorno_real END
            WHERE id=?""",
            (nuevo_estado, cantidad_recibida_total, completa, oid))

        ot_recien_completada = False
        if ott["operacion_id"]:
            op_row = query("SELECT id,qty_requerida,qty_producida,orden_id FROM orden_operaciones WHERE id=?",
                (ott["operacion_id"],), one=True)
            if op_row:
                nueva_qty_prod = float(op_row["qty_producida"] or 0) + cantidad
                qty_req = float(op_row["qty_requerida"] or 0)
                op_completa = qty_req > 0 and nueva_qty_prod >= qty_req - 0.0001
                usa_cajones = _ot_usa_cajones(op_row["orden_id"])
                execute("UPDATE orden_operaciones SET qty_producida=?,estado=? WHERE id=?",
                    (nueva_qty_prod, "Completada" if op_completa else "En proceso", op_row["id"]))
                _sync_cajones_op_tercerizada(op_row["id"], usa_cajones)
                execute("UPDATE ordenes SET estado='En proceso' WHERE id=? AND estado='Pendiente'",
                    (op_row["orden_id"],))
                if op_completa:
                    execute("UPDATE ordenes_tercerizado SET estado='Completado' WHERE id=?", (oid,))
                    _completar_ot_automatico(op_row["orden_id"])
                    _cajones_vincular_lote(op_row["orden_id"])
                    ot_completada_chk = query("SELECT estado FROM ordenes WHERE id=?", (op_row["orden_id"],), one=True)
                    ot_recien_completada = bool(ot_completada_chk and ot_completada_chk["estado"] == "Completada")

        resultado = {
            "ok": True,
            "es_ultimo_nivel": True,
            "completa": completa,
            "cantidad_recibida": cantidad_recibida_total,
            "cantidad_enviada": cantidad_enviada,
            "ot_completada": ot_recien_completada,
            "mensaje": (
                (f"Recepción cargada al Total realizado de la OT ({cantidad_recibida_total:g})."
                 + (" ¡OT completada, lote de PT generado!" if ot_recien_completada
                    else " Falta completar la cantidad de la operación para cerrar la OT."))
                if completa else
                f"Recepción parcial cargada al Total realizado de la OT "
                f"({cantidad_recibida_total:g} de {cantidad_enviada:g} recibido) — "
                "quedan piezas pendientes de recibir."
            )
        }
        _sync_requerimiento_desde_ott(oid)
        _ott_sync_oc_recibido(oid)
        return jsonify(resultado), 201

    # ── Caso operación INTERMEDIA (semielaborado) ──────────────────────────
    # Acá sí se necesita un lote físico: lo recibido alimenta la operación
    # siguiente del proceso, y esa operación se abastece desde Lotes como
    # cualquier otro insumo.
    #
    # Determine material_id for the lote: usar el material vinculado al
    # producto de la operación (semielaborado). Vínculo por producto_id
    # (FK), NO por codigo: dos productos distintos pueden compartir codigo
    # con un material ajeno por casualidad, y buscar solo por codigo
    # terminaría mezclando stock de cosas distintas.
    # Búsqueda por vínculo real (FK): producto_id + operacion_id (proceso_op_id
    # de la OTT). NO solo por producto_id: un mismo producto puede tener más
    # de una operación intermedia tercerizada, y cada una debe generar/usar
    # su PROPIO material de semielaborado (no compartir stock entre sí).
    # El semielaborado ya viene congelado desde que se creó la OTT: es el que
    # corresponde a la definición con la que las piezas salieron del taller,
    # aunque después se hayan editado los insumos en Procesos.
    mat_id = ott["material_se_id"] if "material_se_id" in ott.keys() else None
    if not mat_id:
        # OTT anterior al versionado: se resuelve contra la definición vigente
        # y se congela para las próximas recepciones parciales de esta misma
        # OTT, así todas caen en el mismo material.
        mat_id = _get_or_create_pse(ott["proceso_op_id"])
        if mat_id:
            execute("UPDATE ordenes_tercerizado SET material_se_id=? WHERE id=?",
                    (mat_id, oid))
    if not mat_id:
        # Sin proceso_op_id no hay de dónde derivar el semielaborado (la
        # operación del proceso fue borrada). Camino legado: material colgado
        # del producto, sin versionar.
        op_nombre = (ott["op_nombre"] or "SE").strip()
        codigo_base = f"{ott['prod_codigo']}-{op_nombre}"
        candidato = codigo_base
        intento = 1
        while query("SELECT id FROM materiales WHERE codigo=?", (candidato,), one=True):
            intento += 1
            candidato = f"{codigo_base}-{intento}"
        mat_id = execute("""INSERT INTO materiales
            (codigo,descripcion,categoria,producto_id,operacion_id,unidad,stock,stock_min,precio_unit,activo)
            VALUES (?,?,?,?,?,?,0,0,0,1)""",
            (candidato,
             f"{ott['prod_nombre']} — {op_nombre}",
             "Semielaborado",
             ott["producto_id"],
             ott["proceso_op_id"],
             ott["prod_unidad"] or "unid"))

    # Si ya existe un lote de retorno para esta OTT (de una recepción
    # parcial anterior), se amplía ese mismo lote en vez de crear uno
    # nuevo — todas las entregas del proveedor para esta OTT terminan en
    # un único lote. Queda "Ingresado" (pendiente de aprobación de
    # Calidad), igual que cualquier otro lote que entra al taller: no se
    # aprueba solo ni suma a stock acá, eso pasa recién en Lotes cuando se
    # clasifica como Aprobado (ver update_lote → _sync_ott_retorno_a_operacion),
    # que es el momento en que la operación tercerizada de la OT se da por
    # completada y la OT puede seguir con las operaciones siguientes.
    lote_existente = None
    if ott["lote_retorno_id"]:
        lote_existente = query("SELECT id,numero FROM lotes WHERE id=?", (ott["lote_retorno_id"],), one=True)

    if lote_existente:
        lote_id = lote_existente["id"]
        num_lote = lote_existente["numero"]
        # Si el lote ya había quedado totalmente clasificado (ej. se aprobó
        # todo lo recibido hasta ahora y quedó estado='Aprobado' o
        # 'Rechazado'), esta nueva entrega trae piezas SIN clasificar
        # todavía — hay que reabrirlo a "Ingresado" para que vuelva a
        # aparecer en la cola de Calidad como pendiente de clasificar. Si
        # ya estaba "Ingresado" (quedaba algo pendiente de antes), no hace
        # falta tocar el estado.
        #
        # cantidad_original NO se va sumando con cada recepción parcial: se
        # fija en cantidad_enviada de la OTT (el tamaño total acordado del
        # envío), igual que en los lotes que genera una OC (cantidad_original
        # = cantidad pedida). Si en cambio se fuera acumulando cantidad +
        # cantidad en cada recepción, un ciclo de rechazo → devolución →
        # reingreso del reemplazo (que vuelve a pasar por este mismo camino,
        # ver ott_devolver_rechazo) infla el original más allá de lo
        # realmente enviado (ej. recibo 90, rechazo y devuelvo esas 90,
        # reingresan 80 de reemplazo → el original terminaba en 90+80=170 en
        # vez de quedarse en los 100 que se enviaron en total). Si la OTT no
        # tiene cantidad_enviada cargada (caso legado), se sigue acumulando
        # como antes por no tener un techo de referencia.
        if cantidad_enviada > 0:
            execute("""UPDATE lotes SET cantidad_original=MAX(cantidad_original,?),
                cantidad_disponible=cantidad_disponible+?,
                estado=CASE WHEN estado IN ('Aprobado','Rechazado','Agotado') THEN 'Ingresado' ELSE estado END
                WHERE id=?""",
                (cantidad_enviada, cantidad, lote_id))
        else:
            execute("""UPDATE lotes SET cantidad_original=cantidad_original+?,
                cantidad_disponible=cantidad_disponible+?,
                estado=CASE WHEN estado IN ('Aprobado','Rechazado','Agotado') THEN 'Ingresado' ELSE estado END
                WHERE id=?""",
                (cantidad, cantidad, lote_id))
    else:
        num_lote = siguiente_numero("lotes", "Lote-OTT-", 3)

        # cantidad_original arranca en cantidad_enviada (el total acordado
        # del envío), no en lo recibido en esta primera entrega — ver
        # comentario arriba en la rama de ampliación. Si no hay
        # cantidad_enviada cargada, se usa lo recibido como antes.
        cantidad_original_inicial = cantidad_enviada if cantidad_enviada > 0 else cantidad
        lote_id = execute("""INSERT INTO lotes
            (numero,material_id,cantidad_original,cantidad_disponible,cantidad_activa,
             proveedor_id,estado,obs,creado_por)
            VALUES (?,?,?,?,0,?,?,?,?)""",
            (num_lote, mat_id, cantidad_original_inicial, cantidad, ott["proveedor_id"], "Ingresado",
             f"Retorno OTT {ott['numero']} — OT {ott['ot_numero'] or '—'} — pendiente de aprobación en Lotes",
             session["user_id"]))

    # Las piezas volvieron del tercero y están en el depósito: entran a
    # inventario ahora, las apruebe Calidad o no.
    execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
        WHERE id=?""", (cantidad, mat_id))
    execute("UPDATE lotes SET stock_computado=1 WHERE id=?", (lote_id,))
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,'ingreso',?,?,?)""",
        (mat_id, lote_id, cantidad,
         f"Retorno OTT {ott['numero']} — ingreso a inventario, pendiente de clasificación"
         + (f" · Remito {remito_prov}" if remito_prov else ""),
         session["user_id"]))
    if remito_prov:
        execute("UPDATE lotes SET referencia_proveedor=COALESCE(NULLIF(referencia_proveedor,''),?) WHERE id=?",
                (remito_prov, lote_id))

    # ── Reservar el lote exclusivamente para la OT de origen ──────────────
    # Este material (semielaborado) es el resultado de una operación
    # tercerizada dentro de una OT puntual: no debe quedar disponible como
    # stock libre para cubrir otras OTs (ni para que el análisis de
    # faltantes/MRP lo tome para otra orden). Se reserva de la misma forma
    # que "asignar_lote_a_ot" (cantidad_reservada + orden_lotes), así el
    # lote queda atado exclusivamente a esta OT para la siguiente operación
    # del proceso, y no aparece como "disponible libre" para ninguna otra
    # orden.
    if ott["ot_origen_id"]:
        execute("UPDATE lotes SET cantidad_reservada=COALESCE(cantidad_reservada,0)+? WHERE id=?",
                (cantidad, lote_id))
        # Si el material (semielaborado) no estaba en la foto de
        # orden_materiales tomada al crear la OT, el UPDATE de abajo no
        # afecta ninguna fila y la reserva queda "huérfana": no aparece en
        # "Lotes asignados" y, peor, la novedad que debería consumirla la
        # salta en silencio (ver create_novedad). Se asegura la fila antes
        # de sumarle la cantidad asignada.
        existe_om = query("SELECT 1 FROM orden_materiales WHERE orden_id=? AND material_id=?",
            (ott["ot_origen_id"], mat_id), one=True)
        if not existe_om:
            execute("""INSERT INTO orden_materiales
                (orden_id,material_id,cantidad_requerida,cantidad_asignada,unidad)
                VALUES (?,?,0,0,(SELECT unidad FROM materiales WHERE id=?))""",
                (ott["ot_origen_id"], mat_id, mat_id))
        execute("""UPDATE orden_materiales SET cantidad_asignada=cantidad_asignada+?
            WHERE orden_id=? AND material_id=?""", (cantidad, ott["ot_origen_id"], mat_id))
        execute("""INSERT INTO orden_lotes (orden_id,lote_id,material_id,cantidad_usada,fecha)
            VALUES (?,?,?,?,date('now','localtime'))
            ON CONFLICT(orden_id,lote_id) DO UPDATE SET
                cantidad_usada=cantidad_usada+excluded.cantidad_usada,
                fecha=excluded.fecha""", (ott["ot_origen_id"], lote_id, mat_id, cantidad))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,'reserva',?,?,?)""",
            (mat_id, lote_id, cantidad,
             f"Reservado exclusivo para {ott['ot_numero'] or '—'} | Retorno OTT {ott['numero']} "
             "(no disponible para otras OTs)", session["user_id"]))

    if completa:
        execute("""UPDATE ordenes_tercerizado
            SET estado=?, lote_retorno_id=?, cantidad_recibida=?,
                fecha_retorno_real=date('now','localtime') WHERE id=?""",
            (nuevo_estado, lote_id, cantidad_recibida_total, oid))
    else:
        execute("""UPDATE ordenes_tercerizado
            SET estado=?, lote_retorno_id=?, cantidad_recibida=? WHERE id=?""",
            (nuevo_estado, lote_id, cantidad_recibida_total, oid))

    resultado = {
        "ok": True,
        "lote_numero": num_lote,
        "lote_id": lote_id,
        "mat_id": mat_id,
        "es_ultimo_nivel": False,
        "completa": completa,
        "cantidad_recibida": cantidad_recibida_total,
        "cantidad_enviada": cantidad_enviada,
        "ot_completada": False,
        "mensaje": (
            (f"Lote {num_lote} " + ("actualizado" if lote_existente else "creado") +
             " — queda pendiente de aprobación en Lotes.")
            if completa else
            f"Recepción parcial cargada al lote {num_lote} "
            f"({cantidad_recibida_total:g} de {cantidad_enviada:g} recibido) — "
            "quedan piezas pendientes de recibir."
        )
    }
    _sync_requerimiento_desde_ott(oid)
    _ott_sync_oc_recibido(oid)
    return jsonify(resultado), 201

@app.route("/api/ott/<int:oid>/devolver_rechazo", methods=["POST"])
@login_required(roles=["admin","operario","almacen"])
def ott_devolver_rechazo(oid):
    """Devuelve al proveedor las piezas que Calidad rechazó del lote de
    retorno de esta OTT (paso intermedio — solo aplica a OTTs con
    lote_retorno_id, ver update_lote/_sync_ott_retorno_a_operacion).

    La cantidad a devolver es SIEMPRE la que ya está clasificada como
    Rechazada en el lote y que todavía no se devolvió antes (lote.cantidad_rechazada
    menos lo ya acumulado en ordenes_tercerizado.cantidad_rechazada_devuelta) —
    no se tipea a mano, para que coincida exactamente con lo que Calidad
    clasificó. Si el lote se clasifica de a partes (ej. se rechaza más
    después de una devolución previa), este endpoint se puede volver a
    llamar y solo devuelve el excedente nuevo.

    Efectos:
    1) Se descuenta del lote lo devuelto: cantidad_rechazada y
       cantidad_disponible bajan en esa medida (las piezas ya no están
       físicamente en el taller, dejan de contar en la partición del lote).
       cantidad_activa (aprobado) no se toca.
    2) cantidad_recibida de la OTT baja en la misma medida — así el
       proveedor queda "debiendo" esa cantidad otra vez: pendiente de
       recibir (cantidad_enviada - cantidad_recibida) vuelve a ser mayor a
       0 y el botón "Recibir" reaparece para cargar el reemplazo, que entra
       al MISMO lote (ott.lote_retorno_id no se toca).
    3) cantidad_rechazada_devuelta acumula lo devuelto, para trazabilidad y
       para no devolver dos veces lo mismo.
    4) Se emite un remito de devolución (tipo 'devolucion_ott') vinculado a
       la OTT, igual que el remito de traslado que se emite al enviar.
    """
    ott = query("""SELECT ott.* FROM ordenes_tercerizado ott WHERE ott.id=?""", (oid,), one=True)
    if not ott: return jsonify({"error":"OTT no encontrada"}), 404
    if not ott["lote_retorno_id"]:
        return jsonify({"error":"Esta OTT todavía no recibió ningún lote — no hay nada para devolver"}), 400
    if ott["es_ultimo_nivel"]:
        return jsonify({"error":"Las OTT de último nivel (PT → cliente) no generan lote clasificable "
            "por Calidad, no aplica devolución de rechazo acá"}), 400

    lote = query("SELECT * FROM lotes WHERE id=?", (ott["lote_retorno_id"],), one=True)
    if not lote: return jsonify({"error":"Lote de retorno no encontrado"}), 404

    ya_devuelto = float(ott["cantidad_rechazada_devuelta"] or 0)
    rechazado_actual = float(lote["cantidad_rechazada"] or 0)
    cantidad = round(rechazado_actual - ya_devuelto, 6)
    if cantidad <= 0.0001:
        return jsonify({"error":"No hay piezas rechazadas pendientes de devolver para esta OTT"}), 400

    d = request.json or {}

    # 1) Descontar del lote lo devuelto (sale físicamente del taller)
    execute("""UPDATE lotes SET
            cantidad_disponible=MAX(0, cantidad_disponible-?),
            cantidad_rechazada=MAX(0, cantidad_rechazada-?)
        WHERE id=?""", (cantidad, cantidad, lote["id"]))
    # Las piezas entraron a inventario al recibirse el retorno
    # (stock_computado=1): al volver al proveedor, salen. Igual que en
    # oc_devolver_rechazo.
    if _lote_stock_computado(lote["id"]):
        execute("""UPDATE materiales SET stock=MAX(0, stock-?),
            actualizado=datetime('now','localtime') WHERE id=?""",
            (cantidad, lote["material_id"]))
    # La reserva del lote ya se liberó al clasificarlas como Rechazadas (ver
    # update_lote); acá se baja también lo asignado a la OT, porque el
    # reemplazo, al reingresar, lo vuelve a sumar (ver ott_registrar_retorno).
    if ott["ot_origen_id"]:
        execute("""UPDATE orden_lotes SET cantidad_usada=MAX(0, cantidad_usada-?)
            WHERE orden_id=? AND lote_id=?""", (cantidad, ott["ot_origen_id"], lote["id"]))
        execute("""UPDATE orden_materiales SET cantidad_asignada=MAX(0, cantidad_asignada-?)
            WHERE orden_id=? AND material_id=?""", (cantidad, ott["ot_origen_id"], lote["material_id"]))
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,'salida',?,?,?)""",
        (lote["material_id"], lote["id"], cantidad,
         f"Devolución a proveedor de piezas rechazadas — OTT {ott['numero']} (Lote {lote['numero']})",
         session["user_id"]))

    # 2) La OTT queda "debiendo" esa cantidad de nuevo del lado del proveedor
    cantidad_recibida_previa = float(ott["cantidad_recibida"] or 0)
    cantidad_recibida_nueva = max(0.0, cantidad_recibida_previa - cantidad)
    cantidad_enviada = float(ott["cantidad_enviada"] or 0)
    nuevo_estado = ott["estado"]
    if ott["estado"] != "Completado":
        nuevo_estado = "En proceso" if cantidad_recibida_nueva > 0 else (
            "Remito emitido" if cantidad_enviada > 0 else ott["estado"])

    # 3) Remito de devolución al proveedor
    num_rem = siguiente_numero("remitos", "REM-", 4)
    rid = execute("""INSERT INTO remitos (numero,cliente_id,fecha,estado,obs,creado_por,tipo,ott_id,ott_cantidad)
        VALUES (?,NULL,date('now','localtime'),'Emitido',?,?,?,?,?)""",
        (num_rem, d.get("obs", f"Devolución a proveedor — piezas rechazadas OTT {ott['numero']} "
                               f"(Lote {lote['numero']})"),
         session["user_id"], "devolucion_ott", oid, cantidad))

    execute("""UPDATE ordenes_tercerizado SET
            estado=?, cantidad_recibida=?, cantidad_rechazada_devuelta=?,
            remito_devolucion_id=?
        WHERE id=?""",
        (nuevo_estado, cantidad_recibida_nueva, ya_devuelto + cantidad, rid, oid))

    _ott_sync_oc_recibido(oid)
    _sync_requerimiento_desde_ott(oid)
    return jsonify({"ok": True, "cantidad_devuelta": cantidad, "remito_numero": num_rem,
        "remito_id": rid, "cantidad_recibida": cantidad_recibida_nueva,
        "cantidad_rechazada_devuelta": ya_devuelto + cantidad, "estado": nuevo_estado})

@app.route("/api/ott/<int:oid>/completar", methods=["POST"])
@login_required(roles=["admin","operario"])
def ott_completar(oid):
    """Confirmación MANUAL de cierre de la OTT (botón "Completar"). Aprobar o
    rechazar piezas del lote de retorno (ver update_lote/
    _sync_ott_retorno_a_operacion) solo va actualizando qty_producida de la
    operación de forma incremental — nunca marca nada como Completada por sí
    solo. Acá, y solo acá, es donde el usuario decide dar la OTT por
    cerrada, y recién en ese momento se marca Completada tanto la OTT como
    la operación de la OT asociada (con lo aprobado hasta este momento como
    qty_producida final)."""
    ott = query("""SELECT ott.*, oo.id oo_id, oo.estado oo_estado
        FROM ordenes_tercerizado ott
        LEFT JOIN orden_operaciones oo ON oo.id=ott.operacion_id
        WHERE ott.id=?""", (oid,), one=True)
    if not ott: return jsonify({"error": "OTT no encontrada"}), 404
    if ott["estado"] == "Completado":
        return jsonify({"ok": True})  # ya estaba completada, idempotente

    # Lo aprobado ACUMULADO del lote de retorno: lo que sigue en el lote más
    # lo que ya se consumió para esta OT (novedades de la operación siguiente
    # o reenvío a otro tercero). Mirar solo cantidad_activa pisaba
    # qty_producida con lo que quedaba en el lote y se perdían piezas (mismo
    # criterio que _sync_ott_retorno_a_operacion).
    aprobado = None
    if ott["lote_retorno_id"]:
        lote = query("SELECT cantidad_activa FROM lotes WHERE id=?", (ott["lote_retorno_id"],), one=True)
        if lote:
            aprobado = float(lote["cantidad_activa"] or 0)
            if ott["ot_origen_id"]:
                row = query("""SELECT COALESCE(cantidad_consumida,0) c FROM orden_lotes
                    WHERE orden_id=? AND lote_id=?""",
                    (ott["ot_origen_id"], ott["lote_retorno_id"]), one=True)
                aprobado += float(row["c"] or 0) if row else 0.0

    execute("UPDATE ordenes_tercerizado SET estado='Completado' WHERE id=?", (oid,))
    if ott["oo_id"] and ott["oo_estado"] != "Completada":
        if aprobado is not None:
            execute("UPDATE orden_operaciones SET estado='Completada',qty_producida=? WHERE id=?",
                (aprobado, ott["oo_id"]))
        else:
            execute("UPDATE orden_operaciones SET estado='Completada' WHERE id=?", (ott["oo_id"],))
    # El semielaborado NO se consume acá: lo consume la operación siguiente al
    # declarar sus novedades (ver _materiales_ott_pendientes_por_operacion) o
    # el reenvío a otro tercero. Consumirlo al cerrar la OTT dejaba a la
    # operación siguiente sin material y la OT trabada. Lo que sobre se da de
    # baja al completar la OT (ver _consumir_pse_sobrante_ot).
    _sync_requerimiento_desde_ott(oid)
    return jsonify({"ok": True})

# ── Materiales/PT requeridos por una operación de OT + lotes disponibles ──────
@app.route("/api/orden_operaciones/<int:ooid>/materiales_requeridos")
@login_required()
def get_materiales_requeridos_op(ooid):
    """Para el modal de novedad: qué materiales/PT exige la operación y qué
    lotes están disponibles para vincular a cada uno (stock activo > 0)."""
    oo = query("SELECT * FROM orden_operaciones WHERE id=?", (ooid,), one=True)
    if not oo:
        return jsonify({"error": "Operación no encontrada"}), 404
    mats = query("""SELECT om.material_id, om.cantidad cantidad_unitaria, om.unidad, om.tipo,
        m.codigo, m.descripcion, m.categoria
        FROM orden_operacion_materiales om
        JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_operacion_id=?
          AND EXISTS (
            SELECT 1 FROM orden_materiales omt
            WHERE omt.orden_id=? AND omt.material_id=om.material_id
          )""", (oo["id"], oo["orden_id"]))
    out = []
    for mat in mats:
        es_insumo = mat["categoria"] in ("Insumo", "Herramienta")
        # Los insumos no llevan trazabilidad por lote: se descuentan directo
        # del stock general al completar la OT, sin pedirle al operario que
        # elija un lote acá.
        lotes = [] if es_insumo else query("""SELECT l.id, l.numero,
            MAX(0, l.cantidad_activa - COALESCE(l.cantidad_reservada,0)) AS disponible_libre,
            l.referencia_proveedor, l.fecha_ingreso
            FROM lotes l
            WHERE l.material_id=? AND l.cantidad_activa > COALESCE(l.cantidad_reservada,0)
            ORDER BY l.fecha_ingreso""", (mat["material_id"],))
        # Si esta OT ya tiene un lote vinculado para este material (reservado
        # en una novedad anterior), informarlo para bloquear el selector.
        lote_vinculado = None if es_insumo else query("""
            SELECT l.id, l.numero, ol.cantidad_usada
            FROM orden_lotes ol JOIN lotes l ON l.id=ol.lote_id
            WHERE ol.orden_id=? AND ol.material_id=?""",
            (oo["orden_id"], mat["material_id"]), one=True)
        out.append({
            "material_id": mat["material_id"], "codigo": mat["codigo"],
            "descripcion": mat["descripcion"], "cantidad_unitaria": mat["cantidad_unitaria"],
            "unidad": mat["unidad"], "tipo": mat["tipo"] if "tipo" in mat.keys() else "material",
            "categoria": mat["categoria"], "requiere_lote": not es_insumo,
            "lotes": [dict(l) for l in lotes],
            "lote_vinculado": dict(lote_vinculado) if lote_vinculado else None
        })
    return jsonify(out)

# ── Lotes disponibles para un material (aprobados) ────────────────────────────
@app.route("/api/materiales/<int:mid>/lotes_aprobados")
@login_required()
def get_lotes_aprobados(mid):
    # disponible_libre = solo cantidad_activa (aprobada y no rechazada)
    # Se excluyen lotes sin stock aprobado
    rows = query("""SELECT l.id, l.numero, l.cantidad_disponible,
        l.cantidad_activa,
        MAX(0, l.cantidad_activa - COALESCE(l.cantidad_reservada,0)) AS disponible_libre,
        l.certificado, l.referencia_proveedor, l.fecha_ingreso
        FROM lotes l
        WHERE l.material_id=?
          AND l.cantidad_activa > COALESCE(l.cantidad_reservada,0)
        ORDER BY l.fecha_ingreso""", (mid,))
    return jsonify([dict(r) for r in rows])

# ── Asignar lote específico a OT ──────────────────────────────────────────────
@app.route("/api/ordenes/<int:oid>/materiales/<int:mid>/asignar_lote", methods=["POST"])
@login_required(roles=["admin","almacen","operario"])
def asignar_lote_a_ot(oid, mid):
    d = request.json
    lote_id = d.get("lote_id")
    qty     = float(d.get("cantidad", 0))
    if not lote_id or qty <= 0:
        return jsonify({"error": "lote_id y cantidad requeridos"}), 400

    lote = query("""SELECT l.* FROM lotes l
        WHERE l.id=? AND l.material_id=?""",
        (lote_id, mid), one=True)
    if not lote:
        return jsonify({"error": "Lote no encontrado para este material"}), 404

    orden = query("SELECT estado FROM ordenes WHERE id=?", (oid,), one=True)
    if orden and orden["estado"] == "Completada":
        return jsonify({"error": "La OT ya está completada: no se pueden modificar los lotes asignados"}), 400

    # Disponible libre = aprobado - ya reservado para otras OTs
    reservado_actual = float(lote["cantidad_reservada"] or 0)
    disponible_libre = max(0, float(lote["cantidad_activa"] or 0) - reservado_actual)
    if disponible_libre < qty:
        return jsonify({"error": f"Stock insuficiente: disponible libre {disponible_libre} requerido {qty}"}), 400

    # Solo reservar (no descontar del stock real).
    # El descuento efectivo ocurre al completar la OT.
    execute("UPDATE lotes SET cantidad_reservada=COALESCE(cantidad_reservada,0)+? WHERE id=?",
            (qty, lote_id))

    # Update orden_materiales assigned
    execute("""UPDATE orden_materiales SET cantidad_asignada=cantidad_asignada+?
        WHERE orden_id=? AND material_id=?""", (qty, oid, mid))

    # Record in orden_lotes (sin movimiento de stock todavía)
    # Si ya existía una reserva previa de este lote para esta OT, se SUMA
    # (no se pisa), porque cantidad_reservada en el lote ya se acumula así.
    execute("""INSERT INTO orden_lotes (orden_id,lote_id,material_id,cantidad_usada,fecha)
        VALUES (?,?,?,?,date('now','localtime'))
        ON CONFLICT(orden_id,lote_id) DO UPDATE SET
            cantidad_usada=cantidad_usada+excluded.cantidad_usada,
            fecha=excluded.fecha""", (oid, lote_id, mid, qty))

    num = query("SELECT numero FROM ordenes WHERE id=?", (oid,), one=True)["numero"]
    # Movimiento de reserva (tipo 'reserva') para trazabilidad, sin impacto en stock
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,'reserva',?,?,?)""",
        (mid, lote_id, qty, f"Reservado para {num} | Lote {lote['numero']}", session["user_id"]))

    return jsonify({"ok": True, "lote": lote["numero"], "asignado": qty})

@app.route("/api/ordenes/<int:oid>/materiales/<int:mid>/lotes/<int:lote_id>", methods=["PUT"])
@login_required(roles=["admin","almacen","operario"])
def modificar_cantidad_lote_asignado(oid, mid, lote_id):
    """Modifica la cantidad ya asignada/reservada de un lote puntual para
    esta OT (columna 'Lotes asignados'), sin tener que quitar y volver a
    asignar. Ajusta la reserva del lote y lo asignado del material por la
    diferencia; no toca stock real (eso ocurre al completar la OT).

    Si parte de ese lote ya fue CONSUMIDA (una novedad ya descontó stock
    real usando ese lote), no se puede bajar la cantidad por debajo de lo
    consumido: eso ya se gastó y queda como historial. En ese caso la
    cantidad se recorta a lo consumido en vez de rechazar la operación."""
    d = request.json or {}
    nueva_qty = float(d.get("cantidad", -1))
    if nueva_qty < 0:
        return jsonify({"error": "Cantidad inválida"}), 400

    row = query("""SELECT * FROM orden_lotes WHERE orden_id=? AND lote_id=? AND material_id=?""",
                (oid, lote_id, mid), one=True)
    if not row:
        return jsonify({"error": "Este lote no está asignado a esta OT"}), 404

    orden = query("SELECT estado FROM ordenes WHERE id=?", (oid,), one=True)
    if orden and orden["estado"] == "Completada":
        return jsonify({"error": "La OT ya está completada: no se pueden modificar los lotes asignados"}), 400

    lote = query("SELECT * FROM lotes WHERE id=?", (lote_id,), one=True)
    if not lote:
        return jsonify({"error": "Lote no encontrado"}), 404

    vieja_qty = float(row["cantidad_usada"] or 0)
    consumida = float(row["cantidad_consumida"] or 0) if "cantidad_consumida" in row.keys() else 0
    recortado = False
    if nueva_qty < consumida:
        nueva_qty = consumida  # no se puede liberar lo ya consumido, queda como está
        recortado = True
    delta = round(nueva_qty - vieja_qty, 6)

    if delta > 0:
        reservado_actual = float(lote["cantidad_reservada"] or 0)
        disponible_libre = max(0, float(lote["cantidad_activa"] or 0) - reservado_actual)
        if disponible_libre < delta:
            return jsonify({"error": f"Stock insuficiente en el lote: disponible libre {disponible_libre}, necesitás {delta} más"}), 400

    execute("UPDATE lotes SET cantidad_reservada=MAX(0,COALESCE(cantidad_reservada,0)+?) WHERE id=?",
            (delta, lote_id))
    execute("""UPDATE orden_materiales SET cantidad_asignada=MAX(0,cantidad_asignada+?)
        WHERE orden_id=? AND material_id=?""", (delta, oid, mid))

    if nueva_qty <= 0:
        # nueva_qty solo puede ser 0 acá si consumida también es 0 (si no, ya se recortó arriba)
        execute("DELETE FROM orden_lotes WHERE orden_id=? AND lote_id=? AND material_id=?", (oid, lote_id, mid))
    else:
        execute("UPDATE orden_lotes SET cantidad_usada=? WHERE orden_id=? AND lote_id=? AND material_id=?",
                (nueva_qty, oid, lote_id, mid))

    num = query("SELECT numero FROM ordenes WHERE id=?", (oid,), one=True)["numero"]
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,'reserva',?,?,?)""",
        (mid, lote_id, delta, f"Modificación asignación {num} | Lote {lote['numero']} ({vieja_qty} → {nueva_qty})", session["user_id"]))

    return jsonify({"ok": True, "lote": lote["numero"], "cantidad_anterior": vieja_qty,
                    "cantidad_nueva": nueva_qty, "cantidad_consumida": consumida, "recortado": recortado})

# ── Verificar cobertura de materiales de una OT ───────────────────────────────
@app.route("/api/ordenes/<int:oid>/materiales/alerta")
@login_required()
def alerta_materiales_ot(oid):
    mats = query("""SELECT om.material_id, om.cantidad_requerida, om.cantidad_asignada,
        m.descripcion, m.codigo, m.categoria,
        (SELECT COUNT(*) FROM lotes l WHERE l.material_id=om.material_id AND l.estado='Aprobado'
         AND l.cantidad_activa > COALESCE(l.cantidad_reservada,0)) lotes_ok
        FROM orden_materiales om JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_id=?""", (oid,))
    alertas = []
    for m in mats:
        # Los insumos/herramientas no requieren asignación de lote; se descuentan al completar la OT
        if m["categoria"] in ("Insumo", "Herramienta"):
            continue
        faltante = float(m["cantidad_requerida"] or 0) - float(m["cantidad_asignada"] or 0)
        if faltante > 0:
            alertas.append({
                "material": m["codigo"] + " — " + m["descripcion"],
                "faltante": faltante,
                "hay_lotes_aprobados": bool(m["lotes_ok"]),
            })
    return jsonify({"alertas": alertas, "ok": len(alertas) == 0})

