# ── Lotes ─────────────────────────────────────────────────────────────────────
def _gen_lote_numero():
    """Genera número de lote correlativo por año: LOTE-2026-0001"""
    return siguiente_numero("lotes", f"LOTE-{datetime.now().year}-", 4)

@app.route("/api/lotes", methods=["GET"])
@login_required()
def get_lotes():
    material_id = request.args.get("material_id")
    estado = request.args.get("estado")
    proveedor_id = request.args.get("proveedor_id")
    cliente_id = request.args.get("cliente_id")
    sql = """SELECT l.*,m.codigo mat_codigo,m.descripcion mat_descripcion,m.unidad,
        m.categoria,
        MAX(0, l.cantidad_activa - COALESCE(l.cantidad_reservada,0)) AS disponible_libre,
        p.razon proveedor_nombre, u.nombre creado_por_nombre,
        cl.id cliente_id, cl.razon cliente_nombre
        FROM lotes l
        JOIN materiales m ON m.id=l.material_id
        LEFT JOIN proveedores p ON p.id=l.proveedor_id
        LEFT JOIN usuarios u ON u.id=l.creado_por
        LEFT JOIN productos pr2 ON pr2.id=m.producto_id
        LEFT JOIN clientes cl ON cl.id=pr2.cliente_id"""
    conds, params = [], []
    if material_id:
        conds.append("l.material_id=?"); params.append(material_id)
    if estado:
        conds.append("l.estado=?"); params.append(estado)
    elif "estado" not in request.args:
        # Exclude Agotado only when no estado filter is set at all (default view)
        # When cliente sends ?estado= (Todos los estados), show everything including Agotado
        conds.append("l.estado != 'Agotado'")
    if proveedor_id:
        conds.append("l.proveedor_id=?"); params.append(proveedor_id)
    if cliente_id:
        conds.append("cl.id=?"); params.append(cliente_id)
    if conds:
        sql += " WHERE " + " AND ".join(conds)
    sql += " ORDER BY l.id DESC"
    return jsonify([dict(r) for r in query(sql, params)])

@app.route("/api/lotes", methods=["POST"])
@login_required(roles=["admin","almacen"])
def create_lote():
    d = request.json
    if not d.get("material_id") or not d.get("cantidad"):
        return jsonify({"error": "Material y cantidad requeridos"}), 400
    mat = query("SELECT categoria FROM materiales WHERE id=?", (d["material_id"],), one=True)
    if not mat:
        return jsonify({"error": "Material no encontrado"}), 404
    if mat["categoria"] != "Material":
        return jsonify({"error": "Solo se pueden crear lotes para artículos de categoría Material"}), 400
    numero = _gen_lote_numero()
    qty = float(d["cantidad"])
    lid = execute("""INSERT INTO lotes
        (numero,material_id,cantidad_original,cantidad_disponible,proveedor_id,
         referencia_proveedor,certificado,estado,obs,creado_por,stock_computado)
        VALUES (?,?,?,?,?,?,?,?,?,?,1)""",
        (numero, d["material_id"], qty, qty,
         d.get("proveedor_id"), d.get("referencia_proveedor"),
         d.get("certificado"), "Ingresado", d.get("obs"), session["user_id"]))
    # El material está en el depósito: entra a inventario al ingresarlo.
    execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
        WHERE id=?""", (qty, d["material_id"]))
    # El stock del material representa SOLO lo Aprobado por Calidad. Un lote
    # recién ingresado queda en estado "Ingresado" con cantidad_activa=0
    # (nada aprobado todavía), así que NO se suma a stock acá. El stock se
    # actualiza recién en update_lote(), cuando Calidad clasifica cantidades
    # como Aprobado/Rechazado/Pendiente. Se deja igual un movimiento
    # informativo para trazabilidad, aclarando que todavía no impacta stock.
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,?,?,?,?)""",
        (d["material_id"], lid, "ingreso", qty,
         f"Ingreso lote {numero} — {d.get('referencia_proveedor','')} (pendiente de clasificación, no computa a stock)",
         session["user_id"]))
    return jsonify({"ok": True, "id": lid, "numero": numero}), 201

@auditoria_proceso("sincronización retorno OTT → operación")
def _sync_ott_retorno_a_operacion(lote_id):
    """Si este lote es el lote de retorno de una operación tercerizada
    INTERMEDIA (OTT con lote_retorno_id=lote_id, es_ultimo_nivel=0), actualiza
    qty_producida de la operación siguiente con lo YA APROBADO del lote de
    forma incremental (aprobás 30 → se puede usar 30; aprobás 10 más → 40),
    aunque el lote todavía tenga piezas pendientes de recibir del proveedor
    o pendientes de clasificar.

    IMPORTANTE: esta función NUNCA marca la operación ni la OTT como
    Completada por sí sola, aunque lo aprobado ya alcance la cantidad
    requerida — eso quedó a propósito como un paso MANUAL: el usuario tiene
    que confirmarlo desde OTT con el botón "Completar" (ver ott_completar).
    Antes esto se auto-completaba apenas se llegaba a la cantidad requerida,
    lo cual traía dos problemas: 1) no daba lugar a que alguien revise/decida
    antes de cerrar (ej. dar la OTT por completada con menos de lo pedido si
    el faltante se da de baja), y 2) al recalcularse qty_producida en cada
    aprobación, una OTT que ya se había dejado abierta a propósito podía
    terminar "completándose sola" en un aprobado posterior sin que nadie lo
    pidiera. Acá solo se actualiza qty_producida (lo ya aprobado, para que
    la operación siguiente pueda ir cargando novedades de forma incremental
    — ver _tope_terc_previa); el pase a Completada queda 100% en manos del
    botón "Completar" de OTT. Es idempotente."""
    ott = query("""SELECT ott.*, oo.id oo_id, oo.estado oo_estado, oo.qty_requerida,
            oo.orden_id oo_orden_id, oo.orden oo_orden
        FROM ordenes_tercerizado ott
        LEFT JOIN orden_operaciones oo ON oo.id=ott.operacion_id
        WHERE ott.lote_retorno_id=? AND ott.es_ultimo_nivel=0""", (lote_id,), one=True)
    if not ott or not ott["oo_id"]:
        return
    lote = query("""SELECT id,numero,material_id,cantidad_activa,cantidad_rechazada,
            cantidad_disponible,cantidad_reservada,estado
        FROM lotes WHERE id=?""", (lote_id,), one=True)
    if not lote:
        return

    # Lo aprobado ACUMULADO de este lote: lo que sigue en el lote más lo que
    # ya se consumió para esta OT. Hay que sumar lo consumido porque el
    # semielaborado lo consume la operación siguiente (ver _materiales_ott_pendientes_por_operacion); si
    # se mirara solo cantidad_activa, una segunda aprobación parcial pisaría
    # qty_producida con el delta nuevo en vez del total.
    consumido = 0.0
    if ott["ot_origen_id"]:
        row = query("""SELECT COALESCE(cantidad_consumida,0) c FROM orden_lotes
            WHERE orden_id=? AND lote_id=?""",
            (ott["ot_origen_id"], lote_id), one=True)
        consumido = float(row["c"] or 0) if row else 0.0
    aprobado = float(lote["cantidad_activa"] or 0) + consumido
    if aprobado <= 0:
        return  # todavía no hay nada aprobado

    # Solo actualiza qty_producida (lo ya aprobado hasta ahora), sin tocar
    # el estado de la operación ni de la OTT — el cierre es manual, ver
    # ott_completar.
    if ott["oo_estado"] != "Completada":
        usa_cajones = _ot_usa_cajones(ott["oo_orden_id"])
        execute("UPDATE orden_operaciones SET qty_producida=? WHERE id=?",
            (aprobado, ott["oo_id"]))
        _sync_cajones_op_tercerizada(ott["oo_id"], usa_cajones)


def _consumir_pse_sobrante_ot(oid):
    """Al completar la OT, da de baja el semielaborado aprobado que quedó en
    los lotes de retorno de sus OTT intermedias sin que la operación
    siguiente lo consumiera (piezas que no siguieron la ruta). Antes esto se
    hacía al cerrar cada OTT, pero ahí todavía hacía falta para la operación
    siguiente."""
    for ott in query("""SELECT ott.id, ott.numero, ott.lote_retorno_id FROM ordenes_tercerizado ott
            WHERE ott.ot_origen_id=? AND ott.es_ultimo_nivel=0
              AND ott.lote_retorno_id IS NOT NULL""", (oid,)):
        lote = query("""SELECT id,numero,material_id,cantidad_activa FROM lotes WHERE id=?""",
            (ott["lote_retorno_id"],), one=True)
        if not lote:
            continue
        sobrante = float(lote["cantidad_activa"] or 0)
        if sobrante <= 0.0001:
            continue
        execute("""UPDATE lotes SET
                cantidad_activa=MAX(0, cantidad_activa-?),
                cantidad_disponible=MAX(0, cantidad_disponible-?),
                cantidad_reservada=MAX(0, COALESCE(cantidad_reservada,0)-?),
                estado=CASE WHEN cantidad_disponible-? <= 0.0001 THEN 'Agotado' ELSE estado END
            WHERE id=?""", (sobrante, sobrante, sobrante, sobrante, lote["id"]))
        execute("""UPDATE materiales SET stock=MAX(0, stock-?),
                actualizado=datetime('now','localtime') WHERE id=?""",
            (sobrante, lote["material_id"]))
        execute("""UPDATE orden_lotes SET cantidad_consumida=COALESCE(cantidad_consumida,0)+?
            WHERE orden_id=? AND lote_id=?""", (sobrante, oid, lote["id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,'salida',?,?,?)""",
            (lote["material_id"], lote["id"], sobrante,
             f"Baja del semielaborado sobrante al completar la OT — OTT {ott['numero']} "
             f"— Lote {lote['numero']}", session.get("user_id")))


@app.route("/api/lotes/<int:lid>", methods=["PUT"])
@login_required(roles=["admin","almacen","calidad"])
def update_lote(lid):
    d = request.json
    lote = query("SELECT * FROM lotes WHERE id=?", (lid,), one=True)
    if not lote: return jsonify({"error": "Lote no encontrado"}), 404

    if query("SELECT 1 FROM cajones WHERE lote_id=? LIMIT 1", (lid,), one=True):
        if ("cantidad_aprobada" in d or "cantidad_rechazada" in d
                or ("estado" in d and d.get("estado") != lote["estado"])):
            return jsonify({"error": "Este lote tiene cajones: Calidad libera o rechaza cada cajón "
                                     "desde la lista de cajones del lote."}), 400
        execute("UPDATE lotes SET referencia_proveedor=?,certificado=?,obs=? WHERE id=?",
            (d.get("referencia_proveedor", lote["referencia_proveedor"]),
             d.get("certificado", lote["certificado"]), d.get("obs", lote["obs"]), lid))
        return jsonify({"ok": True, "numero_lote": lote["numero"], "estado": lote["estado"]})

    disp = float(lote["cantidad_disponible"])

    # ── Modelo nuevo: se editan los 3 valores de la partición del lote
    # (Aprobado / Rechazado / Pendiente) de forma absoluta, no incremental.
    # Esto evita que aprobar y rechazar por separado sumen más que el total
    # disponible, y permite corregir un dato mal cargado simplemente
    # reabriendo el lote y volviendo a fijar los valores correctos.
    if "cantidad_aprobada" in d or "cantidad_rechazada" in d:
        aprobado = float(d.get("cantidad_aprobada", lote["cantidad_activa"] or 0) or 0)
        rechazado = float(d.get("cantidad_rechazada", lote["cantidad_rechazada"] or 0) or 0)
        if aprobado < 0 or rechazado < 0:
            return jsonify({"error": "Las cantidades no pueden ser negativas"}), 400
        if aprobado + rechazado > disp + 0.001:
            return jsonify({"error": "Aprobado (%.2f) + Rechazado (%.2f) no puede superar el total disponible (%.2f)"
                % (aprobado, rechazado, disp)}), 400
        # Lo aprobado no puede quedar por debajo de lo que ya está reservado
        # para OTs (asignado desde "Lotes asignados" o retorno de OTT): la
        # reserva quedaría apuntando a piezas que ya no están aprobadas.
        # (lo que pase a Rechazado libera reserva en la misma medida, ver abajo)
        reservado_lote = max(0.0, float(lote["cantidad_reservada"] or 0)
                             - max(0.0, rechazado - float(lote["cantidad_rechazada"] or 0)))
        if aprobado < float(lote["cantidad_activa"] or 0) and aprobado + 0.001 < reservado_lote:
            return jsonify({"error": "No se puede bajar el aprobado a %.2f: hay %.2f reservadas para OTs en este lote. "
                "Liberá esa asignación desde Órdenes de trabajo → Lotes asignados antes de corregir."
                % (aprobado, reservado_lote)}), 400

        pendiente = max(0.0, disp - aprobado - rechazado)
        if disp <= 0.0001:
            estado_lote = "Agotado"
        elif pendiente <= 0.001 and aprobado >= rechazado:
            estado_lote = "Aprobado"
        elif pendiente <= 0.001 and rechazado > aprobado:
            estado_lote = "Rechazado"
        else:
            estado_lote = "Ingresado"  # queda algo pendiente de analizar (parcial)

        execute("""UPDATE lotes SET estado=?,cantidad_activa=?,cantidad_rechazada=?,
            referencia_proveedor=?,certificado=?,obs=? WHERE id=?""",
            (estado_lote, aprobado, rechazado,
             d.get("referencia_proveedor", lote["referencia_proveedor"]),
             d.get("certificado", lote["certificado"]),
             d.get("obs", lote["obs"]), lid))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,?,?,?,?)""",
            (lote["material_id"], lid, "ajuste", disp,
             ("Edición liberación → Aprobado:%.2f Rechazado:%.2f Pendiente:%.2f | Lote %s"
                % (aprobado, rechazado, pendiente, lote["numero"]))
             + (" | Obs: " + d.get("obs") if d.get("obs") else ""),
             session["user_id"]))
        # ── El stock del material representa SOLO lo Aprobado ──────────────
        # Lo Pendiente y lo Rechazado NO cuentan como stock disponible. Por
        # eso el ajuste de stock se calcula en base a la variación de
        # cantidad_aprobada (cantidad_activa) respecto del valor previo, sin
        # importar cómo se haya movido lo Rechazado/Pendiente. Si aprobado
        # sube, entra a stock; si baja (ej. se corrige una clasificación),
        # sale de stock.
        aprobado_anterior = float(lote["cantidad_activa"] or 0)
        delta_aprobado = aprobado - aprobado_anterior
        # Si las piezas ya entraron a inventario al entrar al deposito
        # (stock_computado=1), clasificarlas no mueve nada: estan fisicamente
        # ahi igual, aprobadas o no.
        if bool(lote["stock_computado"] if "stock_computado" in lote.keys() else 0):
            delta_aprobado = 0.0
        if abs(delta_aprobado) > 0.0001:
            execute("""UPDATE materiales SET stock=MAX(0,stock+?),
                actualizado=datetime('now','localtime') WHERE id=?""",
                (delta_aprobado, lote["material_id"]))
            execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
                VALUES (?,?,?,?,?,?)""",
                (lote["material_id"], lid,
                 "entrada" if delta_aprobado > 0 else "salida",
                 abs(delta_aprobado),
                 (f"Aprobación de lote {lote['numero']} — ingreso a inventario"
                  if delta_aprobado > 0 else
                  f"Corrección de aprobación — Lote {lote['numero']} (baja de inventario)"),
                 session["user_id"]))
        auto_generar_sc_bajo_stock(lote["material_id"], f"ajuste de lote {lote['numero']} (aprobado/rechazado)")
        # ── Lo Rechazado nunca podrá usarse, así que si estaba reservado
        # para una OT (ver ott_registrar_retorno / asignar_lote_a_ot) hay
        # que liberar esa reserva en la misma medida en que sube lo
        # rechazado — si no, queda "cantidad_reservada" fantasma que nunca
        # se puede cubrir con material real. Si rechazado bajara (corrección
        # de una clasificación), no se reconstruye la reserva automáticamente.
        rechazado_anterior = float(lote["cantidad_rechazada"] or 0)
        delta_rechazado = rechazado - rechazado_anterior
        if delta_rechazado > 0.0001:
            execute("UPDATE lotes SET cantidad_reservada=MAX(0,COALESCE(cantidad_reservada,0)-?) WHERE id=?",
                (delta_rechazado, lid))
        _sync_ott_retorno_a_operacion(lid)
        return jsonify({"ok": True, "numero_lote": lote["numero"],
            "cantidad_aprobada": aprobado, "cantidad_rechazada": rechazado,
            "cantidad_pendiente": pendiente, "estado": estado_lote})

    # ── Modelo legado: cambio de estado de todo el lote de una sola vez
    # (se mantiene por compatibilidad con otros llamadores internos)
    nuevo_estado = d.get("estado", lote["estado"])
    nueva_activa_total = disp if nuevo_estado == "Aprobado" else 0
    nueva_rechazada_total = disp if nuevo_estado == "Rechazado" else 0
    execute("""UPDATE lotes SET estado=?,cantidad_activa=?,cantidad_rechazada=?,
        referencia_proveedor=?,certificado=?,obs=? WHERE id=?""",
        (nuevo_estado, nueva_activa_total, nueva_rechazada_total,
         d.get("referencia_proveedor", lote["referencia_proveedor"]),
         d.get("certificado", lote["certificado"]),
         d.get("obs", lote["obs"]), lid))
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,?,?,?,?)""",
        (lote["material_id"], lid, "ajuste", disp,
         f"Cambio estado → {nuevo_estado} | Lote {lote['numero']}",
         session["user_id"]))
    # ── El stock del material representa SOLO lo Aprobado (ver explicación
    # detallada en el modelo nuevo más arriba) — el ajuste se calcula según
    # la variación de cantidad_activa (aprobado), no de rechazado ─────────
    aprobado_anterior = float(lote["cantidad_activa"] or 0)
    delta_aprobado = nueva_activa_total - aprobado_anterior
    # Idem: un lote cuyo stock ya se computo al crearlo no se mueve por Calidad.
    if bool(lote["stock_computado"] if "stock_computado" in lote.keys() else 0):
        delta_aprobado = 0.0
    if abs(delta_aprobado) > 0.0001:
        execute("""UPDATE materiales SET stock=MAX(0,stock+?),
            actualizado=datetime('now','localtime') WHERE id=?""",
            (delta_aprobado, lote["material_id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,?,?,?,?)""",
            (lote["material_id"], lid,
             "entrada" if delta_aprobado > 0 else "salida",
             abs(delta_aprobado),
             (f"Aprobación de lote {lote['numero']} — ingreso a inventario"
              if delta_aprobado > 0 else
              f"Corrección de aprobación — Lote {lote['numero']} (baja de inventario)"),
             session["user_id"]))
    auto_generar_sc_bajo_stock(lote["material_id"], f"cambio de estado de lote {lote['numero']}")
    # ── Misma liberación de reserva que en el modelo nuevo: si el lote pasa
    # a Rechazado (o ya tenía algo rechazado), esa porción nunca se puede
    # usar, así que no debe seguir contando como reservada para la OT.
    rechazado_anterior = float(lote["cantidad_rechazada"] or 0)
    delta_rechazado = nueva_rechazada_total - rechazado_anterior
    if delta_rechazado > 0.0001:
        execute("UPDATE lotes SET cantidad_reservada=MAX(0,COALESCE(cantidad_reservada,0)-?) WHERE id=?",
            (delta_rechazado, lid))
    _sync_ott_retorno_a_operacion(lid)
    return jsonify({"ok": True, "accion": "estado_actualizado",
        "estado": nuevo_estado, "cant_activa": nueva_activa_total})

# ── Cajones: consulta, calidad, transferencia y baja ─────────────────────────
_CAJON_SQL = """SELECT cj.*, o.numero ot_numero, o.estado ot_estado, oor.numero ot_origen_numero,
        m.codigo producto_codigo, m.descripcion producto_nombre, l.numero lote_numero
    FROM cajones cj
    JOIN ordenes o ON o.id=cj.orden_id
    LEFT JOIN ordenes oor ON oor.id=cj.orden_origen_id
    JOIN materiales m ON m.id=cj.producto_id
    LEFT JOIN lotes l ON l.id=cj.lote_id"""


def _cajon_dict(c, paso=None):
    d = dict(c)
    por_paso = _cajon_por_paso(c["id"])
    d["terminadas"] = _cajon_terminadas(c, por_paso)
    d["por_paso"] = {str(k): v for k, v in sorted(por_paso.items())}
    if paso is not None:
        d["disponible"] = _cajon_disponible(c, paso, por_paso)
    return d


@app.route("/api/ordenes/<int:oid>/cajones", methods=["GET"])
@login_required()
def get_cajones_ot(oid):
    """Cajones de la OT. Con orden_operacion_id dice si es el primer paso
    (ahí los cajones se llenan solos) o cuánto tiene disponible cada cajón
    para esa operación."""
    oo_id = request.args.get("orden_operacion_id", type=int)
    pasos = _pasos_ot(oid)
    paso, primero = None, False
    if oo_id:
        r = query("SELECT CAST(orden AS INTEGER) p FROM orden_operaciones WHERE id=? AND orden_id=?",
            (oo_id, oid), one=True)
        if r:
            paso = r["p"]
            primero = bool(pasos) and paso == pasos[0]
    rows = query(_CAJON_SQL + " WHERE cj.orden_id=? AND cj.estado<>'Baja' ORDER BY cj.id", (oid,))
    cajones = [_cajon_dict(c, None if primero else paso) for c in rows]
    abierto = next((c for c in cajones if c["estado"] == "En proceso"
                    and c["orden_origen_id"] == c["orden_id"]
                    and c["cantidad"] < c["capacidad"] - 0.0001
                    and c["cantidad_liberada"] + c["cantidad_rechazada"] == 0), None)
    prod = query("""SELECT p.capacidad_cajon FROM ordenes o JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    return jsonify({"usa_cajones": _ot_usa_cajones(oid), "primer_paso": primero, "paso": paso,
                    "capacidad": prod["capacidad_cajon"] if prod else None,
                    "abierto": abierto, "cajones": cajones})


@app.route("/api/cajones", methods=["GET"])
@login_required()
def get_cajones():
    where, params = [], []
    buscar = (request.args.get("buscar") or "").strip()
    if buscar:
        where.append("""(cj.numero LIKE ? OR o.numero LIKE ? OR m.codigo LIKE ?
            OR m.descripcion LIKE ? OR l.numero LIKE ?)""")
        params += [f"%{buscar}%"] * 5
    for arg, col in (("lote_id", "cj.lote_id"), ("orden_id", "cj.orden_id"), ("estado", "cj.estado")):
        if request.args.get(arg):
            where.append(f"{col}=?")
            params.append(request.args.get(arg))
    sql = _CAJON_SQL + (" WHERE " + " AND ".join(where) if where else "") + " ORDER BY cj.id DESC LIMIT 500"
    return jsonify([_cajon_dict(c) for c in query(sql, tuple(params))])


@app.route("/api/cajones/<int:cid>", methods=["GET"])
@login_required()
def get_cajon(cid):
    """Trazabilidad del cajón: OT, lote, producto, piezas por paso, novedades
    (operación, operario, máquina, fecha), lotes de material consumidos en
    esas novedades, decisión de Calidad y remitos con su cliente."""
    c = query(_CAJON_SQL + " WHERE cj.id=?", (cid,), one=True)
    if not c:
        return jsonify({"error": "Cajón no encontrado"}), 404
    d = _cajon_dict(c)
    d["novedades"] = [dict(r) for r in query("""SELECT n.id, n.numero, n.fecha, nc.cantidad,
            oo.nombre operacion, oo.orden paso, o.numero ot_numero,
            e.nombre||' '||e.apellido empleado_nombre, mq.codigo||' — '||mq.nombre maquina_nombre
        FROM novedad_cajones nc
        JOIN novedades_produccion n ON n.id=nc.novedad_id
        JOIN orden_operaciones oo ON oo.id=n.orden_operacion_id
        JOIN ordenes o ON o.id=n.orden_id
        LEFT JOIN empleados e ON e.id=n.empleado_id
        LEFT JOIN maquinas mq ON mq.id=n.maquina_id
        WHERE nc.cajon_id=? ORDER BY CAST(oo.orden AS INTEGER), n.fecha, n.id""", (cid,))]
    d["tercerizadas"] = [dict(r) for r in query("""SELECT oc.cantidad, oo.nombre operacion, oo.orden paso,
            o.numero ot_numero,
            (SELECT GROUP_CONCAT(t.numero, ', ') FROM ordenes_tercerizado t WHERE t.operacion_id=oo.id) ott_numero
        FROM ott_cajones oc
        JOIN orden_operaciones oo ON oo.id=oc.orden_operacion_id
        JOIN ordenes o ON o.id=oo.orden_id
        WHERE oc.cajon_id=? ORDER BY CAST(oo.orden AS INTEGER)""", (cid,))]
    # Una novedad que abarcó varios cajones muestra sus lotes de material en
    # todos ellos: el consumo no se puede repartir por cajón.
    d["materiales"] = [dict(r) for r in query("""SELECT n.numero novedad_numero, l.numero lote_numero,
            m.codigo material_codigo, m.descripcion material,
            SUM(CASE WHEN mv.tipo='salida' THEN mv.cantidad ELSE -mv.cantidad END) cantidad
        FROM novedad_cajones nc
        JOIN novedades_produccion n ON n.id=nc.novedad_id
        JOIN movimientos mv ON (mv.referencia LIKE 'Consumo real por Novedad ' || n.numero || ' %'
                             OR mv.referencia LIKE 'Ajuste consumo ' || n.numero || ' %')
        JOIN lotes l ON l.id=mv.lote_id
        JOIN materiales m ON m.id=mv.material_id
        WHERE nc.cajon_id=?
        GROUP BY n.id, l.id ORDER BY n.id, l.id""", (cid,))]
    u = query("SELECT nombre FROM usuarios WHERE id=?", (c["calidad_por"],), one=True) if c["calidad_por"] else None
    d["calidad_por_nombre"] = u["nombre"] if u else None
    d["remitos"] = [dict(r) for r in query("""SELECT r.id, r.numero, r.fecha, r.estado,
            cl.razon cliente_nombre, ric.cantidad
        FROM remito_item_cajones ric
        JOIN remito_items ri ON ri.id=ric.remito_item_id
        JOIN remitos r ON r.id=ri.remito_id
        LEFT JOIN clientes cl ON cl.id=r.cliente_id
        WHERE ric.cajon_id=? ORDER BY r.id""", (cid,))]
    return jsonify(d)


@app.route("/api/cajones/<int:cid>/calidad", methods=["POST"])
@login_required(roles=["admin","almacen","calidad"])
def calidad_cajon(cid):
    """Calidad libera y/o rechaza piezas terminadas del cajón (valores
    absolutos: se puede liberar una parte y dejar el resto pendiente, o
    corregir/deshacer mientras no se haya remitido). Lo liberado pasa a
    disponible del lote (cantidad_activa) y lo rechazado a su columna
    Rechazado; el estado del lote se deriva de sus cajones."""
    d = request.json or {}
    c = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
    if not c:
        return jsonify({"error": "Cajón no encontrado"}), 404
    if c["estado"] in ("Baja", "En espera"):
        return jsonify({"error": f"El cajón está {c['estado'].lower()}"}), 400
    term = _cajon_terminadas(c)
    lote_id = c["lote_id"] or _lote_pt_ot(c["orden_id"])
    if term <= 0.0001 or not lote_id:
        return jsonify({"error": "El cajón todavía no tiene piezas terminadas por la última operación"}), 400
    try:
        lib = float(d.get("cantidad_liberada", c["cantidad_liberada"]) or 0)
        rech = float(d.get("cantidad_rechazada", c["cantidad_rechazada"]) or 0)
    except (TypeError, ValueError):
        return jsonify({"error": "Cantidades inválidas"}), 400
    if lib < 0 or rech < 0:
        return jsonify({"error": "Las cantidades no pueden ser negativas"}), 400
    if lib + rech > term + 0.0001:
        return jsonify({"error": f"Liberado ({lib:g}) + rechazado ({rech:g}) no puede superar las "
                                 f"{term:g} piezas terminadas del cajón"}), 400
    if lib < float(c["cantidad_remitida"] or 0) - 0.0001:
        return jsonify({"error": f"Del cajón ya se remitieron {float(c['cantidad_remitida']):g} piezas: "
                                 f"no se puede liberar menos"}), 400
    lote = query("SELECT * FROM lotes WHERE id=?", (lote_id,), one=True)
    d_lib = lib - float(c["cantidad_liberada"] or 0)
    d_rech = rech - float(c["cantidad_rechazada"] or 0)
    if d_lib < 0 and float(lote["cantidad_activa"] or 0) + d_lib < -0.0001:
        return jsonify({"error": "El lote ya no tiene esas piezas liberadas disponibles "
                                 "(salieron por otro movimiento)"}), 400
    execute("""UPDATE lotes SET cantidad_activa=MAX(0, COALESCE(cantidad_activa,0)+?),
        cantidad_rechazada=MAX(0, COALESCE(cantidad_rechazada,0)+?) WHERE id=?""", (d_lib, d_rech, lote_id))
    execute("""UPDATE cajones SET cantidad_liberada=?, cantidad_rechazada=?, calidad_por=?,
        calidad_fecha=datetime('now','localtime'), calidad_obs=?, lote_id=? WHERE id=?""",
        (lib, rech, session["user_id"], d.get("obs", c["calidad_obs"]), lote_id, cid))
    _cajon_recalcular(cid)
    _lote_estado_por_cajones(lote_id)
    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
        VALUES (?,?,?,?,?,?)""",
        (c["producto_id"], lote_id, "ajuste", term,
         f"Calidad cajón {c['numero']} → Liberado:{lib:g} Rechazado:{rech:g} "
         f"Pendiente:{term - lib - rech:g} | Lote {lote['numero']}"
         + (" | Obs: " + d["obs"] if d.get("obs") else ""), session["user_id"]))
    c = query("SELECT estado FROM cajones WHERE id=?", (cid,), one=True)
    return jsonify({"ok": True, "estado": c["estado"], "cantidad_liberada": lib,
                    "cantidad_rechazada": rech, "pendiente": term - lib - rech})


@app.route("/api/cajones/<int:cid>/destinos", methods=["GET"])
@login_required()
def get_cajon_destinos(cid):
    """OTs abiertas del mismo producto a las que se puede pasar el cajón."""
    c = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
    if not c:
        return jsonify({"error": "Cajón no encontrado"}), 404
    return jsonify([dict(r) for r in query("""SELECT id, numero, estado, cantidad FROM ordenes
        WHERE producto_id=? AND id<>? AND estado NOT IN ('Cancelada','Completada')
        ORDER BY id DESC""", (c["producto_id"], c["orden_id"]))])


@app.route("/api/cajones/<int:cid>/transferir", methods=["POST"])
@login_required(roles=["admin","operario"])
def transferir_cajon(cid):
    """Un cajón en espera (su OT se canceló) pasa a otra OT abierta del mismo
    producto, que sigue desde la operación donde quedó: el tope de cada paso
    sale de lo que el cajón ya hizo en la OT anterior."""
    d = request.json or {}
    c = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
    if not c:
        return jsonify({"error": "Cajón no encontrado"}), 404
    if c["estado"] != "En espera":
        return jsonify({"error": "Solo se pueden pasar a otra OT los cajones en espera (de una OT cancelada)"}), 400
    try:
        destino = int(d.get("orden_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "Elegí la OT destino"}), 400
    o = query("SELECT id, numero, producto_id, estado FROM ordenes WHERE id=?", (destino,), one=True)
    if not o or o["id"] == c["orden_id"]:
        return jsonify({"error": "OT destino inválida"}), 400
    if o["producto_id"] != c["producto_id"]:
        return jsonify({"error": "La OT destino tiene que ser del mismo producto"}), 400
    if o["estado"] in ("Cancelada", "Completada"):
        return jsonify({"error": "La OT destino tiene que estar abierta"}), 400
    por_paso = _cajon_por_paso(cid)
    if por_paso and not [p for p in _pasos_ot(destino) if p > max(por_paso)]:
        return jsonify({"error": f"La OT {o['numero']} no tiene operaciones después del paso "
                                 f"{max(por_paso)}, donde quedó el cajón"}), 400
    origen = query("SELECT numero FROM ordenes WHERE id=?", (c["orden_id"],), one=True)
    quien = query("SELECT nombre FROM usuarios WHERE id=?", (session["user_id"],), one=True)
    nota = (f"{datetime.now().strftime('%Y-%m-%d %H:%M')} pasado de {origen['numero']} a {o['numero']}"
            f" por {quien['nombre'] if quien else '—'}")
    execute("""UPDATE cajones SET orden_id=?, lote_id=NULL, estado='En proceso',
        obs=CASE WHEN COALESCE(obs,'')='' THEN ? ELSE obs || char(10) || ? END WHERE id=?""",
        (destino, nota, nota, cid))
    _cajon_recalcular(cid)
    return jsonify({"ok": True})


@app.route("/api/cajones/<int:cid>/baja", methods=["POST"])
@login_required(roles=["admin"])
def baja_cajon(cid):
    """Da de baja un cajón en espera (sus piezas no siguen). El número no se
    reutiliza."""
    d = request.json or {}
    c = query("SELECT * FROM cajones WHERE id=?", (cid,), one=True)
    if not c:
        return jsonify({"error": "Cajón no encontrado"}), 404
    if c["estado"] != "En espera":
        return jsonify({"error": "Solo se pueden dar de baja los cajones en espera (de una OT cancelada)"}), 400
    quien = query("SELECT nombre FROM usuarios WHERE id=?", (session["user_id"],), one=True)
    nota = (f"{datetime.now().strftime('%Y-%m-%d %H:%M')} baja por {quien['nombre'] if quien else '—'}"
            + (f": {d['obs']}" if d.get("obs") else ""))
    execute("""UPDATE cajones SET estado='Baja',
        obs=CASE WHEN COALESCE(obs,'')='' THEN ? ELSE obs || char(10) || ? END WHERE id=?""", (nota, nota, cid))
    return jsonify({"ok": True})


@app.route("/api/lotes/<int:lid>/trazabilidad", methods=["GET"])
@login_required()
def trazabilidad_lote(lid):
    """Traza un lote: movimientos, OTs que lo usaron, productos terminados generados."""
    lote = query("""SELECT l.*,m.codigo mat_codigo,m.descripcion mat_descripcion
        FROM lotes l JOIN materiales m ON m.id=l.material_id WHERE l.id=?""",
        (lid,), one=True)
    if not lote: return jsonify({"error": "Lote no encontrado"}), 404

    movimientos = query("""SELECT mv.*,u.nombre usuario_nombre
        FROM movimientos mv LEFT JOIN usuarios u ON u.id=mv.usuario_id
        WHERE mv.lote_id=? ORDER BY mv.id""", (lid,))

    ordenes = query("""SELECT ol.*,o.numero ot_numero,o.estado ot_estado,
        o.fecha_entrega,c.razon cliente_nombre,p.nombre producto_nombre,
        m.descripcion mat_descripcion
        FROM orden_lotes ol
        JOIN ordenes o ON o.id=ol.orden_id
        LEFT JOIN clientes c ON c.id=o.cliente_id
        LEFT JOIN productos p ON p.id=o.producto_id
        JOIN materiales m ON m.id=ol.material_id
        WHERE ol.lote_id=? ORDER BY ol.id""", (lid,))

    return jsonify({
        "lote": dict(lote),
        "movimientos": [dict(r) for r in movimientos],
        "ordenes": [dict(r) for r in ordenes],
    })

# ── Solicitudes de compra ─────────────────────────────────────────────────────
def auto_generar_sc_bajo_stock(material_id, motivo=""):
    """Si el material quedó por debajo de su stock mínimo, genera automáticamente
    una Solicitud de Compra (si no hay ya una en curso para ese material) por la
    diferencia entre stock actual y stock máximo (o el mínimo si no hay máximo
    configurado).

    Mientras haya una SC todavía ajustable (Pendiente o Cotizada, es decir
    que todavía no se emitió su OC) para el material, NO se genera una
    nueva: se sigue trabajando con la misma, actualizando la cantidad
    solicitada si el stock siguió bajando.

    Si la SC ya tiene su OC emitida, su cantidad quedó fijada en esa orden
    de compra y ya no se puede tocar. Mientras esa OC todavía no se recibió
    (total o parcialmente) por una cantidad que cubra el faltante, NO se
    genera una SC nueva: el gasto ya está cubierto por la OC en camino. Solo
    si, aun contando esa OC pendiente de recibir, el faltante neto sigue
    siendo positivo (por ejemplo porque el consumo posterior fue mayor a lo
    pedido), se genera una SC adicional por ese remanente.

    Tampoco se genera (ni se actualiza) una SC por la parte del faltante que
    ya está cubierta por stock que YA ingresó a planta pero todavía está
    pendiente de aprobación de Calidad (lotes en estado 'Ingresado'). Si ese
    stock, al aprobarse, alcanza para llegar al mínimo, no hay necesidad
    real de comprar nada — solo falta que Calidad decida. Solo si, aun
    contando ese stock pendiente de aprobación, el faltante neto sigue
    siendo positivo, se genera la SC por ese remanente.

    Cuando el stock del material vuelve a completarse hasta el objetivo
    (stock máximo, o el mínimo si no hay máximo configurado) —típicamente al
    recibirse/aprobarse la mercadería de la OC emitida— se da por resuelta
    cualquier SC que siguiera abierta para ese material (se marca 'Cerrada').
    Recién ahí, la próxima vez que el stock vuelva a caer por debajo del
    mínimo, se generará una SC nueva.

    No hace nada si el material no es comprable (Producto terminado) o no
    tiene mínimo configurado.

    Desactivado por defecto: ver _sc_automaticas_activas()."""
    if not _sc_automaticas_activas():
        return
    if not material_id:
        return
    mat = query("SELECT id,codigo,descripcion,stock,stock_min,stock_max,unidad,categoria FROM materiales WHERE id=?",
                (material_id,), one=True)
    # "Producto terminado" NUNCA es comprable en Compras: si un material de
    # esta categoría queda bajo stock, el faltante se resuelve fabricándolo
    # (OT auxiliar vía _gap_analysis_materiales), no
    # con una Solicitud de Compra. Este chequeo antes decía excluir "Producto
    # terminado" en el comentario de arriba pero lo dejaba pasar en el código
    # (bug) — quedaba visible como faltante comprable en Compras.
    if not mat or mat["categoria"] not in ("Material", "Insumo", "Herramienta"):
        return
    stock_min = float(mat["stock_min"] or 0)
    stock_max = float(mat["stock_max"] or 0)
    stock = float(mat["stock"] or 0)
    objetivo = stock_max if stock_max > stock_min else stock_min

    # El stock se completó de nuevo hasta el objetivo: cerramos cualquier SC
    # que siguiera en curso para este material, para dejar de "trabajar" con
    # ella y habilitar que se genere una SC nueva la próxima vez que el
    # stock vuelva a quedar bajo.
    if objetivo > 0 and stock >= objetivo:
        execute("""UPDATE solicitudes_compra SET estado='Cerrada'
            WHERE material_id=? AND estado IN ('Pendiente','Cotizada','OC Emitida')""",
            (material_id,))
        return

    if stock_min <= 0 or stock >= stock_min:
        return

    faltante = round(objetivo - stock, 3)

    # Cuánto de ese faltante ya está cubierto por OC emitidas para este
    # material que todavía no se recibieron por completo (lo que está "en
    # camino" o ya recibido pero pendiente de aprobación de Calidad). Si esa
    # cobertura ya alcanza para tapar el faltante, no corresponde generar
    # (ni actualizar) una SC nueva: el gasto ya está cubierto.
    pendiente_entrega = query("""SELECT COALESCE(SUM(i.cantidad - i.cantidad_recibida),0) pend
        FROM ordenes_compra_items i
        JOIN solicitudes_compra s ON s.id = i.solicitud_id
        WHERE s.material_id=? AND s.estado='OC Emitida'""", (material_id,), one=True)["pend"] or 0

    # Stock que YA está en planta pero todavía sin decisión de Calidad
    # (lotes en estado 'Ingresado'): si ese stock se termina aprobando,
    # alcanza para tapar el faltante sin necesidad de comprar nada. Mientras
    # ese pendiente de aprobación cubra (total o parcialmente) el faltante,
    # no corresponde generar ni actualizar una SC por esa parte: no hay
    # ninguna necesidad real de compra todavía, solo falta que Calidad
    # decida sobre lo que ya se recibió.
    pendiente_aprobacion = query("""SELECT COALESCE(SUM(cantidad_disponible),0) pend
        FROM lotes WHERE material_id=? AND estado='Ingresado'""",
        (material_id,), one=True)["pend"] or 0

    faltante_neto = round(faltante - float(pendiente_entrega) - float(pendiente_aprobacion), 3)
    if faltante_neto <= 0:
        return
    faltante = faltante_neto

    # ¿Ya hay una SC todavía ajustable (Pendiente/Cotizada) para este
    # material? Seguimos trabajando con ella en lugar de generar otra.
    # Una SC con OC ya emitida NO bloquea la generación de una nueva: su
    # cantidad quedó fijada en esa orden de compra y, si el stock sigue (o
    # vuelve a quedar) por debajo del mínimo, corresponde generar una SC
    # adicional en vez de esperar a que llegue la mercadería de la anterior.
    activa = query("""SELECT id,estado,cantidad FROM solicitudes_compra
        WHERE material_id=? AND estado IN ('Pendiente','Cotizada')
        ORDER BY id DESC LIMIT 1""", (material_id,), one=True)
    if activa:
        # Todavía está Pendiente/Cotizada: la actualizamos para reflejar el
        # nuevo faltante en vez de crear otra.
        if faltante > float(activa["cantidad"] or 0):
            execute("UPDATE solicitudes_compra SET cantidad=? WHERE id=?", (faltante, activa["id"]))
        return

    numero = next_numero_sc()
    urgencia = "Urgente" if stock <= 0 else "Normal"
    obs = f"Generada automáticamente: stock ({stock}) por debajo del mínimo ({stock_min}). Reposición hasta stock máximo ({objetivo})."
    if motivo: obs += f" Origen: {motivo}."
    tipo_sc = "Productiva" if mat["categoria"] == "Material" else "Indirecta"
    execute("""INSERT INTO solicitudes_compra
        (numero,tipo,material_id,descripcion,cantidad,unidad,urgencia,estado,solicitante_id,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (numero, tipo_sc, material_id, mat["descripcion"], faltante,
         mat["unidad"], urgencia, "Pendiente", session.get("user_id"), obs))

@app.route("/api/solicitudes_compra/pendientes_count", methods=["GET"])
@login_required()
def get_sc_pendientes_count():
    # Cantidad de SC en estado 'Pendiente' -> usado por el badge del sidebar
    # en el módulo de Compras. Liviano a propósito (COUNT en vez de traer
    # todas las filas) porque se consulta con polling desde el frontend.
    row = query("SELECT COUNT(*) c FROM solicitudes_compra WHERE estado='Pendiente'", one=True)
    return jsonify({"count": row["c"]})

@app.route("/api/solicitudes_compra", methods=["GET"])
@login_required()
def get_solicitudes():
    tipo = request.args.get("tipo")
    sql = """SELECT s.*,m.codigo mat_codigo,m.descripcion mat_nombre,m.unidad mat_unidad,
        u.nombre solicitante_nombre, o.numero ot_numero,
        (SELECT oc.id FROM ordenes_compra_items oci JOIN ordenes_compra oc ON oc.id=oci.oc_id
            WHERE oci.solicitud_id=s.id ORDER BY oci.id DESC LIMIT 1) oc_id,
        (SELECT oc.numero FROM ordenes_compra_items oci JOIN ordenes_compra oc ON oc.id=oci.oc_id
            WHERE oci.solicitud_id=s.id ORDER BY oci.id DESC LIMIT 1) oc_numero
        FROM solicitudes_compra s
        LEFT JOIN materiales m ON m.id=s.material_id
        LEFT JOIN usuarios u ON u.id=s.solicitante_id
        LEFT JOIN ordenes o ON o.id=s.ot_origen_id"""
    rows = query(sql+" WHERE s.tipo=? ORDER BY s.id DESC",(tipo,)) if tipo else query(sql+" ORDER BY s.id DESC")
    return jsonify([dict(r) for r in rows])

@app.route("/api/solicitudes_compra", methods=["POST"])
@login_required(roles=["admin","almacen","operario","vendedor"])
def create_solicitud():
    d = request.json
    if not d.get("descripcion") or not d.get("cantidad"):
        return jsonify({"error":"Descripción y cantidad requeridas"}), 400
    tipo = d.get("tipo", "Productiva")
    if d.get("material_id"):
        mat = query("SELECT categoria FROM materiales WHERE id=?", (d["material_id"],), one=True)
        if not mat or mat["categoria"] not in ("Material", "Insumo", "Herramienta"):
            return jsonify({"error":"Solo se pueden solicitar materiales, insumos o herramientas — un producto terminado no se compra, se fabrica (generá o esperá la OT correspondiente)"}), 400
        if tipo == "Productiva" and mat["categoria"] != "Material":
            return jsonify({"error":"Una SC productiva solo puede cargar materiales, no insumos ni herramientas"}), 400
        if tipo == "Indirecta" and mat["categoria"] not in ("Insumo", "Herramienta"):
            return jsonify({"error":"Una SC indirecta solo puede cargar insumos o herramientas"}), 400
    elif tipo == "Productiva":
        return jsonify({"error":"Una SC productiva debe cargar un material o producto terminado"}), 400
    if d.get("material_id"):
        activa = query("""SELECT numero FROM solicitudes_compra
            WHERE material_id=? AND estado IN ('Pendiente','Cotizada')
            ORDER BY id DESC LIMIT 1""", (d["material_id"],), one=True)
        if activa:
            return jsonify({"error":f"Ya existe una solicitud de compra activa ({activa['numero']}) para este material"}), 400
    numero = next_numero_sc()
    lid = execute("""INSERT INTO solicitudes_compra
        (numero,tipo,material_id,descripcion,cantidad,unidad,urgencia,estado,ot_origen_id,centro_costo,solicitante_id,obs)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
        (numero,d.get("tipo","Productiva"),d.get("material_id"),d["descripcion"],d["cantidad"],
         d.get("unidad"),d.get("urgencia","Normal"),"Pendiente",d.get("ot_origen_id"),
         d.get("centro_costo"),session["user_id"],d.get("obs")))
    return jsonify({"ok":True,"id":lid,"numero":numero}), 201

@app.route("/api/solicitudes_compra/<int:sid>", methods=["PUT"])
@login_required(roles=["admin","almacen","vendedor"])
def update_solicitud(sid):
    d = request.json
    actual = query("SELECT * FROM solicitudes_compra WHERE id=?", (sid,), one=True)
    if not actual: return jsonify({"error":"No encontrada"}), 404
    if actual["estado"] == "OC Emitida":
        return jsonify({"error":"No se puede editar: ya tiene una OC emitida"}), 400
    campos = ["tipo","material_id","descripcion","cantidad","unidad","urgencia","estado","ot_origen_id","centro_costo","obs"]
    valores = {c: d[c] if c in d else actual[c] for c in campos}
    # Las validaciones de tipo/material solo tienen sentido cuando alguno de
    # esos dos campos realmente cambia en este PUT. Si el request solo toca
    # otra cosa (p.ej. cancelar una SC cambiando su estado), no hay que
    # revalidar datos que ya estaban guardados así (incluye SC de servicio
    # generadas automáticamente para operaciones tercerizadas, que son
    # "Productiva" sin material_id).
    if "tipo" in d or "material_id" in d:
        if valores.get("material_id"):
            mat = query("SELECT categoria FROM materiales WHERE id=?", (valores["material_id"],), one=True)
            if not mat or mat["categoria"] not in ("Material", "Insumo", "Herramienta"):
                return jsonify({"error":"Solo se pueden solicitar materiales, insumos o herramientas — un producto terminado no se compra, se fabrica"}), 400
            if valores["tipo"] == "Productiva" and mat["categoria"] != "Material":
                return jsonify({"error":"Una SC productiva solo puede cargar materiales, no insumos ni herramientas"}), 400
            if valores["tipo"] == "Indirecta" and mat["categoria"] not in ("Insumo", "Herramienta"):
                return jsonify({"error":"Una SC indirecta solo puede cargar insumos o herramientas"}), 400
        elif valores["tipo"] == "Productiva" and not (actual["material_id"] is None and (actual["unidad"] or "") == "servicio"):
            return jsonify({"error":"Una SC productiva debe cargar un material"}), 400
    execute("""UPDATE solicitudes_compra SET tipo=?,material_id=?,descripcion=?,cantidad=?,unidad=?,
        urgencia=?,estado=?,ot_origen_id=?,centro_costo=?,obs=? WHERE id=?""",
        (valores["tipo"],valores["material_id"],valores["descripcion"],valores["cantidad"],valores["unidad"],
         valores["urgencia"],valores["estado"],valores["ot_origen_id"],valores["centro_costo"],valores["obs"],sid))
    return jsonify({"ok":True})

# ── Cotizaciones de compra ────────────────────────────────────────────────────
@app.route("/api/cotizaciones_compra", methods=["GET"])
@login_required()
@solo_con_monetario
def get_cotizaciones():
    sid = request.args.get("solicitud_id")
    sql = """SELECT c.*,p.razon proveedor_nombre,s.descripcion solicitud_desc,s.cantidad sol_cantidad,s.unidad sol_unidad,s.tipo solicitud_tipo,s.estado solicitud_estado
        FROM cotizaciones_compra c
        JOIN proveedores p ON p.id=c.proveedor_id
        JOIN solicitudes_compra s ON s.id=c.solicitud_id"""
    rows = query(sql+" WHERE c.solicitud_id=? ORDER BY c.precio_unit",(sid,)) if sid else query(sql+" ORDER BY c.id DESC")
    return jsonify([dict(r) for r in rows])

@app.route("/api/cotizaciones_compra", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
@solo_con_monetario
def create_cotizacion():
    d = request.json
    if not d.get("solicitud_id") or not d.get("proveedor_id") or not d.get("precio_unit"):
        return jsonify({"error":"Solicitud, proveedor y precio requeridos"}), 400
    lid = execute("""INSERT INTO cotizaciones_compra
        (solicitud_id,proveedor_id,precio_unit,plazo_entrega_dias,condicion_pago,seleccionada,obs)
        VALUES (?,?,?,?,?,?,?)""",
        (d["solicitud_id"],d["proveedor_id"],d["precio_unit"],d.get("plazo_entrega_dias",3),
         d.get("condicion_pago"),0,d.get("obs")))
    return jsonify({"ok":True,"id":lid}), 201

ESTADOS_SC_CERRADOS = ("OC Emitida", "Cerrada", "Cancelada", "Rechazada")

@app.route("/api/cotizaciones_compra/<int:cid>", methods=["PUT"])
@login_required(roles=["admin","almacen","vendedor"])
@solo_con_monetario
def update_cotizacion(cid):
    cot = query("SELECT * FROM cotizaciones_compra WHERE id=?", (cid,), one=True)
    if not cot: return jsonify({"error":"Cotización no encontrada"}), 404
    sol = query("SELECT estado FROM solicitudes_compra WHERE id=?", (cot["solicitud_id"],), one=True)
    if sol and sol["estado"] in ESTADOS_SC_CERRADOS:
        return jsonify({"error":"No se puede editar: la solicitud de compra ya completó su circuito"}), 400
    d = request.json
    if not d.get("proveedor_id") or not d.get("precio_unit"):
        return jsonify({"error":"Proveedor y precio requeridos"}), 400
    execute("""UPDATE cotizaciones_compra SET proveedor_id=?,precio_unit=?,plazo_entrega_dias=?,
        condicion_pago=?,obs=? WHERE id=?""",
        (d["proveedor_id"],d["precio_unit"],d.get("plazo_entrega_dias",3),
         d.get("condicion_pago"),d.get("obs"),cid))
    return jsonify({"ok":True})

@app.route("/api/cotizaciones_compra/<int:cid>/seleccionar", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
@solo_con_monetario
def seleccionar_cotizacion(cid):
    cot = query("SELECT * FROM cotizaciones_compra WHERE id=?", (cid,), one=True)
    if not cot: return jsonify({"error":"Cotización no encontrada"}), 404
    sol = query("SELECT estado FROM solicitudes_compra WHERE id=?", (cot["solicitud_id"],), one=True)
    if sol and sol["estado"] in ESTADOS_SC_CERRADOS:
        return jsonify({"error":"No se puede seleccionar: la solicitud de compra ya completó su circuito"}), 400
    execute("UPDATE cotizaciones_compra SET seleccionada=0 WHERE solicitud_id=?", (cot["solicitud_id"],))
    execute("UPDATE cotizaciones_compra SET seleccionada=1 WHERE id=?", (cid,))
    execute("UPDATE solicitudes_compra SET estado='Cotizada' WHERE id=?", (cot["solicitud_id"],))
    return jsonify({"ok":True})

@app.route("/api/cotizaciones_compra/<int:cid>/deseleccionar", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
@solo_con_monetario
def deseleccionar_cotizacion(cid):
    cot = query("SELECT * FROM cotizaciones_compra WHERE id=?", (cid,), one=True)
    if not cot: return jsonify({"error":"Cotización no encontrada"}), 404
    sol = query("SELECT estado FROM solicitudes_compra WHERE id=?", (cot["solicitud_id"],), one=True)
    if sol and sol["estado"] in ESTADOS_SC_CERRADOS:
        return jsonify({"error":"No se puede deseleccionar: la solicitud de compra ya completó su circuito"}), 400
    execute("UPDATE cotizaciones_compra SET seleccionada=0 WHERE id=?", (cid,))
    # Si ya se emitió una OC para esta solicitud, no tocamos su estado (ya avanzó
    # más allá de "Cotizada"); si no, la volvemos a "Pendiente" para permitir
    # elegir otra cotización.
    sol = query("SELECT estado FROM solicitudes_compra WHERE id=?", (cot["solicitud_id"],), one=True)
    if sol and sol["estado"] == "Cotizada":
        execute("UPDATE solicitudes_compra SET estado='Pendiente' WHERE id=?", (cot["solicitud_id"],))
    return jsonify({"ok":True})

# ── Órdenes de compra a proveedores ──────────────────────────────────────────
LIMITE_APROBACION = 50000

@app.route("/api/ordenes_compra", methods=["GET"])
@login_required()
def get_ocs():
    sql = """SELECT oc.*,p.razon proveedor_nombre,u.nombre creado_por_nombre,ua.nombre aprobado_por_nombre
        FROM ordenes_compra oc
        JOIN proveedores p ON p.id=oc.proveedor_id
        LEFT JOIN usuarios u ON u.id=oc.creado_por
        LEFT JOIN usuarios ua ON ua.id=oc.aprobado_por"""
    rows = query(sql+" ORDER BY oc.id DESC")
    result = []
    for r in rows:
        d = dict(r)
        d["items"] = [dict(x) for x in query("""SELECT i.*,m.descripcion mat_desc,m.codigo mat_codigo,
            s.numero sc_numero,s.tipo sc_tipo,s.ott_id sc_ott_id,tt.numero ott_numero,
            c.condicion_pago cot_condicion_pago,c.plazo_entrega_dias cot_plazo_entrega_dias,
            l.cantidad_rechazada lote_cantidad_rechazada
            FROM ordenes_compra_items i LEFT JOIN materiales m ON m.id=i.material_id
            LEFT JOIN solicitudes_compra s ON s.id=i.solicitud_id
            LEFT JOIN ordenes_tercerizado tt ON tt.id=s.ott_id
            LEFT JOIN cotizaciones_compra c ON c.solicitud_id=i.solicitud_id AND c.seleccionada=1
            LEFT JOIN lotes l ON l.id=i.lote_id
            WHERE i.oc_id=?""", (r["id"],))]
        # Total de piezas rechazadas (clasificadas por Calidad en los lotes de
        # esta OC) que todavía no se devolvieron al proveedor — ver
        # oc_devolver_rechazo. Se usa para mostrar el botón "Devolver piezas".
        d["rechazado_pendiente_devolver"] = round(sum(
            max(0.0, float(i.get("lote_cantidad_rechazada") or 0) - float(i.get("cantidad_rechazada_devuelta") or 0))
            for i in d["items"]), 6)
        result.append(d)
    return jsonify(result)

@app.route("/api/ordenes_compra/proveedor/<int:pid>", methods=["GET"])
@login_required()
def get_ocs_by_proveedor(pid):
    """Obtiene el historial de órdenes de compra de un proveedor específico"""
    sql = """SELECT oc.*,p.razon proveedor_nombre,u.nombre creado_por_nombre,ua.nombre aprobado_por_nombre
        FROM ordenes_compra oc
        JOIN proveedores p ON p.id=oc.proveedor_id
        LEFT JOIN usuarios u ON u.id=oc.creado_por
        LEFT JOIN usuarios ua ON ua.id=oc.aprobado_por
        WHERE oc.proveedor_id=?"""
    rows = query(sql, (pid,), )
    result = []
    for r in rows:
        d = dict(r)
        d["items"] = [dict(x) for x in query("""SELECT i.*,m.descripcion mat_desc,m.codigo mat_codigo,
            s.numero sc_numero,s.tipo sc_tipo,s.ott_id sc_ott_id,tt.numero ott_numero,
            c.condicion_pago cot_condicion_pago,c.plazo_entrega_dias cot_plazo_entrega_dias
            FROM ordenes_compra_items i LEFT JOIN materiales m ON m.id=i.material_id
            LEFT JOIN solicitudes_compra s ON s.id=i.solicitud_id
            LEFT JOIN ordenes_tercerizado tt ON tt.id=s.ott_id
            LEFT JOIN cotizaciones_compra c ON c.solicitud_id=i.solicitud_id AND c.seleccionada=1
            WHERE i.oc_id=?""", (r["id"],))]
        result.append(d)
    return jsonify(result)

@app.route("/api/ordenes_compra", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
@solo_con_monetario
def create_oc():
    d = request.json
    if not d.get("proveedor_id") or not d.get("items"): return jsonify({"error":"Proveedor e ítems requeridos"}), 400
    # ── Una OC puede juntar varias SC (1 a N) en una sola orden, siempre que
    # todas tengan cotización seleccionada con el MISMO proveedor que la OC
    # (una OC va a un solo proveedor). También se revalida que la SC siga
    # disponible para comprar (evita doble-compra si dos personas abrieron el
    # modal al mismo tiempo). La generación de lotes sigue siendo por ítem
    # (ver el loop de abajo), así que aunque se agrupen varias SC en una
    # misma OC, cada una termina con su propio lote independiente. ──────────
    for item in d["items"]:
        if item.get("material_id"):
            mat = query("SELECT categoria FROM materiales WHERE id=?", (item["material_id"],), one=True)
            if mat and mat["categoria"] == "Producto terminado":
                return jsonify({"error": f"No se puede comprar \"{item.get('descripcion','')}\": es un producto terminado, no se compra, se fabrica (generá la OT correspondiente)."}), 400
        if item.get("solicitud_id"):
            sol = query("SELECT estado FROM solicitudes_compra WHERE id=?", (item["solicitud_id"],), one=True)
            if not sol:
                return jsonify({"error": "Solicitud de compra no encontrada"}), 404
            if sol["estado"] in ("OC Emitida","Cerrada","Cancelada","Rechazada"):
                return jsonify({"error": f"No se puede emitir la OC: la solicitud de compra ya no está disponible (estado: {sol['estado']})"}), 400
            cot = query("""SELECT id,proveedor_id FROM cotizaciones_compra
                WHERE solicitud_id=? AND seleccionada=1""", (item["solicitud_id"],), one=True)
            if not cot:
                return jsonify({"error":"No se puede emitir la OC: la solicitud de compra no tiene una cotización seleccionada"}), 400
            if int(cot["proveedor_id"]) != int(d["proveedor_id"]):
                return jsonify({"error":"No se puede emitir la OC: todas las solicitudes deben tener su cotización seleccionada con el mismo proveedor de la OC"}), 400
    numero = next_numero_oc()
    total = sum(float(i.get("precio_unit",0))*float(i.get("cantidad",0)) for i in d["items"])
    estado = "Aprobada" if total <= LIMITE_APROBACION else "Pendiente aprobacion"
    # v147 (punto 9): una OC generada por una OTT obtiene autorización automática
    # si el precio de TODOS sus ítems coincide con la lista de precios del
    # proveedor; si no coincide, queda pendiente de aprobación (aunque no
    # supere el límite).
    items_ott = [i for i in d["items"] if i.get("solicitud_id") and
                 query("SELECT ott_id FROM solicitudes_compra WHERE id=?", (i["solicitud_id"],), one=True)["ott_id"]]
    if items_ott:
        todos_ok = True
        for i in items_ott:
            lp = query("SELECT precio_unit FROM proveedor_materiales WHERE proveedor_id=? AND material_id=?",
                       (d["proveedor_id"], i.get("material_id")), one=True)
            if not lp or abs(float(lp["precio_unit"] or 0) - float(i.get("precio_unit", 0))) > 0.005:
                todos_ok = False; break
        estado = "Aprobada" if todos_ok else "Pendiente aprobacion"
    lid = execute("""INSERT INTO ordenes_compra
        (numero,proveedor_id,estado,monto_total,fecha_entrega_est,obs,creado_por)
        VALUES (?,?,?,?,?,?,?)""",
        (numero,d["proveedor_id"],estado,total,d.get("fecha_entrega_est"),d.get("obs"),session["user_id"]))
    lotes_creados = []
    for item in d["items"]:
        oci_id = execute("""INSERT INTO ordenes_compra_items
            (oc_id,solicitud_id,material_id,descripcion,cantidad,precio_unit,unidad)
            VALUES (?,?,?,?,?,?,?)""",
            (lid,item.get("solicitud_id"),item.get("material_id"),item["descripcion"],
             item["cantidad"],item["precio_unit"],item.get("unidad")))
        _sync_requerimiento_desde_compra(oci_id)
        if item.get("solicitud_id"):
            execute("UPDATE solicitudes_compra SET estado='OC Emitida' WHERE id=?", (item["solicitud_id"],))
            sc = query("SELECT material_id FROM solicitudes_compra WHERE id=?", (item["solicitud_id"],), one=True)
            if sc and sc["material_id"]:
                auto_generar_sc_bajo_stock(sc["material_id"], f"OC {numero} emitida para SC")
        # ── Al EMITIR la OC se crea de una el Lote de ese ítem (en 0), en
        # estado "Ingresado", ya vinculado al ítem. El lote NO arranca con la
        # cantidad pedida: solo va a reflejar lo que efectivamente vaya
        # llegando (ver recibir_oc), para no dar por planificable algo que
        # todavía no entró físicamente a planta.
        _es_ott_item = bool(item.get("solicitud_id") and
            query("SELECT ott_id FROM solicitudes_compra WHERE id=?", (item["solicitud_id"],), one=True)["ott_id"])
        if item.get("material_id") and not _es_ott_item:
            # (los ítems de OTT no crean lote acá: el lote lo genera la recepción del remito en Terceros)
            mat_cat = query("SELECT categoria FROM materiales WHERE id=?", (item["material_id"],), one=True)
            if mat_cat and mat_cat["categoria"] in ("Material", "Producto terminado"):
                numero_lote = _gen_lote_numero()
                lote_id = execute("""INSERT INTO lotes
                    (numero,material_id,cantidad_original,cantidad_disponible,cantidad_activa,
                     proveedor_id,referencia_proveedor,estado,creado_por)
                    VALUES (?,?,?,?,?,?,?,?,?)""",
                    (numero_lote, item["material_id"], 0, 0, 0,
                     d["proveedor_id"], f"OC {numero}", "Ingresado", session["user_id"]))
                lotes_creados.append(numero_lote)
                execute("UPDATE ordenes_compra_items SET lote_id=? WHERE oc_id=? AND material_id=? AND lote_id IS NULL",
                    (lote_id, lid, item["material_id"]))
    for _i in items_ott:
        _o = query("SELECT ott_id FROM solicitudes_compra WHERE id=?", (_i["solicitud_id"],), one=True)
        if _o and _o["ott_id"]:
            _ott_sync_oc_recibido(_o["ott_id"])
    return jsonify({"ok":True,"id":lid,"numero":numero,"estado":estado,"total":total,"lotes":lotes_creados}), 201

def _ott_sync_oc_recibido(ott_id):
    """v147: reparte lo recibido de una OTT (ordenes_tercerizado.cantidad_recibida)
    entre los ítems de OC vinculados a ella (vía solicitudes_compra.ott_id) y
    recalcula el estado de esas OC. Idempotente."""
    ott = query("SELECT cantidad_recibida FROM ordenes_tercerizado WHERE id=?", (ott_id,), one=True)
    if not ott: return
    restante = float(ott["cantidad_recibida"] or 0)
    items = query("""SELECT i.id,i.cantidad,i.oc_id,oc.estado FROM ordenes_compra_items i
        JOIN solicitudes_compra s ON s.id=i.solicitud_id
        JOIN ordenes_compra oc ON oc.id=i.oc_id
        WHERE s.ott_id=? AND oc.estado!='Anulada' ORDER BY i.id""", (ott_id,))
    ocs = set()
    for it in items:
        asignar = max(0.0, min(float(it["cantidad"] or 0), restante))
        execute("UPDATE ordenes_compra_items SET cantidad_recibida=? WHERE id=?", (asignar, it["id"]))
        restante -= asignar
        ocs.add(it["oc_id"])
    for ocid in ocs:
        oc = query("SELECT estado FROM ordenes_compra WHERE id=?", (ocid,), one=True)
        if not oc or oc["estado"] in ("Pendiente aprobacion", "Completada", "Anulada", "Cerrada"):
            continue
        tot = query("SELECT COALESCE(SUM(cantidad),0) t, COALESCE(SUM(cantidad_recibida),0) r FROM ordenes_compra_items WHERE oc_id=?", (ocid,), one=True)
        if tot["r"] >= tot["t"] - 0.0001 and tot["t"] > 0:
            execute("UPDATE ordenes_compra SET estado='Recibida' WHERE id=?", (ocid,))
        elif tot["r"] > 0:
            execute("UPDATE ordenes_compra SET estado='Recibida parcial' WHERE id=?", (ocid,))

def _gen_recepcion_numero():
    """Genera número de recepción correlativo por año: REC-2026-0001"""
    return siguiente_numero("recepciones", f"REC-{datetime.now().year}-", 4)

@app.route("/api/recepciones", methods=["GET"])
@login_required()
def get_recepciones():
    """Todo lo que ENTRA por Recepción directa, OC (Compras) y OTT
    (retorno de terceros) — las salidas de stock no se listan acá."""
    result = []

    directas = query("""SELECT r.*, m.codigo AS mat_codigo, m.descripcion AS mat_descripcion,
        m.unidad AS mat_unidad, m.categoria AS mat_categoria,
        p.razon AS proveedor_nombre, l.numero AS lote_numero, l.estado AS lote_estado,
        u.username AS usuario
        FROM recepciones r
        JOIN materiales m ON m.id=r.material_id
        LEFT JOIN proveedores p ON p.id=r.proveedor_id
        LEFT JOIN lotes l ON l.id=r.lote_id
        LEFT JOIN usuarios u ON u.id=r.creado_por
        ORDER BY r.id DESC""")
    for r in directas:
        d = dict(r)
        d["origen"] = "Directa"
        result.append(d)

    # ── OC (Compras): movimientos generados al Recibir una Orden de Compra
    # (ver recibir_oc). No hay tabla propia para esto — se identifica por el
    # prefijo fijo de referencia que usa ese endpoint. ──────────────────────
    oc_movs = query("""SELECT mv.id,mv.fecha,mv.cantidad,mv.referencia,mv.lote_id,
        m.codigo AS mat_codigo, m.descripcion AS mat_descripcion, m.unidad AS mat_unidad,
        m.categoria AS mat_categoria, l.numero AS lote_numero, l.estado AS lote_estado,
        u.username AS usuario
        FROM movimientos mv
        JOIN materiales m ON m.id=mv.material_id
        LEFT JOIN lotes l ON l.id=mv.lote_id
        LEFT JOIN usuarios u ON u.id=mv.usuario_id
        WHERE mv.tipo IN ('recepcion','entrada') AND mv.referencia LIKE 'Recep. %'
        ORDER BY mv.id DESC""")
    for mv in oc_movs:
        d = dict(mv)
        oc_numero = d["referencia"][len("Recep. "):].split(" · ")[0].strip()
        d["remito"] = d["referencia"].split(" · Remito ", 1)[1].strip() if " · Remito " in d["referencia"] else None
        oc = query("""SELECT oc.numero,pv.razon AS proveedor_nombre
            FROM ordenes_compra oc LEFT JOIN proveedores pv ON pv.id=oc.proveedor_id
            WHERE oc.numero=?""", (oc_numero,), one=True)
        d["numero"] = oc_numero
        d["proveedor_nombre"] = oc["proveedor_nombre"] if oc else None
        d["precio_unit"] = None
        d["origen"] = "OC"
        result.append(d)

    # ── OTT (Terceros): retornos de operaciones intermedias con lote (ver
    # ott_registrar_retorno). El retorno del ÚLTIMO nivel (PT → cliente) no
    # genera lote/movimiento — se ve reflejado directo en la OT, no acá. ────
    ott_movs = query("""SELECT mv.id,mv.fecha,mv.cantidad,mv.referencia,mv.lote_id,
        m.codigo AS mat_codigo, m.descripcion AS mat_descripcion, m.unidad AS mat_unidad,
        m.categoria AS mat_categoria, l.numero AS lote_numero, l.estado AS lote_estado,
        u.username AS usuario
        FROM movimientos mv
        JOIN materiales m ON m.id=mv.material_id
        LEFT JOIN lotes l ON l.id=mv.lote_id
        LEFT JOIN usuarios u ON u.id=mv.usuario_id
        WHERE mv.tipo='ingreso' AND mv.referencia LIKE 'Retorno OTT %'
        ORDER BY mv.id DESC""")
    for mv in ott_movs:
        d = dict(mv)
        ott_numero = d["referencia"][len("Retorno OTT "):].split(" (")[0].strip()
        d["remito"] = d["referencia"].split(" · Remito ", 1)[1].strip() if " · Remito " in d["referencia"] else None
        ott = query("""SELECT ott.numero,pv.razon AS proveedor_nombre
            FROM ordenes_tercerizado ott LEFT JOIN proveedores pv ON pv.id=ott.proveedor_id
            WHERE ott.numero=?""", (ott_numero,), one=True)
        d["numero"] = ott_numero
        d["proveedor_nombre"] = ott["proveedor_nombre"] if ott else None
        d["precio_unit"] = None
        d["origen"] = "OTT"
        result.append(d)

    result.sort(key=lambda x: x.get("fecha") or "", reverse=True)
    return jsonify(result)

@app.route("/api/recepciones", methods=["POST"])
@login_required(roles=["admin","almacen"])
def create_recepcion():
    """Registra el ingreso físico de material/insumo a planta, independiente
    de cualquier Orden de Compra. Reutiliza la misma lógica de lotes/stock
    que antes solo se disparaba al recibir una OC (ver recibir_oc):
    Material/Producto terminado generan (o hacen crecer) un lote pendiente
    de aprobación de Calidad; el resto de categorías suma directo a stock."""
    d = request.json
    if not d.get("material_id"): return jsonify({"error":"Material requerido"}), 400
    try:
        qty = float(d.get("cantidad", 0))
    except (TypeError, ValueError):
        return jsonify({"error":"Cantidad inválida"}), 400
    if qty <= 0: return jsonify({"error":"La cantidad debe ser mayor a 0"}), 400
    mat = query("SELECT * FROM materiales WHERE id=?", (d["material_id"],), one=True)
    if not mat: return jsonify({"error":"Material no encontrado"}), 404
    precio_unit = d.get("precio_unit")
    try: precio_unit = float(precio_unit) if precio_unit not in (None,"") else None
    except (TypeError, ValueError): precio_unit = None
    numero = _gen_recepcion_numero()
    lote_id = None
    if mat["categoria"] in ("Material", "Producto terminado"):
        numero_lote = _gen_lote_numero()
        lote_id = execute("""INSERT INTO lotes
            (numero,material_id,cantidad_original,cantidad_disponible,cantidad_activa,
             proveedor_id,referencia_proveedor,estado,obs,creado_por,stock_computado)
            VALUES (?,?,?,?,?,?,?,?,?,?,1)""",
            (numero_lote, mat["id"], qty, qty, 0,
             d.get("proveedor_id"), d.get("remito"), "Ingresado", d.get("obs"), session["user_id"]))
        # La mercadería entró al depósito: entra a inventario, la apruebe
        # Calidad o no.
        execute("""UPDATE materiales SET stock=stock+?, actualizado=datetime('now','localtime')
            WHERE id=?""", (qty, mat["id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,?,?,?,?)""",
            (mat["id"], lote_id, "recepcion", qty, f"Recepción {numero}", session["user_id"]))
    else:
        execute("UPDATE materiales SET stock=stock+?,actualizado=datetime('now','localtime') WHERE id=?", (qty, mat["id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,?,?,?,?)""",
            (mat["id"], None, "entrada", qty, f"Recepción {numero}", session["user_id"]))
    rid = execute("""INSERT INTO recepciones
        (numero,material_id,cantidad,proveedor_id,remito,precio_unit,lote_id,obs,creado_por)
        VALUES (?,?,?,?,?,?,?,?,?)""",
        (numero, mat["id"], qty, d.get("proveedor_id"), d.get("remito"), precio_unit,
         lote_id, d.get("obs"), session["user_id"]))
    if precio_unit is not None and precio_unit > 0 and d.get("proveedor_id"):
        execute("""INSERT OR REPLACE INTO proveedor_materiales (proveedor_id,material_id,precio_unit,plazo_dias,es_principal)
            VALUES (?,?,?,COALESCE((SELECT plazo_dias FROM proveedor_materiales WHERE proveedor_id=? AND material_id=?),3),
            COALESCE((SELECT es_principal FROM proveedor_materiales WHERE proveedor_id=? AND material_id=?),0))""",
            (d["proveedor_id"], mat["id"], precio_unit, d["proveedor_id"], mat["id"], d["proveedor_id"], mat["id"]))
    return jsonify({"ok":True,"id":rid,"numero":numero,"lote":lote_id}), 201

@app.route("/api/ordenes_compra/<int:ocid>/aprobar", methods=["POST"])
@login_required(roles=["admin","vendedor"])
def aprobar_oc(ocid):
    oc = query("SELECT estado FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    if oc["estado"] not in ("Borrador", "Pendiente aprobacion"):
        return jsonify({"error": f"No se puede aprobar una OC en estado \"{oc['estado']}\""}), 400
    execute("UPDATE ordenes_compra SET estado='Aprobada',aprobado_por=?,fecha_aprobacion=datetime('now','localtime') WHERE id=?",
        (session["user_id"], ocid))
    return jsonify({"ok":True})

@app.route("/api/ordenes_compra/<int:ocid>/recibir", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
def recibir_oc(ocid):
    d = request.json or {}
    recepciones = d.get("items", [])
    # ── Validaciones ANTES de grabar nada ─────────────────────────────────
    # Solo se recibe una OC aprobada (o ya en recepción / cerrada por saldo
    # que finalmente llega). Antes se podía recibir una OC pendiente de
    # aprobación (salteando la aprobación), una anulada o una completada, y
    # cantidades negativas.
    oc_chk = query("SELECT estado FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc_chk: return jsonify({"error":"OC no encontrada"}), 404
    if oc_chk["estado"] not in ("Aprobada", "Enviada", "Recibida parcial", "Recibida", "Cerrada"):
        return jsonify({"error": f"No se puede recibir una OC en estado \"{oc_chk['estado']}\""
                                  + (" — primero tiene que aprobarse" if oc_chk["estado"] in ("Borrador", "Pendiente aprobacion") else "")}), 400
    for recv in recepciones:
        item = query("SELECT * FROM ordenes_compra_items WHERE id=? AND oc_id=?", (recv.get("item_id"), ocid), one=True)
        if not item:
            return jsonify({"error":"Ítem de OC no encontrado en esta OC"}), 400
        try:
            qty_chk = float(recv.get("cantidad", 0))
        except (TypeError, ValueError):
            return jsonify({"error":"Cantidad inválida"}), 400
        if qty_chk <= 0:
            return jsonify({"error":"La cantidad recibida debe ser mayor a 0"}), 400
        if item["solicitud_id"]:
            _sc_ott = query("SELECT ott_id FROM solicitudes_compra WHERE id=?", (item["solicitud_id"],), one=True)
            if _sc_ott and _sc_ott["ott_id"]:
                return jsonify({"error": "Los ítems de una OC generada por una OTT se reciben desde Recepción → Pendientes de retorno — Terceros (OTT), cargando el remito."}), 400
    for recv in recepciones:
        item = query("SELECT * FROM ordenes_compra_items WHERE id=?", (recv["item_id"],), one=True)
        qty = float(recv.get("cantidad",0))
        # ── Se puede recibir una cantidad distinta a la pedida (de más o de
        # menos). Si además viene un precio_unit distinto al cargado en la
        # OC, lo actualizamos: es común que el proveedor ajuste el precio
        # cuando la cantidad finalmente entregada no coincide con la
        # pedida. El monto_total de la OC se recalcula abajo en base a estos
        # valores actualizados. ─────────────────────────────────────────────
        nuevo_precio = recv.get("precio_unit")
        if nuevo_precio is not None:
            try: nuevo_precio = float(nuevo_precio)
            except (TypeError, ValueError): nuevo_precio = None
        if nuevo_precio is not None and abs(nuevo_precio - float(item["precio_unit"])) > 0.0001:
            execute("UPDATE ordenes_compra_items SET precio_unit=? WHERE id=?", (nuevo_precio, recv["item_id"]))
        execute("UPDATE ordenes_compra_items SET cantidad_recibida=cantidad_recibida+? WHERE id=?", (qty, recv["item_id"]))
        if item["material_id"]:
            mat_cat = query("SELECT categoria FROM materiales WHERE id=?", (item["material_id"],), one=True)
            oc = query("SELECT numero FROM ordenes_compra WHERE id=?", (ocid,), one=True)
            if mat_cat and mat_cat["categoria"] in ("Material", "Producto terminado"):
                # ── El Lote de este ítem se creó al EMITIR la OC (ver
                # create_oc), en 0. Acá va creciendo con lo que efectivamente
                # se recibe en cada entrega — sea igual, menor o mayor a lo
                # pedido — para que siempre refleje la mercadería real que
                # entró a planta, pendiente de aprobación de Calidad. Si más
                # adelante llega el saldo faltante, el lote vuelve a crecer
                # con esa entrega tardía. ──────────────────────────────────
                # Primero se separa la porción de esta recepción que en
                # realidad es el REINGRESO de un reemplazo por piezas
                # rechazadas y devueltas al proveedor (ver
                # oc_devolver_rechazo): esa porción no crea crecimiento nuevo
                # del lote, vuelve al mismo lote como cantidad_disponible
                # directamente (ver bloque siguiente). El resto de la
                # recepción sí hace crecer el lote.
                devuelto = float(item["cantidad_rechazada_devuelta"] or 0)
                reingresado_previo = float(item["cantidad_rechazada_reingresada"] or 0)
                pendiente_reingreso = max(0.0, devuelto - reingresado_previo)
                a_reingresar = min(qty, pendiente_reingreso)
                crecimiento = qty - a_reingresar
                if crecimiento > 0.0001 and item["lote_id"]:
                    execute("""UPDATE lotes SET cantidad_original=cantidad_original+?,
                        cantidad_disponible=cantidad_disponible+?, stock_computado=1
                        WHERE id=?""",
                        (crecimiento, crecimiento, item["lote_id"]))
                    execute("""UPDATE materiales SET stock=stock+?,
                        actualizado=datetime('now','localtime') WHERE id=?""",
                        (crecimiento, item["material_id"]))
                    # (el movimiento de esta recepción se registra una sola
                    # vez más abajo, ya con el lote — antes se grababan dos)
                # ── Reingreso de piezas devueltas por rechazo: si este ítem
                # tuvo alguna devolución a proveedor (ver oc_devolver_rechazo),
                # lo que ahora llega como reemplazo NO forma un lote nuevo:
                # vuelve al MISMO lote de origen, sumándose a cantidad_disponible
                # como "Ingresado" (pendiente de que Calidad lo vuelva a
                # clasificar), igual que si fuera la primera recepción. Se
                # reingresa como máximo lo que efectivamente se devolvió y aún
                # no fue repuesto (cantidad_rechazada_devuelta menos lo ya
                # reingresado en entregas anteriores del reemplazo). ──────────
                if a_reingresar > 0.0001 and item["lote_id"]:
                    execute("""UPDATE lotes SET cantidad_disponible=cantidad_disponible+?,
                        estado=CASE WHEN estado IN ('Aprobado','Rechazado') THEN 'Ingresado' ELSE estado END
                        WHERE id=?""", (a_reingresar, item["lote_id"]))
                    execute("""UPDATE ordenes_compra_items SET
                        cantidad_rechazada_reingresada=? WHERE id=?""",
                        (reingresado_previo + a_reingresar, item["id"]))
                    execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
                        VALUES (?,?,?,?,?,?)""",
                        (item["material_id"], item["lote_id"], "ingreso", a_reingresar,
                         f"OC {oc['numero']} — reingreso al mismo lote de reemplazo por piezas rechazadas "
                         f"(pendiente de aprobación de Calidad, no computa a stock)",
                         session["user_id"]))
            else:
                # Otras categorías (Insumo, Herramienta) no pasan por control
                # de Calidad ni manejan lote: se suman directo, por la
                # cantidad efectivamente recibida (pueda ser más o menos que
                # lo pedido).
                execute("UPDATE materiales SET stock=stock+?,actualizado=datetime('now','localtime') WHERE id=?", (qty, item["material_id"]))
            _es_lote = bool(mat_cat and mat_cat["categoria"] in ("Material","Producto terminado"))
            _qty_mov = (qty - a_reingresar) if _es_lote else qty
            if _qty_mov > 0.0001:
              execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
                (item["material_id"], item["lote_id"] if _es_lote else None,
                 "recepcion" if _es_lote else "entrada",
                 _qty_mov, f"Recep. {oc['numero']}" + (f" · Remito {d.get('remito')}" if d.get("remito") else ""), session["user_id"]))
        _sync_requerimiento_desde_compra(item["id"])
    items = query("SELECT cantidad,cantidad_recibida,precio_unit FROM ordenes_compra_items WHERE oc_id=?", (ocid,))
    total_ord = sum(i["cantidad"] for i in items)
    total_rec = sum(i["cantidad_recibida"] for i in items)
    # ── Monto total de la OC: por cada ítem, si ya se recibió algo se cobra
    # lo efectivamente recibido a su precio (posiblemente ajustado); lo que
    # todavía está pendiente de recibir se sigue proyectando a cantidad
    # pedida x precio, para que el total refleje lo real sin perder de vista
    # lo que falta entregar. ─────────────────────────────────────────────────
    nuevo_monto = sum(
        (i["cantidad_recibida"] if i["cantidad_recibida"] > 0 else i["cantidad"]) * i["precio_unit"]
        + (max(0.0, i["cantidad"] - i["cantidad_recibida"]) * i["precio_unit"] if i["cantidad_recibida"] > 0 and i["cantidad_recibida"] < i["cantidad"] else 0.0)
        for i in items
    )
    execute("UPDATE ordenes_compra SET monto_total=? WHERE id=?", (nuevo_monto, ocid))
    if total_rec >= total_ord: execute("UPDATE ordenes_compra SET estado='Recibida' WHERE id=?", (ocid,))
    elif total_rec > 0: execute("UPDATE ordenes_compra SET estado='Recibida parcial' WHERE id=?", (ocid,))
    return jsonify({"ok":True,"monto_total":nuevo_monto})

@app.route("/api/ordenes_compra/<int:ocid>/devolver_rechazo", methods=["POST"])
@login_required(roles=["admin","operario","almacen"])
def oc_devolver_rechazo(ocid):
    """Misma lógica que ott_devolver_rechazo (ver ese endpoint) pero aplicada
    a Compras: cada ítem de la OC generó su propio Lote al emitirse la OC
    (ver create_oc, ordenes_compra_items.lote_id), y ese lote es el que
    Calidad clasifica al recibir la mercadería. Acá se recorren TODOS los
    ítems de la OC y se devuelve, de cada uno, lo que esté clasificado como
    Rechazado en su lote y todavía no se haya devuelto antes.

    Efectos por ítem con rechazo pendiente:
    1) Se descuenta del lote lo devuelto (cantidad_disponible y
       cantidad_rechazada bajan); cantidad_activa (aprobado) no se toca.
    2) cantidad_recibida del ítem baja en la misma medida — el proveedor
       vuelve a deber esa cantidad (reemplazo), que al recibirse ingresa al
       MISMO lote (no se crea uno nuevo).
    3) cantidad_rechazada_devuelta del ítem acumula lo devuelto, para no
       devolver dos veces lo mismo si el lote se clasifica de a partes.

    Se emite UN solo remito de devolución (tipo 'devolucion_oc') para toda
    la OC, agrupando lo devuelto de todos sus ítems.
    """
    oc = query("SELECT * FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404

    items = query("""SELECT i.*, l.cantidad_rechazada lote_cantidad_rechazada,
        m.descripcion mat_desc, m.codigo mat_codigo
        FROM ordenes_compra_items i
        LEFT JOIN lotes l ON l.id=i.lote_id
        LEFT JOIN materiales m ON m.id=i.material_id
        WHERE i.oc_id=?""", (ocid,))

    total_devuelto = 0.0
    detalle = []
    for item in items:
        if not item["lote_id"]:
            continue
        ya_devuelto = float(item["cantidad_rechazada_devuelta"] or 0)
        rechazado_actual = float(item["lote_cantidad_rechazada"] or 0)
        cantidad = round(rechazado_actual - ya_devuelto, 6)
        if cantidad <= 0.0001:
            continue

        # 1) Descontar del lote lo devuelto (sale físicamente del depósito)
        execute("""UPDATE lotes SET
                cantidad_disponible=MAX(0, cantidad_disponible-?),
                cantidad_rechazada=MAX(0, cantidad_rechazada-?)
            WHERE id=?""", (cantidad, cantidad, item["lote_id"]))
        # Las piezas rechazadas seguían contando en inventario mientras
        # estaban en el depósito. Al volver al proveedor, salen. (Solo para
        # lotes cuyo stock se computó al recibirlos; los anteriores a este
        # modelo nunca habían entrado.)
        if _lote_stock_computado(item["lote_id"]):
            execute("""UPDATE materiales SET stock=MAX(0, stock-?),
                actualizado=datetime('now','localtime') WHERE id=?""",
                (cantidad, item["material_id"]))
        execute("""INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id)
            VALUES (?,?,'salida',?,?,?)""",
            (item["material_id"], item["lote_id"], cantidad,
             f"Devolución a proveedor de piezas rechazadas — OC {oc['numero']} "
             f"({item['mat_codigo'] or item['descripcion']})",
             session["user_id"]))

        # 2) El ítem queda "debiendo" esa cantidad de nuevo del lado del proveedor
        cantidad_recibida_nueva = max(0.0, float(item["cantidad_recibida"] or 0) - cantidad)
        cantidad_rechazada_devuelta_nueva = ya_devuelto + cantidad
        execute("""UPDATE ordenes_compra_items SET
                cantidad_recibida=?, cantidad_rechazada_devuelta=?
            WHERE id=?""", (cantidad_recibida_nueva, cantidad_rechazada_devuelta_nueva, item["id"]))

        total_devuelto += cantidad
        detalle.append(f"{cantidad:g} x {item['mat_codigo'] or ''} {item['mat_desc'] or item['descripcion']}".strip())

    if total_devuelto <= 0.0001:
        return jsonify({"error":"No hay piezas rechazadas pendientes de devolver para esta OC"}), 400

    d = request.json or {}

    # 3) Remito de devolución al proveedor (uno solo para toda la OC)
    num_rem = siguiente_numero("remitos", "REM-", 4)
    obs_default = f"Devolución a proveedor — piezas rechazadas OC {oc['numero']}: " + "; ".join(detalle)
    rid = execute("""INSERT INTO remitos (numero,cliente_id,fecha,estado,obs,creado_por,tipo,oc_id)
        VALUES (?,NULL,date('now','localtime'),'Emitido',?,?,?,?)""",
        (num_rem, d.get("obs", obs_default), session["user_id"], "devolucion_oc", ocid))

    # 4) Recalcular estado de la OC (si lo recibido bajó, puede volver a
    # "Recibida parcial" para reflejar que hace falta el reemplazo)
    items_post = query("SELECT cantidad,cantidad_recibida FROM ordenes_compra_items WHERE oc_id=?", (ocid,))
    total_ord = sum(i["cantidad"] for i in items_post)
    total_rec = sum(i["cantidad_recibida"] for i in items_post)
    nuevo_estado = oc["estado"]
    if oc["estado"] not in ("Borrador","Pendiente aprobacion"):
        nuevo_estado = "Recibida" if total_rec >= total_ord else ("Recibida parcial" if total_rec > 0 else "Aprobada")

    execute("UPDATE ordenes_compra SET estado=?, remito_devolucion_id=? WHERE id=?",
        (nuevo_estado, rid, ocid))

    return jsonify({"ok": True, "cantidad_devuelta": round(total_devuelto, 6), "remito_numero": num_rem,
        "remito_id": rid, "estado": nuevo_estado})

@app.route("/api/ordenes_compra/<int:ocid>/cerrar", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
def cerrar_oc(ocid):
    """Cierre manual de una OC cuando el saldo pendiente (lo que se pidió
    menos lo efectivamente recibido) NO va a llegar más — el proveedor no
    entrega el resto y no tiene sentido seguir esperándolo. Congela la OC en
    'Cerrada' para que deje de listarse como pendiente de recepción (ver
    filtros de MRP/SC), pero NO toca lo ya recibido ni los lotes: el lote
    generado por esta OC queda tal cual con lo que efectivamente ingresó.

    Si más adelante el proveedor manda ese saldo igual (entrega tardía), la
    OC se puede volver a recibir con normalidad: recibir_oc() recalcula el
    estado en base a cantidad_recibida vs cantidad pedida al final de cada
    recepción, así que una nueva recepción saca a la OC de 'Cerrada' sola
    (vuelve a 'Recibida parcial' o 'Recibida' según corresponda) y el lote
    vuelve a crecer con lo que llegue.
    """
    oc = query("SELECT * FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    if oc["estado"] not in ("Aprobada","Enviada","Recibida parcial"):
        return jsonify({"error": f"No se puede cerrar una OC en estado \"{oc['estado']}\""}), 400
    execute("UPDATE ordenes_compra SET estado='Cerrada' WHERE id=?", (ocid,))
    return jsonify({"ok":True,"estado":"Cerrada"})

def _oc_tipo(ocid):
    """'Directa' si algún ítem viene de una SC productiva (o material 'Material'),
    'Indirecta' si todos son insumos/herramientas."""
    rows = query("""SELECT s.tipo sc_tipo, m.categoria cat FROM ordenes_compra_items i
        LEFT JOIN solicitudes_compra s ON s.id=i.solicitud_id
        LEFT JOIN materiales m ON m.id=i.material_id WHERE i.oc_id=?""", (ocid,))
    for r in rows:
        if r["sc_tipo"] == "Productiva" or (not r["sc_tipo"] and r["cat"] in ("Material", "Producto terminado", "Semielaborado")):
            return "Directa"
    return "Indirecta"

@app.route("/api/ordenes_compra/<int:ocid>/remitos", methods=["GET"])
@login_required()
def oc_remitos_recibidos(ocid):
    """Remitos del proveedor ya cargados al recibir esta OC (para vincular al completarla)."""
    oc = query("SELECT numero,remito_numero FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    remitos = []
    for r in query("SELECT referencia FROM movimientos WHERE referencia LIKE ?", (f"Recep. {oc['numero']}%",)):
        if " · Remito " in (r["referencia"] or ""):
            v = r["referencia"].split(" · Remito ", 1)[1].strip()
            if v and v not in remitos: remitos.append(v)
    # remitos de terceros (OTT) vinculados a los ítems de esta OC
    for t in query("""SELECT DISTINCT tt.numero FROM ordenes_compra_items i
        JOIN solicitudes_compra s ON s.id=i.solicitud_id JOIN ordenes_tercerizado tt ON tt.id=s.ott_id
        WHERE i.oc_id=?""", (ocid,)):
        for r in query("SELECT referencia FROM movimientos WHERE referencia LIKE ?", (f"Retorno OTT {t['numero']}%",)):
            if " · Remito " in (r["referencia"] or ""):
                v = r["referencia"].split(" · Remito ", 1)[1].strip()
                if v and v not in remitos: remitos.append(v)
    return jsonify({"tipo": _oc_tipo(ocid), "remitos": remitos, "remito_numero": oc["remito_numero"]})

@app.route("/api/ordenes_compra/<int:ocid>/anular", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
def anular_oc(ocid):
    """v147 (punto 8): anula una OC (directa o indirecta) que todavía no recibió
    mercadería. Libera las SC (vuelven a 'Cotizada' para poder re-emitir) y
    elimina los lotes vacíos creados al emitir."""
    d = request.json or {}
    oc = query("SELECT * FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    if oc["estado"] in ("Anulada","Completada","Recibida","Cerrada"):
        return jsonify({"error": f"No se puede anular una OC en estado \"{oc['estado']}\""}), 400
    items = query("SELECT * FROM ordenes_compra_items WHERE oc_id=?", (ocid,))
    if any(float(i["cantidad_recibida"] or 0) > 0.0001 for i in items):
        return jsonify({"error":"La OC ya tiene mercadería recibida: no se puede anular. Usá 'Completar' o 'Cerrar OC'."}), 400
    for i in items:
        if i["lote_id"]:
            l = query("SELECT cantidad_original FROM lotes WHERE id=?", (i["lote_id"],), one=True)
            mv = query("SELECT COUNT(*) c FROM movimientos WHERE lote_id=?", (i["lote_id"],), one=True)["c"]
            if l and float(l["cantidad_original"] or 0) == 0 and mv == 0:
                execute("UPDATE ordenes_compra_items SET lote_id=NULL WHERE id=?", (i["id"],))
                execute("DELETE FROM lotes WHERE id=?", (i["lote_id"],))
        if i["solicitud_id"]:
            execute("UPDATE solicitudes_compra SET estado='Cotizada' WHERE id=? AND estado='OC Emitida'", (i["solicitud_id"],))
    execute("""UPDATE ordenes_compra SET estado='Anulada',motivo_anulacion=?,fecha_anulada=datetime('now','localtime') WHERE id=?""",
        ((d.get("motivo") or "").strip() or None, ocid))
    return jsonify({"ok":True,"estado":"Anulada"})

@app.route("/api/ordenes_compra/<int:ocid>/completar", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
def completar_oc(ocid):
    """v147 (punto 8): completa una OC. En una OC DIRECTA es obligatorio
    vincular el remito correspondiente; en una indirecta es opcional."""
    d = request.json or {}
    oc = query("SELECT * FROM ordenes_compra WHERE id=?", (ocid,), one=True)
    if not oc: return jsonify({"error":"OC no encontrada"}), 404
    if oc["estado"] not in ("Aprobada","Enviada","Recibida parcial","Recibida","Cerrada"):
        return jsonify({"error": f"No se puede completar una OC en estado \"{oc['estado']}\""}), 400
    tipo = _oc_tipo(ocid)
    remito = (d.get("remito") or "").strip()
    if tipo == "Directa" and not remito:
        return jsonify({"error":"Una OC directa requiere vincular el remito correspondiente para completarse."}), 400
    execute("""UPDATE ordenes_compra SET estado='Completada',remito_numero=?,fecha_completada=datetime('now','localtime') WHERE id=?""",
        (remito or None, ocid))
    return jsonify({"ok":True,"estado":"Completada","tipo":tipo})

# ── MRP ampliado ──────────────────────────────────────────────────────────────
@app.route("/api/mrp")
@login_required()
def mrp():
    return jsonify({
        "criticos": [dict(r) for r in query("""SELECT m.id,m.codigo,m.descripcion,m.stock,m.stock_min,m.stock_max,m.stock_min-m.stock AS faltante,m.unidad,p.razon proveedor,
            (SELECT s.numero FROM solicitudes_compra s WHERE s.material_id=m.id AND s.estado IN ('Pendiente','Cotizada') ORDER BY s.id DESC LIMIT 1) sc_activa
            FROM materiales m LEFT JOIN proveedores p ON p.id=m.proveedor_id WHERE m.stock<m.stock_min AND m.stock_min>0 ORDER BY (m.stock_min-m.stock) DESC""")],
        "ordenes_activas": [dict(r) for r in query("SELECT o.numero,o.descripcion,o.estado,o.fecha_entrega,o.cantidad,c.razon cliente,pr.nombre producto FROM ordenes o LEFT JOIN clientes c ON c.id=o.cliente_id LEFT JOIN productos pr ON pr.id=o.producto_id WHERE o.estado IN ('Pendiente','En proceso') ORDER BY o.fecha_entrega")],
        "oc_cliente_pendientes": [dict(r) for r in query("SELECT oc.*,c.razon cliente_nombre FROM ordenes_cliente oc JOIN clientes c ON c.id=oc.cliente_id WHERE oc.estado IN ('Recibida','Confirmada') ORDER BY oc.fecha_entrega")],
        "pronosticos_pendientes": [dict(r) for r in query("""SELECT p.id,p.codigo,p.periodos,p.fecha_emision,c.razon cliente_nombre,
            (SELECT COUNT(*) FROM pronostico_venta_items i WHERE i.pronostico_id=p.id AND i.cantidad>0
               AND i.id NOT IN (SELECT item_id FROM pronostico_item_ots)) items_pendientes
            FROM pronosticos_venta p LEFT JOIN clientes c ON c.id=p.cliente_id
            WHERE p.estado='Alta' AND EXISTS (
                SELECT 1 FROM pronostico_venta_items i WHERE i.pronostico_id=p.id AND i.cantidad>0
                  AND i.id NOT IN (SELECT item_id FROM pronostico_item_ots))
            ORDER BY p.fecha_emision DESC""")],
        "carga_por_sector": [dict(r) for r in query("""SELECT cm.nombre sector,COUNT(oo.id) ops_pendientes,
            SUM(oo.qty_requerida - oo.qty_producida) piezas_pendientes
            FROM orden_operaciones oo
            JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
            WHERE oo.estado != 'Completada'
            GROUP BY cm.nombre ORDER BY ops_pendientes DESC""")],
    })



@app.route("/api/rendimiento_operario", methods=["GET"])
@login_required()
def get_rendimiento_operario():
    """Rendimiento ponderado por operario, agrupado por año/mes/día."""
    rows = query("""SELECT
        e.id emp_id, e.nombre||' '||e.apellido empleado_nombre,
        strftime('%Y', n.fecha) anio,
        strftime('%Y-%m', n.fecha) mes,
        strftime('%Y-%m-%d', n.fecha) dia,
        COUNT(*) novedades,
        AVG(n.rendimiento_pct) rend_promedio,
        SUM(n.cantidad_producida) total_producido,
        SUM(n.tiempo_real_min) total_min_real
        FROM novedades_produccion n
        JOIN empleados e ON e.id=n.empleado_id
        WHERE n.empleado_id IS NOT NULL
        GROUP BY e.id, strftime('%Y-%m-%d', n.fecha)
        ORDER BY e.apellido, e.nombre, n.fecha DESC""")
    # Group by empleado → año → mes → dia
    result = {}
    for r in rows:
        eid = r["emp_id"]
        if eid not in result:
            result[eid] = {"emp_id": eid, "nombre": r["empleado_nombre"],
                           "años": {}}
        años = result[eid]["años"]
        a = r["anio"]
        if a not in años:
            años[a] = {"año": a, "meses": {}, "total_novedades": 0,
                       "rend_sum": 0.0, "rend_count": 0}
        m = r["mes"]
        if m not in años[a]["meses"]:
            años[a]["meses"][m] = {"mes": m, "dias": [], "total_novedades": 0,
                                   "rend_sum": 0.0, "rend_count": 0}
        años[a]["meses"][m]["dias"].append({
            "dia": r["dia"],
            "novedades": r["novedades"],
            "rend_promedio": round(float(r["rend_promedio"] or 0), 1),
            "total_producido": r["total_producido"],
            "total_min_real": r["total_min_real"],
        })
        años[a]["meses"][m]["total_novedades"] += r["novedades"]
        años[a]["meses"][m]["rend_sum"] += float(r["rend_promedio"] or 0)
        años[a]["meses"][m]["rend_count"] += 1
        años[a]["total_novedades"] += r["novedades"]
        años[a]["rend_sum"] += float(r["rend_promedio"] or 0)
        años[a]["rend_count"] += 1
    # Flatten for JSON
    out = []
    for eid, emp in result.items():
        emp_row = {"emp_id": eid, "nombre": emp["nombre"], "años": []}
        for a, año_data in sorted(emp["años"].items(), reverse=True):
            rc = año_data["rend_count"]
            año_row = {
                "año": a,
                "rend_promedio": round(año_data["rend_sum"]/rc, 1) if rc else 0,
                "total_novedades": año_data["total_novedades"],
                "meses": []
            }
            for m, mes_data in sorted(año_data["meses"].items(), reverse=True):
                mc = mes_data["rend_count"]
                año_row["meses"].append({
                    "mes": m,
                    "rend_promedio": round(mes_data["rend_sum"]/mc, 1) if mc else 0,
                    "total_novedades": mes_data["total_novedades"],
                    "dias": mes_data["dias"]
                })
            emp_row["años"].append(año_row)
        out.append(emp_row)
    return jsonify(out)


@app.route("/api/rendimiento_operario_dias", methods=["GET"])
@login_required()
def get_rendimiento_operario_dias():
    """Rendimiento diario de un operario filtrado por rango de fechas."""
    emp_id = request.args.get("emp_id")
    desde = request.args.get("desde")
    hasta = request.args.get("hasta")
    if not emp_id:
        return jsonify({"error": "emp_id requerido"}), 400
    sql = """SELECT
        strftime('%Y-%m-%d', n.fecha) dia,
        COUNT(*) novedades,
        AVG(n.rendimiento_pct) rend_promedio,
        SUM(n.cantidad_producida) total_producido_bruto,
        SUM(COALESCE(n.piezas_observadas,0)) total_no_ok,
        SUM(n.tiempo_real_min) total_min_real,
        SUM(COALESCE(n.tiempo_perdido,0)) total_tiempo_perdido
        FROM novedades_produccion n
        WHERE n.empleado_id=?"""
    params = [emp_id]
    if desde:
        sql += " AND date(n.fecha)>=?"
        params.append(desde)
    if hasta:
        sql += " AND date(n.fecha)<=?"
        params.append(hasta)
    sql += " GROUP BY strftime('%Y-%m-%d', n.fecha) ORDER BY dia DESC"
    rows = query(sql, tuple(params))
    out = [{
        "dia": r["dia"],
        "novedades": r["novedades"],
        "rend_promedio": round(float(r["rend_promedio"] or 0), 1),
        "total_producido": r["total_producido_bruto"] or 0,
        "total_no_ok": r["total_no_ok"] or 0,
        "total_min_real": r["total_min_real"],
        "total_tiempo_perdido": r["total_tiempo_perdido"],
    } for r in rows]
    return jsonify(out)


# ── Remitos ───────────────────────────────────────────────────────────────────
@app.route("/api/remitos", methods=["GET"])
@login_required()
def get_remitos():
    cliente_id = request.args.get("cliente_id")
    sql = """SELECT r.*,c.razon cliente_nombre,oc.numero oc_numero,
            ott.numero ott_numero, ocp.numero oc_proveedor_numero,
            COALESCE(c.razon, pott.razon, pocp.razon) destinatario
        FROM remitos r
        LEFT JOIN clientes c ON c.id=r.cliente_id
        LEFT JOIN ordenes_cliente oc ON oc.id=r.orden_cliente_id
        LEFT JOIN ordenes_tercerizado ott ON ott.id=r.ott_id
        LEFT JOIN proveedores pott ON pott.id=ott.proveedor_id
        LEFT JOIN ordenes_compra ocp ON ocp.id=r.oc_id
        LEFT JOIN proveedores pocp ON pocp.id=ocp.proveedor_id"""
    items_sql = """SELECT ri.*,m.descripcion mat_descripcion,
            m.codigo mat_codigo,m.unidad,l.numero lote_numero
            FROM remito_items ri
            JOIN materiales m ON m.id=ri.material_id
            JOIN lotes l ON l.id=ri.lote_id
            WHERE ri.remito_id IN ({})"""

    # Modo paginado (pantalla "Remitos emitidos"): filtra y pagina en la base,
    # así se pueden recorrer todos los remitos sin cargarlos de una vez.
    if request.args.get("pagina") is not None:
        w, p = [], []
        if cliente_id:
            w.append("r.cliente_id=?"); p.append(cliente_id)
        fecha = (request.args.get("fecha") or "").strip()
        if fecha:
            w.append("substr(r.fecha,1,10)=?"); p.append(fecha)
        oc = (request.args.get("oc") or "").strip()
        if oc:
            w.append("IFNULL(oc.numero,'') LIKE ?"); p.append(f"%{oc}%")
        mat = (request.args.get("material") or "").strip()
        if mat:
            w.append("""(EXISTS (SELECT 1 FROM remito_items ri2
                JOIN materiales m2 ON m2.id=ri2.material_id
                WHERE ri2.remito_id=r.id
                AND (IFNULL(m2.codigo,'')||' '||IFNULL(m2.descripcion,'')) LIKE ?)
                OR EXISTS (SELECT 1 FROM ordenes_tercerizado o2
                LEFT JOIN proceso_operaciones po2 ON po2.id=o2.proceso_op_id
                LEFT JOIN productos pr2 ON pr2.id=po2.producto_id
                LEFT JOIN materiales ms2 ON ms2.id=o2.material_se_id
                WHERE o2.id=r.ott_id
                AND (IFNULL(pr2.codigo,'')||' '||IFNULL(pr2.nombre,'')||' '||
                     IFNULL(ms2.codigo,'')||' '||IFNULL(ms2.descripcion,'')) LIKE ?))""")
            p.extend([f"%{mat}%", f"%{mat}%"])
        where = (" WHERE " + " AND ".join(w)) if w else ""
        try:
            por_pagina = int(request.args.get("por_pagina", 25))
        except (TypeError, ValueError):
            por_pagina = 25
        por_pagina = min(200, max(10, por_pagina))
        try:
            pagina = max(1, int(request.args.get("pagina", 1)))
        except (TypeError, ValueError):
            pagina = 1
        total = query("SELECT COUNT(*) c FROM remitos r LEFT JOIN ordenes_cliente oc "
                      "ON oc.id=r.orden_cliente_id" + where, p, one=True)["c"]
        paginas = max(1, -(-total // por_pagina))
        pagina = min(pagina, paginas)
        rows = query(sql + where + " ORDER BY r.id DESC LIMIT ? OFFSET ?",
                     (*p, por_pagina, (pagina - 1) * por_pagina))
        result = [dict(r) for r in rows]
        por_id = {d["id"]: d for d in result}
        for d in result:
            d["items"] = []
        if por_id:
            ids = list(por_id)
            for x in query(items_sql.format(",".join("?" * len(ids))), ids):
                por_id[x["remito_id"]]["items"].append(dict(x))
        _items_remitos_proveedor(result)
        return jsonify({"total": total, "pagina": pagina, "por_pagina": por_pagina,
                        "paginas": paginas, "rows": result})

    # Modo clásico (sin paginar): devuelve la lista completa.
    rows = query(sql+" WHERE r.cliente_id=? ORDER BY r.id DESC",(cliente_id,)) if cliente_id else query(sql+" ORDER BY r.id DESC")
    result = []
    for r in rows:
        d = dict(r)
        d["items"] = [dict(x) for x in query(items_sql.format("?"), (r["id"],))]
        result.append(d)
    _items_remitos_proveedor(result)
    return jsonify(result)

@app.route("/api/remitos/<int:rid>", methods=["GET"])
@login_required()
def get_remito(rid):
    """Detalle completo de un remito para la vista "Ver" de Remitos emitidos."""
    r = query("""SELECT r.*, oc.numero oc_cliente_numero, u.nombre creado_por_nombre,
            ott.numero ott_numero, ott.estado ott_estado, ott.proveedor_id ott_proveedor_id,
            o.numero ot_numero, po.nombre operacion_nombre,
            ocp.numero oc_numero, ocp.proveedor_id ocp_proveedor_id
        FROM remitos r
        LEFT JOIN ordenes_cliente oc ON oc.id=r.orden_cliente_id
        LEFT JOIN usuarios u ON u.id=r.creado_por
        LEFT JOIN ordenes_tercerizado ott ON ott.id=r.ott_id
        LEFT JOIN ordenes o ON o.id=ott.ot_origen_id
        LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
        LEFT JOIN ordenes_compra ocp ON ocp.id=r.oc_id
        WHERE r.id=?""", (rid,), one=True)
    if not r: return jsonify({"error": "Remito no encontrado"}), 404
    d = dict(r)
    if d.get("cliente_id"):
        c = query("""SELECT razon,cuit,direccion,localidad,contacto,telefono
            FROM clientes WHERE id=?""", (d["cliente_id"],), one=True)
        d["destino"] = dict(c, tipo="cliente") if c else None
    else:
        prov_id = d.get("ott_proveedor_id") or d.get("ocp_proveedor_id")
        p = query("SELECT razon,cuit,contacto,telefono FROM proveedores WHERE id=?",
                  (prov_id,), one=True) if prov_id else None
        d["destino"] = dict(p, tipo="proveedor") if p else None
    d["items"] = [dict(x) for x in query("""SELECT ri.*, m.descripcion mat_descripcion,
            m.codigo mat_codigo, m.unidad, l.numero lote_numero
        FROM remito_items ri
        JOIN materiales m ON m.id=ri.material_id
        JOIN lotes l ON l.id=ri.lote_id
        WHERE ri.remito_id=?""", (rid,))]
    _items_remitos_proveedor([d])
    return jsonify(d)

def _items_remitos_proveedor(remitos):
    """Los remitos hacia proveedores (traslado/devolución de OTT, devolución
    de OC) no generan remito_items, así que su columna Ítems salía vacía.
    Para mostrarlos se arma el ítem a partir de la OTT/OC de origen. Son
    solo de lectura (sin lote_id): no afectan stock ni entregas."""
    for d in remitos:
        if d.get("items"):
            continue
        tipo = d.get("tipo")
        if tipo in ("traslado_ott", "devolucion_ott") and d.get("ott_id"):
            if tipo == "traslado_ott":
                # La pieza que viaja: el producto de la operación; en una
                # OTT manual (sin operación) el material insumo enviado.
                it = query("""SELECT COALESCE(pr.codigo, m.codigo) mat_codigo,
                        COALESCE(pr.nombre, m.descripcion) mat_descripcion,
                        COALESCE(pr.unidad, m.unidad) unidad
                    FROM ordenes_tercerizado ott
                    LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
                    LEFT JOIN productos pr ON pr.id=po.producto_id
                    LEFT JOIN materiales m ON m.id=ott.material_se_id
                    WHERE ott.id=?""", (d["ott_id"],), one=True)
            else:
                it = query("""SELECT m.codigo mat_codigo, m.descripcion mat_descripcion,
                        m.unidad, l.numero lote_numero
                    FROM ordenes_tercerizado ott
                    JOIN lotes l ON l.id=ott.lote_retorno_id
                    JOIN materiales m ON m.id=l.material_id
                    WHERE ott.id=?""", (d["ott_id"],), one=True)
            if it and (it["mat_codigo"] or it["mat_descripcion"]):
                x = dict(it)
                cant = d.get("ott_cantidad")
                if cant is None and tipo == "traslado_ott":
                    # Remitos viejos sin cantidad guardada: si es el único
                    # traslado de esa OTT, la cantidad es la enviada.
                    _o = query("""SELECT cantidad_enviada,
                            (SELECT COUNT(*) FROM remitos WHERE ott_id=ott.id AND tipo='traslado_ott') n
                        FROM ordenes_tercerizado ott WHERE id=?""", (d["ott_id"],), one=True)
                    if _o and _o["n"] == 1 and float(_o["cantidad_enviada"] or 0) > 0:
                        cant = _o["cantidad_enviada"]
                x.update(remito_id=d["id"], cantidad=cant)
                d["items"] = [x]
        elif tipo == "devolucion_oc" and d.get("oc_id"):
            # Lo devuelto queda acumulado por ítem de OC; la cantidad solo es
            # exacta si la OC tiene un único remito de devolución.
            unico = query("""SELECT COUNT(*) c FROM remitos
                WHERE oc_id=? AND tipo='devolucion_oc'""", (d["oc_id"],), one=True)["c"] == 1
            d["items"] = [dict(remito_id=d["id"], mat_codigo=x["mat_codigo"],
                               mat_descripcion=x["mat_descripcion"], unidad=x["unidad"],
                               cantidad=x["cantidad"] if unico else None)
                for x in query("""SELECT COALESCE(m.codigo, i.descripcion) mat_codigo,
                        COALESCE(m.descripcion, i.descripcion) mat_descripcion, m.unidad,
                        i.cantidad_rechazada_devuelta cantidad
                    FROM ordenes_compra_items i LEFT JOIN materiales m ON m.id=i.material_id
                    WHERE i.oc_id=? AND COALESCE(i.cantidad_rechazada_devuelta,0) > 0""",
                    (d["oc_id"],))]

@app.route("/api/remitos/opciones", methods=["GET"])
@login_required()
def get_remitos_opciones():
    """Sugerencias para los filtros de Remitos emitidos (OC y materiales usados)."""
    ocs = query("""SELECT DISTINCT oc.numero FROM remitos r
        JOIN ordenes_cliente oc ON oc.id=r.orden_cliente_id
        WHERE oc.numero IS NOT NULL ORDER BY oc.numero""")
    mats = query("""SELECT m.codigo, m.descripcion FROM remito_items ri
            JOIN materiales m ON m.id=ri.material_id
        UNION
        SELECT COALESCE(pr.codigo, ms.codigo), COALESCE(pr.nombre, ms.descripcion)
            FROM remitos r JOIN ordenes_tercerizado ott ON ott.id=r.ott_id
            LEFT JOIN proceso_operaciones po ON po.id=ott.proceso_op_id
            LEFT JOIN productos pr ON pr.id=po.producto_id
            LEFT JOIN materiales ms ON ms.id=ott.material_se_id
            WHERE COALESCE(pr.codigo, ms.codigo) IS NOT NULL
        ORDER BY 1""")
    return jsonify({"ocs": [r["numero"] for r in ocs],
                    "materiales": [{"codigo": r["codigo"], "descripcion": r["descripcion"]} for r in mats]})

@app.route("/api/pt_disponible", methods=["GET"])
@login_required()
def get_pt_disponible():
    """Productos terminados con lotes activos disponibles para remitir."""
    cliente_id = request.args.get("cliente_id")
    # La vinculación a la OC de cliente solo cuenta si esa OC está activa
    # (no Cancelada). Si se cancela la OC, el producto ya hecho y aprobado
    # queda "sin OC vinculada" (aunque el vínculo OT->ítem siga existiendo);
    # si la OC se reabre (vuelve a un estado activo), el join vuelve a
    # resolver y la vinculación reaparece sola — todo se calcula en vivo a
    # partir de ordenes_cliente.estado, sin tocar el vínculo real.
    #
    # El join a la OT que originó el lote usa orden_cliente_item_ots (no la
    # columna ot_id, que solo guarda la primera OT vinculada a un ítem) para
    # cubrir también lotes de OTs vinculadas como 2da/3ra OT de un ítem.
    #
    # Un lote deja de listarse acá en cuanto el pendiente del ítem al que
    # está vinculado llega a 0 (ya se remitió todo lo pedido): el resto de
    # producto terminado que haya quedado (porque la OT pedía más de lo que
    # esa OC necesitaba) no debe ofrecerse para remitir contra esa OC. Si esa
    # OT se desvincula y se vincula a otra OC con pendiente, el lote vuelve a
    # aparecer solo.
    rows = query("""SELECT l.*,m.codigo mat_codigo,m.descripcion mat_descripcion,m.unidad,
        p.nombre producto_nombre, p.id producto_id,
        pcli.razon producto_cliente_nombre,
        CASE WHEN oc.id IS NOT NULL THEN oc_items.id END oc_item_id,
        CASE WHEN oc.id IS NOT NULL THEN oc_items.cantidad END oc_cantidad,
        CASE WHEN oc.id IS NOT NULL THEN oc_items.orden_cliente_id END orden_cliente_id,
        oc.numero oc_numero,
        CASE WHEN oc.id IS NOT NULL THEN oc.cliente_id END oc_cliente_id,
        CASE WHEN oc.id IS NOT NULL THEN
            (SELECT COALESCE(SUM(ri.cantidad),0) FROM remito_items ri JOIN remitos rr ON rr.id=ri.remito_id
             WHERE ri.orden_cliente_item_id=oc_items.id AND rr.estado!='Anulado')
        END ya_remitido
        FROM lotes l
        JOIN materiales m ON m.id=l.material_id
        LEFT JOIN productos p ON p.id=m.id
        LEFT JOIN clientes pcli ON pcli.id=p.cliente_id
        LEFT JOIN ordenes ot_gen ON (ot_gen.numero=l.numero
            OR l.numero=ot_gen.numero || '-PT'
            OR l.numero LIKE ot_gen.numero || '-C%')
        LEFT JOIN orden_cliente_item_ots ocio ON ocio.ot_id=ot_gen.id
        LEFT JOIN ordenes_cliente_items oc_items ON oc_items.id=ocio.item_id
            AND oc_items.producto_id=p.id
        LEFT JOIN ordenes_cliente oc ON oc.id=oc_items.orden_cliente_id
            AND oc.estado IN ('Recibida','Confirmada','En proceso')
        WHERE m.categoria='Producto terminado'
        AND l.cantidad_activa>0 AND l.estado != 'Agotado' AND l.estado != 'Bloqueado'
        AND oc.id IS NOT NULL
        AND oc_items.cantidad > (SELECT COALESCE(SUM(ri.cantidad),0) FROM remito_items ri JOIN remitos rr ON rr.id=ri.remito_id
             WHERE ri.orden_cliente_item_id=oc_items.id AND rr.estado!='Anulado')
        """ + ("AND oc.cliente_id=?" if cliente_id else "") + """
        ORDER BY l.id DESC""", (cliente_id,) if cliente_id else ())
    return jsonify([dict(r) for r in rows])

@app.route("/api/remitos", methods=["POST"])
@login_required(roles=["admin","almacen","vendedor"])
def create_remito():
    d = request.json
    if not d.get("cliente_id"): return jsonify({"error": "Cliente requerido"}), 400
    items_in = [it for it in (d.get("items") or []) if it.get("lote_id") and it.get("cantidad")]
    if not items_in:
        return jsonify({"error": "El remito debe tener al menos un ítem"}), 400
    # Validar TODOS los ítems antes de grabar nada: antes un ítem que pedía
    # más de lo aprobado se salteaba en silencio y el remito salía igual,
    # incompleto, sin avisar. Se suma por lote por si el mismo lote viene en
    # más de un renglón.
    pedido_por_lote = {}
    for it in items_in:
        try:
            qty_it = float(it["cantidad"])
        except (TypeError, ValueError):
            return jsonify({"error": "Cantidad inválida en un ítem del remito"}), 400
        if qty_it <= 0:
            return jsonify({"error": "Las cantidades del remito deben ser mayores a 0"}), 400
        pedido_por_lote[it["lote_id"]] = pedido_por_lote.get(it["lote_id"], 0.0) + qty_it
    for lid_it, qty_it in pedido_por_lote.items():
        l_it = query("SELECT numero,cantidad_activa FROM lotes WHERE id=?", (lid_it,), one=True)
        if not l_it:
            return jsonify({"error": "Lote no encontrado en un ítem del remito"}), 400
        if qty_it > float(l_it["cantidad_activa"] or 0) + 0.0001:
            return jsonify({"error": f"El lote {l_it['numero']} tiene {float(l_it['cantidad_activa'] or 0):g} aprobado/disponible y se quieren remitir {qty_it:g}"}), 400
    numero = siguiente_numero("remitos", "REM-", 4)
    rid = execute("""INSERT INTO remitos (numero,cliente_id,orden_cliente_id,obs,creado_por)
        VALUES (?,?,?,?,?)""",
        (numero, d.get("cliente_id"), d.get("orden_cliente_id"),
         d.get("obs"), session["user_id"]))
    items_insertados = 0
    for item in items_in:
        qty = float(item["cantidad"])
        lote = query("""SELECT id,material_id,cantidad_disponible,cantidad_activa
            FROM lotes WHERE id=?""", (item["lote_id"],), one=True)
        if not lote: continue
        activa = float(lote["cantidad_activa"] or 0)
        if qty > activa:
            # Can't remit more than what's active/approved
            continue
        ri_id = execute("""INSERT INTO remito_items
            (remito_id,material_id,lote_id,orden_cliente_item_id,cantidad,obs)
            VALUES (?,?,?,?,?,?)""",
            (rid, lote["material_id"], item["lote_id"],
             item.get("orden_cliente_item_id"), qty, item.get("obs")))
        items_insertados += 1
        # Discount from lote (both disponible and activa)
        nueva_disp   = max(0, float(lote["cantidad_disponible"]) - qty)
        nueva_activa = max(0, activa - qty)
        nuevo_estado = "Agotado" if nueva_disp <= 0 else ("Aprobado" if nueva_activa > 0 else "Ingresado")
        execute("""UPDATE lotes SET cantidad_disponible=?,cantidad_activa=?,estado=?
            WHERE id=?""", (nueva_disp, nueva_activa, nuevo_estado, lote["id"]))
        if query("SELECT 1 FROM cajones WHERE lote_id=? LIMIT 1", (lote["id"],), one=True):
            _remitir_de_cajones(ri_id, lote["id"], qty)
            _lote_estado_por_cajones(lote["id"])
        # Discount from PT stock
        execute("UPDATE materiales SET stock=MAX(0,stock-?),actualizado=datetime('now','localtime') WHERE id=?",
            (qty, lote["material_id"]))
        execute("INSERT INTO movimientos (material_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES (?,?,?,?,?,?)",
            (lote["material_id"], lote["id"], "salida", qty, f"Remito {numero}", session["user_id"]))
        if item.get("orden_cliente_item_id"):
            _sync_requerimiento_desde_pedido(item["orden_cliente_item_id"])
    if items_insertados == 0:
        # Ningún ítem pudo aplicarse (stock insuficiente en todos): abortar remito
        execute("DELETE FROM remitos WHERE id=?", (rid,))
        return jsonify({"error": "No se pudo generar el remito: stock insuficiente en los ítems seleccionados"}), 400

    # ── Cierre automático de la OC: si con este remito se cubrió el 100% de
    # lo pedido (sumando todos los remitos, no solo este), marcar la OC como
    # "Completada". No completar OCs que todavía tengan renglones sin OT
    # (item["ot_id"] NULL), porque eso significa que ni siquiera se terminó
    # de planificar todo el pedido.
    ocids_afectadas = set()
    if d.get("orden_cliente_id"):
        ocids_afectadas.add(d["orden_cliente_id"])
    for item in items_in:
        oci = item.get("orden_cliente_item_id")
        if oci:
            row = query("SELECT orden_cliente_id FROM ordenes_cliente_items WHERE id=?", (oci,), one=True)
            if row: ocids_afectadas.add(row["orden_cliente_id"])
    for ocid_remito in ocids_afectadas:
        oc_items = query("""SELECT id,cantidad,ot_id FROM ordenes_cliente_items
            WHERE orden_cliente_id=?""", (ocid_remito,))
        def _cubierto(it):
            _o, c = _ots_vinculadas_item(it["id"])
            return c >= float(it["cantidad"])
        if oc_items and all(_cubierto(it) for it in oc_items):
            total_req = sum(float(it["cantidad"]) for it in oc_items)
            total_ent = 0.0
            for it in oc_items:
                ent = query("""SELECT COALESCE(SUM(ri.cantidad),0) total
                    FROM remito_items ri JOIN remitos r ON r.id=ri.remito_id
                    WHERE ri.orden_cliente_item_id=? AND r.estado!='Anulado'""",
                    (it["id"],), one=True)["total"]
                total_ent += float(ent)
            if total_req > 0 and total_ent >= total_req - 0.001:
                execute("UPDATE ordenes_cliente SET estado='Completada' WHERE id=?", (ocid_remito,))
                _forzar_completar_ots_oc(ocid_remito)

    return jsonify({"ok": True, "id": rid, "numero": numero}), 201





# ── Configuración del sistema ─────────────────────────────────────────────────
# Claves de `configuracion` cuyo contenido es (o revela) un importe.
CONFIG_CLAVES_MONETARIAS = ("valor_hora_mo", "pdf_mostrar_costos", "pdf_mostrar_precios")


@app.route("/api/config", methods=["GET"])
@login_required()
def get_config():
    rows = query("SELECT clave, valor, descripcion FROM configuracion ORDER BY clave")
    ver = puede_ver_monetario()
    return jsonify({r["clave"]: {"valor": r["valor"] or "", "descripcion": r["descripcion"]}
                    for r in rows
                    if ver or r["clave"] not in CONFIG_CLAVES_MONETARIAS})

@app.route("/api/config", methods=["POST"])
@login_required(roles=["admin"])
def save_config():
    d = request.json or {}
    if not puede_ver_monetario():
        # No puede verlas, tampoco pisarlas.
        d = {k: v for k, v in d.items() if k not in CONFIG_CLAVES_MONETARIAS}
    for clave, valor in d.items():
        execute("UPDATE configuracion SET valor=? WHERE clave=?", (str(valor), clave))
    return jsonify({"ok": True})

# ── PDFs: base común (OT, OP y OC) ───────────────────────────────────────────
# Los tres PDFs comparten la configuración, la paleta de la marca, la cabecera
# con logo, la ficha, las barras de sección, las tablas y el pie con firmas.
# Todo eso vive acá; cada _build_*_pdf arma solo su contenido.
def _pdf_o_error(armar, *args):
    """Devuelve el PDF que arma `armar`, o una página con el error si falla."""
    try:
        return armar(*args)
    except Exception:
        import traceback
        tb = traceback.format_exc()
        return (
            '<html><body style="font-family:monospace;padding:20px">'
            '<h2 style="color:red">Error al generar PDF</h2>'
            '<pre style="background:#f5f5f5;padding:16px;border-radius:4px;font-size:12px">'
            + tb.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
            + '</pre></body></html>'
        ), 500


def _pdf_fecha(d):
    if not d: return "—"
    try: return datetime.strptime(d[:10], "%Y-%m-%d").strftime("%d/%m/%Y")
    except: return str(d)


def _pdf_dinero(n):
    try: return f"$ {float(n or 0):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except: return "$ 0,00"


class _PdfBase:
    """Documento A4 con la estética de la empresa. Uso:
        pdf = _PdfBase(numero, titulo)       # titulo: metadato del PDF
        pdf.cabecera("ORDEN DE TRABAJO", numero)
        ... pdf.story.append(...) con pdf.P, pdf.ficha, pdf.tabla, etc.
        pdf.firmas("Supervisor de producción", "Control de calidad")
        return pdf.enviar("OT-001.pdf")
    """

    def __init__(self, numero, titulo):
        import io
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import mm
        from reportlab.lib import colors
        from reportlab.platypus import SimpleDocTemplate

        cfg = {r["clave"]: (r["valor"] or "") for r in query("SELECT clave, valor FROM configuracion")}
        self.cfg = cfg
        self.numero = numero

        h = (cfg.get("pdf_color_hex") or "2C5F8A").strip().lstrip("#")
        if len(h) != 6:
            h = "2C5F8A"
        try:
            self.PRIMARY = colors.HexColor("#" + h)
        except Exception:
            self.PRIMARY = colors.HexColor("#2C5F8A")
        self.PRIMARY_L = colors.HexColor("#ECF3FA")   # variante clara para filas alternadas
        self.GRAY_L    = colors.HexColor("#F5F5F5")
        self.GRAY_D    = colors.HexColor("#CCCCCC")
        self.WHITE     = colors.white
        self.BLACK     = colors.HexColor("#1A1A1A")
        self.MUTED     = colors.HexColor("#666666")

        self.W, self.H = A4
        self.M = 15 * mm
        self.FOOTER_H = 34 * mm  # espacio reservado al pie para firmas/nota/generado
        self.CW = self.W - 2 * self.M
        self.buf = io.BytesIO()
        self.doc = SimpleDocTemplate(
            self.buf, pagesize=A4,
            leftMargin=self.M, rightMargin=self.M,
            topMargin=self.M, bottomMargin=self.M + self.FOOTER_H,
            title=titulo,
        )
        self.story = []
        self.firma_tbl = None

    def paleta(self):
        return (self.PRIMARY, self.PRIMARY_L, self.GRAY_L, self.GRAY_D,
                self.WHITE, self.BLACK, self.MUTED)

    # ── Estilos ──────────────────────────────────────────────────────────────
    def sty(self, size=9, bold=False, color=None, align=None, leading=None, space_after=0):
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.enums import TA_LEFT
        align = TA_LEFT if align is None else align
        return ParagraphStyle(
            name=f"s{size}{'b' if bold else ''}{align}",
            fontSize=size,
            fontName="Helvetica-Bold" if bold else "Helvetica",
            textColor=color or self.BLACK,
            alignment=align,
            leading=leading or size * 1.35,
            spaceAfter=space_after,
        )

    def P(self, text, **kw):
        from reportlab.platypus import Paragraph
        return Paragraph(str(text or "—"), self.sty(**kw))

    # ── 1. Encabezado: logo y empresa (izq) | tipo y número (der) ─────────────
    def cabecera(self, tipo, numero):
        import io, base64
        from reportlab.lib.units import mm
        from reportlab.lib.enums import TA_RIGHT
        from reportlab.platypus import Paragraph, Spacer, Table, TableStyle, Image
        cfg, P, CW = self.cfg, self.P, self.CW

        empresa_nombre    = "Mecanizado Ituzaingo"
        empresa_subtitulo = cfg.get("empresa_subtitulo", "")
        contact_parts = [p for p in [cfg.get("empresa_direccion", ""),
                                     cfg.get("empresa_telefono", ""),
                                     cfg.get("empresa_email", "")] if p]
        empresa_txt = "<br/>".join(
            [f'<font size="12"><b>{empresa_nombre}</b></font>'] +
            ([f'<font size="9" color="#555555">{empresa_subtitulo}</font>'] if empresa_subtitulo else []) +
            ([f'<font size="8" color="#888888">{" · ".join(contact_parts)}</font>'] if contact_parts else [])
        )

        logo_w, logo_h = 26*mm, 26*mm * (408/576)
        logo_img = Image(io.BytesIO(base64.b64decode(_LOGO_ITUZAINGO_B64)),
                          width=logo_w, height=logo_h)

        empresa_bloque = Table([[
            logo_img,
            Paragraph(empresa_txt, self.sty(size=10)),
        ]], colWidths=[logo_w + 3*mm, CW - 72*mm - logo_w - 3*mm])
        empresa_bloque.setStyle(TableStyle([
            ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
            ("LEFTPADDING", (0,0), (-1,-1), 0),
            ("RIGHTPADDING", (0,0), (0,-1), 0),
            ("TOPPADDING", (0,0), (-1,-1), 0),
            ("BOTTOMPADDING", (0,0), (-1,-1), 0),
        ]))

        hdr = Table([[
            empresa_bloque,
            Table([[
                P(tipo, size=8, bold=True, color=self.MUTED, align=TA_RIGHT),
                P(numero, size=20, bold=True, color=self.PRIMARY, align=TA_RIGHT),
            ]], colWidths=[30*mm, 40*mm],
               style=TableStyle([("VALIGN",(0,0),(-1,-1),"BOTTOM"),("BOTTOMPADDING",(0,0),(-1,-1),0)])),
        ]], colWidths=[CW - 72*mm, 72*mm])
        hdr.setStyle(TableStyle([
            ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
            ("LINEBELOW", (0,0), (-1,0), 2, self.PRIMARY),
            ("BOTTOMPADDING", (0,0), (-1,0), 6),
            ("TOPPADDING", (0,0), (-1,0), 2),
        ]))
        self.story.append(hdr)
        self.story.append(Spacer(1, 4*mm))

    # ── 2. Ficha: 4 columnas, rótulos sobre fondo de la marca ─────────────────
    def ficha(self, filas, estilo_extra=()):
        from reportlab.lib.units import mm
        from reportlab.platypus import Table, TableStyle
        CW = self.CW
        tbl = Table(filas, colWidths=[32*mm, CW/2-32*mm, 28*mm, CW/2-28*mm])
        tbl.setStyle(TableStyle([
            ("GRID",            (0,0), (-1,-1), 0.4, self.GRAY_D),
            ("BACKGROUND",      (0,0), (0,-1), self.PRIMARY_L),
            ("BACKGROUND",      (2,0), (2,-1), self.PRIMARY_L),
            ("ROWBACKGROUNDS",  (0,0), (-1,-1), [self.WHITE, self.GRAY_L]),
            ("VALIGN",          (0,0), (-1,-1), "MIDDLE"),
            *estilo_extra,
            ("TOPPADDING",      (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",   (0,0), (-1,-1), 4),
            ("LEFTPADDING",     (0,0), (-1,-1), 5),
        ]))
        self.story.append(tbl)

    def observaciones(self, texto):
        """Recuadro amarillo de observaciones, solo si hay texto."""
        if not texto:
            return
        from reportlab.lib.units import mm
        from reportlab.lib import colors
        from reportlab.platypus import Spacer, Table, TableStyle
        self.story.append(Spacer(1, 2*mm))
        obs_tbl = Table([[
            self.P("Observaciones:", size=8, bold=True, color=self.MUTED),
            self.P(texto, size=8, color=self.MUTED),
        ]], colWidths=[32*mm, self.CW-32*mm])
        obs_tbl.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,-1), colors.HexColor("#FFFDE7")),
            ("GRID", (0,0), (-1,-1), 0.3, self.GRAY_D),
            ("VALIGN", (0,0), (-1,-1), "TOP"),
            ("TOPPADDING", (0,0), (-1,-1), 4),
            ("BOTTOMPADDING", (0,0), (-1,-1), 4),
            ("LEFTPADDING", (0,0), (-1,-1), 5),
        ]))
        self.story.append(obs_tbl)

    # ── Secciones y tablas ───────────────────────────────────────────────────
    def barra(self, titulo):
        """Barra de título de sección (OPERACIONES, MATERIALES, ...)."""
        from reportlab.platypus import Table, TableStyle
        return Table([[self.P(titulo, size=10, bold=True, color=self.WHITE)]],
                     colWidths=[self.CW],
                     style=TableStyle([
                         ("BACKGROUND", (0,0), (-1,-1), self.PRIMARY),
                         ("TOPPADDING", (0,0), (-1,-1), 5),
                         ("BOTTOMPADDING", (0,0), (-1,-1), 5),
                         ("LEFTPADDING", (0,0), (-1,-1), 6),
                     ]))

    def tabla(self, filas, anchos, estilo_extra=()):
        """Tabla de datos: encabezado con el color de la marca y filas alternadas."""
        from reportlab.platypus import Table, TableStyle
        tbl = Table(filas, colWidths=anchos)
        tbl.setStyle(TableStyle([
            ("BACKGROUND",     (0,0), (-1,0), self.PRIMARY),
            ("ROWBACKGROUNDS", (0,1), (-1,-1), [self.WHITE, self.PRIMARY_L]),
            ("GRID",           (0,0), (-1,-1), 0.4, self.GRAY_D),
            ("VALIGN",         (0,0), (-1,-1), "MIDDLE"),
            ("TOPPADDING",     (0,0), (-1,-1), 4),
            ("BOTTOMPADDING",  (0,0), (-1,-1), 4),
            ("LEFTPADDING",    (0,0), (-1,-1), 4),
            *estilo_extra,
        ]))
        return tbl

    def vacio(self, texto):
        """Renglón gris para una sección sin datos."""
        from reportlab.platypus import Table, TableStyle
        return Table([[self.P(texto, size=8, color=self.MUTED)]],
            colWidths=[self.CW], style=TableStyle([
                ("BACKGROUND", (0,0), (-1,-1), self.GRAY_L),
                ("TOPPADDING", (0,0), (-1,-1), 6),
                ("BOTTOMPADDING", (0,0), (-1,-1), 6),
                ("LEFTPADDING", (0,0), (-1,-1), 6),
            ]))

    # ── Pie: firmas + nota + datos de emisión, fijo en cada página ────────────
    def firmas(self, firma_centro, firma_derecha):
        """Arma la tabla de firmas. La primera columna ("Emitido por") se
        completa sola con el usuario logueado."""
        from reportlab.lib.units import mm
        from reportlab.lib.enums import TA_CENTER
        from reportlab.platypus import Table, TableStyle
        P, MUTED, GRAY_D = self.P, self.MUTED, self.GRAY_D
        emisor_nombre = session.get("nombre") or session.get("username") or "—"
        emisor_rol = (session.get("rol") or "").strip()
        emisor_rol_label = {"admin": "Administrador"}.get(emisor_rol, emisor_rol.capitalize() if emisor_rol else "")
        firma_head = [
            P(f"Emitido por: {emisor_nombre}" + (f" ({emisor_rol_label})" if emisor_rol_label else ""),
              size=7, color=MUTED, align=TA_CENTER),
            P(firma_centro, size=7, color=MUTED, align=TA_CENTER),
            P(firma_derecha, size=7, color=MUTED, align=TA_CENTER),
        ]
        firma_sign = [
            P("Generado automáticamente por el sistema", size=6.5, color=GRAY_D, align=TA_CENTER),
            P("", size=7), P("", size=7),
        ]
        firma_label = [
            P("Usuario y rol", size=6, color=GRAY_D, align=TA_CENTER),
            P("Firma y aclaración", size=6, color=GRAY_D, align=TA_CENTER),
            P("Firma y aclaración", size=6, color=GRAY_D, align=TA_CENTER),
        ]
        fw = self.CW / 3
        self.firma_tbl = Table(
            [firma_head, firma_sign, firma_label],
            colWidths=[fw, fw, fw],
            rowHeights=[8*mm, 18*mm, 6*mm],
        )
        self.firma_tbl.setStyle(TableStyle([
            ("BOX",        (0,0), (-1,-1), 0.5, GRAY_D),
            ("INNERGRID",  (0,0), (-1,-1), 0.4, GRAY_D),
            ("BACKGROUND", (0,0), (-1,0),  self.PRIMARY_L),
            ("BACKGROUND", (0,2), (-1,2),  self.GRAY_L),
            ("LINEBELOW",  (0,1), (-1,1),  0.8, self.BLACK),
            ("VALIGN",     (0,0), (-1,-1), "BOTTOM"),
            ("ALIGN",      (0,0), (-1,-1), "CENTER"),
            ("TOPPADDING", (0,0), (-1,-1), 3),
            ("BOTTOMPADDING",(0,0),(-1,-1),3),
        ]))

    def enviar(self, nombre_archivo):
        """Arma el PDF (con el pie dibujado sobre cada página) y lo devuelve."""
        from reportlab.lib.units import mm
        from reportlab.platypus import Paragraph
        from flask import send_file
        M, W, CW, FOOTER_H = self.M, self.W, self.CW, self.FOOTER_H
        nota_pie = self.cfg.get("pdf_nota_pie", "")
        ahora = datetime.now().strftime("%d/%m/%Y %H:%M")

        # Firmas, nota y datos de emisión se dibujan directo sobre el canvas
        # para que queden anclados al pie sin importar cuánto contenido tenga
        # el documento ni en cuántas páginas se divida.
        def _draw_footer(canvas, doc_):
            canvas.saveState()
            y = M + FOOTER_H  # tope del área reservada al pie
            fw_, fh_ = self.firma_tbl.wrap(CW, FOOTER_H)
            self.firma_tbl.drawOn(canvas, M, y - fh_)
            y -= fh_ + 2*mm
            if nota_pie:
                canvas.setStrokeColor(self.GRAY_D)
                canvas.setLineWidth(0.5)
                canvas.line(M, y, W - M, y)
                y -= 3*mm
                nota_p = Paragraph(nota_pie, self.sty(size=7.5, color=self.MUTED, space_after=0))
                nw_, nh_ = nota_p.wrap(CW, 12*mm)
                nota_p.drawOn(canvas, M, y - nh_)
                y -= nh_ + 2*mm
            canvas.setStrokeColor(self.GRAY_D)
            canvas.setLineWidth(0.5)
            canvas.line(M, y, W - M, y)
            canvas.setFont("Helvetica", 7)
            canvas.setFillColor(self.GRAY_D)
            canvas.drawCentredString(
                W/2, y - 9,
                f'MetalERP v3 · {self.numero} · Generado el {ahora} · Página {doc_.page}')
            canvas.restoreState()

        self.doc.build(self.story, onFirstPage=_draw_footer, onLaterPages=_draw_footer)
        self.buf.seek(0)
        return send_file(self.buf, mimetype="application/pdf",
                         as_attachment=False, download_name=nombre_archivo)


# ── Emisión de OT (PDF con ReportLab) ────────────────────────────────────────
@app.route("/api/ordenes/<int:oid>/pdf")
@login_required()
def emitir_ot_pdf(oid):
    return _pdf_o_error(_build_ot_pdf, oid)


def _build_ot_pdf(oid):
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER
    from reportlab.platypus import Paragraph, Spacer, KeepTogether

    # ── Datos ────────────────────────────────────────────────────────────────
    ot = query("""SELECT o.*,c.razon cliente_nombre,
        p.nombre producto_nombre, p.codigo producto_codigo
        FROM ordenes o
        LEFT JOIN clientes c ON c.id=o.cliente_id
        LEFT JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    if not ot:
        return jsonify({"error": "OT no encontrada"}), 404

    ops = query("""SELECT oo.*,
        cm.nombre cat_maquina_nombre, m.nombre maquina_nombre,
        p.razon proveedor_nombre
        FROM orden_operaciones oo
        LEFT JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
        LEFT JOIN maquinas m ON m.id=oo.maquina_id
        LEFT JOIN proveedores p ON p.id=oo.proveedor_id
        WHERE oo.orden_id=? ORDER BY CAST(oo.orden AS INTEGER), oo.orden""", (oid,))

    mats = query("""SELECT om.*,
        m.descripcion, m.codigo, m.unidad,
        COALESCE(m.stock,0) AS stock
        FROM orden_materiales om
        JOIN materiales m ON m.id=om.material_id
        WHERE om.orden_id=? ORDER BY m.codigo""", (oid,))

    pdf = _PdfBase(ot["numero"], f"OT {ot['numero']}")
    PRIMARY, PRIMARY_L, GRAY_L, GRAY_D, WHITE, BLACK, MUTED = pdf.paleta()
    P, sty, story = pdf.P, pdf.sty, pdf.story

    mostrar_costos  = pdf.cfg.get("pdf_mostrar_costos",  "0") == "1"
    mostrar_precios = pdf.cfg.get("pdf_mostrar_precios", "0") == "1"
    # Sin el permiso no hay importes en el PDF, aunque la configuración los pida.
    ver_monetario_pdf = puede_ver_monetario()
    if not ver_monetario_pdf:
        mostrar_costos = mostrar_precios = False

    def fmt_min(n):
        try:
            v = float(n or 0)
        except Exception:
            return "0"
        if v == int(v):
            return str(int(v))
        return f"{v:.1f}".replace(".", ",")

    # ── 1. Encabezado ─────────────────────────────────────────────────────────
    pdf.cabecera("ORDEN DE TRABAJO", ot["numero"])

    # ── 2. Ficha OT ───────────────────────────────────────────────────────────
    estado_color = {
        "Pendiente":  colors.HexColor("#E65100"),
        "En proceso": PRIMARY,
        "Completada": colors.HexColor("#1B5E20"),
        "Cancelada":  colors.HexColor("#A32D2D"),
    }.get(ot["estado"], BLACK)
    estado_badge = (
        f'<font color="{estado_color.hexval()}"><b>{ot["estado"].upper()}</b></font>'
    )

    pdf.ficha([
        [P("Producto / descripción", size=8, bold=True, color=MUTED),
         P(ot["producto_nombre"] or ot["descripcion"] or "—", size=9),
         P("Estado", size=8, bold=True, color=MUTED),
         Paragraph(estado_badge, sty(size=10, bold=True))],

        [P("Cliente", size=8, bold=True, color=MUTED),
         P(ot["cliente_nombre"] or "—", size=9),
         P("Prioridad", size=8, bold=True, color=MUTED),
         P(ot["prioridad"] or "—", size=9)],

        [P("Cantidad", size=8, bold=True, color=MUTED),
         P(str(ot["cantidad"]), size=9),
         P("Fecha inicio", size=8, bold=True, color=MUTED),
         P(_pdf_fecha(ot["fecha_inicio"]), size=9)],

        # Sin permiso no queda ni la etiqueta: con los flags apagados esta
        # celda mostraba igual el rótulo "Precio venta" con un guión debajo,
        # que es un rastro de que ahí va un importe.
        [P("Costo material" if mostrar_costos else "Fecha entrega",
           size=8, bold=True, color=MUTED),
         P(_pdf_dinero(ot["costo_mat"]) if mostrar_costos else _pdf_fecha(ot["fecha_entrega"]), size=9),
         P(("Fecha entrega" if mostrar_costos else "Precio venta") if ver_monetario_pdf else "",
           size=8, bold=True, color=MUTED),
         P((_pdf_fecha(ot["fecha_entrega"]) if mostrar_costos else
            (_pdf_dinero(ot["precio_venta"]) if mostrar_precios else "—"))
           if ver_monetario_pdf else "", size=9)],
    ])
    pdf.observaciones(ot["obs"])
    story.append(Spacer(1, 6*mm))

    # ── 3. Operaciones ────────────────────────────────────────────────────────
    story.append(KeepTogether([pdf.barra("OPERACIONES")]))

    if ops:
        op_head = [
            P("Ord.", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Operación", size=8, bold=True, color=WHITE),
            P("Sector / Máquina", size=8, bold=True, color=WHITE),
            P("Setup (min)", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Ciclo (seg)", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Cant. req.", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Ciclo x Cant.", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Estado", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Firma / V°B°", size=8, bold=True, color=WHITE, align=TA_CENTER),
        ]
        op_rows = [op_head]
        for op in ops:
            est_c = {
                "Pendiente":  colors.HexColor("#E65100"),
                "En proceso": PRIMARY,
                "Completada": colors.HexColor("#1B5E20"),
            }.get(op["estado"], MUTED)

            tercerizado = op["es_tercerizada"] if "es_tercerizada" in op.keys() else 0
            if tercerizado:
                sector = f'<font color="#A32D2D"><b>TERC.</b></font> {op["proveedor_nombre"] or "—"}'
            else:
                sector = op["cat_maquina_nombre"] or "—"
                if op["maquina_nombre"]:
                    sector += f'<br/><font size="7" color="#888888">{op["maquina_nombre"]}</font>'

            # El ciclo esta en segundos por pieza; la columna "Ciclo x Cant."
            # se muestra en minutos, que es la escala util para el operario.
            ciclo_x_cant = float(op["tiempo_ciclo_seg"] or 0) * float(op["qty_requerida"] or 0) / 60.0

            op_rows.append([
                P(op["orden"], size=8, align=TA_CENTER),
                Paragraph(op["nombre"], sty(size=8)),
                Paragraph(sector, sty(size=8)),
                P(op["tiempo_setup_min"] or 0, size=8, align=TA_CENTER),
                P(op["tiempo_ciclo_seg"] or 0, size=8, align=TA_CENTER),
                P(op["qty_requerida"] or 0, size=8, align=TA_CENTER),
                Paragraph(f'<b>{fmt_min(ciclo_x_cant)}</b> min', sty(size=8, align=TA_CENTER)),
                Paragraph(f'<font color="{est_c.hexval()}"><b>{op["estado"]}</b></font>',
                          sty(size=7, align=TA_CENTER)),
                P("", size=8),   # firma
            ])

        story.append(pdf.tabla(op_rows,
            [9*mm, 42*mm, 36*mm, 14*mm, 14*mm, 14*mm, 19*mm, 20*mm, 12*mm],
            # Recuadro de la firma con borde más grueso
            [("BOX", (8,1), (8,-1), 0.8, GRAY_D)]))
    else:
        story.append(pdf.vacio("Sin operaciones registradas."))

    story.append(Spacer(1, 6*mm))

    # ── 4. Materiales ─────────────────────────────────────────────────────────
    story.append(KeepTogether([pdf.barra("MATERIALES / INSUMOS")]))

    if mats:
        mat_head = [
            P("Código", size=8, bold=True, color=WHITE),
            P("Descripción", size=8, bold=True, color=WHITE),
            P("Cant. requerida", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Cant. asignada", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Unidad", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Stock disp.", size=8, bold=True, color=WHITE, align=TA_CENTER),
        ]
        mat_rows = [mat_head]
        for m in mats:
            ok = float(m["cantidad_asignada"] or 0) >= float(m["cantidad_requerida"] or 0)
            asn_color = colors.HexColor("#1B5E20") if ok else colors.HexColor("#E65100")
            mat_rows.append([
                P(m["codigo"], size=8),
                Paragraph(m["descripcion"], sty(size=8)),
                P(m["cantidad_requerida"], size=8, align=TA_CENTER),
                Paragraph(
                    f'<font color="{asn_color.hexval()}"><b>{m["cantidad_asignada"]}</b></font>',
                    sty(size=8, align=TA_CENTER)),
                P(m["unidad"], size=8, align=TA_CENTER),
                P(m["stock"], size=8, align=TA_CENTER),
            ])

        story.append(pdf.tabla(mat_rows, [25*mm, 70*mm, 26*mm, 26*mm, 18*mm, 15*mm]))
    else:
        story.append(pdf.vacio("Sin materiales registrados."))

    # ── 5. Pie ────────────────────────────────────────────────────────────────
    pdf.firmas("Supervisor de producción", "Control de calidad")
    return pdf.enviar(f'{ot["numero"]}.pdf')


# ── Emisión de OP (planilla de trazabilidad por operación) ──────────────────
@app.route("/api/ordenes/<int:oid>/operaciones/<int:opid>/pdf")
@login_required()
def emitir_op_pdf(oid, opid):
    return _pdf_o_error(_build_op_pdf, oid, opid)


def _build_op_pdf(oid, opid):
    """Genera la planilla de trazabilidad de una operación puntual de una OT,
    con la misma estética que el PDF de OT, más una tabla de
    fecha/operador/piezas OK/piezas NOK para completar a mano."""
    from reportlab.lib.units import mm
    from reportlab.lib.enums import TA_CENTER
    from reportlab.platypus import Spacer, Table, TableStyle

    ot = query("""SELECT o.*,c.razon cliente_nombre,
        p.nombre producto_nombre, p.codigo producto_codigo
        FROM ordenes o
        LEFT JOIN clientes c ON c.id=o.cliente_id
        LEFT JOIN productos p ON p.id=o.producto_id
        WHERE o.id=?""", (oid,), one=True)
    if not ot:
        return jsonify({"error": "OT no encontrada"}), 404

    op = query("""SELECT oo.*,cm.nombre cat_maquina_nombre,m.nombre maquina_nombre,
        p.razon proveedor_nombre
        FROM orden_operaciones oo
        LEFT JOIN categorias_maquina cm ON cm.id=oo.categoria_maquina_id
        LEFT JOIN maquinas m ON m.id=oo.maquina_id
        LEFT JOIN proveedores p ON p.id=oo.proveedor_id
        WHERE oo.id=? AND oo.orden_id=?""", (opid, oid), one=True)
    if not op:
        return jsonify({"error": "Operación no encontrada"}), 404

    # Materias primas asociadas a este paso puntual del proceso (si el
    # proceso definió consumos para esta operación).
    mats = query("""SELECT mt.codigo,mt.descripcion,mt.unidad
        FROM orden_operacion_materiales om
        JOIN materiales mt ON mt.id=om.material_id
        WHERE om.orden_operacion_id=? AND om.material_id IS NOT NULL""", (op["id"],))
    mat_prima_txt = ", ".join(f'{m["codigo"]} — {m["descripcion"]}' for m in mats) if mats else "—"

    maquina_txt = op["maquina_nombre"] or op["cat_maquina_nombre"] or ("Tercerizado — " + (op["proveedor_nombre"] or "—") if op["es_tercerizada"] else "—")
    pieza_txt = f'{ot["producto_codigo"] or ""} {ot["producto_nombre"] or ""}'.strip() or "—"
    unidad = "PZ"

    numero_op = f'{ot["numero"]}-{op["orden"]}'
    pdf = _PdfBase(numero_op, f'OP {numero_op}')
    PRIMARY, PRIMARY_L, GRAY_L, GRAY_D, WHITE, BLACK, MUTED = pdf.paleta()
    P, CW, story = pdf.P, pdf.CW, pdf.story

    # ── 1. Encabezado (idéntico al de la OT) ────────────────────────────────
    pdf.cabecera("ORDEN DE PROCESO", numero_op)

    # ── 2. Ficha de la operación (misma paleta que la ficha de la OT) ──────
    pdf.ficha([
        [P("Cliente", size=8, bold=True, color=MUTED),
         P(ot["cliente_nombre"] or "—", size=9),
         P("Partida (OT)", size=8, bold=True, color=MUTED),
         P(ot["numero"], size=9)],

        [P("Pieza", size=8, bold=True, color=MUTED),
         P(pieza_txt, size=9),
         P("Cantidad", size=8, bold=True, color=MUTED),
         P(f'{op["qty_requerida"] or 0:g} {unidad}', size=9)],

        [P("Máquina / Sector", size=8, bold=True, color=MUTED),
         P(maquina_txt, size=9),
         P("Operación", size=8, bold=True, color=MUTED),
         P(f'{op["orden"]} — {op["nombre"]}' if op["nombre"] else str(op["orden"]), size=9)],

        [P("Materia prima", size=8, bold=True, color=MUTED),
         P(mat_prima_txt, size=8.5),
         P("", size=8, bold=True, color=MUTED),
         P("", size=9)],
    ], [("SPAN", (1,3), (1,3)),
        ("SPAN", (2,3), (3,3))])
    story.append(Spacer(1, 6*mm))

    # ── 3. Trazabilidad ──────────────────────────────────────────────────────
    story.append(pdf.barra("TRAZABILIDAD"))

    n_rows = 19  # ajustado para que la planilla entre siempre en una sola página
    tbl_head = [P("Fecha", size=8, bold=True, color=WHITE, align=TA_CENTER),
                P("Operador", size=8, bold=True, color=WHITE, align=TA_CENTER),
                P("Piezas OK", size=8, bold=True, color=WHITE, align=TA_CENTER),
                P("Piezas NOK", size=8, bold=True, color=WHITE, align=TA_CENTER)]
    tbl_data = [tbl_head] + [["", "", "", ""] for _ in range(n_rows)]
    trz = Table(tbl_data, colWidths=[28*mm, CW-28*mm-30*mm-30*mm, 30*mm, 30*mm],
        rowHeights=[8*mm] + [7*mm]*n_rows)
    trz.setStyle(TableStyle([
        ("BACKGROUND",     (0,0), (-1,0), PRIMARY),
        ("ROWBACKGROUNDS", (0,1), (-1,-1), [WHITE, PRIMARY_L]),
        ("GRID",           (0,0), (-1,-1), 0.4, GRAY_D),
        ("VALIGN",         (0,0), (-1,-1), "MIDDLE"),
        ("ALIGN",          (0,0), (-1,0), "CENTER"),
    ]))
    story.append(trz)

    # ── 4. Pie (igual que OT) ────────────────────────────────────────────────
    pdf.firmas("Operador", "Control de calidad")
    return pdf.enviar(f'OP_{ot["numero"]}_op{op["orden"]}.pdf')


# ── Emisión de OC (PDF con ReportLab, misma estética que la OT) ─────────────
@app.route("/api/ordenes_compra/<int:ocid>/pdf")
@login_required()
@solo_con_monetario
def emitir_oc_pdf(ocid):
    return _pdf_o_error(_build_oc_pdf, ocid)


def _build_oc_pdf(ocid):
    """Genera el PDF de la Orden de Compra con la misma estética que el PDF
    de OT."""
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    from reportlab.platypus import Paragraph, Spacer, KeepTogether

    # ── Datos ────────────────────────────────────────────────────────────────
    oc = query("""SELECT oc.*, p.razon proveedor_nombre, p.cuit proveedor_cuit,
        p.contacto proveedor_contacto, p.telefono proveedor_telefono,
        p.email proveedor_email,
        u.nombre creado_por_nombre, ua.nombre aprobado_por_nombre
        FROM ordenes_compra oc
        JOIN proveedores p ON p.id=oc.proveedor_id
        LEFT JOIN usuarios u ON u.id=oc.creado_por
        LEFT JOIN usuarios ua ON ua.id=oc.aprobado_por
        WHERE oc.id=?""", (ocid,), one=True)
    if not oc:
        return jsonify({"error": "OC no encontrada"}), 404

    items = query("""SELECT i.*, m.descripcion mat_desc, m.codigo mat_codigo,
        s.numero sc_numero, s.tipo sc_tipo,
        c.condicion_pago cot_condicion_pago, c.plazo_entrega_dias cot_plazo_entrega_dias
        FROM ordenes_compra_items i
        LEFT JOIN materiales m ON m.id=i.material_id
        LEFT JOIN solicitudes_compra s ON s.id=i.solicitud_id
        LEFT JOIN cotizaciones_compra c ON c.solicitud_id=i.solicitud_id AND c.seleccionada=1
        WHERE i.oc_id=?""", (ocid,))

    pdf = _PdfBase(oc["numero"], f"OC {oc['numero']}")
    PRIMARY, PRIMARY_L, GRAY_L, GRAY_D, WHITE, BLACK, MUTED = pdf.paleta()
    P, sty, story = pdf.P, pdf.sty, pdf.story

    # ── 1. Encabezado ─────────────────────────────────────────────────────────
    pdf.cabecera("ORDEN DE COMPRA", oc["numero"])

    # ── 2. Ficha OC ───────────────────────────────────────────────────────────
    estado_color = {
        "Pendiente aprobacion": colors.HexColor("#E65100"),
        "Aprobada":             colors.HexColor("#1B5E20"),
        "Enviada":              PRIMARY,
        "Recibida parcial":     colors.HexColor("#E65100"),
        "Recibida":             colors.HexColor("#1B5E20"),
        "Cancelada":            colors.HexColor("#A32D2D"),
    }.get(oc["estado"], BLACK)
    estado_badge = f'<font color="{estado_color.hexval()}"><b>{(oc["estado"] or "—").upper()}</b></font>'

    prov_contacto_parts = [p for p in [oc["proveedor_telefono"], oc["proveedor_email"]] if p]

    pdf.ficha([
        [P("Proveedor", size=8, bold=True, color=MUTED),
         P(oc["proveedor_nombre"] or "—", size=9),
         P("Estado", size=8, bold=True, color=MUTED),
         Paragraph(estado_badge, sty(size=10, bold=True))],

        [P("CUIT", size=8, bold=True, color=MUTED),
         P(oc["proveedor_cuit"] or "—", size=9),
         P("Fecha emisión", size=8, bold=True, color=MUTED),
         P(_pdf_fecha(oc["creado"]), size=9)],

        [P("Contacto", size=8, bold=True, color=MUTED),
         P(oc["proveedor_contacto"] or (" · ".join(prov_contacto_parts) if prov_contacto_parts else "—"), size=9),
         P("Entrega estimada", size=8, bold=True, color=MUTED),
         P(_pdf_fecha(oc["fecha_entrega_est"]), size=9)],

        [P("Monto total", size=8, bold=True, color=MUTED),
         Paragraph(f'<b>{_pdf_dinero(oc["monto_total"])}</b>', sty(size=9)),
         P("Aprobada por", size=8, bold=True, color=MUTED),
         P(oc["aprobado_por_nombre"] or "—", size=9)],
    ])
    pdf.observaciones(oc["obs"])
    story.append(Spacer(1, 6*mm))

    # ── 3. Ítems ──────────────────────────────────────────────────────────────
    story.append(KeepTogether([pdf.barra("ÍTEMS SOLICITADOS")]))

    if items:
        it_head = [
            P("N° SC", size=8, bold=True, color=WHITE),
            P("Descripción / Material", size=8, bold=True, color=WHITE),
            P("Cantidad", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Entrega", size=8, bold=True, color=WHITE, align=TA_CENTER),
            P("Precio unit.", size=8, bold=True, color=WHITE, align=TA_RIGHT),
            P("Total", size=8, bold=True, color=WHITE, align=TA_RIGHT),
        ]
        it_rows = [it_head]
        for i in items:
            desc = (f'{i["mat_codigo"]} — ' if i["mat_codigo"] else "") + (i["mat_desc"] or i["descripcion"] or "—")
            entrega = f'{i["cot_plazo_entrega_dias"]} días' if i["cot_plazo_entrega_dias"] else "—"
            total_item = float(i["precio_unit"] or 0) * float(i["cantidad"] or 0)
            it_rows.append([
                P(i["sc_numero"] or "—", size=8),
                Paragraph(desc, sty(size=8)),
                P(f'{i["cantidad"]} {i["unidad"] or ""}', size=8, align=TA_CENTER),
                P(entrega, size=8, align=TA_CENTER),
                P(_pdf_dinero(i["precio_unit"]), size=8, align=TA_RIGHT),
                Paragraph(f'<b>{_pdf_dinero(total_item)}</b>', sty(size=8, align=TA_RIGHT)),
            ])

        story.append(pdf.tabla(it_rows, [18*mm, 62*mm, 24*mm, 20*mm, 24*mm, 24*mm]))

        condiciones = sorted(set(i["cot_condicion_pago"] for i in items if i["cot_condicion_pago"]))
        if condiciones:
            story.append(Spacer(1, 2*mm))
            story.append(P(f'Condición de pago: {", ".join(condiciones)}', size=8, color=MUTED))
    else:
        story.append(pdf.vacio("Sin ítems registrados."))

    story.append(Spacer(1, 6*mm))
    story.append(P("Entregar certificado de material. Por favor indicar N° de OC en factura y/o remito.",
                    size=8, color=MUTED))

    # ── 4. Pie ────────────────────────────────────────────────────────────────
    pdf.firmas("Autorizado por", "Recepción / Proveedor")
    return pdf.enviar(f'{oc["numero"]}.pdf')


# ── Gestión de archivos de producto ──────────────────────────────────────────
import os as _os, mimetypes as _mimetypes
from werkzeug.utils import secure_filename as _secure

FILES_BASE = _os.path.join(_os.path.dirname(__file__), "documentos")

def _prod_dir(pid):
    """Returns the directory path for a product's files, creating it if needed."""
    prod = query("SELECT codigo FROM materiales WHERE id=?", (pid,), one=True)
    if not prod:
        return None, None
    safe_code = "".join(c if c.isalnum() or c in "-_." else "_" for c in prod["codigo"])
    path = _os.path.join(FILES_BASE, f"{safe_code}__{pid}")
    if not _os.path.isdir(path) and _os.path.isdir(FILES_BASE):
        # Si el código del artículo cambió (ahora se puede editar desde
        # Procesos o desde Inventario), la carpeta vieja sigue llamándose
        # <código viejo>__<id>: se la renombra para no "perder" los archivos.
        previas = [x for x in _os.listdir(FILES_BASE)
                   if x.endswith(f"__{pid}") and _os.path.isdir(_os.path.join(FILES_BASE, x))]
        if previas:
            try:
                _os.rename(_os.path.join(FILES_BASE, previas[0]), path)
            except OSError:
                return _os.path.join(FILES_BASE, previas[0]), prod["codigo"]
    _os.makedirs(path, exist_ok=True)
    return path, prod["codigo"]

# ── Versiones de producto ─────────────────────────────────────────────────────
@app.route("/api/productos/<int:pid>/versiones", methods=["GET"])
@login_required()
def list_versiones(pid):
    rows = query(
        """SELECT id,version_num,motivo,creado_por,creado
           FROM producto_versiones WHERE producto_id=?
           ORDER BY version_num DESC""", (pid,)
    )
    return jsonify([dict(r) for r in rows])

@app.route("/api/productos/<int:pid>/versiones/<int:vid>", methods=["GET"])
@login_required()
def get_version(pid, vid):
    import json
    row = query(
        "SELECT * FROM producto_versiones WHERE id=? AND producto_id=?",
        (vid, pid), one=True
    )
    if not row: return jsonify({"error":"Versión no encontrada"}), 404
    d = dict(row)
    d["snapshot"] = json.loads(d["snapshot"])
    prod_snap = d["snapshot"]["producto"]
    cat_id = prod_snap.get("categoria_id")
    if cat_id:
        cat = query("SELECT nombre FROM categorias_producto WHERE id=?", (cat_id,), one=True)
        prod_snap["categoria_nombre"] = cat["nombre"] if cat else None
    cli_id = prod_snap.get("cliente_id")
    if cli_id:
        cli = query("SELECT razon FROM clientes WHERE id=?", (cli_id,), one=True)
        prod_snap["cliente_nombre"] = cli["razon"] if cli else None
    # Completar datos de las operaciones que puedan faltar en snapshots viejos
    # (nombre de máquina específica y nombre de proveedor en tercerizadas)
    for op in d["snapshot"].get("operaciones", []):
        if not op.get("cat_maq_nombre") and op.get("categoria_maquina_id"):
            cm = query("SELECT nombre FROM categorias_maquina WHERE id=?", (op["categoria_maquina_id"],), one=True)
            op["cat_maq_nombre"] = cm["nombre"] if cm else None
        if not op.get("maquina_nombre") and op.get("maquina_id"):
            mq = query("SELECT nombre FROM maquinas WHERE id=?", (op["maquina_id"],), one=True)
            op["maquina_nombre"] = mq["nombre"] if mq else None
        if not op.get("proveedor_nombre") and op.get("proveedor_id"):
            pv = query("SELECT razon FROM proveedores WHERE id=?", (op["proveedor_id"],), one=True)
            op["proveedor_nombre"] = pv["razon"] if pv else None
    return jsonify(d)

@app.route("/api/productos/<int:pid>/versiones/<int:vid>", methods=["DELETE"])
@login_required(roles=["admin"])
def delete_version(pid, vid):
    execute("DELETE FROM producto_versiones WHERE id=? AND producto_id=?", (vid, pid))
    return jsonify({"ok": True})

def _sub_path(base, sub):
    """Resuelve una subcarpeta relativa dentro de la carpeta del artículo, sin permitir salir de ella."""
    sub = (sub or "").replace("\\", "/").strip("/")
    parts = [_secure(x) for x in sub.split("/") if x and x not in (".", "..")]
    full = _os.path.realpath(_os.path.join(base, *parts)) if parts else _os.path.realpath(base)
    root = _os.path.realpath(base)
    if full != root and not full.startswith(root + _os.sep):
        return None, ""
    return full, "/".join(parts)

@app.route("/api/productos/<int:pid>/archivos", methods=["GET"])
@login_required()
def list_archivos(pid):
    """Lista archivos y carpetas del artículo. ?sub=carpeta/subcarpeta navega la estructura."""
    path, codigo = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    full, sub = _sub_path(path, request.args.get("sub"))
    if not full or not _os.path.isdir(full):
        return jsonify({"error": "Carpeta no encontrada"}), 404
    files, folders = [], []
    for fname in sorted(_os.listdir(full), key=str.lower):
        fpath = _os.path.join(full, fname)
        if _os.path.isdir(fpath):
            folders.append({"nombre": fname, "items": len(_os.listdir(fpath))})
        elif _os.path.isfile(fpath):
            stat = _os.stat(fpath)
            mime, _ = _mimetypes.guess_type(fname)
            files.append({
                "nombre": fname,
                "ruta":   (sub + "/" if sub else "") + fname,
                "size":   stat.st_size,
                "mime":   mime or "application/octet-stream",
                "is_img": (mime or "").startswith("image/"),
                "is_pdf": mime == "application/pdf",
            })
    return jsonify({"archivos": files, "carpetas": folders, "sub": sub, "carpeta": path})

@app.route("/api/productos/<int:pid>/carpetas", methods=["POST"])
@login_required(roles=["admin", "operario"])
def create_carpeta_archivos(pid):
    path, _ = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    d = request.json or {}
    nombre = _secure((d.get("nombre") or "").strip())
    if not nombre:
        return jsonify({"error": "Nombre de carpeta requerido"}), 400
    base, _s = _sub_path(path, d.get("sub"))
    if not base:
        return jsonify({"error": "Ruta inválida"}), 400
    dest = _os.path.join(base, nombre)
    if _os.path.exists(dest):
        return jsonify({"error": "Ya existe una carpeta o archivo con ese nombre"}), 409
    _os.makedirs(dest)
    return jsonify({"ok": True, "nombre": nombre}), 201

@app.route("/api/productos/<int:pid>/carpetas", methods=["DELETE"])
@login_required(roles=["admin"])
def delete_carpeta_archivos(pid):
    path, _ = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    full, sub = _sub_path(path, request.args.get("sub"))
    if not full or not sub or not _os.path.isdir(full):
        return jsonify({"error": "Carpeta no encontrada"}), 404
    if _os.listdir(full):
        return jsonify({"error": "La carpeta no está vacía. Eliminá primero su contenido."}), 400
    _os.rmdir(full)
    return jsonify({"ok": True})

@app.route("/api/productos/<int:pid>/archivos", methods=["POST"])
@login_required(roles=["admin", "operario"])
def upload_archivo(pid):
    from flask import request as _req
    path, _ = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    if "file" not in _req.files:
        return jsonify({"error": "Sin archivo"}), 400
    f = _req.files["file"]
    if not f.filename:
        return jsonify({"error": "Nombre vacío"}), 400
    full, _s = _sub_path(path, _req.form.get("sub") or _req.args.get("sub"))
    if not full:
        return jsonify({"error": "Ruta inválida"}), 400
    _os.makedirs(full, exist_ok=True)
    safe = _secure(f.filename)
    dest = _os.path.join(full, safe)
    f.save(dest)
    return jsonify({"ok": True, "nombre": safe}), 201

@app.route("/api/productos/<int:pid>/archivos/<path:nombre>", methods=["GET"])
@login_required()
def download_archivo(pid, nombre):
    from flask import send_from_directory
    path, _ = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    return send_from_directory(path, nombre)

@app.route("/api/productos/<int:pid>/archivos/<path:nombre>", methods=["DELETE"])
@login_required(roles=["admin"])
def delete_archivo(pid, nombre):
    path, _ = _prod_dir(pid)
    if not path:
        return jsonify({"error": "Producto no encontrado"}), 404
    fpath = _os.path.realpath(_os.path.join(path, nombre))
    if not fpath.startswith(_os.path.realpath(path) + _os.sep) or not _os.path.isfile(fpath):
        return jsonify({"error": "Archivo no encontrado"}), 404
    _os.remove(fpath)
    return jsonify({"ok": True})

# ── Cargas masivas ────────────────────────────────────────────────────────────
@app.route("/api/bulk/schema", methods=["GET"])
@login_required(roles=["admin"])
def get_bulk_schema():
    """Returns all tables with their columns (excluding system tables and PKs)."""
    import sqlite3 as _sq
    db2 = _sq.connect(DB_PATH)
    tables = db2.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT IN "
        "('sqlite_sequence') ORDER BY name").fetchall()
    result = {}
    for (tname,) in tables:
        cols = db2.execute(f"PRAGMA table_info({tname})").fetchall()
        # cid, name, type, notnull, default, pk
        result[tname] = [
            {"name": r[1], "type": r[2], "notnull": bool(r[3]),
             "default": r[4], "pk": bool(r[5])}
            for r in cols
        ]
    db2.close()
    return jsonify(result)

@app.route("/api/bulk/import", methods=["POST"])
@login_required(roles=["admin"])
def bulk_import():
    """Imports rows from JSON payload: {table: str, rows: list[dict], mode: 'insert'|'upsert'}"""
    d = request.json
    table  = d.get("table", "")
    rows   = d.get("rows", [])
    mode   = d.get("mode", "insert")   # insert = always insert, upsert = INSERT OR REPLACE

    if not table or not rows:
        return jsonify({"error": "table y rows requeridos"}), 400

    # Whitelist: only real tables
    import sqlite3 as _sq
    db2 = _sq.connect(DB_PATH)
    valid = {r[0] for r in db2.execute(
        "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
    db2.close()

    if table not in valid:
        return jsonify({"error": f"Tabla '{table}' no existe"}), 400
    if table in ("usuarios", "sqlite_sequence"):
        return jsonify({"error": "Tabla protegida"}), 403

    # Get column names (skip 'id' for plain inserts unless provided)
    pragma = query(f"PRAGMA table_info({table})")
    col_meta = {r["name"]: r for r in pragma}

    inserted = 0
    errors = []
    # True upsert (update-in-place, keeps the existing id and doesn't cascade-delete
    # related rows like proceso_operaciones) when the table has a UNIQUE key we can
    # conflict on. Falls back to INSERT OR REPLACE only if no unique key is found.
    unique_col = None
    if mode == "upsert":
        idx_list = query(f"PRAGMA index_list({table})")
        for ix in idx_list:
            if ix["unique"]:
                ix_cols = query(f"PRAGMA index_info({ix['name']})")
                if len(ix_cols) == 1 and ix_cols[0]["name"] != "id":
                    unique_col = ix_cols[0]["name"]
                    break

    # Get FK info for this table to nullify invalid references
    import sqlite3 as _sq3
    _db_fk = _sq3.connect(DB_PATH)
    fk_info = _db_fk.execute(f"PRAGMA foreign_key_list({table})").fetchall()
    # fk_info: (id, seq, table, from, to, on_update, on_delete, match)
    fk_cols = {row[3]: (row[2], row[4]) for row in fk_info}  # {col: (ref_table, ref_col)}
    _db_fk.close()

    for i, row in enumerate(rows):
        # Only keep columns that exist in the table
        valid_row = {k: v for k, v in row.items() if k in col_meta}
        # Remove 'id' for plain inserts (let autoincrement handle it)
        if mode == "insert" and "id" in valid_row:
            del valid_row["id"]
        if not valid_row:
            errors.append(f"Fila {i+1}: sin columnas válidas")
            continue
        # Nullify FK columns with empty/zero/nonexistent values
        for col, (ref_table, ref_col) in fk_cols.items():
            if col in valid_row:
                val = valid_row[col]
                # If blank, None, or 0 — set to NULL (avoids FK error)
                if val is None or val == "" or val == 0:
                    valid_row[col] = None
                else:
                    # Special case: cliente_id/proveedor_id given as a razon (name) instead of
                    # an id. Resolve by name (case-insensitive), auto-creating the record if needed.
                    if ref_table in ("clientes", "proveedores") and ref_col == "id" and not (
                        isinstance(val, (int, float)) or (isinstance(val, str) and val.strip().isdigit())
                    ):
                        nombre = str(val).strip()
                        found = query(f"SELECT id FROM {ref_table} WHERE lower(razon)=lower(?)",
                                      (nombre,), one=True)
                        if not found:
                            try:
                                new_id = execute(f"INSERT INTO {ref_table} (razon) VALUES (?)", (nombre,))
                                valid_row[col] = new_id
                            except Exception:
                                valid_row[col] = None
                        else:
                            valid_row[col] = found["id"]
                        continue
                    # Check if referenced value exists
                    try:
                        exists = query(f"SELECT 1 FROM {ref_table} WHERE {ref_col}=?",
                                       (val,), one=True)
                        if not exists:
                            valid_row[col] = None  # silently nullify invalid FK
                    except Exception:
                        valid_row[col] = None
        cols_str = ", ".join(valid_row.keys())
        placeholders = ", ".join("?" * len(valid_row))
        try:
            if mode == "upsert" and unique_col and unique_col in valid_row:
                update_cols = [c for c in valid_row.keys() if c not in ("id", unique_col)]
                if update_cols:
                    set_str = ", ".join(f"{c}=excluded.{c}" for c in update_cols)
                    sql = (f"INSERT INTO {table} ({cols_str}) VALUES ({placeholders}) "
                           f"ON CONFLICT({unique_col}) DO UPDATE SET {set_str}")
                else:
                    sql = f"INSERT OR IGNORE INTO {table} ({cols_str}) VALUES ({placeholders})"
                execute(sql, list(valid_row.values()))
            else:
                cmd = "INSERT OR REPLACE" if mode == "upsert" else "INSERT OR IGNORE"
                execute(f"{cmd} INTO {table} ({cols_str}) VALUES ({placeholders})",
                        list(valid_row.values()))
            inserted += 1
        except Exception as e:
            errors.append(f"Fila {i+1}: {str(e)[:80]}")

    return jsonify({"ok": True, "inserted": inserted,
                    "errors": errors, "total": len(rows)})

# ── Boot ──────────────────────────────────────────────────────────────────────
def get_local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80)); ip = s.getsockname()[0]; s.close(); return ip
    except: return "127.0.0.1"


def _backfill_requerimientos_desde_ott():
    """Corre en cada arranque: sincroniza cualquier OTT que todavía no tenga
    su requerimiento_productivo espejo (OTT cargadas antes de este cambio,
    o casos donde el sync en caliente falló). Es idempotente y rápido —
    solo toca las OTT que faltan, no vuelve a tocar las que ya están."""
    faltantes = query("""SELECT ott.id FROM ordenes_tercerizado ott
        WHERE NOT EXISTS (SELECT 1 FROM requerimientos_productivos rp WHERE rp.numero=ott.numero)""")
    if faltantes:
        print(f"[requerimientos_productivos] Backfill: sincronizando {len(faltantes)} OTT existentes...")
        for row in faltantes:
            _sync_requerimiento_desde_ott(row["id"])
        print("[requerimientos_productivos] Backfill completo.")

def _backfill_requerimientos_desde_compras():
    """Corre en cada arranque: sincroniza cualquier ítem de OC productivo
    (material categoria='Material') que todavía no tenga su
    requerimiento_productivo espejo (OC cargadas antes de este cambio, o
    casos donde el sync en caliente falló). Idempotente — solo toca lo que
    falta. _sync_requerimiento_desde_compra ya filtra internamente por
    categoría, así que acá alcanza con pasarle todos los ítems sin espejo."""
    faltantes = query("""SELECT oci.id FROM ordenes_compra_items oci
        LEFT JOIN materiales m ON m.id=oci.material_id
        WHERE m.categoria='Material'
          AND NOT EXISTS (SELECT 1 FROM requerimientos_productivos rp WHERE rp.numero='OCP-ITEM-'||oci.id)""")
    if faltantes:
        print(f"[requerimientos_productivos] Backfill: sincronizando {len(faltantes)} ítems de OC existentes...")
        for row in faltantes:
            _sync_requerimiento_desde_compra(row["id"])
        print("[requerimientos_productivos] Backfill completo (compras).")

def _backfill_requerimientos_desde_pedidos():
    """Corre en cada arranque: sincroniza cualquier ítem de pedido de cliente
    (ordenes_cliente_items) que todavía no tenga su requerimiento_productivo
    espejo (pedidos cargados antes de este cambio, o casos donde el sync en
    caliente falló). Idempotente — solo toca lo que falta."""
    faltantes = query("""SELECT oci.id FROM ordenes_cliente_items oci
        WHERE NOT EXISTS (SELECT 1 FROM requerimientos_productivos rp WHERE rp.numero='OC-CLI-ITEM-'||oci.id)""")
    if faltantes:
        print(f"[requerimientos_productivos] Backfill: sincronizando {len(faltantes)} ítems de pedido existentes...")
        for row in faltantes:
            _sync_requerimiento_desde_pedido(row["id"])
        print("[requerimientos_productivos] Backfill completo (pedidos de cliente).")

# ── Bitácora de auditoría — API (solo lectura, solo admin) ───────────────────
AUDITORIA_ACCIONES = ("alta", "modificacion", "baja")


def _aud_cargar(txt):
    if not txt:
        return {}
    try:
        v = _json.loads(txt)
        return v if isinstance(v, dict) else {}
    except Exception:
        return {}


def _aud_cambios(fila):
    """Comparación campo por campo entre el valor anterior y el nuevo."""
    antes, despues = _aud_cargar(fila["valores_antes"]), _aud_cargar(fila["valores_despues"])
    if not puede_ver_monetario():
        antes, despues = _aud_enmascarar(antes), _aud_enmascarar(despues)
    campos = sorted(set(antes) | set(despues))
    return [{"campo": c, "antes": antes.get(c), "despues": despues.get(c)} for c in campos]


def _aud_filtros():
    """WHERE + parámetros armados con los filtros de la query string."""
    w, p = ["1=1"], []
    desde = (request.args.get("desde") or "").strip()
    hasta = (request.args.get("hasta") or "").strip()
    origen = (request.args.get("origen") or "").strip()
    actor = (request.args.get("usuario") or "").strip()
    entidad = (request.args.get("entidad") or "").strip()
    accion = (request.args.get("accion") or "").strip()
    q = (request.args.get("q") or "").strip()
    if desde:
        w.append("fecha >= ?"); p.append(desde + " 00:00:00")
    if hasta:
        w.append("fecha <= ?"); p.append(hasta + " 23:59:59")
    if origen in ("usuario", "sistema"):
        w.append("origen = ?"); p.append(origen)
    if actor:
        w.append("actor = ?"); p.append(actor)
    if entidad:
        w.append("entidad = ?"); p.append(entidad)
    if accion in AUDITORIA_ACCIONES:
        w.append("accion = ?"); p.append(accion)
    if q:
        if puede_ver_monetario():
            w.append("(entidad LIKE ? OR actor LIKE ? OR IFNULL(registro_id,'') LIKE ?"
                     " OR IFNULL(valores_antes,'') LIKE ? OR IFNULL(valores_despues,'') LIKE ?)")
            p += [f"%{q}%"] * 5
        else:
            # Buscar dentro de los JSON permitiría adivinar importes probando
            # números hasta que un asiento aparezca: para el restringido la
            # búsqueda libre se limita a los metadatos del asiento.
            w.append("(entidad LIKE ? OR actor LIKE ? OR IFNULL(registro_id,'') LIKE ?)")
            p += [f"%{q}%"] * 3
    return " AND ".join(w), p


@app.route("/api/auditoria")
@login_required(roles=["admin"])
def get_auditoria():
    where, params = _aud_filtros()
    try:
        pagina = max(1, int(request.args.get("pagina", 1)))
    except (TypeError, ValueError):
        pagina = 1
    try:
        por_pagina = int(request.args.get("por_pagina", 50))
    except (TypeError, ValueError):
        por_pagina = 50
    por_pagina = min(200, max(10, por_pagina))
    total = query(f"SELECT COUNT(*) c FROM auditoria WHERE {where}", params, one=True)["c"]
    filas = query(
        f"SELECT * FROM auditoria WHERE {where} ORDER BY fecha DESC, id DESC LIMIT ? OFFSET ?",
        (*params, por_pagina, (pagina - 1) * por_pagina))
    rows = []
    for f in filas:
        cambios = _aud_cambios(f)
        rows.append({
            "id": f["id"], "fecha": f["fecha"], "origen": f["origen"],
            "usuario_id": f["usuario_id"], "actor": f["actor"],
            "entidad": f["entidad"], "registro_id": f["registro_id"],
            "accion": f["accion"], "ruta": f["ruta"],
            "campos": [c["campo"] for c in cambios],
        })
    return jsonify({
        "total": total, "pagina": pagina, "por_pagina": por_pagina,
        "paginas": max(1, -(-total // por_pagina)), "rows": rows,
    })


@app.route("/api/auditoria/opciones")
@login_required(roles=["admin"])
def get_auditoria_opciones():
    return jsonify({
        "entidades": [r["entidad"] for r in query("SELECT DISTINCT entidad FROM auditoria ORDER BY entidad")],
        "usuarios": [r["actor"] for r in query("SELECT DISTINCT actor FROM auditoria ORDER BY actor")],
        "acciones": list(AUDITORIA_ACCIONES),
        "origenes": ["usuario", "sistema"],
    })


@app.route("/api/auditoria/<int:aid>")
@login_required(roles=["admin"])
def get_auditoria_detalle(aid):
    f = query("SELECT * FROM auditoria WHERE id=?", (aid,), one=True)
    if not f:
        return jsonify({"error": "Asiento no encontrado"}), 404
    d = dict(f)
    d["cambios"] = _aud_cambios(f)
    d.pop("valores_antes", None)
    d.pop("valores_despues", None)
    return jsonify(d)


if __name__ == "__main__":
    print("="*52+"\n   MetalERP v3.0 - Taller Metalurgico\n"+"="*52)
    init_db()
    with app.app_context(), auditoria_proceso("backfill de requerimientos"):
        _backfill_requerimientos_desde_ott()
        _backfill_requerimientos_desde_compras()
        _backfill_requerimientos_desde_pedidos()
    ip = get_local_ip()
    
    # 1. Definimos el puerto en una variable única
    PUERTO = 5000
    
    # 2. Usamos la variable en las URLs dinámicamente
    print(f"\n   Local:   http://localhost:{PUERTO}")
    print(f"  Red:     http://{ip}:{PUERTO}")
    print(f"\n   Usuario: admin  |  Contraseña: admin123\n")
    
    # 3. Le pasamos la variable a Flask
    # threaded=True: atiende varias conexiones en paralelo. Sin esto, con
    # varios operarios conectados por la misma wifi, una request lenta
    # (ej. declarar la ultima operacion, que descuenta MP y genera PT)
    # bloqueaba a todas las demas hasta terminar.
    app.run(host="0.0.0.0", port=PUERTO, debug=False, threaded=True)